/* ---- the game's settings ---- */

#define GAME_SETTINGS GA(0x8016475Cu)   /* settings block: +36 difficulty, +37 map, +38/+39 keypad layouts */
#define TITLE_SCREEN GA(0x8012DF84u)    /* shell screens return the next screen to run */
#define HISTORY_SCREEN GA(0x8013629Cu)


static int game_started; /* the title screen has run: the settings block is the game's */

/* Writes the settings into the game (its settings block) and the mixer. */
static void apply_game_settings(void)
{
    if (game_started) {
        mem_w8(&M.cpu, GAME_SETTINGS + 36, (uint8_t)settings_game.difficulty);
        mem_w8(&M.cpu, GAME_SETTINGS + 37, (uint8_t)settings_game.map);
        mem_w8(&M.cpu, GAME_SETTINGS + 38, (uint8_t)settings_game.keypad[0]);
        mem_w8(&M.cpu, GAME_SETTINGS + 39, (uint8_t)settings_game.keypad[1]);
    }
    audio_set_volumes(settings_game.music, settings_game.effects);
}

/* ---- sounds ----
 * The game's own menu sounds, keyed on the SPU directly (the game is stopped
 * while the pages are open), with the voice settings the game's menus use:
 * the cursor sound, and for select and back the explosion (the menus' music
 * under it, as the game's). They take the highest silent voices. */
/* With the decomp's 48 voices (TM2_PORT_SPU48, its SPU_VOICES.md 5: portSpuExt in the build) the game's driver
 * keeps to voices 0..43 and leaves 44..47 to these, in the SPU's second register block (0x1F802C00, hw.c); with
 * 24 the highest silent ones below 24, as before. */
#define SPU_VOICE(v, reg) ((v) < 24 ? 0x1F801C00u + (uint32_t)(v) * 16 + (reg) : 0x1F802C00u + (uint32_t)((v) - 24) * 16 + (reg))
#define SPU_KEY_ON(v) ((v) < 24 ? 0x1F801D88u + ((v) >= 16 ? 2u : 0u) : 0x1F802D88u + ((v) - 24 >= 16 ? 2u : 0u))
static int spu48(void) { static int has = -1; if (has < 0) has = port_sym("portSpuExt") != 0; return has; }
static int voices_top(void) { return spu48() ? 48 : 24; }

typedef struct { uint16_t vol, pitch, start, adsr1, adsr2; } MenuSound;
static const MenuSound CURSOR_SOUND = {0x1932, 0x050A, 0x1A70, 0x80FF, 0x4E00};
static const MenuSound SELECT_SOUND = {0x274E, 0x050A, 0x1264, 0x80FF, 0x5FC0};

static int free_voice(int below)
{
    for (int v = below - 1; v >= (spu48() ? 44 : 0); v--)
        if (!(rc_io_read(&M.cpu, SPU_VOICE(v, 0xC), 2) & 0xFFFF))
            return v;
    return -1;
}

static int key_on(const MenuSound *snd, int below, int pitch_shift, int volume_percent)
{
    int v = free_voice(below);
    if (v < 0)
        return voices_top();
    uint32_t vol = (uint32_t)snd->vol * (uint32_t)volume_percent / 100;
    rc_io_write(&M.cpu, SPU_VOICE(v, 0), vol, 2);
    rc_io_write(&M.cpu, SPU_VOICE(v, 2), vol, 2);
    rc_io_write(&M.cpu, SPU_VOICE(v, 4), (uint32_t)snd->pitch >> pitch_shift, 2);
    rc_io_write(&M.cpu, SPU_VOICE(v, 6), snd->start, 2);
    rc_io_write(&M.cpu, SPU_VOICE(v, 8), snd->adsr1, 2);
    rc_io_write(&M.cpu, SPU_VOICE(v, 0xA), snd->adsr2, 2);
    rc_io_write(&M.cpu, SPU_VOICE(v, 0xE), snd->start, 2);
    spu_port_keyon = 1; /* not thinned */
    rc_io_write(&M.cpu, SPU_KEY_ON(v), 1u << ((v < 24 ? v : v - 24) & 15), 2);
    spu_port_keyon = 0;
    if (M.trace) fprintf(stderr, "options: sound %04X on voice %d\n", snd->start, v);
    return v;
}

static int from_title;  /* opened from the title menu's Options, not with F1 in a race */

/* Back to the game's picture after the port's pages: the frame buffer still
 * holds what the game last showed (the title, a battle, the arena select...).
 * So the page's last picture stays up until the game has drawn two frames of
 * its next screen (SetFrameStart; the first can be unsettled, as car select's
 * car before it turns), or 10 seconds at most: no old screen flashes up. */
static int display_hold, display_hold_frames;
static uint64_t display_hold_until;
static Image display_held;
static void battle_overlay_off(void); /* (below, with the scoreboard) */
static void display_to_game(const Image *last)
{
    static const unsigned char black[4 * 4 * 3] = {0};
    Psyz_VideoSetDisplayRGB24Fill(1);
    if (last && last->px && image_resize(&display_held, last->w, last->h)) {
        memcpy(display_held.px, last->px, (size_t)last->w * last->h * 3);
        Psyz_VideoSetDisplayRGB24(display_held.px, display_held.w, display_held.h);
    } else {
        Psyz_VideoSetDisplayRGB24(black, 4, 4);
    }
    display_hold = 1;
    display_hold_frames = 0;
    display_hold_until = M.vblanks + 600;
}
/* a loading picture (the line-up, the globe's LOADING) held until the level draws: the game's own load frames between
 * (its globe and title, a wide stretched frame) ended the hold after 2 frames, and a long online load showed them (the
 * user's 2026-11-11 take, 1:34); 2: held until the next screen takes it (the podium's scene: no arena frames before) */
static int display_hold_round, display_hold_serial;
int vp_round_serial(void); /* vplus/fixes.c */
static void display_hold_to_round(int how)
{
    display_hold_round = how;
    display_hold_serial = vp_round_serial();
    display_hold_until = M.vblanks + 60 * 60;
}
static void display_release(void)
{
    if (!display_hold) return;
    display_hold = 0;
    display_hold_round = 0;
    Psyz_VideoSetDisplayRGB24Fill(0);
    Psyz_VideoSetDisplayRGB24(NULL, 0, 0);
}
/* runtime/movie.c: a movie starts: it draws straight to the display, never the game's frames that end the hold, so a
 * page's held picture (the co-op duel's "WINS" menu) stayed over the winner's ending, its sound alone playing (the
 * user's online co-op take 2026-11-16) */
void ui_movie_start(void) { display_release(); }
/* hle.c: each frame of the game's */
static void carsel_overlay(int force);
static int carsel_info, carsel_info_frames; /* (below: car select's CAR INFO) */
void ui_frame_start(void)
{
    if (display_hold && display_hold_round) { /* (counted from the level's round on) */
        if (display_hold_round == 1 && vp_round_serial() != display_hold_serial) display_hold_round = 0, display_hold_frames = 0;
    } else if (display_hold && ++display_hold_frames >= 2) display_release();
    /* car select is up again: drawn with the port's picture (3, ui_SceneBackground; a frame more, 4, as that frame is
     * shown a frame later: else the bar over CAR INFO's picture), else after 3 frames */
    if (carsel_info == 3) carsel_info = 4;
    else if (carsel_info == 4 || (carsel_info == 2 && ++carsel_info_frames >= 3)) { carsel_info = 0; carsel_overlay(1); }
}
/* the tournament's save cards opened to save (after a won level), not to load */
static struct {
    int active, level, players, cars[PROFILE_SAVE_PLAYERS], difficulty, saved;
    int online;                                   /* made hosting a server (online ids) */
    char who[PROFILE_SAVE_PLAYERS][32];           /* each seat's profile ("" a guest); online the lobby's names */
    unsigned char ids[PROFILE_SAVE_PLAYERS][8];   /* online: each seat's profile online id (all 0 a guest) */
} saving;
/* A save's players against the seats now (any order: each one's car goes with them; every guest one profile): map[seat]
 * the save's seat, 1 when they are the same players. A save from before 2026-11-10 (who not kept): anyone, in order. */
static int save_seat_match(const ProfileSave *sv, int seats, const char (*names)[32], const unsigned char (*ids)[8], int *map)
{
    if (!sv || !sv->used || seats != sv->players || seats > PROFILE_SAVE_PLAYERS) return 0;
    if (!sv->ident) {
        for (int s = 0; s < seats; s++) map[s] = s;
        return 1;
    }
    int used[PROFILE_SAVE_PLAYERS] = {0};
    for (int s = 0; s < seats; s++) {
        map[s] = -1;
        for (int k = 0; k < sv->players && map[s] < 0; k++)
            if (!used[k] && (sv->online ? !memcmp(ids[s], sv->ids[k], 8) : !SDL_strcasecmp(names[s], sv->who[k])))
                map[s] = k, used[k] = 1;
        if (map[s] < 0) return 0;
    }
    return 1;
}
static int local_save_ok(const ProfileSave *sv, int *map); /* (below, with the sign-in: this PC's players) */
static void save_who_text(const ProfileSave *sv, char *out, size_t n) /* "TOKATTA, DREW (A GUEST)" */
{
    size_t at = 0;
    out[0] = 0;
    for (int p = 0; p < sv->players && p < PROFILE_SAVE_PLAYERS && at < n; p++)
        at += (size_t)snprintf(out + at, n - at, "%s%s", p ? ", " : "", sv->who[p][0] ? sv->who[p] : "a guest");
}
static int play_players = 1; /* Local Play: how many are playing (signed in); a save loads with as many */
static int group_players = 2; /* the 2, 3 or 4 Players menu chosen */
static char sp_extra_name[2][64]; /* players 3 and 4: the profile each signed in as ("" a guest) */
static int in_pause;    /* the pause menu is open (F1 does nothing then) */
static int boom_queued; /* the closing sound, for the game's sound driver once the pages close */

static void menu_sound(int select);

/* The select sound as the pages close. Opened from the title menu, the game's
 * own screens run next, and its sound driver silences voices it isn't using
 * at its next VBlank, cutting off a sound of ours: so the driver plays it
 * (sound 0x1D, the title menu's select), as the pages close. In a race the
 * loaded sounds are others: there it stays ours. */
static void closing_sound(void)
{
    if (from_title)
        boom_queued = settings_game.menu_sounds;
    else
        menu_sound(1);
}

static void closing_sound_now(void) { menu_sound(1); }

/* The menus' frame for sound: the effects volume for new voices. Every
 * menu loop calls it once a frame. */
static void ui_audio_frame(void) { audio_volumes_vblank(); }

/* "Not available" (the game has no buzzer of its own): the cursor click at a
 * low pitch, a short low tap (the user's pick of the candidates
 * tools/audio/render_spu_sounds.py renders). */
static void denied_sound(void)
{
    if (!settings_game.menu_sounds) return;
    MenuSound tap = CURSOR_SOUND;
    tap.pitch = 0x0380;
    key_on(&tap, voices_top(), 0, 100);
    ui_audio_frame();
}

/* The menus' select boom through the game's sound driver (sound 0x1D, as its title's), and two of the game's VBlanks
 * for it: the driver sets a voice's volume at its VBlank, so without them it stayed silent (the user's: no boom into
 * Local Play, Network Play, or after the sign-in's Start; Options had them). Scripted runs: no VBlanks (the timing). */
static int script_running(void);
static void game_boom(void)
{
    if (!settings_game.menu_sounds) return;
    guest_call(GA(0x800D3334u), 0x1D, 0, 0, 99);
    guest_call(GA(0x800D34C0u), 0, 0, 0, 0); /* soundUpdate, soundFlush: now */
    guest_call(GA(0x800D34E8u), 0, 0, 0, 0);
    if (!script_running() || getenv("TM2PC_TEST_BOOM") || getenv("TM2PC_TRAILER")) { rt_vblank(); rt_vblank(); } /* (tests: TM2PC_TEST_BOOM,
                                                                                                        * heard; trailer footage) */
}
static void menu_sound(int select)
{
    if (!settings_game.menu_sounds)
        return;
    if (!select) {
        key_on(&CURSOR_SOUND, voices_top(), 0, 100);
    } else {
        key_on(&SELECT_SOUND, voices_top(), 0, 100); /* (the menus' music under it gives it its body: no bass copy, the user's) */
    }
    ui_audio_frame(); /* the effects volume for the new voices */
}

