static void shorten(char *out, size_t n, const char *name, int strip_ext)
{
    char tmp[256];
    snprintf(tmp, sizeof tmp, "%s", name);
    char *dot = strip_ext ? strrchr(tmp, '.') : NULL;
    if (dot) *dot = 0;
    for (char *p = tmp; *p; p++) *p = (char)toupper((unsigned char)*p);
    if (strlen(tmp) > 60) strcpy(tmp + 57, "...");
    snprintf(out, n, "%s", tmp);
}

static void load_music_values(void)
{
    music_file_total = music_file_count();
    if (music_file_total > MUSIC_FILES) music_file_total = MUSIC_FILES;
    for (int i = 0; i < music_file_total; i++) {
        music_file_name(i, music_files[i], sizeof music_files[i]);
        shorten(music_names[i], sizeof music_names[i], music_files[i], 1);
    }
}

