typedef struct {
    int active, renaming;             /* entering a name: for a new profile or a rename */
    int for_player2;                  /* the profile is only made, not signed in (the sign-in screen) */
    char text[192];                   /* up to max (0: a profile name's PROFILE_NAME_MAX) */
    int max;
    int row, col, caps;               /* the grid's cursor; caps: letters are capitals */
    const char *message;              /* why the name was not taken */
    uint16_t prev;
    int held_for[4];
    char rename_from[64];             /* renaming this profile (not the signed-in one: the sign-in's halves) */
    int game_type;                    /* naming a Challenge Match game type: 1 a new one, 2 a rename, 3 its
                                       * description (edit_gt) */
} Naming;
