/* Customize HUD edits one player's HUD (their profile's), or the guests' (tm2pc.ini): each change
 * kept and saved at once */
static int hud_edit = -2; /* -2: not chosen yet (the first profile's) */
static int hud_slot[5], hud_slot_n;
static char hud_slot_name[5][48];
static const char *hud_slot_values[5];
static void hud_changed(void)
{
    hud_store(hud_edit);
    if (hud_edit >= 0 && profile_hud_save(hud_edit)) return;
    for (int p = 0; p < 4; p++) if (!profile_hud_owner(p)[0]) hud_reset_player(p); /* the guests: the defaults */
    changed |= SAVE_VIDEO;
}
static void hud_slots_make(void) /* each signed-in profile, then the guests */
{
    hud_slot_n = 0;
    for (int p = 0; p < 4; p++) {
        const char *who = profile_hud_owner(p);
        if (!who[0]) continue;
        snprintf(hud_slot_name[hud_slot_n], sizeof hud_slot_name[0], "%s", who);
        for (char *q = hud_slot_name[hud_slot_n]; *q; q++) *q = (char)toupper((unsigned char)*q);
        hud_slot[hud_slot_n++] = p;
    }
    snprintf(hud_slot_name[hud_slot_n], sizeof hud_slot_name[0], "GUESTS");
    hud_slot[hud_slot_n++] = -1;
    for (int i = 0; i < hud_slot_n; i++) hud_slot_values[i] = hud_slot_name[i];
    int found = 0;
    for (int i = 0; i < hud_slot_n; i++) found |= hud_slot[i] == hud_edit;
    if (!found) hud_edit = hud_slot[0]; /* player 1's profile when signed in, else the guests' */
    hud_select(hud_edit);
}
static int get_hud_slot(int a)
{
    (void)a;
    for (int i = 0; i < hud_slot_n; i++) if (hud_slot[i] == hud_edit) return i;
    return 0;
}
static void set_hud_slot(int a, int v)
{
    (void)a;
    if (v < 0 || v >= hud_slot_n) return;
    hud_store(hud_edit);
    hud_edit = hud_slot[v];
    hud_select(hud_edit);
    rebuild_page = 1;
}
