static int get_mode(int a)
{
    (void)a;
    int plus = 0, original = 0; /* each change as the preset has it */
    for (int i = 0; i < VP_COUNT; i++) {
        if (vp_retired(i)) { plus++; original++; continue; } /* (not offered: either preset's) */
        int v = vp_value((VpChangeId)i);
        plus += v == (vp_changes[i].values ? vp_changes[i].plus_value : !vp_changes[i].plus_off);
        original += v == 0;
    }
    return plus == VP_COUNT ? 1 : original == VP_COUNT ? 0 : 2;
}
static void set_mode(int a, int v) { (void)a; vp_preset(v); changed |= SAVE_VPLUS; }

static int grid_car(int column);

static Row *add(RowKind kind, const char *label, const char *desc)
{
    static Row spare; /* (a page past ROWS_MAX: the extra rows go here, not shown) */
    if (row_count >= ROWS_MAX - 1) { /* the last row: a note that more did not fit */
        if (!rows_overflow++) {
            Row *last = &rows[ROWS_MAX - 1];
            memset(last, 0, sizeof *last);
            last->kind = ROW_HEADER;
            snprintf(last->label, sizeof last->label, "MORE THAN FIT: TURN SOME OFF");
            row_count = ROWS_MAX;
            fprintf(stderr, "options: a page has more than %d rows; the rest are not shown\n", ROWS_MAX - 1);
        }
        memset(&spare, 0, sizeof spare);
        return &spare;
    }
    Row *r = &rows[row_count++];
    memset(r, 0, sizeof *r);
    r->kind = kind;
    r->desc = desc;
    for (int i = 0; label[i] && i < (int)sizeof r->label - 1; i++)
        r->label[i] = (char)toupper((unsigned char)label[i]);
    return r;
}

static void add_page(const char *label, int page, const char *desc) { add(ROW_PAGE, label, desc)->page = page; }

static Row *add_choice(const char *label, const char *desc, int (*get)(int), void (*set)(int, int), int arg,
                       const char *const *values, int count)
{
    Row *r = add(ROW_CHOICE, label, desc);
    r->get = get;
    r->set = set;
    r->arg = arg;
    r->values = values;
    r->count = count;
    return r;
}

