/* ---- the Stats page: a profile's counts (profile/feats.h), view only ----
 * Left/Right on Profile: another profile's; on Play: local play, online play, or all (the two added; Survival's
 * best round the higher). The profile shown first is the signed-in one. */
static const char *stats_names[PROFILE_MAX];
static int stats_profile = -1, stats_play = 2;
static const char *const stats_play_values[3] = {"LOCAL", "ONLINE", "ALL"};
static int get_stats_profile(int a) { (void)a; return stats_profile; }
static void set_stats_profile(int a, int v) { (void)a; stats_profile = v; rebuild_page = 1; }
static int get_stats_play(int a) { (void)a; return stats_play; }
static void set_stats_play(int a, int v) { (void)a; stats_play = v; rebuild_page = 1; }
static char stats_text[STAT_COUNT][24];
static const char *stats_value[STAT_COUNT];
static void add_stats_rows(void)
{
    static const char *const none[1] = {""};
    profile_rescan();
    int n = profile_count();
    for (int i = 0; i < n && i < PROFILE_MAX; i++) stats_names[i] = profile_list_name(i);
    if (!n) {
        add_choice("No profiles yet", "Profiles keep stats: make one in Options, Profiles.", get_zero, set_none, 0,
                   none, 1)->info = 1;
        return;
    }
    if (stats_profile < 0 || stats_profile >= n) { /* the signed-in profile first */
        stats_profile = 0;
        for (int i = 0; i < n; i++)
            if (profile_signed_in() && !SDL_strcasecmp(stats_names[i], profile_name())) stats_profile = i;
    }
    add_choice("Profile", "Left/Right: another profile's stats.", get_stats_profile, set_stats_profile, 0, stats_names,
               n);
    add_choice("Play", "Local play, online play, or both together.", get_stats_play, set_stats_play, 0,
               stats_play_values, 3);
    Feats f;
    profile_read_stats(stats_names[stats_profile], &f);
    for (int s = 0; s < STAT_COUNT; s++) {
        uint32_t l = f.stat[STATS_LOCAL][s], o = f.stat[STATS_ONLINE][s];
        uint32_t v = stats_play == 0 ? l : stats_play == 1 ? o : s == STAT_SURVIVAL_BEST ? (l > o ? l : o)
                   : s == STAT_SURVIVAL_TIME ? (!l ? o : !o ? l : l < o ? l : o) : l + o;
        if (s == STAT_SURVIVAL_TIME)
            snprintf(stats_text[s], sizeof stats_text[s], v ? "%u:%02u" : "-", v / 60, v % 60);
        else if (s == STAT_SECONDS)
            snprintf(stats_text[s], sizeof stats_text[s], "%u:%02u:%02u", v / 3600, v / 60 % 60, v % 60);
        else
            snprintf(stats_text[s], sizeof stats_text[s], "%u", v);
        stats_value[s] = stats_text[s];
    }
    static const struct { int stat; const char *label; } list[] = {
        {-1, "Matches"}, {STAT_MATCHES, "Matches played"}, {STAT_MATCH_WINS, "Matches won"},
        {STAT_TOURNAMENT_WINS, "Tournaments won"}, {STAT_VERSUS_GOLD, "Versus Tournament golds"},
        {STAT_VERSUS_SILVER, "Versus Tournament silvers"}, {STAT_VERSUS_BRONZE, "Versus Tournament bronzes"},
        {STAT_VERSUS_PLAYED, "Versus Tournaments played"}, {STAT_BOSSES_BEATEN, "Versus bosses beaten"},
        {STAT_BOSS_WINS, "Versus wins as the boss"}, {STAT_JOINS, "Online matches joined midway"},
        {STAT_SECONDS, "Time in matches"},
        {STAT_SURVIVAL_BEST, "Survival best round"}, {STAT_SURVIVAL_TIME, "Survival best time"}, /* (side by side; tournaments
                                                                                                * started: still counted, not shown) */
        {-1, "Combat"}, {STAT_KILLS, "Kills"}, {STAT_DEATHS, "Deaths"}, {STAT_DAMAGE, "Damage dealt"}, {STAT_FALLS, "Falls off the arena"},
        {STAT_SELF_KILLS, "Destroyed by your own weapon"},
        {STAT_FREEZES, "Enemies frozen"}, {STAT_FROZEN, "Times frozen"}, {STAT_PEDESTRIANS, "Pedestrians"},
        {-1, "Kills by weapon"}, {STAT_MG_KILLS, "Machine guns"}, {STAT_FIRE_KILLS, "Fire missiles"},
        {STAT_HOMING_KILLS, "Homing missiles"}, {STAT_POWER_KILLS, "Power missiles"}, {STAT_NAPALM_KILLS, "Napalm"},
        {STAT_REMOTE_KILLS, "Remote bombs"}, {STAT_MINE_KILLS, "Mines"}, {STAT_RICOCHET_KILLS, "Ricochet bombs"},
        {STAT_LIGHTNING_KILLS, "Lightning"}, {STAT_SPECIAL_KILLS, "Specials"}, {STAT_RAM_KILLS, "Rams"},
        {-1, "Pickups"}, {STAT_TURBOS, "Turbos"}, {STAT_HEALTHS, "Health"},
    };
    for (unsigned i = 0; i < sizeof list / sizeof list[0]; i++) {
        if (list[i].stat < 0) { add(ROW_HEADER, list[i].label, NULL); continue; }
        Row *r = add_choice(list[i].label, NULL, get_zero, set_none, 0, &stats_value[list[i].stat], 1);
        r->info = 1;
        r->small = 1;
    }
}

/* ---- passwords (Vanilla Plus "Remove password menu" off) ----
 * Six symbols, each blank, triangle, circle, cross or square (the game's
 * digits 0-4, its font's _ < @ > =): the code in base 5, most significant
 * first, decoded as the game's 8012CE7C (decomp TOURNAMENT_PASSWORDS.md). */
static struct { int d[6], slot, bad, level, car, flag; } pw;

static int password_decode(const int *d, int *level, int *car, int *flag)
{
    int code = 0;
    for (int i = 0; i < 6; i++) code = code * 5 + d[i];
    int lv = ((code >> 1) & 7) + 1, c = ((code >> 4) & 15) - 4, f = (code >> 9) & 1, check = (code >> 10) & 15;
    if ((code & 1) || (code & 0x100) || (code >> 14) || lv < 2 || c < 0 || c > 11 || (f && lv != 8) ||
        check != (c + 1) * (lv - 1) % 13)
        return 0;
    *level = lv;
    *car = c;
    *flag = f;
    return 1;
}

/* ---- Challenge Match ----
 * GAME TYPES (built in, with a padlock, and the profile's own) by mode;
 * then the match (arena, opponents, the mode's settings) and Start. Square
 * makes a new game type from the one highlighted, Triangle edits one of the
 * profile's. Beside the lists, a summary: the line-up (the arena's card
 * screen with every car) and the rules. Made so far: Last Car Standing with
 * the game's rules, the arena, the opponents and the drivers allowed; the
 * rest is gray (docs/CUSTOM_BATTLE.md). */
static const char *const arena_values[BATTLE_ARENAS + 1 + BATTLE_SECRET_ARENAS] = {"RANDOM", "LOS ANGELES", "MOSCOW", "PARIS",
    "AMAZONIA", "NEW YORK", "ANTARCTICA", "HOLLAND", "HONG KONG", "SUICIDE SWAMP", "CYBURBIA", "ROOF TOPS"};
/* the arena choices shown: the 8, then the secret arenas one by one as they unlock (2, 3 and 4 drivers' endings,
 * everyone signed in counted: profile_secret_levels_unlocked); a value past them (a profile with fewer) plays as
 * random. The match keeps the choice (9..11 the secret ones), arena_level gives the game's level (10..12). */
static int arena_choices(void) { return BATTLE_ARENAS + 1 + profile_secret_levels_unlocked(); }
/* Mod arenas (mods/mod_arena.c; the user's 2026-11-13): after the secret arenas, as mod cars come last; the arena mods
 * that are on (Options > Mods), in the mods' order, or online the server's list's order (every machine the same: a
 * match's arena ARENA_MOD_BASE + k is the same mod everywhere). Random picks among them too. */
enum { ARENA_MOD_BASE = 100, ARENA_MODS_MAX = 48 };
static void upper(char *t); /* (below) */
static int mod_arenas(int *out) /* their indexes (mods_get) */
{
    int n = 0;
    if (mods_online()) {
        const char *uid;
        for (int i = 0; n < ARENA_MODS_MAX && (uid = mods_online_uid(i)); i++)
            for (int j = 0; j < mods_count(); j++)
                if (mods_get(j)->kind == MOD_ARENA && mods_get(j)->ok && !strcmp(mods_get(j)->uid, uid)) { out[n++] = j; break; }
        return n;
    }
    for (int j = 0; j < mods_count() && n < ARENA_MODS_MAX; j++)
        if (mods_get(j)->kind == MOD_ARENA && mods_get(j)->ok && mod_on(mods_get(j))) out[n++] = j;
    return n;
}
static const char *arena_name(int v) /* a match's arena value, by name ("?": a mod arena not here) */
{
    if (v >= 0 && v < BATTLE_ARENAS + 1 + BATTLE_SECRET_ARENAS) return arena_values[v];
    int idx[ARENA_MODS_MAX], n = mod_arenas(idx), k = v - ARENA_MOD_BASE;
    if (k < 0 || k >= n) return "?";
    static char names[4][64];
    static int ring;
    char *s = names[ring++ & 3];
    snprintf(s, sizeof names[0], "%s", mods_get(idx[k])->name);
    upper(s);
    return s;
}
/* the list a row offers: Random, the 8, the secret ones unlocked, the mod arenas (values and names) */
static int arena_list_val[BATTLE_ARENAS + 1 + BATTLE_SECRET_ARENAS + ARENA_MODS_MAX], arena_list_n;
static const char *arena_list_names[BATTLE_ARENAS + 1 + BATTLE_SECRET_ARENAS + ARENA_MODS_MAX];
static int arena_list_make(void)
{
    int idx[ARENA_MODS_MAX], n = mod_arenas(idx);
    arena_list_n = 0;
    for (int v = 0; v < arena_choices(); v++) arena_list_val[arena_list_n] = v, arena_list_names[arena_list_n++] = arena_values[v];
    for (int k = 0; k < n; k++) {
        static char names[ARENA_MODS_MAX][64];
        snprintf(names[k], sizeof names[k], "%s", mods_get(idx[k])->name);
        upper(names[k]);
        arena_list_val[arena_list_n] = ARENA_MOD_BASE + k, arena_list_names[arena_list_n++] = names[k];
    }
    return arena_list_n;
}
static int arena_list_index(int v)
{
    for (int i = 0; i < arena_list_n; i++) if (arena_list_val[i] == v) return i;
    return 0;
}
static int arena_list_value(int i) { return i >= 0 && i < arena_list_n ? arena_list_val[i] : 0; }
static const Image *mod_arena_lineup(int arena); /* (below, with the cards) */
/* Random: any of the 8 or the mod arenas that are on (rolled with the match's random numbers: the same online) */
static int arena_random(void)
{
    int idx[ARENA_MODS_MAX], n = mod_arenas(idx), r = (int)SDL_rand(BATTLE_ARENAS + n);
    return r < BATTLE_ARENAS ? r + 1 : ARENA_MOD_BASE + (r - BATTLE_ARENAS);
}
int arena_level(int choice)
{
    if (mod_arena_test_level()) return MOD_ARENA_LEVEL; /* (tests: TM2PC_TEST_MOD_ARENA, a mod arena) */
    if (choice >= ARENA_MOD_BASE) { /* a mod arena: chosen for the loads, the session's level 13 */
        int idx[ARENA_MODS_MAX], n = mod_arenas(idx), k = choice - ARENA_MOD_BASE;
        return k < n && mod_arena_choose(mods_get(idx[k])->uid) ? MOD_ARENA_LEVEL : 0;
    }
    if (choice > BATTLE_ARENAS && choice >= arena_choices()) return 0; /* (locked now: random) */
    return choice > BATTLE_ARENAS ? choice + 1 : choice; /* 9..11: Suicide Swamp 10, Cyburbia 11, Roof Tops 12 */
}
