enum { BF_ARENA, BF_DIFFICULTY, BF_OPPONENTS, BF_LIVES, BF_TEAMS, BF_KILLS, BF_TIME, BF_POINTS };
enum { KILLS_STEPS = 8, TIME_STEPS = 7 };
static const int kills_steps[KILLS_STEPS] = {0, 5, 10, 15, 20, 25, 30, 50}, time_steps[TIME_STEPS] = {0, 3, 5, 10, 15, 20, 30};
static const char *const kills_values[KILLS_STEPS] = {"OFF", "5", "10", "15", "20", "25", "30", "50"};
enum { POINTS_STEPS = 8 }; /* King of the Hill's and Hunted's points to win: a point a second */
static const int points_steps[POINTS_STEPS] = {0, 50, 100, 150, 200, 300, 500, 1000};
static const char *const points_values[POINTS_STEPS] = {"OFF", "50", "100", "150", "200", "300", "500", "1000"};
static const char *const time_values[TIME_STEPS] = {"OFF", "3 MINUTES", "5 MINUTES", "10 MINUTES", "15 MINUTES", "20 MINUTES",
                                                    "30 MINUTES"};
static int step_of(const int *steps, int n, int v) { for (int i = 0; i < n; i++) if (steps[i] == v) return i; return 0; }
static const char *const team_count_values[] = {"OFF", "2", "3", "4"};
static const char *const team_values[BATTLE_TEAM_COLORS] = {"RED", "BLUE", "GREEN", "YELLOW"};
static const uint8_t TEAM_COLOR[BATTLE_TEAM_COLORS][3] = {{228, 24, 36}, {50, 110, 235}, {50, 190, 70}, {238, 190, 60}};
