{
    battle_match()->player_team[a & 3] = v;
    changed |= SAVE_BATTLE;
    rebuild_page = 1; /* its dot */
}
static int get_battle(int a)
{
    const MatchSetup *m = battle_match();
    if (a == BF_TEAMS) return m->teams ? m->teams - 1 : 0;
    if (a == BF_KILLS) return step_of(kills_steps, KILLS_STEPS, m->kills);
    if (a == BF_POINTS) return step_of(points_steps, POINTS_STEPS, m->points);
    if (a == BF_TIME) return step_of(time_steps, TIME_STEPS, m->time_limit);
    return a == BF_ARENA ? arena_list_index(m->arena) : a == BF_DIFFICULTY ? m->difficulty : a == BF_LIVES ? m->lives - 1
           : battle_opponents_shown() - 1 + number_base() < 0 ? 0 : battle_opponents_shown() - 1 + number_base();
}
static void set_battle(int a, int v)
{
    MatchSetup *m = battle_match();
    if (a == BF_KILLS) m->kills = kills_steps[v % KILLS_STEPS];
    else if (a == BF_POINTS) m->points = points_steps[v % POINTS_STEPS];
    else if (a == BF_TIME) m->time_limit = time_steps[v % TIME_STEPS];
    else if (a == BF_TEAMS) { /* the cars split evenly, the players red and red the smaller (the user's 2026-10-29: 15 cars
                               * 7/8, 5/5/5, 3/4/4/4) */
        m->teams = v ? v + 1 : 0;
        if (m->teams >= 2) {
            int players = play_players < 1 ? 1 : play_players > 4 ? 4 : play_players;
            int no = battle_full() ? battle_max_opponents() - (players - 1) : battle_opponents_shown();
            if (no < 0) no = 0;
            if (no > BATTLE_OPPONENT_SLOTS) no = BATTLE_OPPONENT_SLOTS;
            int n = players + no, size[BATTLE_TEAM_COLORS], k = 0, car = 0;
            for (int t = 0; t < m->teams; t++) size[t] = n / m->teams + (t >= m->teams - n % m->teams ? 1 : 0); /* (the extras last) */
            for (int t = 0; t < m->teams; t++)
                for (int j = 0; j < size[t]; j++, car++) {
                    if (car < players) m->player_team[car] = t;
                    else if (k < BATTLE_OPPONENT_SLOTS) m->team[k++] = t;
                }
        }
    } else if (a == BF_ARENA) m->arena = arena_list_value(v);
    else if (a == BF_DIFFICULTY) m->difficulty = v;
    else if (a == BF_LIVES) m->lives = v + 1;
    else m->opponents = v - number_base() + 1;
    changed |= SAVE_BATTLE;
    if (a != BF_DIFFICULTY && a != BF_LIVES) rebuild_page = 1; /* the opponents' rows follow */
}
static int get_opponent(int a)
{
    int car = battle_match()->opponent[a];
    for (int k = 0; k < opponent_count; k++) if (opponent_order[k] == car) return k + 1;
    return 0; /* random */
}
static void set_opponent(int a, int v)
{
    /* Dark Tooth once a match online (every machine's records alike, not tested with more): passed over on a slot while
     * another computer car has him (the user's 2026-11-18: three picked, two became Random at the start); offline as
     * many as picked (decomp request 33-2e: each his own head and state; ui_AiSelect checks the room) */
    int count = 1 + opponent_count, cur = get_opponent(a), step = (v - cur + count) % count == 1 ? 1 : -1;
    for (int tries = 0; tries < count && v && opponent_order[v - 1] == TOUR_DARK_TOOTH && netplay_lobby(); tries++) {
        int taken = 0;
        for (int i = 0; i < battle_match()->opponents && i < BATTLE_OPPONENT_SLOTS; i++)
            taken |= i != a && battle_match()->opponent[i] == TOUR_DARK_TOOTH;
        if (!taken) break;
        v = (v + step + count) % count;
    }
    battle_match()->opponent[a] = v ? opponent_order[v - 1] : -1;
    changed |= SAVE_BATTLE;
}
