enum { NS_MAX_PLAYERS, NS_BOTS, NS_REPLACE, NS_VISIBILITY, NS_VOICE, NS_TOUR_DIFFICULTY, NS_FIXED_CPUS, NS_TEAM_MODE, NS_KILL_CAM,
       NS_TOUR_LOAD, NS_TOUR_MODE, NS_SLOTS, NS_HUMANS };
/* A Challenge Match's slots (the user's, 2026-11-11): Slots (2-16) = Human only + CPU only + CPU / Open, always. As the
 * server has them: CPU only = fixed_cpus, CPU / Open = bots (a player joining takes one, Human only first), the players'
 * room max_players = Human only + CPU / Open. Human only at least 1 (the host), the room at least 2. Changing one row:
 * CPU only and CPU / Open trade with Human only first, Human only with CPU / Open first; Slots itself grows Human only,
 * shrinks Human only, then CPU / Open, then CPU only. */
enum { SLOT_HUMAN, SLOT_CPU, SLOT_OPEN };
static void net_slots_get(int x[3])
{
    int o = net_server.bots < net_server.max_players - 1 ? net_server.bots : net_server.max_players - 1; /* (more CPU / Open
                                                                       * than the room less the host: the same match) */
    x[SLOT_HUMAN] = net_server.max_players - (o < 0 ? 0 : o);
    x[SLOT_CPU] = net_server.fixed_cpus;
    x[SLOT_OPEN] = o < 0 ? 0 : o;
}
static void net_slots_put(const int x[3])
{
    net_server.fixed_cpus = x[SLOT_CPU];
    net_server.bots = x[SLOT_OPEN];
    net_server.max_players = x[SLOT_HUMAN] + x[SLOT_OPEN];
}
static int net_slots_min(const int x[3], int k) /* the least row k may go to, the others as they are */
{
    if (k == SLOT_HUMAN) return x[SLOT_OPEN] ? 1 : 2;
    if (k == SLOT_OPEN) return x[SLOT_HUMAN] >= 2 ? 0 : 1;
    return 0;
}
static void net_slots_set(int which, int v)
{
    static const int most[3] = {16, 12, 15};
    static const int order[3][2] = {{SLOT_OPEN, SLOT_CPU}, {SLOT_HUMAN, SLOT_OPEN}, {SLOT_HUMAN, SLOT_CPU}};
    int x[3];
    net_slots_get(x);
    if (v > most[which]) v = most[which];
    int d = v - x[which];
    if (d < 0) { /* (fewer: the room to the first of the others) */
        if (v < net_slots_min(x, which)) v = net_slots_min(x, which), d = v - x[which];
        x[order[which][0]] -= d;
        x[which] = v;
    } else {
        x[which] = v;
        for (int i = 0; i < 2 && d > 0; i++) { /* (more: taken from the others, each down to its least) */
            int k = order[which][i], take = x[k] - net_slots_min(x, k);
            if (take > d) take = d;
            if (take > 0) x[k] -= take, d -= take;
        }
        x[which] -= d; /* (what could not be taken: not added) */
    }
    net_slots_put(x);
}
static void net_slots_total(int t)
{
    int x[3];
    net_slots_get(x);
    int d = t - (x[0] + x[1] + x[2]);
    if (d > 0) x[SLOT_HUMAN] += d;
    static const int order[3] = {SLOT_HUMAN, SLOT_OPEN, SLOT_CPU};
    for (int i = 0; i < 3 && d < 0; i++) {
        int k = order[i], take = x[k] - net_slots_min(x, k);
        if (take > -d) take = -d;
        if (take > 0) x[k] -= take, d += take;
    }
    net_slots_put(x);
}
static int net_host_kill_cam = -1; /* (a joiner) the host's final kill cam (0 off, 1-3 shots; -1: not known) */
int ui_net_kill_cam(void) { return net_in_server && !net_server.host ? net_host_kill_cam : -1; } /* (vplus.c: online, the host's) */
static int get_net_server(int a)
{
    switch (a) {
    case NS_MAX_PLAYERS: return (NET_CPU_GAME(net_server.game) || net_server.max_players <= 4 ? net_server.max_players : 4) - 2;
    case NS_BOTS: { int x[3]; net_slots_get(x); return x[SLOT_OPEN]; } /* (CPU / Open: computer cars a player joining replaces) */
    case NS_REPLACE: return net_server.replace;
    case NS_VISIBILITY: return net_server.visibility;
    case NS_VOICE: return net_server.voice;
    case NS_FIXED_CPUS: return net_server.fixed_cpus;
    case NS_TEAM_MODE: return net_server.team_mode;
    case NS_KILL_CAM: return vp_value(VP_FINAL_KILL_CAM) & 3; /* (the host's own Vanilla Plus setting: one for everyone) */
    case NS_TOUR_LOAD: return net_tour_slot;
    case NS_TOUR_MODE: return net_tour_custom ? 2 : net_tour_loading;
    case NS_SLOTS: { int x[3]; net_slots_get(x); return x[0] + x[1] + x[2] - 2; }
    case NS_HUMANS: { int x[3]; net_slots_get(x); return x[SLOT_HUMAN] - 1; }
    default: return net_server.tour_difficulty;
    }
}
static void set_net_server(int a, int v)
{
    if ((a == NS_SLOTS || a == NS_HUMANS || a == NS_FIXED_CPUS || a == NS_BOTS) && netplay_in_match()) {
        void net_send_settings_now(void);
        a == NS_SLOTS ? net_slots_total(v + 2) : net_slots_set(a == NS_HUMANS ? SLOT_HUMAN : a == NS_BOTS ? SLOT_OPEN : SLOT_CPU,
                                                              a == NS_HUMANS ? v + 1 : v);
        rebuild_page = 1;
        net_send_settings_now(); /* (a match on, the lobby's frames not running: the room and the browser's listing now) */
        return;
    }
    switch (a) {
    case NS_MAX_PLAYERS: net_server.max_players = v + 2; break; /* (Co-op, Survival, Versus: a Challenge Match's is NS_SLOTS) */
    case NS_BOTS: net_slots_set(SLOT_OPEN, v); rebuild_page = 1; break;
    case NS_SLOTS: net_slots_total(v + 2); rebuild_page = 1; break;
    case NS_HUMANS: net_slots_set(SLOT_HUMAN, v + 1); rebuild_page = 1; break;
    case NS_REPLACE: net_server.replace = v; break;
    case NS_VISIBILITY: net_server.visibility = v; net_password_apply(); rebuild_page = 1; break;
    case NS_VOICE: net_server.voice = v; rebuild_page = 1; break;
    case NS_FIXED_CPUS: net_slots_set(SLOT_CPU, v); rebuild_page = 1; break; /* (the slots' total kept) */
    case NS_TEAM_MODE: net_server.team_mode = v; break;
    case NS_KILL_CAM: vp_set(VP_FINAL_KILL_CAM, v); changed |= SAVE_VPLUS; break;
    case NS_TOUR_LOAD: /* (a save: its difficulty too) */
        net_tour_slot = v;
        if (net_tour_save_loaded()) net_server.tour_difficulty = net_tour_save_loaded()->difficulty % 3;
        rebuild_page = 1;
        break;
    case NS_TOUR_MODE: /* NEW / LOAD / CUSTOM (LOAD: on the first slot that loads) */
        if (v == 1) { /* LOAD with no online save that loads: passed over (Mohamed Eissa's lobby, 2026-11-23: LOAD on an empty
                       * slot, each countdown ended in a chat line he could not read and no match) */
            int any = 0;
            for (int k = 0; k < PROFILE_SAVES; k++) any |= !net_tour_slot_why(k);
            if (!any) v = net_tour_custom ? 0 : 2; /* (from CUSTOM going left: NEW; from NEW going right: CUSTOM) */
        }
        net_tour_custom = v == 2;
        net_tour_loading = v == 1;
        if (v && net_tour_slot_why(net_tour_slot))
            for (int k = 0; k < PROFILE_SAVES; k++) if (!net_tour_slot_why(k)) { net_tour_slot = k; break; }
        if (net_tour_save_loaded()) net_server.tour_difficulty = net_tour_save_loaded()->difficulty % 3;
        rebuild_page = 1;
        break;
    default: net_server.tour_difficulty = v; break;
    }
}
