/* The host's Start: a countdown first (NET_COUNTDOWN seconds), in the chat in its own color with a beep each second,
 * on every machine; Start again stops it. */
static int net_countdown_secs(void) /* 5 (tests: TM2PC_NET_COUNTDOWN=N, 0 none: the start at once) */
{
    const char *e = getenv("TM2PC_NET_COUNTDOWN");
    return e ? atoi(e) : 5;
}
#define NET_COUNTDOWN net_countdown_secs()
static int net_countdown;        /* (host) the seconds left (0 none, -1 just stopped: once in the settings) */
static uint64_t net_countdown_at; /* (host) its start */
#define NET_CHAT_COUNTDOWN "\x01" /* (a chat line's speaker: the countdown's, drawn in its color, no name) */
static void net_chat_add(const char *who, const char *text);
static void net_countdown_show(int n) /* every machine: a new second (or the stop) in the chat, with its beep */
{
    static int shown;
    if (n == shown) return;
    if (n > 0) {
        char line[32];
        snprintf(line, sizeof line, n == NET_COUNTDOWN ? "Match starts in %d" : "%d", n);
        net_chat_add(NET_CHAT_COUNTDOWN, line);
        if (settings_game.menu_sounds) /* the menus' own: the cursor's click, the last one the select's explosion (the user's) */
        {
            key_on(n == 1 ? &SELECT_SOUND : &CURSOR_SOUND, voices_top(), 0, 100);
            ui_audio_frame();
        }
    } else if (n < 0 && shown > 0) net_chat_add(NET_CHAT_COUNTDOWN, "The countdown stopped");
    shown = n;
}
static void net_chat_add(const char *who, const char *text)
{
    if (net_chat_n == NET_CHAT_LINES) { memmove(net_chat[0], net_chat[1], sizeof net_chat[0] * (NET_CHAT_LINES - 1)); net_chat_n--; }
    snprintf(net_chat[net_chat_n++], sizeof net_chat[0], "%s: %s", who, text);
    if (!strcmp(who, "SERVER") || !strcmp(who, NET_CHAT_COUNTDOWN)) fprintf(stderr, "network: (chat) %s\n", text); /* (the
                                                                          * server's own lines, the countdown: the log too) */
}
static const char *player_name(int i); /* (below) */
static void net_names(char (*names)[LOBBY_NAME]) /* this PC's players' names, for the server */
{
    for (int p = 0; p < 4; p++) snprintf(names[p], LOBBY_NAME, "%s", p < play_players ? player_name(p) : "");
}
static int net_team[4]; /* (below) */
static void net_entered(void) /* on a server: its chat and our choices start over */
{
    memset(net_chat, 0, sizeof net_chat);
    net_chat_n = net_chat_seen = 0;
    net_seq_seen = 0;
    net_status_seen = -1;
    net_remote_n = 0;
    net_team_used = 0;
    net_kicked = net_muted = 0;
    memset(net_sent, 0xFF, sizeof net_sent);
    for (int p = 0; p < 4; p++) net_ready[p] = 0;
    net_starts_seen = 0;
    for (int p = 0; p < 4; p++) net_team[p] = -1;
    net_in_server = 1;
}
static void net_named(int kind, const char *text) /* the name grid's: 4 a chat line, 5 the server's name, 6 its address,
                                                    * 7 a friend code, 8 the master servers, 9 a private server's password */
{
    if (kind == 9) {
        if (net_join_where[0]) { /* joining a private server: with this password */
            char where[64];
            snprintf(where, sizeof where, "%s", net_join_where);
            net_join_where[0] = 0;
            if (!text[0]) return; /* (none typed: not joined) */
            snprintf(net_join_password, sizeof net_join_password, "%s", text);
            net_named(6, where); /* (then the server's page, net_goto) */
            return;
        }
        snprintf(net_server.password, sizeof net_server.password, "%s", text); /* (host) */
        net_password_apply();
        fprintf(stderr, "network: the server's password %s\n", text[0] ? "set" : "cleared");
        return;
    }
    if (kind == 8) { /* the master servers (Online Services): kept in tm2pc.ini, used from now on */
        void netplay_masters_changed(void);
        snprintf(settings_masters, sizeof settings_masters, "%s", text);
        settings_save_section("network");
        netplay_masters_changed();
        fprintf(stderr, "network: the master servers: %s\n", text[0] ? text : "the game's own");
        return;
    }
    if (kind == 7) {
        uint8_t id[MASTER_ID_BYTES];
        if (!friends_parse_code(text, id)) { net_chat_add("SERVER", "That is not a player ID (8 letters and digits)."); return; }
        friends_add(id);
        char c[10];
        friends_code(id, c);
        net_chat_add("SERVER", "Friend request sent.");
        fprintf(stderr, "network: friend request to %s\n", c);
        return;
    }
    if (kind == 4 && text[0]) {
        if (netplay_lobby()) lobby_chat(netplay_lobby(), text); /* (the lobby keeps the line: shown from it) */
        else net_chat_add(player_name(0), text);
        fprintf(stderr, "network: chat: %s\n", text);
    } else if (kind == 5 && text[0]) snprintf(net_server.name, sizeof net_server.name, "%s", text);
    else if (kind == 6 && text[0]) {
        char names[4][LOBBY_NAME];
        net_names(names);
        net_entered();
        net_server.host = 0;
        snprintf(net_server.name, sizeof net_server.name, "%s", text);
        netplay_internet(!net_lan);
        if (!netplay_join(text, play_players, (const char (*)[LOBBY_NAME])names)) {
            net_chat_add("SERVER", "That address was not found.");
            net_in_server = 0;
            net_join_password[0] = 0;
            return;
        }
        if (!net_join_password[0] && getenv("TM2PC_NET_JOIN_PASSWORD")) /* tests: the password a join types */
            snprintf(net_join_password, sizeof net_join_password, "%s", getenv("TM2PC_NET_JOIN_PASSWORD"));
        lobby_set_password(netplay_lobby(), net_join_password); /* (a private server's, typed; else none) */
        net_join_password[0] = 0;
        net_pictures();
        net_chat_add("SERVER", "Connecting...");
        net_goto = PAGE_NET_SERVER;
    }
}
static int get_net_team(int p); static int net_teams(void); static int net_launch(void); static int roster_n(void);
static int random_car_ok(int car);
static int net_room(void); static void net_balance_teams(Lobby *l); /* (below) */
typedef struct {
    int game, max_players, fixed_cpus, team_mode, bots, teams;
    MatchSetup match;
    GameType type;
    int pl_on, vote_round, vote_n, vote_winner; /* the playlist; its vote: the round, its cards, the winner (-1 not yet) */
    int vote_left;                              /* its seconds left */
    int vote_cars, vote_go;                     /* a car picked on its screen too; the host's go (the vote won, the cars
                                                 * locked or the time up): every machine on to the next match */
    NetPlEntry vote[3];
    int playing;                                /* a match on (a machine joining now plays the next one) */
    int survival_arena, survival_boss;          /* Survival's: its arena (0 random), Dark Tooth at the end */
    int tour_difficulty;                        /* Co-op Tournament's */
    int voice;                                  /* voice chat on the server */
    CustomTour vt;                              /* Versus Tournament's setup (the host's Custom Tournament page) */
    int vt_arena[TOUR_STAGES_MAX], vt_enemies[TOUR_STAGES_MAX]; /* its stages, the random ones rolled by the host */
    int countdown;                              /* the host's Start: the seconds to the match (0 none, -1 stopped) */
    int story_n;                                /* the online tournament: the story screens player 1 went on from */
    int tour_dec_n, tour_dec_level, tour_dec_kind, tour_dec; /* the online tournament: player 1's choices so far, the last
                                                   * one's level, kind (0 won, 1 lost) and choice (TOUR_DEC_*) */
    int kill_cam;                               /* the host's final kill cam for everyone: 1 + its shots (1 off, 2-4: 1-3) */
    int tour_level;                             /* Co-op Tournament: the level it starts at (a saved one's; 0 or 1: level 1) */
    int tour_custom;                            /* Co-op Tournament: a custom one (vt, vt_arena, vt_enemies its stages) */
} NetSettings;
_Static_assert(sizeof(NetSettings) <= LOBBY_SETTINGS_MAX, "the settings sent fit the lobby's");
/* the playlist's vote, over the match's end (net_vote_overlay): the host's round, its cards, the winner; every player
 * one vote (theirs in the lobby: LobbyPlayer.vote of this round), the tally from the lobby on every machine */
static int net_vote_round, net_vote_n, net_vote_winner = -1, net_vote_left, net_vote_seen;
static NetPlEntry net_vote_card[3];
static int net_vote_entry[3];       /* (host) each card's entry */
static int net_next_entry = -1;     /* (host) the playlist's match to start once back from this one */
static int net_vote_cursor[4], net_vote_mine[4]; /* this machine's players: the card each is on, each one's vote (-1) */
static int net_vote_local = 1;      /* this machine's players (each votes) */
static int net_vote_cars, net_vote_go; /* this round: a car picked too (the playlist's setting); the host's go */
static int net_vote_row[4], net_vote_lock[4]; /* this machine's players: on the cards (0) or their car (1); car locked */
enum { NET_VOTE_SECONDS = 15, NET_VOTE_CAR_SECONDS = 20 };
static int net_vote_secs(void) { return net_vote_cars ? NET_VOTE_CAR_SECONDS : NET_VOTE_SECONDS; }
/* a player's vote in the lobby (LobbyPlayer.vote, a byte): the card (-1 none), 0x40 their car locked too */
static int vote_enc(int vote, int locked) { return locked ? 0x40 | (vote < 0 ? 0x3F : vote) : vote; }
static int vote_card(int v) { return v >= 0 && (v & 0x40) ? ((v & 0x3F) == 0x3F ? -1 : v & 0x3F) : v; }
static int vote_locked(int v) { return v >= 0 && (v & 0x40); }
int mod_next_look(int number); const char *mod_car_name(int number); /* vplus/mod_cars.c */
/* the vote's car pick: player p's look (a skin of their car, else the car) */
static int vote_look(int p)
{
    return mod_is_look(net_skin[p]) && mod_car_base(net_skin[p]) == net_car[p] ? net_skin[p] : net_car[p];
}
/* the car's next (dir 1) or last (-1) look: its own, then each skin that is on here and in the server's list (every
 * machine can load it) */
static int vote_next_look(int car, int look, int dir)
{
    int looks[64], n = 0, at = 0;
    looks[n++] = car;
    for (int k = mod_next_look(car), guard = 0; k != car && mod_is_look(k) && guard < 63; k = mod_next_look(k), guard++)
        if ((lobby_mods_skin_index(k) >= 0 || k == LOOK_DT2) && n < 64) { /* (his second phase: every machine has it) */
            if (k == look) at = n;
            looks[n++] = k;
        }
    return looks[(at + dir + n) % n];
}
static int vote_has_looks(int car) { return car >= 0 && vote_next_look(car, car, 1) != car; }
/* An online tournament's choices after a level (the user's, 2026-11-05): player 1 (the host) chooses, CONTINUE / EXIT
 * won, RESTART / QUIT lost (EXIT and QUIT asked again); the others wait ("WAITING FOR ...") and follow. The host's in its
 * settings; a machine takes the one for its level and kind it has not taken yet */
enum { TOUR_DEC_CONTINUE, TOUR_DEC_EXIT, TOUR_DEC_RESTART, TOUR_DEC_QUIT };
static struct { int n, level, kind, choice; } net_tour_dec; /* (host) its last; (a machine) .n: the ones taken */
static int net_story_n, story_idx; /* (host) the story screens gone on from; (every machine) the ones come to */
static void net_send_settings(void);
void net_send_settings_now(void) { net_send_settings(); }
static void net_send_settings(void) /* (host) the game as it is now */
{
    Lobby *l = netplay_lobby();
    if (!l || !lobby_is_host(l)) return;
    NetSettings s;
    memset(&s, 0, sizeof s);
    s.game = net_server.game;
    s.max_players = net_server.max_players;
    s.fixed_cpus = net_server.fixed_cpus;
    s.team_mode = net_server.team_mode;
    s.bots = net_server.bots;
    s.teams = net_teams();
    s.match = *battle_match();
    s.type = *battle_match_type();
    s.pl_on = net_pl.on;
    s.vote_round = net_vote_round;
    s.vote_n = net_vote_n;
    s.vote_winner = net_vote_winner;
    s.vote_left = net_vote_left;
    s.vote_cars = net_vote_cars;
    s.vote_go = net_vote_go;
    memcpy(s.vote, net_vote_card, sizeof s.vote);
    s.playing = netplay_in_match();
    s.survival_arena = survival_arena;
    s.survival_boss = survival_boss_pick;
    s.tour_difficulty = net_server.tour_difficulty;
    s.voice = net_server.voice;
    s.kill_cam = 1 + (vp_value(VP_FINAL_KILL_CAM) & 3);
    s.tour_level = net_tour_load_level();
    s.countdown = net_countdown;
    s.story_n = net_story_n;
    s.tour_dec_n = net_tour_dec.n, s.tour_dec_level = net_tour_dec.level, s.tour_dec_kind = net_tour_dec.kind, s.tour_dec = net_tour_dec.choice;
    s.tour_custom = net_server.game == NET_GAME_TOURNAMENT && net_tour_custom;
    if (net_server.game == NET_GAME_VERSUS || s.tour_custom) { /* (the random ones rolled here: every machine plays the same) */
        battle_tour_versus(net_server.game == NET_GAME_VERSUS); /* (Versus: its own setup; a custom co-op tournament the
                                                                  * Custom Tournament's) */
        s.vt = *battle_tour();
        battle_tour_versus(net_hosting_versus());
        static int rolled_arena[TOUR_STAGES_MAX], rolled_enemies[TOUR_STAGES_MAX], rolled;
        if (!rolled || !netplay_in_match()) { /* (a match on: as it started) */
            for (int i = 0; i < TOUR_STAGES_MAX; i++) {
                rolled_arena[i] = s.vt.stage[i].arena ? s.vt.stage[i].arena : arena_random();
                rolled_enemies[i] = !s.tour_custom ? net_server.fixed_cpus /* (CPU only; CPU / Open added at the start: versus_begin) */
                                  : s.vt.stage[i].enemies ? s.vt.stage[i].enemies : 3 + (int)SDL_rand(5); /* (co-op: Random 3..7) */
            }
            rolled = 1;
        }
        memcpy(s.vt_arena, rolled_arena, sizeof s.vt_arena);
        memcpy(s.vt_enemies, rolled_enemies, sizeof s.vt_enemies);
    }
    lobby_set_settings(l, &s, (int)sizeof s);
    lobby_set_max_players(l, net_room()); /* (each player one of the room: a machine whose players do not fit is refused) */
    LobbyListing li; /* (what the LAN browser shows) */
    memset(&li, 0, sizeof li);
    snprintf(li.name, sizeof li.name, "%s", net_server.name);
    snprintf(li.host, sizeof li.host, "%s", player_name(0));
    snprintf(li.type, sizeof li.type, "%s", s.type.name);
    if (net_server.game == NET_GAME_TOURNAMENT) { /* (a co-op tournament: its level where the browser shows the arena) */
        int lvl = netplay_in_match() ? mem_r8(&M.cpu, GA(0x8016475Cu) + 24) : net_tour_load_level();
        snprintf(li.type, sizeof li.type, "LEVEL %d", lvl >= 1 && lvl <= 8 ? lvl : 1);
        if (s.tour_custom) snprintf(li.type, sizeof li.type, "CUSTOM, %d STAGES", s.vt.stages);
    }
    li.max = (uint8_t)net_room();
    li.game = (uint8_t)net_server.game;
    li.arena = (uint8_t)s.match.arena;
    li.mode = (uint8_t)s.type.mode;
    li.playing = (uint8_t)netplay_in_match();
    for (int i = 0; i < mods_count(); i++) { /* the server's mods: the host's skins and characters that are on (lobby_mods.c) */
        const Mod *m = mods_get(i);
        if ((m->kind != MOD_SKIN && m->kind != MOD_CHARACTER) || !mod_on(m) || li.mods == 255) continue;
        size_t at = strlen(li.mod_names), room = sizeof li.mod_names - 1 - at;
        char one[64];
        snprintf(one, sizeof one, "%s%s", li.mods ? ", " : "", m->name);
        for (char *q = one + (li.mods ? 2 : 0); *q; q++) if (*q == ',') *q = ' '; /* (commas part the names) */
        if (strlen(one) <= room && !strstr(li.mod_names, "...")) memcpy(li.mod_names + at, one, strlen(one) + 1);
        else if (!li.mods) snprintf(li.mod_names, sizeof li.mod_names, "%.44s...", one); /* (one long name: cut) */
        else if (!strstr(li.mod_names, "...") && room >= 5) memcpy(li.mod_names + at, ", ...", 6);
        li.mods++;
    }
    lobby_set_listing(l, &li);
}
/* the server as the lobby has it: the others' players, the host's game; this PC's players' choices sent; the chat; and
 * what the network says (joined, refused, the host gone, kicked). Returns a page to open, NET_REBUILD, or -1. */
static uint64_t net_test_start_at; /* (tests: TM2PC_NET_TEST_MIGRATE_START, a new host's Start) */
static int net_host_start(void);   /* (below) */
static int net_sync(void)
{
    Lobby *l = netplay_lobby();
    if (!l || !net_in_server) return -1;
    int out = -1;
    int st = lobby_status(l);
    if (st != net_status_seen) {
        static const char *const why[] = {NULL, NULL, "Another version of the game: both need the same build.",
                                          "The server is full.", "You were removed from this server.",
                                          "The server cannot be reached.", "You were removed from the server.",
                                          "Wrong password. This server is private: choose it in the server list to type its password."};
        if (st >= LOBBY_REFUSED_BUILD && why[st]) {
            const char *say = st == LOBBY_REFUSED_BUILD && update_state() == UPDATE_READY /* (updated, not restarted) */
                                  ? "The new version is in place: restart the game to play online." : why[st];
            net_chat_add("SERVER", say);
            fprintf(stderr, "network: %s\n", say);
            netplay_leave();
            net_in_server = 0;
            net_server.host = 0;
            net_status_seen = st;
            return PAGE_NET_MODE;
        }
        if (st == LOBBY_IN && net_status_seen == LOBBY_CONNECTING) {
            const LobbyView *jv = lobby_view(l);
            if (!lobby_rejoining(l)) net_starts_seen = jv->starts; /* (a match started before this machine came: not this
                                                                    * machine's; but one it is asked into, come meanwhile: its) */
            int playing = jv->settings_len == (int)sizeof(NetSettings) && ((const NetSettings *)jv->settings)->playing;
            net_chat_add("SERVER", playing ? "Joined. A match is on: you play in the next one." : "Joined.");
        }
        net_status_seen = st;
        out = NET_REBUILD;
    }
    if (!lobby_is_host(l)) { /* the server's mods: missing ones asked about, downloaded, or the server left */
        const char *why = "";
        long done = 0, total = 0;
        int ms = lobby_mods_state(&done, &total, &why);
        static int ms_seen = -1;
        static long done_seen;
        if (ms == LOBBY_MODS_FAILED) {
            char msg[200];
            snprintf(msg, sizeof msg, "Mods: %s.", why);
            net_chat_add("SERVER", msg);
            fprintf(stderr, "network: %s\n", msg);
            netplay_leave();
            net_in_server = 0;
            net_server.host = 0;
            ms_seen = -1;
            return PAGE_NET_MODE;
        }
        if (ms == LOBBY_MODS_ASK && getenv("TM2PC_NET_AUTOMODS")) { /* tests: Download, as if pressed */
            lobby_mods_download(settings_mod_download_mb > 0 ? settings_mod_download_mb * 1048576L : 0);
            ms = lobby_mods_state(&done, &total, &why);
        }
        if ((ms == LOBBY_MODS_ASK || ms == LOBBY_MODS_DOWNLOADING) && built_page != PAGE_NET_MODS) return PAGE_NET_MODS;
        if (ms == LOBBY_MODS_READY && built_page == PAGE_NET_MODS) { ms_seen = ms; return PAGE_NET_SERVER; }
        if (ms != ms_seen || (ms == LOBBY_MODS_DOWNLOADING && done - done_seen >= 65536)) {
            ms_seen = ms;
            done_seen = done;
            if (built_page == PAGE_NET_MODS) out = NET_REBUILD;
        }
    }
    const LobbyView *v = lobby_view(l);
    int me = lobby_node(l), new_host;
    static uint32_t migrated_seen;
    uint32_t migrated = lobby_migrated_at(l, &new_host);
    if (migrated && migrated != migrated_seen) { /* the host left: the machine there longest is the host now */
        migrated_seen = migrated;
        char line[64];
        if (new_host == me) snprintf(line, sizeof line, "Host dropped. You are the host now.");
        else snprintf(line, sizeof line, "Host dropped. %s is the host now.", v->m[new_host].count ? v->m[new_host].p[0].name : "Another player");
        net_chat_add("SERVER", line);
        if (lobby_is_host(l) && !net_server.host) { /* this PC: the server's game kept as it was (the playlist was the old host's) */
            static NetSettings kept;
            if (v->settings_len == (int)sizeof(NetSettings)) {
                kept = *(const NetSettings *)v->settings;
                kept.pl_on = 0;
                battle_match_override(&kept.match);
                battle_type_override(&kept.type);
                net_server.game = kept.game;
                net_server.max_players = kept.max_players;
                net_server.fixed_cpus = kept.fixed_cpus;
                net_server.bots = kept.bots;
            }
            net_server.host = 1;
            net_pl.on = 0;
            net_send_settings(); /* (its listing: the room too; a joiner's had none, "1/0" in the browsers) */
            if (getenv("TM2PC_NET_TEST_MIGRATE_START")) net_test_start_at = SDL_GetTicks() + 3000; /* tests: the new host starts */
        }
        out = NET_REBUILD;
    }
    if (lobby_is_host(l) && net_countdown) {
        int left = net_countdown < 0 ? 0 : NET_COUNTDOWN - (int)((SDL_GetTicks() - net_countdown_at) / 1000);
        if (net_countdown < 0) { net_countdown = 0; net_send_settings(); net_countdown_show(0); } /* (the stop: sent once) */
        else if (left <= 0) { /* the match */
            net_countdown = 0;
            net_countdown_show(0);
            net_send_settings();
            if (net_pl.on && net_pl.n) { /* a playlist: its first match */
                net_pl.last = net_pl.first < net_pl.n ? net_pl.first : 0;
                battle_match_override(&net_pl.e[net_pl.last].match);
                battle_type_override(&net_pl.e[net_pl.last].type);
            }
            int to = net_host_start();
            if (to != NET_LAUNCH) { battle_match_override(NULL); battle_type_override(NULL); }
            return to;
        } else if (left != net_countdown) { net_countdown = left; net_send_settings(); net_countdown_show(left); }
    }
    if (!lobby_is_host(l) && v->settings_len == (int)sizeof(NetSettings))
        net_countdown_show(((const NetSettings *)v->settings)->countdown);
    if (net_test_start_at && SDL_GetTicks() >= net_test_start_at && lobby_is_host(l)) {
        net_test_start_at = 0;
        fprintf(stderr, "network: (test) the new host starts the match\n");
        return net_host_start();
    }
    if (!lobby_is_host(l) && v->starts != net_starts_seen) { net_vote_n = 0; return net_launch(); }
    if (!lobby_is_host(l) && me >= 0 && me < SES_MAX_NODES) /* a joiner: the team the host put each player on (until one is chosen) */
        for (int p = 0; p < play_players && p < 4 && p < v->m[me].count; p++)
            if (net_team[p] < 0 && v->m[me].p[p].team >= 0) net_team[p] = v->m[me].p[p].team;
    if (lobby_is_host(l)) net_balance_teams(l);
    static int table_tick; /* (each player's button table: every machine plays them with it; now and then, it may change) */
    if (table_tick++ % 120 == 0)
        for (int p = 0; p < play_players && p < 4 && p < LOBBY_LOCAL_MAX; p++) {
            uint8_t t[128];
            humans_local_table(p, t);
            lobby_set_table(l, p, t);
        }
    if (getenv("TM2PC_NET_CAR")) { /* tests, trailer footage: this PC's players' cars ("7,3,6,11") */
        const char *q = getenv("TM2PC_NET_CAR");
        for (int p = 0; p < 4 && *q; p++) {
            if (net_car[p] < 0) net_car[p] = atoi(q);
            q += strcspn(q, ",");
            if (*q == ',') q++;
        }
    }
    for (int p = 0; p < play_players && p < 4; p++) { /* this PC's players' choices */
        int car = net_car[p], team = net_teams() ? get_net_team(p) : -1, ready = net_ready[p];
        static int test_dt2 = -1; /* tests: TM2PC_TEST_NET_DT2, a player on Dark Tooth sends his second phase */
        if (test_dt2 < 0) test_dt2 = getenv("TM2PC_TEST_NET_DT2") != NULL;
        if (test_dt2 && car == 14 && net_skin[p] < 0) net_skin[p] = LOOK_DT2;
        int skin = mod_is_look(net_skin[p]) && mod_car_base(net_skin[p]) == car ? lobby_mods_skin_index(net_skin[p]) : -1;
        if (skin != net_skin_sent[p]) { lobby_set_skin(l, p, skin); net_skin_sent[p] = skin; } /* (the server's list's index) */
        if (car != net_sent[p][0] || team != net_sent[p][1] || ready != net_sent[p][2]) {
            lobby_set_player(l, p, car, team, ready);
            net_sent[p][0] = car;
            net_sent[p][1] = team;
            net_sent[p][2] = ready;
        }
    }
    if (lobby_is_host(l)) net_send_settings();
    if (net_chat_seen < lobby_chat_first(l)) net_chat_seen = lobby_chat_first(l); /* (older ones gone) */
    for (int sp, k = net_chat_seen; ; k++) { /* the chat's new lines */
        const char *t;
        if (!lobby_chat_lines(l, k, &sp, &t)) break;
        const char *who = sp == lobby_node(l) ? player_name(0) : sp >= 0 && sp < SES_MAX_NODES && v->m[sp].count ? v->m[sp].p[0].name : "?";
        net_chat_add(who, t);
        net_chat_seen = k + 1;
        out = NET_REBUILD;
    }
    if (v->seq != net_seq_seen || (lobby_is_host(l) && out == NET_REBUILD)) { /* the lobby changed: the others' players */
        net_seq_seen = v->seq;
        net_remote_n = 0;
        net_team_used = 0;
        for (int n = 0; n < SES_MAX_NODES; n++) {
            if (!v->m[n].present || n == lobby_node(l)) continue;
            for (int i = 0; i < v->m[n].count && net_remote_n < NET_REMOTE_MAX; i++) {
                const LobbyPlayer *pl = &v->m[n].p[i];
                snprintf(net_remote[net_remote_n].name, sizeof net_remote[0].name, "%s", pl->name);
                net_remote[net_remote_n].team = pl->team;
                net_remote[net_remote_n].car = pl->car;
                net_remote[net_remote_n].host = n == lobby_host_node(l) && i == 0;
                net_remote_node[net_remote_n] = n;
                net_remote_local[net_remote_n] = i;
                if (pl->team >= 0) net_team_used |= 1u << (pl->team % BATTLE_TEAM_COLORS);
                net_remote_n++;
            }
        }
        net_server.remote = net_remote_n;
        static uint32_t logged = (uint32_t)-1;
        if (logged != v->seq) { /* (the log: who is there, their cars, teams, ready marks; each update once) */
            logged = v->seq;
            char line[512];
            int at = snprintf(line, sizeof line, "network: lobby %u:", (unsigned)v->seq);
            for (int n = 0; n < SES_MAX_NODES; n++)
                for (int i = 0; v->m[n].present && i < v->m[n].count && at < (int)sizeof line - 40; i++)
                    at += snprintf(line + at, sizeof line - (size_t)at, " [%d] %s car %d team %d%s", n, v->m[n].p[i].name,
                                   v->m[n].p[i].car, v->m[n].p[i].team, v->m[n].p[i].ready ? " ready" : "");
            fprintf(stderr, "%s\n", line);
        }
        if (!lobby_is_host(l) && v->settings_len == (int)sizeof(NetSettings)) { /* the host's game */
            const NetSettings *s = (const NetSettings *)v->settings;
            net_server.game = s->game;
            net_server.max_players = s->max_players;
            net_server.fixed_cpus = s->fixed_cpus;
            net_server.team_mode = s->team_mode;
            net_server.bots = s->bots;
            net_server.voice = s->voice;
            if (net_host_kill_cam != (s->kill_cam >= 1 && s->kill_cam <= 4 ? s->kill_cam - 1 : -1))
                fprintf(stderr, "network: the host's kill cam: %d shots\n", s->kill_cam - 1);
            net_host_kill_cam = s->kill_cam >= 1 && s->kill_cam <= 4 ? s->kill_cam - 1 : -1;
            net_server.arena = s->match.arena;
            net_server.mode = s->type.mode;
            snprintf(net_type_name, sizeof net_type_name, "%s", s->type.name);
            net_server.type = net_type_name;
            for (int k = 0; k < s->teams && k < BATTLE_TEAM_COLORS; k++) net_team_used |= 1u << k;
            net_pl.on = s->pl_on; /* (the lobby's "PLAYLIST") */
            if (getenv("TM2PC_NET_DEBUG")) fprintf(stderr, "network: settings seq %u: vote round %d n %d winner %d\n", (unsigned)v->seq,
                                                   s->vote_round, s->vote_n, s->vote_winner);

        }
        if (!lobby_is_host(l) && getenv("TM2PC_NET_DEBUG") && v->settings_len != (int)sizeof(NetSettings))
            fprintf(stderr, "network: settings of %d bytes, not %d\n", v->settings_len, (int)sizeof(NetSettings));
        if (!lobby_is_host(l)) snprintf(net_server.name, sizeof net_server.name, "%s", v->server);
        out = NET_REBUILD;
    }
    return out;
}
/* the host's Start arrived (or was given): the same match on every machine, the host's (its settings, game type, every
 * player's team), the players numbered by machine in node order, their cars the host's; on from where car select goes */
static int net_match_room, net_match_bots, net_match_fixed;
static int net_match_game; /* the match's game (NET_GAME_*): Survival starts as Survival */
static int net_match_difficulty; /* (Co-op Tournament: the host's) */
static int net_match_level = 1;   /* (Co-op Tournament: the level it starts at, a saved one's) */
static int net_tour_on;          /* a Co-op Tournament online: its levels one after another, then the lobby */
static int net_match_custom;     /* (Co-op Tournament) a custom one: the host's stages (trun, co-op rules) */
void netplay_each_battle(int on); /* net/game_tm2.c */ /* the match's: the players' room, the CPU / OPEN spots (Fill CPU cars) */
/* (net/game_tm2.c) a player left the match, `humans` players still in: was the spot they leave a CPU / OPEN one (a
 * computer car takes it over), or only OPEN (the car leaves)? */
int ui_net_fixed_cpus(void) { return net_match_fixed; } /* (net/game_tm2.c) the match's fixed computer cars (before CPU / OPEN) */
int ui_net_dropin_game(void) /* (net/game_tm2.c) a match a new player may drop into: computer cars in CPU / OPEN spots */
{
    return net_match_game == NET_GAME_CHALLENGE && !net_tour_on && net_match_bots > 0 && !getenv("TM2PC_NET_NO_DROPIN"); /* (tests: off) */
}
/* (net/game_tm2.c) a match a machine joining meanwhile comes in to watch, playing from the next one (the user's
 * 2026-11-11): a Challenge Match (its players in at the next match's start, the lobby's) */
int ui_net_watch_game(void)
{
    if (getenv("TM2PC_NET_NO_WATCH")) return 0; /* (tests: off) */
    return (net_match_game == NET_GAME_CHALLENGE && !net_tour_on) || net_match_game == NET_GAME_VERSUS;
}

void ui_net_starts_caught_up(void) { Lobby *l = netplay_lobby(); if (l) net_starts_seen = lobby_view(l)->starts; }
int ui_net_spot_cpu(int humans)
{
    return net_match_bots > 0 && net_match_room - humans <= net_match_bots;
}
static int net_launch(void)
{
    Lobby *l = netplay_lobby();
    if (!l) return -1;
    const LobbyView *v = lobby_view(l);
    const LobbyStart *s = &v->start;
    net_starts_seen = v->starts;
    static NetSettings ns;
    if (lobby_is_host(l)) {
        ns.match = *battle_match();
        ns.type = *battle_match_type();
    } else if (v->settings_len == (int)sizeof(NetSettings)) ns = *(const NetSettings *)v->settings;
    else return -1;
    for (int n = 0; n < SES_MAX_NODES; n++) /* every player's team, by human */
        for (int i = 0; s->first[n] != 0xFF && i < v->m[n].count && s->first[n] + i < 16; i++)
            ns.match.player_team[s->first[n] + i] = v->m[n].p[i].team < 0 ? 0 : v->m[n].p[i].team;
    { /* the computer cars: the lobby's (the fixed ones, then CPU / OPEN in the players' room left) */
        int host = lobby_is_host(l), game = host ? net_server.game : ns.game, fixed = host ? net_server.fixed_cpus : ns.fixed_cpus;
        net_match_game = game;
        net_match_difficulty = (host ? net_server.tour_difficulty : ns.tour_difficulty) % 3;
        net_match_level = host ? net_tour_load_level() : ns.tour_level >= 1 && ns.tour_level <= 8 ? ns.tour_level : 1;
        net_match_custom = game == NET_GAME_TOURNAMENT && (host ? net_tour_custom : ns.tour_custom);
        if (game == NET_GAME_SURVIVAL && !host) { /* (Survival: the host's arena and boss) */
            survival_arena = ns.survival_arena;
            survival_boss_pick = ns.survival_boss;
        }
        int maxp = host ? net_server.max_players : ns.max_players, bots = host ? net_server.bots : ns.bots;
        net_match_room = maxp < 16 - fixed ? maxp : 16 - fixed;
        net_match_bots = game == NET_GAME_CHALLENGE ? bots : 0; /* (versus: each stage's own computer cars) */
        net_match_fixed = game == NET_GAME_CHALLENGE || game == NET_GAME_VERSUS ? fixed : 0; /* (versus: a player joining
                                                                        * takes a CPU / Open car's place, never a CPU only one) */
        if (game == NET_GAME_CHALLENGE) {
            int fill = net_match_room - s->humans;
            ns.match.opponents = fixed + (fill < 0 ? 0 : fill > bots ? bots : fill);
        }
    }
    battle_match_override(&ns.match);
    battle_type_override(&ns.type);
    play_players = s->humans;
    for (int h = 0; h < 4; h++) /* (each human's skin: the server's list's, as this machine numbers it) */
        lobby_car[h] = h < s->humans ? s->car[h] : -1, lobby_skin[h] = h < s->humans ? lobby_mods_skin_number(s->skin[h]) : -1;
    { /* whose each human is (this machine's: its slots; the others' -1), the others' button tables */
        int8_t slots[SES_MAX_NODES];
        memset(slots, -1, sizeof slots);
        humans_clear_tables();
        int me = lobby_node(l);
        for (int n = 0; n < SES_MAX_NODES; n++)
            for (int i = 0; s->first[n] != 0xFF && i < v->m[n].count && s->first[n] + i < SES_MAX_NODES; i++) {
                int h = s->first[n] + i;
                if (n == me) slots[h] = (int8_t)i;
                /* every player's table as the lobby has it, this machine's own too: the one every other machine plays
                 * them with (built again here at the battle's start, the host's own came out as the bare layout on
                 * Roof Tops and Cyburbia: a re-sync every 8 steps, Enough Boxes / Tegu 2026-11-23); none sent yet
                 * (all zero): built here, vplus/humans.c */
                int sent = 0;
                for (int k = 0; k < 128 && !sent; k++) sent = v->m[n].p[i].table[k] != 0;
                if (sent) humans_set_table(h, v->m[n].p[i].table);
            }
        humans_set_map(s->humans, slots);
    }
    SDL_srand(s->seed); /* the match's random picks (a random arena, random opponents) the same on every machine */
    lobby_next = GA(0x80131EECu); /* as after car select: on to the opponents */
    if (!netplay_match_begin()) {
        battle_match_override(NULL);
        battle_type_override(NULL);
        net_chat_add("SERVER", "The match could not start.");
        return NET_REBUILD;
    }
    void stats_online(int on); /* profile/feats.c: this match's stats in the profiles' online ones */
    stats_online(1);
    net_send_settings(); /* (host: "a match on", for the machines joining meanwhile) */
    fprintf(stderr, "network: the match starts (%d players, %s, arena %d)\n", s->humans, ns.type.name, ns.match.arena);
    return NET_LAUNCH;
}
