static int mf_slot = -1; /* the online Options pages open (menu_fiber.c): this PC's player (slot) they belong to */
static void mf_body(void) { from_title = 0; run(PAGE_MAIN); }
static void net_pause_reopen(int slot); /* (below: the online menu again, back from the pages) */
static int mf_open(int slot) /* online, in a match: the Options pages beside the running game */
{
    if (mf_slot >= 0 || !menu_fiber_start(mf_body)) return 0;
    mf_slot = slot;
    input_set_menu_player(slot);
    fprintf(stderr, "options: open beside the match (player %d)\n", slot + 1);
    return 1;
}
static void mf_frame(void) /* each of the game's VBlanks: one of the pages' frames */
{
    extern int killcam_replaying; /* vplus/killcam.c */
    if (mf_slot < 0) return;
    if (killcam_replaying || !netplay_in_match() || !feats_in_battle()) mf_force = 1; /* (the round over: they close) */
    if (menu_fiber_resume()) { /* closed: the game's picture again, the online menu back */
        Psyz_VideoSetDisplayRGB24Fill(0);
        Psyz_VideoSetDisplayRGB24(NULL, 0, 0);
        input_set_menu_player(0);
        int slot = mf_slot;
        mf_slot = -1;
        fprintf(stderr, "options: closed (the match went on%s)\n", mf_force ? ", its round over" : "");
        if (!mf_force) net_pause_reopen(slot);
        mf_force = 0;
    }
}
/* The game's car select (one or two players in turn): each player starts on their own car. The game starts every
 * player on one remembered car (carSelectStartCar: the last CAR INFO's, else its start), so after a random car in the
 * lobby the carousel opened on Dark Tooth (the user's take 2026-11-17, 24:11). Now: the car chosen in the lobby, else
 * the roster's column of the player (Roadkill for player 1, the next for player 2), once as each turn begins (CAR INFO's
 * return keeps the car it showed). Tests keep the game's start. */
static int carsel_start_turn = -1; /* the player whose start was set (-1: none yet) */
static void carsel_start_frame(void)
{
    int vp_carousel_start(int number); /* vplus/fixes.c */
    static int off = -1; /* (tests: the game's start; cached, a per-frame path) */
    if (off < 0) off = getenv("TM2PC_CARSEL_START") != NULL, off |= (getenv("TM2PC_TEST_CARSEL_START") == NULL) << 1;
    if (ui_carsel_live() || (off & 1) || (script && (off & 2))) return;
    int p = mem_r8(&M.cpu, GA(0x8016475Cu) + 6); /* settings: the players who have picked a car */
    /* (every player has picked: the screen is only leaving, so no next turn. Moving the carousel then flashed the next
     * player's portrait over the last pick, Twister after Spectre alone: the user's 2026-11-18) */
    if (p == carsel_start_turn || p > 3 || p >= mem_r8(&M.cpu, GA(0x8016475Cu) + 4)) return;
    int car = -1;
    if (lobby_pick) car = net_carsel ? net_car[p] : (lobby_car[p] >= 0 ? (int)lobby_number(p) : -1);
    if (car < 0) car = grid_car(p);
    if (vp_carousel_start(car)) {
        carsel_start_turn = p;
        fprintf(stderr, "car select: player %d starts on %s\n", p + 1, profile_character_name(car >= 0x20 ? mod_car_base(car) : car));
    }
}

static int qp_open; /* (Escape's "Quit?", below: the overlay is its meanwhile) */
void ui_vblank(void)
{
    static int key_held;
    start_once();
    if (qp_open) return;
    if (mf_slot >= 0) { mf_frame(); scoreboard_frame(); return; } /* (the pages beside the match: theirs the buttons; nothing over them) */
    if (display_hold && M.vblanks >= display_hold_until) display_release();
    scoreboard_frame();
    if (carsel_active) carsel_start_frame();
    if (carsel_active)
        carsel_overlay(0);
    if (carsel_active && turntable_on() && !ui_carsel_live()) turntable_vblank();
    if (carsel_active && !ui_carsel_live() && !carsel_info) { /* the game's car select: Select, the car's next skin */
        static int select_held;
        int sel = M.ram && (!(M.pad_buttons[0] & 1) || !(M.pad_buttons[1] & 1)); /* (the pads as the game reads them) */
        if (sel && !select_held && vp_carousel_select()) {
            menu_sound(0);
            carsel_overlay(1);
        }
        select_held = sel;
    }
    if ((!M.live_input && !script) || in_pause)
        return;
    int key;
    menu_input(&key);
    if (key && !key_held) {
        load_art();
        if (text_ready() && netplay_in_match() && feats_in_battle()) { /* online: the match goes on (nobody pauses everyone) */
            key_held = 1;
            mf_open(0);
        } else if (text_ready()) {
            from_title = 0;
            run(PAGE_MAIN); /* returns once every button and the key are released */
        } else {
            key_held = 1;
        }
        return;
    }
    key_held = key;
}

/* ---- the title screen ----
 * The game's title (8012DF84, decomp shell_screens2.c) shows three 3D menu
 * items over the logo: 1 Player, 2 Player, Options. The port draws its own
 * at the window's resolution, as the Options pages: the PC version's title
 * picture and LOCAL PLAY, NETWORK PLAY, OPTIONS in the menu lettering, the
 * copper bar behind the chosen one. Around it the game's own steps are kept:
 * its music starts the same way, and picking an item starts the submenus'
 * music loop (sound 27: sample EF4C on two voices) and stops the music. The
 * select explosion, which the game's menu machinery plays, is the pages' own
 * (menu_sound). The game keys sounds on and off at its VBlank, which these
 * screens hold back, so the title runs two first: without them the loop
 * stopped on returning from Options went on under the title song. Left alone, the game goes to the attract
 * demo (8012DE3C) after 2020 VBlanks; here it waits for the title music to
 * end instead (the song plays out, then the demo starts), or 60 seconds
 * without music. A press during the song gives it another play. */
#define LOCAL_PLAY_SCREEN GA(0x8012E908u)
#define NETWORK_PLAY_SCREEN GA(0x8012F5F8u)
#define OPTIONS_SCREEN GA(0x80133C08u)
#define ATTRACT_SCREEN GA(0x8012DE3Cu)
#define TITLE_IDLE_VBLANKS 3600 /* without music */
#define MUSIC_OBJECT GA(0x80180BCCu)       /* the music object (D_80180BCC) */
#define VOL_SERIAL GA(0x80180E0Cu)         /* CD (serial) volume */
#define VOL_SFX GA(0x80180E18u)
#define VOL_MAX GA(0x80180E24u)
#define VOL_MIN GA(0x80180E28u)

static void music_call(int slot, uint32_t arg) /* the music object's virtual slot */
{
    uint32_t obj = mem_r32(&M.cpu, MUSIC_OBJECT), vt = mem_r32(&M.cpu, obj + 8);
    int16_t delta = (int16_t)mem_r16(&M.cpu, vt + (uint32_t)slot * 8);
    guest_call(mem_r32(&M.cpu, vt + (uint32_t)slot * 8 + 4), obj + (uint32_t)(int32_t)delta, arg, 0, 0);
}

static int32_t clamp_volume(int32_t v)
{
    int32_t hi = (int32_t)mem_r32(&M.cpu, VOL_MAX), lo = (int32_t)mem_r32(&M.cpu, VOL_MIN);
    (void)hi; /* as the game: the upper clamp is overwritten by the lower one */
    return v < lo ? lo : v;
}

/* The menus' music (sound 27, the submenus' loop, at the music's volume): the port's alone. Started once as the menus
 * open (from the title, back from a match or a movie) and looped through every menu, car select too; stopped only as a
 * match loads, a movie plays or the title shows. The game's own starts and stops of it are ignored while the port's
 * plays (vplus/fixes.c, soundPlay / soundStop: ui_menu_music_keeps): car select started a copy of its own (two at once:
 * out of step) or none (1 player: silence), and every way into a menu stopped and started it its own way. */
static int menu_music;     /* the port's copy is playing */
static int menu_music_own; /* the port's own calls (not ignored) */
extern int spu_keyon_record; /* runtime/hw.c: the voices keyed on, noted in spu_keyed */
extern uint64_t spu_keyed;
static uint16_t menu_music_sample[8]; /* the song's samples (a voice's +6), from its start */
static int menu_music_samples;
static uint32_t music_voice_reg(int v) { return v < 24 ? 0x1F801C00u + 16u * (uint32_t)v : 0x1F802C00u + 16u * (uint32_t)(v - 24); }
int ui_menu_music_keeps(int code, int start) /* fixes.c: the game's soundPlay (start 1) / soundStop of `code`: ignored */
{
    if (code != 27 || menu_music_own) return 0;
    if (start && !menu_music) { menu_music = 1; return 0; } /* (the game's way into a menu the port does not see: its copy is the one) */
    return menu_music;
}
static void menu_loop_start(void)
{
    if (menu_music) return; /* (one copy: already on) */
    menu_music_own = 1;
    uint32_t saved = mem_r32(&M.cpu, VOL_SFX);
    guest_call(GA(0x800D3464u), 27, 0, 0, 0); /* one loop only: a copy still playing would play out of step (louder or quieter) */
    guest_call(GA(0x800D34C0u), 0, 0, 0, 0);
    mem_w32(&M.cpu, VOL_SFX, (uint32_t)clamp_volume((int32_t)guest_call(GA(0x800D362Cu), 0, 0, 0, 0)));
    spu_keyed = 0;
    spu_keyon_record = 1;
    guest_call(GA(0x800D3334u), 27, 0, 0, 99);
    guest_call(GA(0x800D34C0u), 0, 0, 0, 0);
    guest_call(GA(0x800D34E8u), 0, 0, 0, 0);
    spu_keyon_record = 0;
    for (int v = 0; v < 48; v++) /* (its samples: is it still sounding, below) */
        if ((spu_keyed >> v) & 1) {
            uint16_t sm = (uint16_t)rc_io_read(&M.cpu, music_voice_reg(v) + 6, 2);
            int known = 0;
            for (int i = 0; i < menu_music_samples; i++) known |= menu_music_sample[i] == sm;
            if (!known && menu_music_samples < 8) menu_music_sample[menu_music_samples++] = sm;
        }
    mem_w32(&M.cpu, VOL_SFX, (uint32_t)clamp_volume((int32_t)saved));
    menu_music_own = 0;
    menu_music = 1;
}
/* Each VBlank (vplus/fixes.c): the menus' song is on, but none of its voices sounds for half a second (the game's
 * car select silences the voices as it opens, 1 player): started again */
void ui_menu_music_vblank(void)
{
    static int quiet;
    if (!menu_music || menu_music_own || !menu_music_samples) { quiet = 0; return; }
    for (int v = 0; v < 48; v++) {
        uint16_t sm = (uint16_t)rc_io_read(&M.cpu, music_voice_reg(v) + 6, 2);
        for (int i = 0; i < menu_music_samples; i++)
            if (sm == menu_music_sample[i] && (rc_io_read(&M.cpu, music_voice_reg(v) + 0xC, 2) & 0xFFFF)) { quiet = 0; return; }
    }
    if (++quiet < 30) return;
    quiet = 0;
    fprintf(stderr, "menu music: silent, started again\n");
    menu_music = 0;
    menu_loop_start();
}

static void menu_loop_stop_all(int wait) /* every copy of the menus' loop: a match, a movie, the title */
{
    menu_music_own = 1;
    for (int i = 0; i < 4; i++) {
        guest_call(GA(0x800D3464u), 27, 0, 0, 0);
        guest_call(GA(0x800D34C0u), 0, 0, 0, 0);
        guest_call(GA(0x800D34E8u), 0, 0, 0, 0);
    }
    menu_music_own = 0;
    menu_music = 0;
    if (wait) rt_vblank(); /* (the stops take effect at the game's VBlank) */
}
static void set_serial_volume(int32_t v)
{
    v = clamp_volume(v);
    mem_w32(&M.cpu, VOL_SERIAL, (uint32_t)v);
    guest_call(GA(0x80145F8Cu), 0, (uint32_t)(int16_t)v, (uint32_t)(int16_t)v, 0); /* SsSetSerialVol */
}

static const char *const title_items[3] = {"LOCAL PLAY", "NETWORK PLAY", "OPTIONS"};
static const int title_x[3] = {112, 320, 528}; /* centers, on the 640x480 screen */
enum { TITLE_MENU_Y = 404, TITLE_ITEM_SIZE = 20 };

/* Sweet Tooth's hair: 19 frames of 128x128 in ui/hair.bmp, one per game
 * frame (30 a second); placed over the hair painted into the title picture
 * (found by matching: 1.18 times their size, at 259, 210 on the 640x480
 * screen). */
#define HAIR_FRAMES 19
enum { HAIR_X = 259, HAIR_Y = 210, HAIR_SIZE = 151 };

static void compose_title_base(Image *c, int sel);
static void draw_title_hair(Image *c, int hair_frame);

static void compose_title(Image *c, int sel, int hair_frame)
{
    /* the picture and the menu are drawn once per choice and size; the
     * hair over them for each of its frames */
    static Image base;
    static int base_sel = -1;
    if (base.w != c->w || base.h != c->h || base_sel != sel) {
        if (!image_resize(&base, c->w, c->h))
            return;
        compose_title_base(&base, sel);
        base_sel = sel;
    }
    memcpy(c->px, base.px, (size_t)c->w * c->h * 3);
    draw_title_hair(c, hair_frame);
}

static void draw_title_hair(Image *c, int hair_frame)
{
    if (hair.px && hair.w >= hair.h * HAIR_FRAMES) {
        View v = view_fit(c);
        static const uint8_t key[3] = {255, 0, 255};
        int f = hair_frame % HAIR_FRAMES, fw = hair.w / HAIR_FRAMES;
        draw_image_keyed(c, &hair, (float)(f * fw), 0, (float)fw, (float)hair.h,
                         X(&v, HAIR_X), Y(&v, HAIR_Y), S(&v, HAIR_SIZE), S(&v, HAIR_SIZE), key);
    }
}

static void compose_title_base(Image *c, int sel)
{
    View v = view_fit(c);
    int cw = (int)(640 * v.s + 0.5f);
    lettering();
    /* the picture scaled once per size (at 4K its scaling took 140 ms: each move of the cursor froze the hair), the
     * menu on a copy of it; the title's picture is on near-black: the sides take its edge color */
    static Image pic;
    static const uint8_t *pic_of;
    if (pic.w != c->w || pic.h != c->h || pic_of != bg_title.px) {
        if (!image_resize(&pic, c->w, c->h)) return;
        pic_of = bg_title.px;
        memset(pic.px, 0, (size_t)pic.w * pic.h * 3);
        if (bg_title.px) {
            unsigned sum[3] = {0, 0, 0};
            for (int y = 0; y < bg_title.h; y++)
                for (int k = 0; k < 3; k++)
                    sum[k] += bg_title.px[(size_t)y * bg_title.w * 3 + k] + bg_title.px[((size_t)y * bg_title.w + bg_title.w - 1) * 3 + k];
            uint8_t edge[3];
            for (int k = 0; k < 3; k++) edge[k] = (uint8_t)(sum[k] / (2u * (unsigned)bg_title.h));
            draw_fill(&pic, 0, 0, pic.w, pic.h, edge, 255);
            draw_image(&pic, &bg_title, 0, 0, (float)bg_title.w, (float)bg_title.h, v.ox, v.oy, cw, S(&v, 480), 0);
        }
    }
    memcpy(c->px, pic.px, (size_t)c->w * c->h * 3);
    int size = S(&v, TITLE_ITEM_SIZE), cy = Y(&v, TITLE_MENU_Y);
    for (int i = 0; i < 3 && sel >= 0; i++) {
        int w = text_width(title_items[i], size), x = X(&v, title_x[i]) - w / 2;
        int lift = i == sel ? S(&v, 3) : 0; /* the chosen item rises a little, as the game's bob */
        if (i == sel)
            draw_bar(&v, x - S(&v, 12), x + w + S(&v, 12), cy - lift, size);
        text_draw(c, title_items[i], x, text_top_for_center(cy - lift, size), size, WHITE);
    }
}

/* ---- Local Play (docs/MENUS_PLAN.md) ----
 * How many players, then the 1 Player menu (Tournament, Challenge Match) and
 * Tournament (New; Load and Custom to come), as the port's pages, while the
 * submenus' music loop plays. They end as the game's 1 Player menu (8012E908,
 * decomp screen_single.c) does: its settings for the mode, then car select
 * (801307EC) for a tournament, level select (8012FD30) for a challenge.
 * 2 Players goes to the game's 2 Player menu for now; O on the first page
 * back to the title. */
void F_8012E908_orig(CPU *c);

/* The game's 1 Player menu (8012E908), wrapped: with Passwords off, the
 * port's pages instead, from the title or back from car or level select. */
void ui_OnePlayerMenu(CPU *c);

#define CAR_SELECT_SCREEN GA(0x801307ECu)
#define LEVEL_SELECT_SCREEN GA(0x8012FD30u)
#define TITLE_SCREEN_FN GA(0x8012DF84u)

/* ---- 2 players: split-screen sign-in (docs/MENUS_PLAN.md) ----
 * Each half is a player's, laid out as the profile screen: PLAYER n, the
 * profiles (and New Profile, and for player 2 Guest) on the left, the chosen
 * one's portrait on the right. Each is read from their own controller (player
 * 1 also from the keyboard). X signs in and readies; O un-readies, or
 * (player 1) goes back, or (player 2) leaves. New Profile opens the letter
 * grid on that half: both can name at once (the keyboard types for player 1
 * only). Player 2 joins with Start on a second controller. When both are
 * ready, X or Start goes on; Square opens Controls for the two (each saved
 * to their own profile). A profile can be only one player's. */
enum { SIGNIN_NEW = -1, SIGNIN_GUEST = -2 };
static struct {
    int joined, ready, sel;
    char name[64];       /* ready as: a profile's name, or "" for guest */
    uint16_t prev;
    int held_for[2];
    Naming nm;           /* entering a new profile's name on this half */
    int mode, msel, gsel, gtop; /* the profile's options (SP_MENU), its portrait grid, deleting */
    unsigned char unl[512], hid[512]; /* the profile's pictures: unlocked, hidden (read when its grid opens) */
    int pic;                          /* its picture */
    char edit[64];       /* the profile being changed */
    uint64_t held_since; /* deleting: X held since (ms), 0 not held */
} sp[4];
static int sp_n = 2;          /* players signing in: 2, or the 3 and 4 Players menus' */

/* A half's profile options (Square on a profile), as the profile page:
 * PORTRAIT (the portrait grid, in the half), RENAME (the letter grid),
 * DELETE (X held 3.5 s), DONE. Both halves can change a profile at once:
 * the profile's unlocks are read when its grid opens (it is signed in for
 * that moment), and each change signs it in only while it is made. */
enum { SP_LIST, SP_MENU, SP_GRID, SP_DELETE };
static const char *const sp_menu_items[4] = {"PORTRAIT", "RENAME", "DELETE", "DONE"};
static char signin_home[64]; /* player 1's profile when the sign-in opened (signed in again after a change) */
static int sp_pics[512], sp_npics; /* the pictures in the grid's order */
enum { SP_COLS = 7, SP_ROWS = 3 }; /* half the portrait page's 14: the drivers' columns kept */

static int sp_list_picture(const char *who)
{
    for (int i = 0; i < profile_count(); i++)
        if (!SDL_strcasecmp(profile_list_name(i), who)) return profile_list_picture(i);
    return 0;
}
static void sp_edit_begin(int p, const char *who)
{
    snprintf(sp[p].edit, sizeof sp[p].edit, "%s", who);
    sp[p].pic = sp_list_picture(who);
}
static void sp_edit_end(void) { profile_rescan(); }
/* the profile's unlocks, for its grid: it is signed in to read them, then player 1's again */
static void sp_read_unlocks(int p)
{
    const char *who = sp[p].edit;
    int other = !profile_signed_in() || SDL_strcasecmp(profile_name(), who);
    if (other) profile_use(who);
    for (int i = 0; i < sp_npics; i++) {
        sp[p].unl[i] = (unsigned char)profile_picture_unlocked(sp_pics[i]);
        sp[p].hid[i] = (unsigned char)profile_picture_hidden(sp_pics[i]);
    }
    if (other && signin_home[0] && profile_exists(signin_home)) profile_use(signin_home);
}
static void sp_build_pics(void)
{
    build_grid();
    sp_npics = 0;
    for (int r = 0; r < grid_rows; r++)
        for (int c = 0; c < grid_len[r] && sp_npics < (int)(sizeof sp_pics / sizeof sp_pics[0]); c++)
            sp_pics[sp_npics++] = grid[r][c];
}

static int signin_items(int p) { return profile_count() + 1 + (p >= 1); }
static int signin_item(int p, int i) /* the profiles, Guest (players 2-4), New Profile */
{
    if (i < profile_count()) return i;
    return p >= 1 && i == profile_count() ? SIGNIN_GUEST : SIGNIN_NEW;
}
static int signin_taken(int p, int i) /* another player is ready as this profile */
{
    for (int o = 0; o < sp_n && o < 4; o++)
        if (o != p && i >= 0 && sp[o].ready && sp[o].name[0] && !SDL_strcasecmp(sp[o].name, profile_list_name(i))) return 1;
    return 0;
}
static int signin_min = 2; /* players needed (Network Play: one) */
static int signin_all_ready(void) /* two or more in (Network Play: one or more), all of them ready */
{
    int in = 0;
    for (int p = 0; p < sp_n && p < 4; p++) {
        if (!sp[p].joined) continue;
        if (!sp[p].ready) return 0;
        in++;
    }
    return in >= signin_min;
}

/* the letter grid inside a half (hx..hx+hw on the 640 screen) */
static void draw_naming_half(const View *v, const Naming *nm, int hx, int hw)
{
    static const uint8_t black[3] = {0, 0, 0}, line[3] = {188, 188, 196};
    int cw = (hw - 20) / NAME_GRID_COLS, size = S(v, 15), gx = hx + 10;
    int bx = X(v, gx), by = Y(v, 74), bw = S(v, cw * NAME_GRID_COLS), bh = S(v, 26);
    int t = S(v, 1.5f) > 1 ? S(v, 1.5f) : 1;
    draw_fill(v->c, bx, by, bw, bh, black, 200);
    draw_fill(v->c, bx, by + bh - t, bw, t, line, 255);
    char shown[sizeof nm->text + 2];
    snprintf(shown, sizeof shown, "%s%s", nm->text, strlen(nm->text) < PROFILE_NAME_MAX ? "_" : "");
    text_draw(v->c, shown, bx + S(v, 8), text_top_for_center(by + bh / 2, S(v, 18)), S(v, 18), WHITE);
    for (int r = 0; r < NAME_GRID_ROWS; r++) {
        int cy = Y(v, 124 + r * 30);
        if (r < NAME_GRID_ROWS - 1) {
            for (int c = 0; c < NAME_GRID_COLS; c++) {
                char ch[8] = {name_grid[r][c], 0};
                if (isalpha((unsigned char)ch[0]) && !nm->caps) ch[0] = (char)tolower((unsigned char)ch[0]);
                if (ch[0] == ' ') snprintf(ch, sizeof ch, "SP");
                int cx = X(v, gx + c * cw + cw / 2), w = text_width(ch, size);
                if (r == nm->row && c == nm->col)
                    draw_bar(v, cx - S(v, cw / 2 - 2), cx + S(v, cw / 2 - 2), cy, size);
                text_draw(v->c, ch, cx - w / 2, text_top_for_center(cy, size), size, WHITE);
            }
        } else {
            static const int spans[3][2] = {{0, 3}, {3, 6}, {6, 10}};
            for (int k = 0; k < 3; k++) {
                int ks = S(v, 13), w = text_width(name_keys[k], ks);
                int cx = X(v, gx + (spans[k][0] + spans[k][1]) * cw / 2);
                if (r == nm->row && name_key_at(nm->col) == k)
                    draw_bar(v, cx - w / 2 - S(v, 6), cx + w / 2 + S(v, 6), cy, ks);
                text_draw(v->c, name_keys[k], cx - w / 2, text_top_for_center(cy, ks), ks,
                          k == 0 && nm->caps ? ORANGE : WHITE);
            }
        }
    }
    if (nm->message) {
        int ms = S(v, 13);
        text_draw(v->c, nm->message, X(v, gx), Y(v, 290), ms, ORANGE);
    }
}

static void compose_signin(Image *c)
{
    static const uint8_t black[3] = {0, 0, 0}, line[3] = {188, 188, 196}, frame[3] = {188, 188, 196};
    View v = view_fit(c);
    int cw = (int)(640 * v.s + 0.5f);
    lettering();
    /* the glass, its sides and seams: made once per size and sides (a move redrew it all, 48 ms at 2000x1124: the
     * portrait grid's cursor slow and quick presses missed, the user's 2026-10-31) */
    static Image base;
    static int base_sides = -1;
    if (base_sides != settings_video.menu_sides || base.w != c->w || base.h != c->h) {
        if (!image_resize(&base, c->w, c->h)) return;
        View bv = v;
        bv.c = &base;
        memset(base.px, 0, (size_t)base.w * base.h * 3);
        draw_sides(&bv, &bg_glass);
        if (bg_glass.px)
            draw_image(&base, &bg_glass, 0, 0, (float)bg_glass.w, (float)bg_glass.h, v.ox, v.oy, cw, S(&v, 480), 0);
        extend_sides(&bv);
        base_sides = settings_video.menu_sides;
    }
    memcpy(c->px, base.px, (size_t)c->w * c->h * 3);
    int lw = S(&v, 2) > 1 ? S(&v, 2) : 1;
    int wide = sp_n <= 2 && v.ox > S(&v, 40) && (settings_video.menu_sides == 0 || settings_video.menu_sides == 1);
    if (wide) /* the window split down the middle */
        draw_fill(c, c->w / 2 - lw / 2, Y(&v, 20), lw, Y(&v, 400) - Y(&v, 20), line, 255);
    for (int p = 0; p < sp_n && p < 4; p++) {
        int hx = p * 320; /* the half's left, on the 640 screen */
        View hv = v;      /* the half's view: wide, centered in its half of the window */
        View hr, hcv; /* the panel's right (the portrait) and centered views: the same as hv for 2 players */
        if (sp_n > 2) { /* the cells fill the screen: quarters (3: player 1 the whole top row); the panel's
                         * contents at half size, the list at the cell's left, the portrait at its right */
            int q = sp_n == 3 ? (p == 0 ? -1 : p + 1) : p;
            float x0u = q < 0 ? 8 : (q & 1) ? 323 : 8, x1u = q < 0 ? 632 : (q & 1) ? 632 : 317;
            float y0u = (q >= 0 && (q & 2)) ? 205 : 10, y1u = y0u + 191;
            hx = 0;
            hv.s = v.s * 0.5f;
            /* a quarter: the list from 18% in, the portrait's middle at 70%: the two together, centered, the longest
             * names still whole (the list's middle at a third cut "SCOTT CAMPB..."; from 7% with the portrait at 5/6 the
             * gap between them looked odd: the user's, 2026-11-04); player 1's whole top row (3 players) as before */
            hv.ox = q < 0 ? X(&v, x0u + (x1u - x0u) / 3) - (int)(95 * hv.s + 0.5f) : X(&v, x0u + (x1u - x0u) * 0.18f) - (int)(18 * hv.s + 0.5f);
            hv.oy = Y(&v, y0u) - (int)(18 * hv.s + 0.5f);
            hr = hv;
            hr.ox = X(&v, x0u + (x1u - x0u) * (q < 0 ? 2.0f / 3 : 0.70f)) - (int)(254 * hv.s + 0.5f); /* the portrait's middle */
            hcv = hv;
            hcv.ox = X(&v, (x0u + x1u) / 2) - (int)(160 * hv.s + 0.5f);
            int x0 = X(&v, x0u), x1 = X(&v, x1u), y0 = Y(&v, y0u), y1 = Y(&v, y1u);
            draw_fill(c, x0, y0, x1 - x0, lw, line, 255);
            draw_fill(c, x0, y1 - lw, x1 - x0, lw, line, 255);
            draw_fill(c, x0, y0, lw, y1 - y0, line, 255);
            draw_fill(c, x1 - lw, y0, lw, y1 - y0, line, 255);
        } else if (wide) hv.ox = (c->w / 4) * (1 + 2 * p) - (int)((hx + 160) * v.s + 0.5f);
        else { /* each player's area framed */
            int x0 = X(&v, hx + 8), x1 = X(&v, hx + 312), y0 = Y(&v, 18), y1 = Y(&v, 398);
            draw_fill(c, x0, y0, x1 - x0, lw, line, 255);
            draw_fill(c, x0, y1 - lw, x1 - x0, lw, line, 255);
            draw_fill(c, x0, y0, lw, y1 - y0, line, 255);
            draw_fill(c, x1 - lw, y0, lw, y1 - y0, line, 255);
        }
        if (sp_n <= 2) hr = hcv = hv;
        const View *hp = &hv, *hpr = &hr, *hpc = &hcv;
        char title[16];
        snprintf(title, sizeof title, "PLAYER %d", p + 1);
        int ts = S(hp, 26);
        text_draw(c, title, X(hpc, hx + 160) - text_width(title, ts) / 2, Y(hpc, 28), ts, TITLE);
        if (!sp[p].joined) {
            const char *a = "PRESS START TO JOIN", *b2 = "";
            int s1 = S(hp, sp_n > 2 ? 32 : 22), s2 = S(hp, sp_n > 2 ? 20 : 14);
            text_draw(c, a, X(hpc, hx + 160) - text_width(a, s1) / 2, text_top_for_center(Y(hpc, 200), s1), s1, ORANGE);
            text_draw(c, b2, X(hpc, hx + 160) - text_width(b2, s2) / 2, text_top_for_center(Y(hpc, 230), s2), s2, WHITE);
            continue;
        }
        if (sp[p].nm.active) {
            draw_naming_half(hpc, &sp[p].nm, hx + 10, 300);
            continue;
        }
        if (sp[p].mode == SP_GRID) { /* the portrait grid, in the half */
            hp = hpc;
            int tw = 36, th = 72, pitch_x = 41, pitch_y = 86, gx = hx + 160 - (SP_COLS * pitch_x - 5) / 2;
            for (int r = 0; r < SP_ROWS; r++)
                for (int k = 0; k < SP_COLS; k++) {
                    int i = (sp[p].gtop + r) * SP_COLS + k;
                    if (i >= sp_npics) break;
                    int x = X(hp, gx + k * pitch_x), y = Y(hp, 70 + r * pitch_y), w = S(hp, tw), h = S(hp, th);
                    int t = i == sp[p].gsel ? S(hp, 3) : (S(hp, 1) > 1 ? S(hp, 1) : 1);
                    static const uint8_t copper[3] = {238, 164, 74}, gray[3] = {70, 70, 76};
                    draw_fill(c, x - t, y - t, w + 2 * t, h + 2 * t, i == sp[p].gsel ? copper : gray, 255);
                    if (sp[p].hid[i]) {
                        int qs = h / 3;
                        draw_fill(c, x, y, w, h, black, 255);
                        text_draw(c, "?", x + w / 2 - text_width("?", qs) / 2, text_top_for_center(y + h / 2, qs), qs, GRAY);
                    } else {
                        draw_portrait_image(hp, sp_pics[i], x, y, w, h);
                        if (!sp[p].unl[i]) draw_fill(c, x, y, w, h, black, 150);
                    }
                }
            int pic = sp_pics[sp[p].gsel], cs = S(hp, 14);
            char cap[48], fit[48];
            portrait_caption(cap, sizeof cap, pic); /* as on the profile's own portrait screen: a secret "???", else its name */
            fit_text(fit, sizeof fit, cap, S(hp, 290), cs);
            text_draw(c, fit, X(hp, hx + 160) - text_width(fit, cs) / 2, Y(hp, 350), cs, WHITE);
            { /* how it is earned, locked or not (an ending's still too, as on the profile's own portrait screen) */
                char how[128], *nl;
                snprintf(how, sizeof how, "%s", profile_picture_how(pic));
                if ((nl = strchr(how, '\n'))) *nl = ' ';
                int hs = S(hp, 12);
                fit_text(fit, sizeof fit, how, S(hp, 290), hs);
                text_draw(c, fit, X(hp, hx + 160) - text_width(fit, hs) / 2, Y(hp, 372), hs, GRAY);
            }
            continue;
        }
        if (sp[p].mode == SP_MENU || sp[p].mode == SP_DELETE) { /* the profile's options */
            char nm[64];
            snprintf(nm, sizeof nm, "%s", sp[p].edit);
            for (char *q = nm; *q; q++) *q = (char)toupper((unsigned char)*q);
            int big = sp_n > 2; /* the quarters: the list's bigger letters (Portrait, Rename... as big as the names) */
            int size = S(hp, big ? 24 : 17), lx = X(hp, hx + 18), pitch = big ? 34 : 28;
            text_draw(c, nm, lx, text_top_for_center(Y(hp, 92), size), size, ORANGE);
            for (int i = 0; i < 4; i++) {
                int cy = Y(hp, 134 + i * pitch);
                if (i == sp[p].msel) draw_bar(hp, X(hp, hx + 12), lx + text_width(sp_menu_items[i], size) + S(hp, 10), cy, size);
                text_draw(c, sp_menu_items[i], lx, text_top_for_center(cy, size), size, WHITE);
            }
            /* (the quarters: as tall as the list's seven rows, the user's) */
            int pw = S(hpr, sp_n > 2 ? 114 : 96), ph = 2 * pw, px = X(hpr, hx + 206), py = Y(hpr, 80), t = S(hp, 1.5f) > 1 ? S(hp, 1.5f) : 1;
            draw_fill(c, px - t, py - t, pw + 2 * t, ph + 2 * t, frame, 255);
            draw_portrait_image(hpr, sp[p].pic, px, py, pw, ph);
            if (sp[p].mode == SP_DELETE) {
                static const uint8_t red[3] = {200, 40, 30}, dark[3] = {40, 40, 46};
                const char *hold = "HOLD X TO DELETE";
                int hs = S(hpc, 16), by = Y(hpc, 330), bw = S(hpc, 260), bx = X(hpc, hx + 30), bh = S(hpc, 10);
                uint64_t ms = sp[p].held_since ? SDL_GetTicks() - sp[p].held_since : 0;
                text_draw(c, hold, X(hpc, hx + 160) - text_width(hold, hs) / 2, Y(hpc, 296), hs, ORANGE);
                draw_fill(c, bx, by, bw, bh, dark, 255);
                draw_fill(c, bx, by, (int)(bw * (ms < DELETE_HOLD ? ms : DELETE_HOLD) / DELETE_HOLD), bh, red, 255);
            }
            continue;
        }
        /* the list, on the left: a name as wide as the room to the portrait, its letters smaller (to 3/4) before it is cut */
        int big = sp_n > 2; /* the quarters: bigger letters, fewer rows (it scrolls) */
        int room = X(hpr, hx + 206) - X(hp, hx + 18) - S(hp, 14);
        if (room < S(hp, big ? 190 : 160)) room = S(hp, big ? 190 : 160);
        int n = signin_items(p), size = S(hp, big ? 24 : 17), pitch = big ? 34 : 28, rows_shown = big ? 7 : 9;
        int first = sp[p].sel - (rows_shown - 2), last_first = n - rows_shown < 0 ? 0 : n - rows_shown;
        if (first > last_first) first = last_first; /* only as far as the list needs */
        if (first < 0) first = 0;
        for (int i = first; i < n && i < first + rows_shown; i++) {
            int it = signin_item(p, i), cy = Y(hp, 92 + (i - first) * pitch);
            char label[64];
            snprintf(label, sizeof label, "%s", it >= 0 ? profile_list_name(it) : it == SIGNIN_NEW ? "NEW PROFILE" : "GUEST");
            for (char *q = label; *q; q++) *q = (char)toupper((unsigned char)*q);
            char fit[64];
            int ls = size, wl = text_width(label, size);
            if (wl > room) ls = wl * 3 > room * 4 ? size * 3 / 4 : size * room / wl;
            fit_text(fit, sizeof fit, label, room, ls);
            int lx = X(hp, hx + 18);
            if (i == sp[p].sel) /* the chosen one on the copper bar (orange once ready), clear of the frame */
                draw_bar(hp, X(hp, hx + 12), lx + text_width(fit, ls) + S(hp, 10), cy, size);
            text_draw(c, fit, lx, text_top_for_center(cy, ls), ls,
                      signin_taken(p, it) ? GRAY : sp[p].ready && i == sp[p].sel ? ORANGE : WHITE);
        }
        /* the portrait, on the right */
        int item = signin_item(p, sp[p].sel), pic = item >= 0 ? profile_list_picture(item) : -1;
        /* (the quarters: as tall as the list's seven rows, the user's) */
        int pw = S(hpr, sp_n > 2 ? 114 : 96), ph = 2 * pw, px = X(hpr, hx + 206), py = Y(hpr, 80), t = S(hp, 1.5f) > 1 ? S(hp, 1.5f) : 1;
        draw_fill(c, px - t, py - t, pw + 2 * t, ph + 2 * t, frame, 255);
        if (pic >= 0) {
            draw_portrait_image(hpr, pic, px, py, pw, ph);
        } else {
            draw_fill(c, px, py, pw, ph, black, 255);
            const char *q = item == SIGNIN_NEW ? "+" : "?";
            int qs = S(hp, 40);
            text_draw(c, q, px + pw / 2 - text_width(q, qs) / 2, text_top_for_center(py + ph / 2, qs), qs, GRAY);
        }
        if (sp[p].ready) {
            const char *r = "READY";
            int rs = S(hpc, 28), cy = Y(hpc, 340);
            draw_fill(c, X(hpc, hx + 20), cy - S(hpc, 20), S(hpc, 280), S(hpc, 40), black, 170);
            text_draw(c, r, X(hpc, hx + 160) - text_width(r, rs) / 2, text_top_for_center(cy, rs), rs, ORANGE);
        }
    }
    int both = signin_all_ready();
    int in = 0;
    for (int p = 0; p < sp_n && p < 4; p++) in += sp[p].joined;
    if (sp_n <= 2) /* (Multiplayer: the panels say it) */
        draw_description(&v, both ? "Everyone's ready: player 1, Start to go on."
                         : in < 2 ? "Players 2 to 4: press Start on your controller to join."
                                  : "Each player: X to sign in and get ready.");
    static const char *const legend[] = {CROSS " = READY", SQUARE " = PROFILE", CIRCLE " = BACK"};
    static const char *const legend_both[] = {"START = PLAY", SQUARE " = CONTROLS", CIRCLE " = BACK"};
    draw_legend(&v, both ? legend_both : legend, 3);
}

/* A player's buttons: theirs, or in tests TM2PC_UI_SCRIPT (player 1) and
 * TM2PC_P2_SCRIPT (player 2). */
static const char *p2_script; /* tests: player 2's script from car select on (TM2PC_CARSEL_P2_SCRIPT) */
static uint64_t p34_ticks[4] = {0, 0, 600 - 24, 600 - 24}; /* tests: players 3-4's script places (car select starts them again) */
static int cl_on_script(int p);
static uint16_t signin_input(int p, uint64_t *p2_tick)
{
    int key;
    if (p == 0 && script && cl_on_script(0) && getenv("TM2PC_TRAILER") && getenv("TM2PC_CARSEL_SCRIPT")) {
        /* (trailer footage: player 1's car select script on its own clock, a step as long as players 2-4's; the
         * shared one is also read elsewhere each frame and ran ahead) */
        const char *saved = script;
        uint64_t saved_tick = script_tick;
        script = getenv("TM2PC_CARSEL_SCRIPT");
        script_tick = p34_ticks[0]++;
        uint16_t b = menu_input(&key);
        script = saved;
        script_tick = saved_tick;
        return b;
    }
    if (p == 0)
        return script ? menu_input(&key) : input_player_menu_buttons(0);
    if (p >= 2) { /* players 3 and 4: their controllers (tests: TM2PC_CARSEL_P3_SCRIPT, TM2PC_P3_SCRIPT ...) */
        char env[40];
        snprintf(env, sizeof env, "TM2PC_CARSEL_P%d_SCRIPT", p + 1);
        const char *ps = cl_on_script(p) ? getenv(env) : NULL;
        if (!ps) { snprintf(env, sizeof env, "TM2PC_P%d_SCRIPT", p + 1); ps = getenv(env); }
        if (script || ps) {
            if (!ps) return 0;
            const char *saved = script;
            uint64_t saved_tick = script_tick;
            script = ps;
            script_tick = p34_ticks[p & 3]++;
            uint16_t b = menu_input(&key);
            script = saved;
            script_tick = saved_tick;
            return b;
        }
        return input_player_menu_buttons(p);
    }
    const char *p2s = p2_script ? p2_script : getenv("TM2PC_P2_SCRIPT");
    if (script || p2s) {
        if (!p2s) return 0;
        const char *saved = script;
        uint64_t saved_tick = script_tick;
        script = p2s;
        script_tick = (*p2_tick)++;
        uint16_t b = menu_input(&key);
        script = saved;
        script_tick = saved_tick;
        return b;
    }
    return input_player_menu_buttons(1);
}

void profile_extra_use(int p, const char *who); /* profile/profile.c */
static const char *local_seat_name(int p) /* this PC's player p's profile ("" a guest) */
{
    if (play_players < 2) return p == 0 && profile_signed_in() ? profile_name() : ""; /* (1 player: the one signed in) */
    return p >= 0 && p < 4 ? sp[p].name : ""; /* (2-4: the sign-in's seats) */
}
static int local_save_ok(const ProfileSave *sv, int *map) /* the save's players are the ones signed in now */
{
    char names[PROFILE_SAVE_PLAYERS][32];
    unsigned char ids[PROFILE_SAVE_PLAYERS][8] = {{0}};
    int seats = play_players < 1 ? 1 : play_players > PROFILE_SAVE_PLAYERS ? PROFILE_SAVE_PLAYERS : play_players;
    for (int p = 0; p < seats; p++) snprintf(names[p], sizeof names[p], "%s", local_seat_name(p));
    return save_seat_match(sv, seats, (const char (*)[32])names, (const unsigned char (*)[8])ids, map);
}
static void signin_apply(void) /* the two as they are ready */
{
    if (sp[0].name[0]) {
        profile_use(sp[0].name);
        apply_game_settings();
    }
    if (sp[1].name[0]) profile_p2_use(sp[1].name);
    else profile_p2_clear();
    for (int p = 2; p < 4; p++) {
        snprintf(sp_extra_name[p - 2], sizeof sp_extra_name[0], "%s", p < sp_n ? sp[p].name : "");
        profile_extra_use(p, sp_extra_name[p - 2]); /* their controls */
    }
}

/* Runs the sign-in; 1 when both are ready and go on, 0 back. */
static int signin_run(void)
{
    memset(sp, 0, sizeof sp);
    static int joined_before; /* back from the players' menu: those who were in, still in, signed in and ready */
    static struct { int sel; char name[64]; } kept[4];
    sp_n = 4; /* Multiplayer: four places; players 2-4 join with Start */
    profile_rescan();
    snprintf(signin_home, sizeof signin_home, "%s", profile_signed_in() ? profile_name() : "");
    sp[0].joined = 1;
    for (int i = 0; i < profile_count(); i++) /* player 1 starts on the profile signed in */
        if (profile_signed_in() && !SDL_strcasecmp(profile_list_name(i), profile_name())) sp[0].sel = i;
    /* in by Start (tests: their scripts); back from the players' menu, those who were in */
    sp[1].joined = joined_before > 1 || (getenv("TM2PC_P2_SCRIPT") != NULL && !getenv("TM2PC_SIGNIN_ONE")); /* (tests: one player) */
    sp[2].joined = joined_before > 2 || getenv("TM2PC_P3_SCRIPT") != NULL;
    sp[3].joined = joined_before > 3 || getenv("TM2PC_P4_SCRIPT") != NULL;
    for (int p = 0; p < joined_before && p < 4; p++) { /* as they were: ready (O to change, player 1's O again to leave) */
        sp[p].joined = sp[p].ready = 1;
        sp[p].sel = kept[p].sel;
        snprintf(sp[p].name, sizeof sp[p].name, "%s", kept[p].name);
    }
    for (int p = 0; p < 4; p++) sp[p].prev = 0xFFFF;
    uint64_t p2_tick = 600 - 24;
    int result = -1, dirty = 1;
    Image canvas = {0, 0, NULL};
    display_hold = 0; /* this page takes the screen */
    Psyz_VideoSetDisplayRGB24Fill(1);
    uint64_t next = SDL_GetTicksNS();
    while (result < 0) {
        /* players 2-4 join: Start on a controller no one who joined has (the first free place) */
        for (int j = 1; j < sp_n && !script; j++) {
            if (sp[j].joined) continue;
            for (int i = 0; i < input_controller_count(); i++) {
                int taken = 0;
                for (int q = 0; q < sp_n; q++) taken |= sp[q].joined && input_player_controller(q) == i;
                if (!taken && (input_controller_buttons(i) & B_START)) {
                    input_set_player_controller(j, i);
                    sp[j].joined = 1;
                    sp[j].prev = 0xFFFF;
                    menu_sound(1);
                    dirty = 1;
                    break;
                }
            }
            break; /* one place at a time, in order */
        }
        for (int p = 0; p < sp_n && result < 0; p++) {
            if (!sp[p].joined) continue;
            uint16_t b = signin_input(p, &p2_tick);
            if (sp[p].nm.active) { /* naming on this half */
                naming = sp[p].nm;
                naming_pad = p;
                int done = naming_input(b);
                naming_pad = -1;
                sp[p].nm = naming;
                naming.active = 0;
                if (done && sp[p].nm.renaming) { /* back to the profile's options, under its new name */
                    if (done > 0) {
                        if (!SDL_strcasecmp(signin_home, sp[p].edit))
                            snprintf(signin_home, sizeof signin_home, "%s", sp[p].nm.text);
                        snprintf(sp[p].edit, sizeof sp[p].edit, "%s", sp[p].nm.text);
                    }
                    profile_rescan();
                    sp[p].mode = SP_MENU;
                }
                if (done > 0) {
                    profile_rescan();
                    for (int i = 0; i < profile_count(); i++)
                        if (!SDL_strcasecmp(profile_list_name(i), sp[p].nm.text)) sp[p].sel = i;
                }
                if (done) sp[p].prev = 0xFFFF;
                dirty = 1;
                continue;
            }
            if (sp[p].mode != SP_LIST) { /* the profile's options */
                uint16_t pr = (uint16_t)(b & ~sp[p].prev);
                sp[p].prev = b;
                if (sp[p].mode == SP_MENU) {
                    if (pr & (B_UP | B_DOWN)) {
                        sp[p].msel = (sp[p].msel + ((pr & B_UP) ? 3 : 1)) % 4;
                        menu_sound(0);
                    } else if (pr & (B_CROSS | B_START)) {
                        menu_sound(1);
                        if (sp[p].msel == 0) { /* the portrait grid, on the profile's own */
                            sp_build_pics();
                            sp_read_unlocks(p);
                            sp[p].gsel = 0;
                            for (int i = 0; i < sp_npics; i++) if (sp_pics[i] == sp[p].pic) sp[p].gsel = i;
                            sp[p].gtop = sp[p].gsel / SP_COLS;
                            sp[p].mode = SP_GRID;
                        } else if (sp[p].msel == 1) { /* the name, on this half */
                            Naming saved = naming;
                            name_start(1);
                            snprintf(naming.text, sizeof naming.text, "%s", sp[p].edit);
                            snprintf(naming.rename_from, sizeof naming.rename_from, "%s", sp[p].edit);
                            naming.caps = 0;
                            naming.prev = 0xFFFF;
                            sp[p].nm = naming;
                            naming = saved;
                            if (p == 0 && !script) input_new_key();
                        } else if (sp[p].msel == 2) {
                            sp[p].mode = SP_DELETE;
                            sp[p].held_since = 0;
                        } else { /* DONE */
                            sp_edit_end();
                            sp[p].mode = SP_LIST;
                        }
                    } else if (pr & (B_CIRCLE | B_SELECT | B_SQUARE)) {
                        menu_sound(1);
                        sp_edit_end();
                        sp[p].mode = SP_LIST;
                    }
                } else if (sp[p].mode == SP_GRID) {
                    int g = sp[p].gsel;
                    if (pr & B_LEFT) g--;
                    if (pr & B_RIGHT) g++;
                    if (pr & B_UP) g -= SP_COLS;
                    if (pr & B_DOWN) g += SP_COLS;
                    if (g != sp[p].gsel && g >= 0 && g < sp_npics) {
                        sp[p].gsel = g;
                        if (g / SP_COLS < sp[p].gtop) sp[p].gtop = g / SP_COLS;
                        if (g / SP_COLS >= sp[p].gtop + SP_ROWS) sp[p].gtop = g / SP_COLS - SP_ROWS + 1;
                        menu_sound(0);
                    }
                    if (pr & (B_CROSS | B_START)) {
                        int pic = sp_pics[sp[p].gsel];
                        if (sp[p].unl[sp[p].gsel]) {
                            profile_set_picture_of(sp[p].edit, pic);
                            sp[p].pic = pic;
                            menu_sound(1);
                            sp[p].mode = SP_MENU;
                        } else {
                            denied_sound();
                        }
                    } else if (pr & (B_CIRCLE | B_SELECT)) {
                        menu_sound(1);
                        sp[p].mode = SP_MENU;
                    }
                } else { /* SP_DELETE: X held 3.5 s */
                    if (b & B_CROSS) {
                        if (!sp[p].held_since) sp[p].held_since = SDL_GetTicks();
                        else if (SDL_GetTicks() - sp[p].held_since >= DELETE_HOLD) {
                            char who[64];
                            snprintf(who, sizeof who, "%s", sp[p].edit);
                            if (!SDL_strcasecmp(signin_home, who)) signin_home[0] = 0;
                            profile_delete(who);
                            sp_edit_end();
                            menu_sound(1);
                            sp[p].mode = SP_LIST;
                            sp[p].held_since = 0;
                            if (sp[p].sel >= signin_items(p)) sp[p].sel = signin_items(p) - 1;
                            sp[p].prev = 0xFFFF;
                        }
                    } else {
                        sp[p].held_since = 0;
                    }
                    if (pr & (B_CIRCLE | B_SELECT)) {
                        menu_sound(1);
                        sp[p].mode = SP_MENU;
                        sp[p].held_since = 0;
                    }
                }
                dirty = 1;
                continue;
            }
            uint16_t pressed = (uint16_t)(b & ~sp[p].prev);
            static const uint16_t dirs[2] = {B_UP, B_DOWN};
            for (int d = 0; d < 2; d++) {
                if (!(b & dirs[d])) { sp[p].held_for[d] = 0; continue; }
                if (++sp[p].held_for[d] > 18 && (sp[p].held_for[d] - 18) % 5 == 0) pressed |= dirs[d];
            }
            sp[p].prev = b;
            int n = signin_items(p), both = signin_all_ready();
            if (both && p == 0 && (pressed & B_SQUARE)) { /* Controls for the two */
                menu_sound(1);
                signin_apply();
                from_title = 1;
                edit_player = 0;
                signin_controls = 1;
                run(PAGE_CONTROLS);
                signin_controls = 0;
                Psyz_VideoSetDisplayRGB24Fill(1);
                for (int q = 0; q < 4; q++) sp[q].prev = 0xFFFF;
                dirty = 1;
            } else if (both && p == 0 && (pressed & (B_CROSS | B_START))) {
                result = 1;
                boom_queued = settings_game.menu_sounds; /* (the select boom, as the pages close: its callers play it) */
            } else if (!sp[p].ready && (pressed & B_SQUARE)) { /* the profile's options */
                int it = signin_item(p, sp[p].sel);
                int edited = 0; /* another player is changing this profile */
                for (int q = 0; q < sp_n && it >= 0; q++)
                    edited |= q != p && sp[q].mode != SP_LIST && !SDL_strcasecmp(sp[q].edit, profile_list_name(it));
                if (it < 0 || signin_taken(p, it) || edited) {
                    denied_sound();
                } else {
                    menu_sound(1);
                    sp_edit_begin(p, profile_list_name(it));
                    sp[p].mode = SP_MENU;
                    sp[p].msel = 0;
                }
                dirty = 1;
            } else if (!sp[p].ready && (pressed & (B_UP | B_DOWN))) {
                sp[p].sel = (sp[p].sel + ((pressed & B_UP) ? n - 1 : 1)) % n;
                menu_sound(0);
                dirty = 1;
            } else if (!sp[p].ready && (pressed & (B_CROSS | B_START))) {
                int it = signin_item(p, sp[p].sel);
                if (signin_taken(p, it)) {
                    denied_sound();
                } else if (it == SIGNIN_NEW) { /* the name, on this half */
                    menu_sound(1);
                    Naming saved = naming;
                    name_start(0);
                    naming.for_player2 = 1; /* made, not signed in yet */
                    naming.prev = 0xFFFF;
                    sp[p].nm = naming;
                    naming = saved;
                    if (p == 0 && !script) input_new_key();
                } else {
                    sp[p].ready = 1;
                    snprintf(sp[p].name, sizeof sp[p].name, "%s", it >= 0 ? profile_list_name(it) : "");
                    fprintf(stderr, "sign-in: player %d ready as %s\n", p + 1, sp[p].name[0] ? sp[p].name : "a guest");
                    menu_sound(1);
                }
                dirty = 1;
            } else if (pressed & (B_CIRCLE | B_SELECT)) {
                menu_sound(1);
                if (sp[p].ready) sp[p].ready = 0;
                else if (p == 0) { result = 0; joined_before = 0; }
                else sp[p].joined = 0;
                dirty = 1;
            }
        }
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) &&
            image_resize(&canvas, size.w, size.h)) {
            compose_signin(&canvas);
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
            dirty = 0;
        }
        ui_audio_frame();
        ui_vsync();
        next += 1000000000ull / 60;
        uint64_t now = SDL_GetTicksNS();
        if (next > now) SDL_DelayNS(next - now);
        else next = now;
    }
    if (result == 1) { /* the players in, in order (a gap closed up, their controllers with them) */
        int n = 0;
        for (int p = 0; p < 4; p++) {
            if (!sp[p].joined) continue;
            if (p != n) {
                int pad = input_player_controller(p);
                sp[n] = sp[p];
                sp[p].joined = 0;
                input_set_player_controller(n, pad);
            }
            n++;
        }
        sp_n = n;
        group_players = joined_before = n;
        for (int p = 0; p < n; p++) { kept[p].sel = sp[p].sel; snprintf(kept[p].name, sizeof kept[p].name, "%s", sp[p].name); }
        signin_apply();
        fprintf(stderr, "sign-in: player 1 %s, player 2 %s (%d players)\n", sp[0].name[0] ? sp[0].name : "guest",
                sp[1].name[0] ? sp[1].name : "guest", group_players);
    }
    display_to_game(&canvas);
    image_free(&canvas);
    return result;
}

static int local_from_title; /* the title chose Local Play (else back from car or level select) */
void four_setup(int humans, int car3, int car4); /* vplus/four.c: players 3-4 in the battle */
int four_humans(void);
int four_car_of(int player);
static int tour_running(void); /* (below, with the custom tournament: trun.on) */

/* Starts the Challenge Match set on its pages: the game's settings as its
 * menus leave them (8012E908 for 1 player, 8012F5F8 for 2), with the arena
 * and the number of opponents set here; then its car select. The opponents
 * are filled in for its opponent select (ui_AiSelect), the difficulty for
 * the match (ui_SessionRunner). */
static uint32_t battle_start(int survival);
/* where the match goes on from car select, after battle_start: lobby_next, except that "on to the opponents" in the
 * game's mode 4 (2 players, no computer cars) is the world globe, as its car select goes (the opponents' screen with
 * none: the movie decoder's code, a freeze; the user's online playtest 2026-11-01) */
static uint32_t lobby_next_for_mode(void)
{
    if (lobby_next == GA(0x80131EECu) && guest_call(GA(0x8013793Cu), GA(0x8016475Cu), 0, 0, 0) == 4) return GA(0x801334E8u);
    return lobby_next;
}
static uint32_t battle_start(int survival)
{
    const uint32_t S = GA(0x8016475Cu);
    const MatchSetup *b = battle_match();
    int arena = arena_level(getenv("TM2PC_TEST_ARENA_VALUE") ? atoi(getenv("TM2PC_TEST_ARENA_VALUE")) /* (tests: a list value, 100 the first mod arena) */
                            : survival ? survival_arena : b->arena);
    int humans = play_players;
    if (play_players == 2 && !survival && getenv("TM2PC_TEST_FOUR") && atoi(getenv("TM2PC_TEST_FOUR")) > 2) { /* tests: players 3-4 too */
        humans = atoi(getenv("TM2PC_TEST_FOUR")) > 3 ? 4 : 3;
        four_setup(humans, 3, 5);
    }
    int level = arena ? arena : arena_level(arena_random());
    if (getenv("TM2PC_TEST_ARENA")) level = atoi(getenv("TM2PC_TEST_ARENA")); /* tests: this arena (1..8) */
    survival_on = survival;
    /* (with texture banks every car its own VRAM: room beside him for any car) */
    int room_beside_boss = cars_banks() || level < 0 || level >= 13 ? CARS_MAX : boss_room[level];
    survival_boss_on = survival && survival_boss_pick && room_beside_boss > play_players && port_config_on(); /* (his fight is the variant's C) */
    int boss_cap = survival_boss_on ? room_beside_boss - play_players + 1 : opponents_playable(); /* others, then him */
    if (boss_cap > opponents_playable()) boss_cap = opponents_playable();
    if (survival && boss_cap > SURVIVAL_CARS) boss_cap = SURVIVAL_CARS; /* (12 computer cars at most, any player count) */
    guest_call(GA(0x80137930u), S, (uint32_t)(play_players > 2 ? 2 : play_players), 0, 0); /* the game's humans: 2 at most */
    guest_call(GA(0x801378B4u), S, 0, 0, 0);
    guest_call(GA(0x80137900u), S, 0, 0, 0);
    guest_call(GA(0x801378E8u), S, 0, 0, 0);
    guest_call(GA(0x80137864u), S, 0, 0, 0);
    guest_call(GA(0x80137814u), S, (uint32_t)level, 0, 0);
    if (play_players >= 2 && survival) { /* co-op Survival: the challenge mode with every player (and the computer cars);
                                          * players 3-4 the port's (vplus/four.c) */
        int m = cars_arena_room(level) - play_players;
        guest_call(GA(0x80137948u), S, 3, 0, 0);
        guest_call(GA(0x80137918u), S, (uint32_t)(boss_cap < m ? boss_cap : m), 0, 0);
        guest_call(GA(0x80137820u), S, 0, 1, 0);
        guest_call(GA(0x80137820u), S, 1, 1, 0);
    } else if (play_players >= 2 && (battle_full() || b->opponents > 0 || humans > 2 || tour_running())) {
        /* (a custom tournament's stage, a Versus's too, with 2 players and no computer cars: the challenge mode as with
         * more, not the head to head, whose end goes another way: a 2-player online Versus ended after its first stage,
         * the 2026-11-14 podium check) */
        /* 2 players and computer cars: the challenge mode with both (as co-op Survival); the
         * port's rules decide the round (vp_duo_frame: the last car, or team, in). 3-4 players:
         * the same, players 3-4 the port's (vplus/four.c) */
        int n = battle_full() ? opponents_playable() : b->opponents, m = cars_arena_room(level) - (humans > 2 ? humans : 2);
        guest_call(GA(0x80137948u), S, 3, 0, 0);
        guest_call(GA(0x80137918u), S, (uint32_t)(n < m ? n : m), 0, 0);
        guest_call(GA(0x80137820u), S, 0, 1, 0);
        guest_call(GA(0x80137820u), S, 1, 1, 0);
    } else if (play_players >= 2) {
        guest_call(GA(0x80137948u), S, 4, 0, 0); /* mode: 2 players against each other */
        guest_call(GA(0x80137918u), S, 0, 0, 0);
        guest_call(GA(0x80137820u), S, 0, 1, 0);
        guest_call(GA(0x80137820u), S, 1, 1, 0);
    } else {
        int n = survival ? boss_cap : b->opponents > opponents_playable() ? opponents_playable() : b->opponents, m = cars_arena_room(level) - 1;
        guest_call(GA(0x80137948u), S, 3, 0, 0); /* mode: challenge */
        guest_call(GA(0x80137918u), S, (uint32_t)(n < m ? n : m), 0, 0);
        guest_call(GA(0x80137820u), S, 0, 1, 0);
    }
    battle_live = 1;
    battle_new_match = 1;
    fprintf(stderr, "local play: %s (%s, %d player%s, %s, %d opponents, %s)\n", survival ? "survival" : "challenge match",
            survival ? "Last Car Standing" : battle_match_type()->name,
            play_players, play_players > 1 ? "s" : "", level >= 0 && level < 13 ? tournament_arenas[level] : "?", mem_r8(&M.cpu, S + 5),
            difficulty_values[survival ? 2 : b->difficulty]);
    return CAR_SELECT_SCREEN;
}

static int battle_results(int result, int mode);
/* ---- Custom Tournament: its stages played one after another as Challenge Matches (Last Car Standing), the cars
 * chosen once; each stage's arena and enemies from the setup (random ones rolled at the start), lives carried from
 * stage to stage (Vanilla Plus "lives per level": the setup's at each stage). A won stage: its results with NEXT
 * STAGE / QUIT; a lost one: RETRY STAGE / QUIT; the last: TOURNAMENT WON. No endings or unlocks of the game's own.
 * (docs/CUSTOM_TOURNAMENT.md) */
enum { TOUR_NEXT_NONE, TOUR_NEXT_STAGE, TOUR_NEXT_RETRY, TOUR_NEXT_DUEL };
static struct {
    int on, stage, n, next;
    int duel;                          /* 2-4 players, the last stage won: the players fight it out on its arena (as the
                                        * co-op tournament's duel); its winner wins the tournament */
    int arena[TOUR_STAGES_MAX], enemies[TOUR_STAGES_MAX];
    int lives[4];                      /* each player's, carried */
    int versus;                        /* an online Versus Tournament: the players against each other, 1 life a stage,
                                        * points by place (vplus/fixes.c vp_versus_score), a player drives the boss */
    int car[16];                       /* (versus) each human's own car (a boss stage's driver gets the boss's) */
} trun;
static int tour_running(void) { return trun.on; }
static void carry_clear(void);
static CustomTour versus_tour;         /* (versus) the host's setup */
static int versus_cpu[BATTLE_OPPONENT_SLOTS], versus_cpu_n; /* (versus) the first stage's computer cars, the same in
                                       * every stage after it (from the host's state: every machine the same) */
static MatchSetup tour_match;          /* the stage being played (battle_match() while trun.on) */
static int tour_returning;             /* the tournament is over: back to its page */
int ui_tour_on(void) { return battle_live && trun.on && !trun.duel && !trun.versus; } /* the players one side (the duel, versus: each their own) */
static int tour_start_lives(void) /* as the tournament's: 3 (3 players: 2, 4 players: 1, as Vanilla Plus's lives per level) */
{
    int lives = 3 - (play_players > 2 ? play_players - 2 : 0);
    return lives < 1 ? 1 : lives;
}
int ui_tour_lives(int p) /* fixes.c, at a stage's start: a player's lives (0: not a custom tournament) */
{
    if (!trun.on || p < 0) return 0;
    int vp_versus_duelist(int h); /* vplus/fixes.c: a boss round's two */
    if (trun.versus && !trun.duel && p < 16) /* a Versus Tournament's stage: the host's extra lives (a boss round:
                                                           * one life each) */
        return vp_versus_duelist(p) ? 1 : 1 + (battle_tour()->versus_lives > 0 ? battle_tour()->versus_lives : 0);
    if (p > 3) return 0;
    if (trun.duel || trun.versus) return 1; /* the final battle: one life each */
    return vp_on(VP_LIVES_PER_LEVEL) ? tour_start_lives() : trun.lives[p] > 0 ? trun.lives[p] : 1;
}
static void tour_stage_setup(void)
{
    const CustomTour *t = battle_tour();
    battle_match_defaults(&tour_match);
    tour_match.arena = trun.arena[trun.stage];
    tour_match.opponents = trun.duel ? 0 : trun.enemies[trun.stage];
    tour_match.difficulty = t->difficulty;
    tour_match.lives = 1; /* the computer cars: one each, as the tournament's (the players' from ui_tour_lives) */
    /* 2-4 players: together against the computer cars, as the tournament's co-op (vplus/fixes.c vp_duo_frame: the
     * players one side), no team colors */
    battle_match_override(&tour_match);
}
static void tour_begin(void)
{
    const CustomTour *t = battle_tour();
    memset(&trun, 0, sizeof trun);
    carry_clear(); /* (a new tournament: nothing carried in) */
    trun.on = 1;
    trun.n = t->stages;
    for (int i = 0; i < trun.n; i++) {
        trun.arena[i] = t->stage[i].arena ? t->stage[i].arena : arena_random();
        trun.enemies[i] = t->stage[i].enemies ? t->stage[i].enemies : 3 + (int)SDL_rand(5); /* random: 3..7 */
    }
    for (int p = 0; p < 4; p++) trun.lives[p] = tour_start_lives();
    tour_stage_setup();
    fprintf(stderr, "custom tournament: %d stages, %s, %d lives\n", trun.n, difficulty_values[t->difficulty], tour_start_lives());
}
static void tour_end(void)
{
    if (!trun.on) return;
    trun.on = 0;
    battle_match_override(NULL);
    results_items[0] = results_items[1] = NULL;
    results_title_tour[0] = 0;
    if (netplay_in_match()) { battle_tour_override(NULL); netplay_each_battle(0); } /* (online: the server's lobby next) */
    else tour_returning = 1;
    fprintf(stderr, "custom tournament: over\n");
}
int vp_lives_left(int p); /* fixes.c */
/* a stage played out (the game's result r): its results screen, then the next stage, this one again, or out */
static void versus_stage_end(void);
static int net_custom_coop(void);              /* (below) an online custom co-op tournament on */
static const char *match_human_name(int h);    /* (below) */
static int net_tour_choose(int level, int kind); /* (below) the host's choice between levels online, the others wait */
static int results_skip;                       /* (battle_results) the match counted, no screen (a custom tournament's stage) */
static int tournament_menu(const char *title, const char *const *items, int count);
static int menu_keep_frame;                    /* (below) */
static int tour_left_server;                  /* (online) this machine left the server at a stage's choice */
/* Weapons carried to the next stage (the user's 2026-11-16: Co-Op, Custom and Versus Tournaments, a player who lives
 * keeps what they have; not Challenge Match playlists or Survival). The co-op tournament (the game's own) keeps them
 * already: carResetWeapons stays 0 for a car that lived through a won level. A Custom or Versus Tournament plays each
 * stage as a Challenge Match, whose round end resets every car's weapons (the decomp's portHumanRules, mode 3 and 4):
 * here each living player's weapons (ammo slots 1-9, the special refilled as the game does; the one chosen) are kept at
 * the stage's end and put back at the next stage's first round. A player out, or a lost stage played again: none. Every
 * machine of an online match runs the same stage ends, so the same weapons come back on each. */
enum { CARRY_HUMANS = 16, CARRY_SLOTS = 10 };
static struct { int pending, have[CARRY_HUMANS], sel[CARRY_HUMANS]; int16_t ammo[CARRY_HUMANS][CARRY_SLOTS]; } carry;
static void carry_clear(void) { memset(&carry, 0, sizeof carry); }
static void carry_save(int won)
{
    int vp_versus_parked(int h); /* vplus/fixes.c: sat a boss round out (their weapons as they were) */
    if (!won) { carry_clear(); return; }
    int n = (int)mem_r32(&M.cpu, GA(0x80181014u));
    for (int h = 0; h < n && h < CARRY_HUMANS; h++) {
        if (vp_versus_parked(h)) continue; /* (not in this round: what they had before stays) */
        uint32_t rec = HUMAN_REC(h);
        carry.have[h] = !mem_r8(&M.cpu, rec + 0x9C); /* (alive at the end) */
        carry.sel[h] = (int8_t)mem_r8(&M.cpu, rec + 0x7D5);
        for (int i = 0; i < CARRY_SLOTS; i++) carry.ammo[h][i] = carry.have[h] ? (int16_t)mem_r16(&M.cpu, rec + 0x7D6 + 2u * (uint32_t)i) : 0;
    }
    carry.pending = 1;
}
void tour_carry_round(void) /* a round's start (ui_MainLoop): a new stage's first round, its players' weapons back */
{
    if (!carry.pending) return;
    carry.pending = 0;
    if (!trun.on || survival_on) { carry_clear(); return; }
    int n = (int)mem_r32(&M.cpu, GA(0x80181014u));
    for (int h = 0; h < n && h < CARRY_HUMANS; h++) {
        if (!carry.have[h]) continue;
        uint32_t rec = HUMAN_REC(h);
        if (mem_r8(&M.cpu, rec + 0x9C)) continue;
        for (int i = 1; i < CARRY_SLOTS; i++) mem_w16(&M.cpu, rec + 0x7D6 + 2u * (uint32_t)i, (uint16_t)carry.ammo[h][i]);
        int s = carry.sel[h];
        if (s >= 0 && s < CARRY_SLOTS && carry.ammo[h][s] > 0) mem_w8(&M.cpu, rec + 0x7D5, (uint8_t)s);
        fprintf(stderr, "tournament: player %d keeps their weapons (%d %d %d %d %d %d %d %d %d)\n", h + 1, carry.ammo[h][1],
                carry.ammo[h][2], carry.ammo[h][3], carry.ammo[h][4], carry.ammo[h][5], carry.ammo[h][6], carry.ammo[h][7],
                carry.ammo[h][8], carry.ammo[h][9]);
    }
}
static void tour_stage_end(int r, int mode)
{
    carry_save(trun.versus ? 1 : mode == 3 && r == 3);
    if (trun.versus) { versus_stage_end(); return; }
    int won = mode == 3 && r == 3, last = won && trun.stage + 1 >= trun.n, duel_next = last && !trun.duel && play_players > 1;
    if (won) for (int p = 0; p < 4; p++) trun.lives[p] = vp_lives_left(p);
    if (trun.duel) { /* the final battle: its winner wins the tournament */
        int h = -1, ai = -1;
        won = last = 1;
        if (vp_duo_winner(&h, &ai) && h >= 0 && h < 4 && r == 3) {
            snprintf(results_title_tour, sizeof results_title_tour, "%s WINS!", match_human_name(h)); /* (the menu's big title: a longer one is off the screen) */ /* (online: the match's player h, not this machine's) */
            upper(results_title_tour);
        } else snprintf(results_title_tour, sizeof results_title_tour, "NO ONE IS LEFT");
        fprintf(stderr, "custom tournament: the final battle: %s\n", results_title_tour);
    } else if (duel_next) {
        snprintf(results_title_tour, sizeof results_title_tour, "STAGE %d OF %d COMPLETE", trun.stage + 1, trun.n);
        last = 0;
    } else if (last) snprintf(results_title_tour, sizeof results_title_tour, "TOURNAMENT WON!");
    else if (won) snprintf(results_title_tour, sizeof results_title_tour, "STAGE %d OF %d COMPLETE", trun.stage + 1, trun.n);
    else snprintf(results_title_tour, sizeof results_title_tour, "GAME OVER");
    /* No results screen between stages (the user's 2026-11-13: a tournament is surviving to the next stage): the match
     * counted (Stats, the masters), then a won stage straight on; a lost one GAME OVER: RESTART / QUIT (online the
     * host's, the others waiting for it); the tournament's end its title and FINISH */
    const char *saved_script = script; /* tests: TM2PC_TMENU_SCRIPT answers the menus */
    if (getenv("TM2PC_TMENU_SCRIPT")) { script = getenv("TM2PC_TMENU_SCRIPT"); script_tick = 600 - 24; }
    int online = net_custom_coop(), chosen = 0;
    results_skip = 1;
    battle_results(r, mode);
    results_skip = 0;
    fprintf(stderr, "custom tournament: stage %d %s\n", trun.stage + 1, won ? "won" : "lost");
    if (!won && online) {
        menu_keep_frame = 1; /* (the battle's last frame behind) */
        int choice = net_tour_choose(100 + trun.stage, 1);
        chosen = choice != TOUR_DEC_RESTART;
        if (choice < 0) tour_left_server = 1;
        fprintf(stderr, "custom co-op tournament: after stage %d: %s\n", trun.stage + 1,
                choice == TOUR_DEC_RESTART ? "restart" : choice < 0 ? "left the server" : "to the lobby");
    } else if (!won) {
        static const char *const lost_items[2] = {"RESTART", "QUIT"};
        menu_keep_frame = 1;
        chosen = tournament_menu("GAME OVER", lost_items, 2) != 0;
    } else if (last) {
        static const char *const finish[1] = {"FINISH"};
        menu_keep_frame = 1;
        tournament_menu(results_title_tour, finish, 1);
    }
    script = saved_script;
    trun.next = TOUR_NEXT_NONE;
    if (duel_next) { trun.duel = 1; trun.next = TOUR_NEXT_DUEL; } /* (one choice: on to it) */
    else if (!last && !chosen) {
        if (won) trun.stage++;
        else for (int p = 0; p < 4; p++) trun.lives[p] = tour_start_lives(); /* a retry: the starting lives again */
        trun.next = won ? TOUR_NEXT_STAGE : TOUR_NEXT_RETRY;
    }
    results_items[0] = results_items[1] = NULL;
    results_title_tour[0] = 0;
}
/* the next stage (or the same again): the arena and the enemies in the settings, then the opponents' screen
 * (ui_AiSelect picks them as for a Challenge Match), the cars kept */
static void versus_cars(void);
int vp_versus_boss_driver(void); /* vplus/fixes.c: a Versus Tournament's boss round on (its boss's driver), else -1 */
/* The podium (vplus/podium.c, the user's 2026-11-07): after the last stage a New York round of the top three (it ends at
 * once), its scene, then the final standings. versus_podium: 1 the podium round next, 2 it is on. The honorable
 * mentions: each contestant's kills, damage dealt and deaths over every stage (by kind: 0 a player, 1 a computer car) */
enum { AW_KILLS, AW_DAMAGE, AW_DEATHS, AWARDS };
static int versus_aw[AWARDS][2][16];
static int versus_podium, versus_final_champ = -1, versus_final_champ_ai = -1;
static char versus_final_title[64];
static int podium_place_kind[3], podium_place_index[3]; /* each place's contestant (kind -1: none) */
static int podium_test_car[16] = {-1, -1, -1};         /* tests: TM2PC_TEST_PODIUM_CARS=1st,2nd,3rd (car numbers); more: the
                                                         * art's line-up (every car of the round side by side) */
static int podium_lineup;
static int podium_ai_k[3], podium_ai_n;                  /* the podium round's computer cars: their contestants */
static void versus_podium_cast(void);                    /* (below, with the standings) */
static void versus_podium_show(void);
void vp_versus_podium(unsigned mask);                    /* vplus/fixes.c */
void vp_versus_podium_done(void);
static uint32_t tour_next_stage(void)
{
    const uint32_t S = GA(0x8016475Cu);
    tour_stage_setup();
    if (trun.versus && versus_podium == 1) { /* the podium round: New York, the top three only (the players' own cars, the
                                              * computer cars on it as themselves) */
        tour_match.arena = PODIUM_LEVEL;
        if (podium_lineup && getenv("TM2PC_TEST_LINEUP_ARENA")) tour_match.arena = atoi(getenv("TM2PC_TEST_LINEUP_ARENA")); /* (tools: 1 LA) */
        tour_match.opponents = podium_ai_n;
        for (int i = 0; i < BATTLE_OPPONENT_SLOTS; i++)
            tour_match.opponent[i] = i < podium_ai_n && podium_test_car[i] >= 0 ? podium_test_car[i]
                                   : i < podium_ai_n && podium_ai_k[i] < versus_cpu_n ? versus_cpu[podium_ai_k[i]] : -1;
        unsigned mask = 0;
        for (int p = 0; p < 3; p++) if (podium_place_kind[p] == 0) mask |= 1u << podium_place_index[p];
        if (podium_lineup) mask = 0xFFFFu; /* (tools: the line-up: every player in it) */
        vp_versus_podium(mask);
        versus_podium = 2;
    }
    if (trun.versus) versus_cars();
    trun.next = TOUR_NEXT_NONE;
    int level = arena_level(tour_match.arena);
    if (!level) level = arena_level(arena_random());
    int humans = play_players > 2 ? play_players : mem_r8(&M.cpu, S + 4) < 1 ? 1 : mem_r8(&M.cpu, S + 4);
    int n = tour_match.opponents < opponents_playable() ? tour_match.opponents : opponents_playable();
    if (trun.versus && vp_versus_boss_driver() >= 0) n = 0; /* (a Versus Tournament's boss round: the two only) */
    if (trun.versus && versus_podium == 2) n = podium_ai_n;
    int m = cars_arena_room(level) - humans;
    guest_call(GA(0x80137814u), S, (uint32_t)level, 0, 0);
    guest_call(GA(0x80137918u), S, (uint32_t)(n < m ? n : m), 0, 0);
    battle_new_match = 1;
    fprintf(stderr, "custom tournament: %s %d of %d, %s, %d enemies\n", trun.duel ? "the final battle after stage" : "stage",
            trun.stage + 1, trun.n, level < 13 ? tournament_arenas[level] : "?", mem_r8(&M.cpu, S + 5));
    return GA(0x80131EEC); /* the opponents' screen (ui_AiSelect) */
}
static const char *match_human_name(int h); /* (below) */

/* ---- an online Versus Tournament (docs/ONLINE_PLAN.md 10): the Custom Tournament's stages, the players against each
 * other (1 life each a stage, the computer cars the setup's), points by place (vplus/fixes.c vp_versus_score: kept in
 * the network states; players out at the same step share the place), the standings after each stage; a boss stage
 * then has a boss round on its arena: the stage's winner against the boss, driven by the player lowest in points (a
 * tie: one of them at random), the others watching: the winner +3, the boss +10 (a comeback); each round from the
 * host's state; the most points after the last stage wins ---- */
/* by place: the top 8 score, whatever the field (the user's, 2026-11-05: with 16 cars a few in the points was too few) */
static const int VERSUS_POINTS[] = {15, 12, 10, 8, 6, 4, 2, 1};
void vp_versus(int on);
void vp_versus_score(int humans, const int *place_points, int n_points);
