/* Runs the title: the item picked (0-2), -1 when left alone too long, or
 * TITLE_PROFILES when O asks for the profile screen. */
enum { TITLE_PROFILES = -2 };
static int title_run(void)
{
    int sel = 0, dirty = 1, held_for[2] = {0}, chosen = -1, idle = 0, menu_key, ticks = 0, hair_frame = -1;
    int loops = cd_audio_loop_count(), pressed_this_play = 0;
    uint16_t prev = 0xFFFF;
    Image canvas = {0, 0, NULL};
    display_hold = 0; /* this page takes the screen */
    Psyz_VideoSetDisplayRGB24Fill(1);
    uint64_t next = SDL_GetTicksNS();
    for (;;) {
        uint16_t b = menu_input(&menu_key), pressed = (uint16_t)(b & ~prev);
        static const uint16_t dirs[2] = {B_LEFT, B_RIGHT};
        for (int d = 0; d < 2; d++) {
            if (!(b & dirs[d])) { held_for[d] = 0; continue; }
            if (++held_for[d] > 18 && (held_for[d] - 18) % 6 == 0) pressed |= dirs[d];
        }
        prev = b;
        idle = b ? 0 : idle + 1;
        if (b) pressed_this_play = 1;
        if (cd_audio_loop_count() != loops) { /* the song ended (and starts over) */
            loops = cd_audio_loop_count();
            if (!pressed_this_play) break;
            pressed_this_play = 0;
        }
        if (pressed & (B_LEFT | B_RIGHT)) {
            sel = (sel + ((pressed & B_LEFT) ? 2 : 1)) % 3;
            menu_sound(0);
            dirty = 1;
        } else if (pressed & (B_CROSS | B_START)) {
            chosen = sel;
            break;
        } else if (pressed & (B_CIRCLE | B_SELECT)) {
            chosen = TITLE_PROFILES; /* back to the profile screen */
            menu_sound(1);
            break;
        }
        if (idle >= TITLE_IDLE_VBLANKS && !cd_audio_music_playing())
            break;
        if (ticks++ / 2 != hair_frame) { /* a new hair frame every other VBlank */
            hair_frame = (ticks - 1) / 2;
            dirty = 1;
        }
        PsyzSize size = menu_canvas_size(); /* (at most 2560 x 1440: the GPU scales it up to a 4K screen) */
        if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) &&
            image_resize(&canvas, size.w, size.h)) {
            uint64_t t0 = SDL_GetTicksNS();
            compose_title(&canvas, sel, hair_frame);
            uint64_t t1 = SDL_GetTicksNS();
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
            if (getenv("TM2PC_MENU_TIMING")) /* tests: what a title frame costs (composed, handed over) */
                fprintf(stderr, "title: %dx%d composed in %.1f ms, shown in %.1f ms\n", canvas.w, canvas.h, (t1 - t0) / 1e6,
                        (SDL_GetTicksNS() - t1) / 1e6);
            dirty = 0;
        }
        ui_audio_frame();
        uint64_t tv = SDL_GetTicksNS();
        ui_vsync();
        if (getenv("TM2PC_MENU_TIMING") && SDL_GetTicksNS() - tv > 20000000ull)
            fprintf(stderr, "title: the frame's present took %.1f ms\n", (SDL_GetTicksNS() - tv) / 1e6);
        next += 1000000000ull / 60;
        uint64_t now = SDL_GetTicksNS();
        if (next > now) SDL_DelayNS(next - now);
        else next = now;
    }
    /* the next screen starts with the buttons released */
    while (input_menu_buttons(&menu_key) && !script) {
        ui_vsync();
        SDL_DelayNS(1000000000ull / 60);
    }
    display_to_game(&canvas); /* the title stays up until the next screen draws */
    image_free(&canvas);
    return chosen;
}

/* The title screen (8012DF84): the game's settings block is set up by then,
 * so the saved settings are written into it, each time the title menu
 * comes back (a password for a later level entered on Easy switches the game
 * to Medium; the title menu puts the setting back). */
void F_8012DF84_orig(CPU *c);
/* back from a server's match with a playlist on: its next one (the host starts the vote's winner; a joiner waits for that
 * start, 20 s at most): LOCAL_BATTLE, or -1 (the lobby) */
static int net_next_match(void)
{
    Lobby *l = netplay_lobby();
    if (!l || !net_pl.on) return -1;
    if (lobby_is_host(l)) {
        int i = net_next_entry;
        net_next_entry = -1;
        if (i < 0) return -1;
        return net_play_entry(i) == NET_LAUNCH ? LOCAL_BATTLE : -1;
    }
    if (net_vote_winner < 0) return -1;
    uint64_t t0 = SDL_GetTicks();
    while (lobby_view(l)->starts == net_starts_seen && lobby_status(l) == LOBBY_IN && SDL_GetTicks() - t0 < 20000) {
        ui_vsync();
        SDL_DelayNS(1000000000ull / 60);
    }
    net_vote_winner = -1;
    return lobby_view(l)->starts != net_starts_seen && net_launch() == NET_LAUNCH ? LOCAL_BATTLE : -1;
}
/* Network Play from the title: the players sign in (1-4), then its pages (nothing connected yet), then the title; from
 * the lobby, the game's car select (the lobby again after it: resume) */
static void net_play(CPU *c, int resume)
{
    static const char *saved_script;
    load_art();
    if (resume) menu_loop_start(); /* back from car select: on (it was) */
    int in = 1;
    if (!resume) {
        signin_min = 1;
        in = signin_run();
        signin_min = 2;
        saved_script = script;
        if (in && boom_queued) game_boom(); /* (Start: the select boom now) */
        boom_queued = 0;
    }
    if (in) {
        play_players = group_players;
        from_title = 1;
        if (!resume) { /* tests: TM2PC_NET_SCRIPT drives the Network Play pages (on through car select) */
            if (getenv("TM2PC_NET_SCRIPT")) script = getenv("TM2PC_NET_SCRIPT");
            if (script) script_tick = 600 - 24;
        } else run_open_on = PAGE_NET_SERVER;
        int r = resume ? net_next_match() : -1; /* (a playlist: its next match straight away, no lobby between) */
        if (r != LOCAL_BATTLE) r = run(PAGE_NETWORK);
        else run_open_on = -1;
        from_title = 0;
        if (r != LOCAL_BATTLE && !netplay_lobby()) netplay_friends_page(0); /* (out of Network Play: not shown online) */
        if (r == LOCAL_BATTLE) { /* a server's match: the cars the host's, on from car select's next screen */
            menu_loop_stop_all(1);
            const uint32_t S = GA(0x8016475Cu);
            four_setup(0, -1, -1);
            if (net_match_game == NET_GAME_TOURNAMENT && !net_match_custom) { /* the co-op tournament: level 1, every level from the host's state */
                if (getenv("TM2PC_NET_TOUR_LEVEL")) net_match_level = atoi(getenv("TM2PC_NET_TOUR_LEVEL")); /* tests: from this level (every machine) */
                guest_call(GA(0x80137930u), S, 2, 0, 0);
                guest_call(GA(0x80137900u), S, 0, 0, 0);
                guest_call(GA(0x801378B4u), S, 0, 0, 0);
                guest_call(GA(0x80137864u), S, 0, 0, 0);
                guest_call(GA(0x80137948u), S, 2, 0, 0); /* mode: co-op tournament */
                if (net_match_level == 8) guest_call(GA(0x801377FCu), S, 0, 0, 0); /* (level 8 from its start: Dark Tooth after) */
                guest_call(GA(0x80137814u), S, (uint32_t)net_match_level, 0, 0); /* (level 1, or a saved tournament's) */
                uint32_t value = guest_call(GA(0x8012AFE8u), S, guest_call(GA(0x80137808u), S, 0, 0, 0), 0, 0);
                guest_call(GA(0x80137918u), S, value - guest_call(GA(0x80137924u), S, 0, 0, 0), 0, 0);
                guest_call(GA(0x801378E8u), S, 0, 0, 0);
                guest_call(GA(0x80137820u), S, 0, 6, 0);
                guest_call(GA(0x80137820u), S, 1, 6, 0);
                mem_w8(&M.cpu, S + 36, (uint8_t)(net_match_level >= 5 && net_match_difficulty == 0 ? 1 : net_match_difficulty)); /*
                                                                         * (the host's; a save's from level 5: as a password's) */
                int8_t cars[14];
                memset(cars, -1, sizeof cars);
                const LobbyView *lv = netplay_lobby() ? lobby_view(netplay_lobby()) : NULL;
                for (int h = 2; h < play_players && h < 16; h++) cars[h - 2] = lv ? lv->start.car[h] : lobby_car[h & 3];
                void four_setup_cars(int humans, const int8_t *cars); /* vplus/four.c */
                if (play_players > 2) four_setup_cars(play_players, cars);
                for (int h = 2; h < 16; h++) mod_cars_human_number(h, lv && h < play_players ? lobby_mods_skin_number(lv->start.skin[h]) : -1);
                for (int p = 0; p < play_players && p < 2; p++) guest_call(GA(0x801378A4u), S, (uint32_t)p, lobby_number(p), 0);
                net_tour_on = 1;
                memset(&net_tour_dec, 0, sizeof net_tour_dec); /* (the host's sent anew below: none yet) */
                net_story_n = story_idx = 0;
                if (netplay_lobby() && lobby_is_host(netplay_lobby())) net_send_settings();
                netplay_each_battle(1);
                fprintf(stderr, "network: co-op tournament, %d players, difficulty %d, level %d, cars %d %d\n", play_players,
                        net_match_difficulty, net_match_level, (int)lobby_number(0), (int)lobby_number(1));
                c->r[2] = GA(0x801334C0u); /* the opponents, the globe, the arena */
                return;
            }
            if (net_match_game == NET_GAME_VERSUS) { /* a Versus Tournament: its first stage (the host's setup) */
                const LobbyView *lv = netplay_lobby() ? lobby_view(netplay_lobby()) : NULL;
                if (lv && lv->settings_len == (int)sizeof(NetSettings)) versus_begin((const NetSettings *)lv->settings);
            }
            if (net_match_game == NET_GAME_TOURNAMENT && net_match_custom) { /* a custom co-op tournament: its first stage */
                const LobbyView *lv = netplay_lobby() ? lobby_view(netplay_lobby()) : NULL;
                if (lv && lv->settings_len == (int)sizeof(NetSettings)) coop_custom_begin((const NetSettings *)lv->settings);
            }
            battle_start(net_match_game == NET_GAME_SURVIVAL);
            if (play_players > 2) { /* players 3..: every one's car from the host's start */
                int8_t cars[14];
                memset(cars, -1, sizeof cars);
                const LobbyView *lv = netplay_lobby() ? lobby_view(netplay_lobby()) : NULL;
                for (int h = 2; h < play_players && h < 16; h++) cars[h - 2] = lv ? lv->start.car[h] : lobby_car[h & 3];
                void four_setup_cars(int humans, const int8_t *cars); /* vplus/four.c */
                four_setup_cars(play_players, cars);
            }
            {
                const LobbyView *lv = netplay_lobby() ? lobby_view(netplay_lobby()) : NULL;
                for (int h = 2; h < 16; h++) mod_cars_human_number(h, lv && h < play_players ? lobby_mods_skin_number(lv->start.skin[h]) : -1);
            }
            for (int p = 0; p < play_players && p < 2; p++) guest_call(GA(0x801378A4u), S, (uint32_t)p, lobby_number(p), 0);
            if (trun.versus) versus_cars(); /* (a boss stage first: its driver's car) */
            c->r[2] = lobby_next_for_mode();
            return;
        }
        if (r == LOCAL_LOBBY_CAR) { /* the game's car select, then the lobby (ui_CarSelect: net_carsel) */
            menu_loop_start(); /* (on through car select) */
            Lobby *l = netplay_lobby();
            if (l && !lobby_is_host(l) && lobby_view(l)->settings_len == (int)sizeof(NetSettings)) { /* a joiner: the host's
                                                                                   * game in car select (its teams), ours after */
                static NetSettings cs;
                cs = *(const NetSettings *)lobby_view(l)->settings;
                for (int p = 0; p < 4; p++) cs.match.player_team[p] = net_team[p];
                battle_match_override(&cs.match);
                battle_type_override(&cs.type);
                net_carsel_host_game = 1;
            }
            four_setup(0, -1, -1);
            net_carsel = lobby_pick = 1;
            /* the game's start car (carSelectStartCar) before its screen: it starts the carousel there and its name
             * label with it. Set after the screen began (carsel_start_frame), the carousel moved and the label kept the
             * old car's name until Left / Right (the online lobby's car select, 2026-11-24) */
            if (net_car[0] >= 0 && net_car[0] < 0x20) mem_w32(&M.cpu, GA(0x80180D14u), (uint32_t)net_car[0]);
            c->r[2] = battle_start(0);
            return;
        }
        script = saved_script;
    }
    net_hosting = net_in_server = 0; /* (Local Play's Challenge Match pages: theirs again) */
    play_players = 1;
    c->r[2] = TITLE_SCREEN_FN;
    fprintf(stderr, "title: NETWORK PLAY (menus only)\n");
}
void ui_TitleScreen(CPU *c)
{
    game_started = 1;
    start_once();
    apply_game_settings();
    load_art();
    if ((!M.live_input && !script) || !text_ready() || !bg_title.px) {
        F_8012DF84_orig(c); /* tests and tapes, or without the pictures: the game's own */
        return;
    }
    if (net_return) { /* car select from Network Play's lobby: the lobby again (net_play: the music, one copy) */
        net_return = 0;
        net_play(c, 1);
        return;
    }
    if (netplay_lobby()) { /* the title with a server still joined (an online match quit from the pause, one gone on
                            * alone): out of it, or it lives on unseen, its host's listing too (the user's online playtest
                            * 2026-11-01: Caesar's copy, host after a migration, listed "Tokatta's server" for an hour) */
        fprintf(stderr, "network: left the server (the title)\n");
        netplay_match_end();
        netplay_leave();
        humans_set_map(0, NULL);
        net_tour_on = 0;
        netplay_each_battle(0);
        net_in_server = net_hosting = 0;
        net_server.host = 0;
        battle_match_override(NULL);
        battle_type_override(NULL);
        profile_unlocks_mine();
    }
    if (two_return) { /* a tournament quit: its menu again (2 players: both still signed in) */
        int two = two_return == 2;
        two_return = 0;
        menu_loop_start();
        c->r[2] = two ? GA(0x8012F5F8u) : GA(0x8012E908u); /* the game's 2 Player / 1 Player menu: the port's */
        fprintf(stderr, "title: skipped, back to the %s menu\n", two ? "2 Players" : "Single Player");
        return;
    }
    /* as the game's title: stop sound 27, start the title music at the CD volume */
    menu_loop_stop_all(1);
    rt_vblank(); /* (the stop takes effect at the game's VBlank) */
    music_call(2, 11);
    set_serial_volume((int32_t)guest_call(GA(0x800D362Cu), 0, 0, 0, 0));
    if (script) script_tick = 600 - 24;
    /* the profile screen before the first title menu (the title song plays),
     * and again whenever O is pressed on the title menu */
    static int profiles_shown;
    uint64_t shown;
    int chosen = profiles_shown ? title_run() : TITLE_PROFILES;
    while (chosen == TITLE_PROFILES) {
        profiles_shown = 1;
        startup = 1;
        from_title = 1;
        boom_queued = 0;
        run(PAGE_PROFILES);
        if (boom_queued) menu_sound(1); /* the title menu runs no game VBlank: ours plays out */
        boom_queued = 0;
        startup = 0;
        from_title = 0;
        if (script) script_tick = 600 - 24;
        shown = SDL_GetTicksNS();
        chosen = title_run();
    }
    shown = SDL_GetTicksNS();
    if (chosen < 0) { /* left alone: the attract demo */
        guest_call(GA(0x800D3A44u), mem_r32(&M.cpu, VOL_SERIAL), 0, 0, 0);
        music_call(3, 11);
    } else {
        /* the select explosion, through the game's sound driver (sound 0x1D, as
         * its title's menu): sounds of our own on the SPU are silenced at the
         * game's next VBlank, which takes the voices it isn't using */
        music_call(3, 11); /* the title's music stops first (stopped after, it cut the loop started with the boom) */
        if (!script || getenv("TM2PC_TRAILER")) rt_vblank(); /* (scripted runs: none, the tests' timing as before; trailer footage: heard) */
        menu_loop_start(); /* the submenus' loop at the music's volume (first: started after the boom it took one of its voices) */
        if (!script || getenv("TM2PC_TRAILER")) rt_vblank(); /* (and a VBlank apart: started in the same tick, the boom took the loop's
                                                       * voices and cut it) */
        game_boom();
    }
    set_serial_volume(0);
    if (chosen == 1) { /* Network Play */
        net_play(c, 0);
        return;
    }
    const uint32_t screens[3] = {LOCAL_PLAY_SCREEN, NETWORK_PLAY_SCREEN, OPTIONS_SCREEN};
    c->r[2] = chosen < 0 ? ATTRACT_SCREEN : screens[chosen];
    local_from_title = chosen == 0; /* the 1 Player menu's wrap opens on how many players */
    fprintf(stderr, "title: %s after %.1f s\n", chosen < 0 ? "attract demo" : title_items[chosen],
            (SDL_GetTicksNS() - shown) / 1e9);
}

/* The game's Options screen (80133C08), replaced: the pages run in its
 * place, then the title menu comes back (what its Back does), or the
 * game's History screen for Movies. Like every shell screen it returns the
 * next screen to run. Runs without live input (headless, tapes) keep the
 * original screen. */
void F_80133C08_orig(CPU *c);
void ui_OptionsScreen(CPU *c)
{
    start_once();
    if (!M.live_input && !script) {
        F_80133C08_orig(c);
        return;
    }
    load_art();
    from_title = 1;
    if (script) script_tick = 600 - 24; /* a test script starts just after the pages open */
    /* As the game's own submenus: the title menu's select sound and the menu
     * music loop it queued start within two VBlanks (the game is stopped
     * while the pages are open, so let them run first), and the CD music
     * goes quiet until the title menu starts it again. */
    rt_vblank();
    rt_vblank();
    cd_audio_hold(1);
    boom_queued = 0;
    int result = text_ready() ? run(PAGE_MAIN) : 0;
    cd_audio_hold(0);
    if (boom_queued) game_boom(); /* (now, with its VBlanks: only queued, the title's start silenced it) */
    boom_queued = 0;
    from_title = 0;
    c->r[2] = result == PAGE_MOVIES ? HISTORY_SCREEN : result == PAGE_CREDITS ? GA(0x80136A3Cu) : TITLE_SCREEN;
}

