/* tools: TM2PC_TURNTABLE=dir, 1-player car select's cars, each turned a whole turn, a picture per step
 * (dir/turn_NN_SSS.bmp, NN its car number), with no name, portraits' row or legend: the first car, then Right to
 * the next, until the carousel comes back to the first (or TM2PC_TURNTABLE_CARS cars); then the game closes
 * (tools/art/turntable.py) */
static int turntable_heading = -1;
static int turntable_on(void) { return getenv("TM2PC_TURNTABLE") != NULL; }
static void turntable_vblank(void)
{
    extern uint16_t rt_pad_tool[2]; /* runtime/hle.c */
    static int wait, step = -1, first = -1, done, press;
    int steps = getenv("TM2PC_TURNTABLE_STEPS") ? atoi(getenv("TM2PC_TURNTABLE_STEPS")) : 90;
    int most = getenv("TM2PC_TURNTABLE_CARS") ? atoi(getenv("TM2PC_TURNTABLE_CARS")) : 64;
    if (steps < 1) steps = 1;
    if (press) { /* Right held a few VBlanks: the next car */
        rt_pad_tool[0] = --press > 4 ? 0x20 : 0;
        return;
    }
    /* the car turned steadily, a little every VBlank (as car select turns it: held at each heading and then stepped,
     * the carousel's smoothing of each part's place lagged each step and Mr. Grimm's helmet jumped about; without the
     * smoothing it rocked a pixel, the user's 2026-11-08), a picture every PER VBlanks (a multiple of the game's 3) */
    enum { PER = 6, PRE = 36 };
    static int t;
    if (step < 0) { /* (the titles slid in, the car loaded and settled) */
        if (++wait < (done ? 180 : 300)) return;
        int car = vp_carousel_number();
        if (done && car == first) { fprintf(stderr, "turntable: %d cars\n", done); exit(0); }
        if (first < 0) first = car;
        step = 0, t = -PRE; /* (a turn's start before the first picture: the smoothing's history) */
    }
    turntable_heading = (int)((long long)t * 4096 / ((long long)steps * PER)) & 4095;
    int at = t++;
    if (at < 0 || at % PER) return;
    step = at / PER;
    int w = 0, h = 0;
    unsigned char *px = ui_capture_clean(&w, &h);
    if (px) {
        Image im = {w, h, px};
        char path[600];
        snprintf(path, sizeof path, "%s/turn_%02d_%03d.bmp", getenv("TM2PC_TURNTABLE"), vp_carousel_number(), step);
        image_save_bmp(&im, path);
        free(px);
    }
    if (step + 1 >= steps) {
        fprintf(stderr, "turntable: car %d, %d pictures\n", vp_carousel_number(), steps);
        if (++done >= most) exit(0);
        step = -1, wait = 0, turntable_heading = -1;
        press = 10; /* (6 held, 4 released) */
    }
}

static void carsel_overlay(int force)
{
    static int shown_car = -2, shown_w, shown_h, shown_item, shown_info, shown_number = -2;
    static Image ov;
    int car = vp_carousel_car(), item = carsel_chosen_item(), number = vp_carousel_number(); /* (number: a skin's own) */
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (size.w <= 0 || size.h <= 0) return;
    int live_state = (carsel_live_state() * 2 + carsel_second) * 65536 + carsel_art_gen;
    static int shown_live = -1;
    if (carsel_hd && !carsel_live_on() && !carsel_info) shown_item = item; /* (the HD overlay is the same for either item: the
                                                                             * titles are in the background, composed there) */
    if (!force && car == shown_car && item == shown_item && carsel_info == shown_info && size.w == shown_w &&
        size.h == shown_h && live_state == shown_live && number == shown_number)
        return;
    if (getenv("TM2PC_CARSEL_TRACE")) /* tests: each overlay drawn again, and why */
        fprintf(stderr, "carsel overlay: %llu car %d item %d info %d live %d number %d size %dx%d force %d\n",
                (unsigned long long)M.vblanks, car, item, carsel_info, live_state, number, size.w, size.h, force);
    shown_number = number;
    shown_live = live_state;
    shown_item = item;
    shown_info = carsel_info;
    int info_car = number >= 0x20 ? number : car; /* (a skin: its own CAR INFO) */
    if (carsel_info == 1 && car >= 0 && carinfo_pic(info_car) && image_resize(&ov, size.w, size.h)) {
        /* CAR INFO: its picture over everything (the last frame's car and gold arrows stayed drawn over the game's) */
        memset(ov.px, 0, (size_t)ov.w * ov.h * 3);
        draw_contain(&ov, carinfo_pic(info_car), 0, 0, ov.w, ov.h);
        int r[1][4] = {{0, 0, ov.w, ov.h}};
        Psyz_VideoSetOverlay(ov.px, ov.w, ov.h, &r[0][0], 1);
        return;
    }
    if (carsel_info) { /* (put away: nothing over the game's picture until car select draws itself) */
        Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
        return;
    }
    if (car != shown_car) fprintf(stderr, "car select: car %d\n", car);
    shown_car = car;
    shown_w = size.w;
    shown_h = size.h;
    if (car < 0 || !image_resize(&ov, size.w, size.h)) {
        Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
        return;
    }
    int split = carsel_live_on() && carsel_live_split();
    if (carsel_live_on() && !split && cl_shared_info()) { /* player 1's CAR INFO, the whole window */
        memset(ov.px, 0, (size_t)ov.w * ov.h * 3);
        draw_contain(&ov, carinfo_pic(cl_shared_car()), 0, 0, ov.w, ov.h);
        int r[1][4] = {{0, 0, ov.w, ov.h}};
        Psyz_VideoSetOverlay(ov.px, ov.w, ov.h, &r[0][0], 1);
        return;
    }
    if (split) { /* the layout's sides (beyond the game's picture) and its strip, over everything */
        if (split_win.px && split_win.h == ov.h && split_win.w <= ov.w) {
            /* the strip over the cars (the rest is in the game's picture) */
            int ox = (ov.w - split_win.w) / 2, sy = (int)(ov.h * split_strip_y() / 480.0f), r[1][4];
            int ey = (int)(ov.h * (split_strip_y() + 76) / 480.0f + 0.5f); /* SPLIT_STRIP_H */
            if (ey > ov.h) ey = ov.h;
            for (int y = sy; y < ey; y++)
                memcpy(ov.px + ((size_t)y * ov.w + ox) * 3, split_win.px + (size_t)y * split_win.w * 3, (size_t)split_win.w * 3);
            r[0][0] = ox; r[0][1] = sy; r[0][2] = split_win.w; r[0][3] = ey - sy;
            Psyz_VideoSetOverlay(ov.px, ov.w, ov.h, &r[0][0], 1);
        } else {
            Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
        }
        return;
    }
    if (carsel_hd && turntable_on()) { Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0); return; } /* (tools: the car alone) */
    if (carsel_hd) {
        /* the art is in the background; over everything (the cars and their shadows): the
         * drivers' row and the second portrait of a driver just chosen; the window's sides
         * stay black (the picture mirrored there looked like a fault) */
        const Image *art = split ? &split_bg : &carsel_hd_img;
        int bar_top = split ? 404 : 410, n = 0, rects[4][4]; /* 480 - SPLIT_STRIP_H; CS_BOTTOM */
        if (!art->px) { Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0); return; }
        View v = view_fit(&ov);
        int cw = (int)(640 * v.s + 0.5f);
        float k = art->h / 480.0f;
        int by = Y(&v, bar_top);
        uint64_t tb = SDL_GetTicksNS();
        draw_image(&ov, art, 0, bar_top * k, (float)art->w, (480 - bar_top) * k, v.ox, by, cw, ov.h - by, 0);
        if (getenv("TM2PC_CARSEL_TIMES")) fprintf(stderr, "carsel bar %.1f ms\n", (SDL_GetTicksNS() - tb) / 1e6);
        rects[n][0] = v.ox; rects[n][1] = by; rects[n][2] = cw; rects[n][3] = ov.h - by; n++;
        int sw = 0; /* black sides */
        if (sw > 0 && bg_carsel.px) {
            static const uint8_t black[3] = {0, 0, 0};
            float src = (float)bg_carsel.w * sw / cw;
            draw_image(&ov, &bg_carsel, 0, 0, src, (float)bg_carsel.h, v.ox - sw, 0, sw, ov.h, 1);
            draw_image(&ov, &bg_carsel, bg_carsel.w - src, 0, src, (float)bg_carsel.h, v.ox + cw, 0, sw, ov.h, 1);
            draw_fill(&ov, v.ox - sw, by, sw, ov.h - by, black, 255);
            draw_fill(&ov, v.ox + cw, by, sw, ov.h - by, black, 255);
            rects[n][0] = v.ox - sw; rects[n][1] = 0; rects[n][2] = sw; rects[n][3] = ov.h; n++;
            rects[n][0] = v.ox + cw; rects[n][1] = 0; rects[n][2] = sw; rects[n][3] = ov.h; n++;
        }
        if (carsel_second && !carsel_live_on()) {
            /* the driver just chosen: the game shows no further frame of its screen, so the
             * second portrait (in the art) goes over it, its top above the car */
            int r0 = X(&v, 50), r1 = Y(&v, 10), r2 = S(&v, 140), r3 = Y(&v, 200) - Y(&v, 10);
            draw_image(&ov, art, 50 * k, 10 * k, 140 * k, 190 * k, r0, r1, r2, r3, 0);
            rects[n][0] = r0; rects[n][1] = r1; rects[n][2] = r2; rects[n][3] = r3; n++;
        }
        Psyz_VideoSetOverlay(ov.px, ov.w, ov.h, &rects[0][0], n);
        return;
    }
    if (carsel_live_on()) { /* two players: drawn every change (the cars and their states) */
        int rects2[6][4];
        if (!image_resize(&ov, size.w, size.h)) return;
        carsel_compose2(&ov, item, rects2);
        Psyz_VideoSetOverlay(ov.px, ov.w, ov.h, &rects2[0][0], 6);
        return;
    }
    int rects[3][4];
    carsel_compose(&ov, car, item, rects);
    Psyz_VideoSetOverlay(ov.px, ov.w, ov.h, &rects[0][0], 3);
}

/* Car select, rebuilt (docs/MENUS_PLAN.md): the game's screen keeps its
 * middle (the turning car, the arrows, the name); the port draws the rest at
 * the window's resolution and copies it over (PSY-Z patch 07): the top (the
 * clean picture, the driver's portrait, SELECT CAR / CAR INFO with the
 * chosen one on its bar, the emblem) and the bottom (the drivers' portraits
 * in car select's order, the carousel's framed, in place of the legend).
 * Positions are the game's, measured on its screen (640x480). */
enum { CS_PORTRAIT_X = 50, CS_PORTRAIT_W = 140, CS_PORTRAIT_END = 266 }; /* the game's portrait, to cover */
enum { CS_PORTRAIT_Y = 10 }; /* the game's portrait: 10 lines below the top (measured), x 56..184 */
enum { CS_STATS_TOP = 130, CS_NAME_Y = 396 }; /* the stat bars, under the titles; a 2-player name */
enum { CS_TOP = 204, CS_BOTTOM = 410, CS_ROW_Y = 413, CS_THUMB_W = 31, CS_THUMB_H = 62, CS_PITCH = 37 };
#define SHELL_SCENE GA(0x8016303Cu)
#define ITEM_SELECT_CAR 9001
#define CARSEL_EMBLEM_Y (-2) /* the emblem picture's top: its ring (12 units in) level with the portrait's top, 10 (the game: 40, lower) */

static int carsel_chosen_item(void) /* 9001 SELECT CAR, 9002 CAR INFO: the scene's current item */
{
    uint32_t idx = mem_r32(&M.cpu, SHELL_SCENE + 0x34);
    if (idx > 16) return ITEM_SELECT_CAR;
    uint32_t item = mem_r32(&M.cpu, SHELL_SCENE + 0xA8 + idx * 4);
    return item >= 0x80000000u && item < 0x80000000u + GUEST_RAM_BYTES ? mem_r16(&M.cpu, item) : ITEM_SELECT_CAR;
}

/* draws a part of a sheet (keyed or not) to the 640x480 screen's x, y, w, h */
static void cs_part(const View *v, const Image *img, int sx, int sy, int sw, int sh, float x, float y, float w, float h,
                    int keyed)
{
    static const uint8_t key[3] = {255, 0, 255};
    if (!img->px) return;
    if (keyed)
        draw_image_keyed(v->c, img, (float)sx, (float)sy, (float)sw, (float)sh, X(v, x), Y(v, y), S(v, w), S(v, h), key);
    else
        draw_image(v->c, img, (float)sx, (float)sy, (float)sw, (float)sh, X(v, x), Y(v, y), S(v, w), S(v, h), 0);
}

/* Car select's art (the game's places, 640x480): the driver's portrait (the
 * second one once chosen, as the game), SELECT CAR / CAR INFO, the emblem,
 * the drivers' bar. */
static void draw_car_name_scaled(const View *v, Image *c, const char *name, int cx, int y, int locked, float scale);
static void draw_car_name(const View *v, Image *c, const char *name, int cx, int y, int locked)
{
    draw_car_name_scaled(v, c, name, cx, y, locked, 1);
}
static int names_as_sprites;            /* the drivers' names are drawn by the game (name_sprites), not in the art */
static void name_sprites_off(void);
/* The drivers in car select's portrait bars, in car-select order: all, or
 * (Vanilla Plus "Hide locked drivers") without the secret ones still locked. */
static int cs_available(int car);
static int carsel_teams(void);
static int bar_count(void)
{
    int n = 0;
    for (int col = 0; col < roster_n(); col++)
        n += !vp_on(VP_HIDE_LOCKED_DRIVERS) || grid_car(col) < 12 || cs_available(grid_car(col));
    return n;
}
static int bar_car(int i)
{
    for (int col = 0; col < roster_n(); col++) {
        int car = grid_car(col);
        if (vp_on(VP_HIDE_LOCKED_DRIVERS) && car >= 12 && !cs_available(car)) continue;
        if (i-- == 0) return car;
    }
    return 0;
}

/* A portrait row's window (the user's: many cars, as with mods, scroll): the columns that fit in `width` units centred
 * on `mid`, around the focused car's column; *x0 the first shown one's x. Arrows mark more on a side (bar_arrows). */
static int bar_column(int car) { for (int i = 0; i < bar_count(); i++) if (bar_car(i) == car) return i; return 0; }
static void bar_window(int focus_car, int mid, int width, int pitch, int *first, int *count, int *x0)
{
    int n = bar_count(), fit = (width - 24 + (pitch - CS_THUMB_W)) / pitch; /* (12 units each side for the arrows) */
    if (fit < 1) fit = 1;
    *first = 0, *count = n;
    if (n > fit) {
        int f = bar_column(focus_car) - fit / 2;
        *first = f < 0 ? 0 : f > n - fit ? n - fit : f;
        *count = fit;
    }
    *x0 = mid - (*count * pitch - (pitch - CS_THUMB_W)) / 2;
}
static void bar_arrows(const View *v, Image *img, int first, int count, int x0, int pitch, int y, int h)
{
    int size = S(v, 20);
    if (first > 0)
        text_draw(img, "<", X(v, x0 - 14) - text_width("<", size) / 2, text_top_for_center(Y(v, y + h / 2), size), size, ORANGE);
    if (first + count < bar_count())
        text_draw(img, ">", X(v, x0 + count * pitch - (pitch - CS_THUMB_W) + 8) - text_width(">", size) / 2,
                  text_top_for_center(Y(v, y + h / 2), size), size, ORANGE);
}

static void carsel_art(const View *vp, Image *ovp, int car, int item)
{
    static const uint8_t frame[3] = {60, 60, 66}, copper[3] = {238, 164, 74}, black[3] = {0, 0, 0};
    View v = *vp;
    if (turntable_on()) return; /* (tools: the car on the road and the flames alone, the user's 2026-11-08) */
    int vp_carousel_look(void); /* vplus/fixes.c */
    int number = carsel_live_on() ? car : vp_carousel_look(); /* (a skin, LOOK_DT2: its own name) */
    if (number >= 0x20 && skin_portrait(ovp, number, carsel_second, X(&v, 56), Y(&v, CS_PORTRAIT_Y), S(&v, 128), S(&v, 256)))
        ; /* (a skin: its own picture) */
    else if (car >= PROFILE_CHARACTERS) /* (Dark Tooth, mods: their own picture) */
        draw_car_portrait(&v, car, carsel_second, X(&v, 56), Y(&v, CS_PORTRAIT_Y), S(&v, 128), S(&v, 256));
    else if (portraits.px && portraits.w >= PROFILE_CHARACTERS * 2) {
        float fw = (float)portraits.w / (PROFILE_CHARACTERS * 2);
        /* as the game: the whole portrait, twice the size, from 10 lines down to the road (its bottom is flames) */
        draw_image(ovp, &portraits, (car * 2 + carsel_second) * fw + 1, 1, fw - 2, (float)portraits.h - 1, /* inside its own frame: no edge of the next */ X(&v, 56), Y(&v, CS_PORTRAIT_Y), S(&v, 128),
                   S(&v, 256), 0);
    }
    int sel = item == ITEM_SELECT_CAR;
    /* the sheet: SELECT CAR and CAR INFO on their bar (rows 0-35, 35-71), plain (78-99, 113-134) */
    /* the port's lettering, the chosen one on the copper bar, where the game's are */
    lettering();
    static const char *const cs_items[2] = {"SELECT CAR", "CAR INFO"};
    /* as tall as the game's (18 of its 480 lines) and as wide: larger, narrowed */
    text_set_style(0, 0.97f, 0);
    for (int i = 0; i < 2; i++) {
        int size = S(&v, 34), cy = Y(&v, i ? 106 : 60), w = text_width(cs_items[i], size), x = X(&v, 320 + carsel_title_x[i] / 2) - w / 2; /* sliding in at the start, as the game's */
        if (sel == !i)
            draw_bar(&v, x - S(&v, 16), x + w + S(&v, 16), cy, size);
        text_draw(ovp, cs_items[i], x, text_top_for_center(cy, size), size, WHITE);
    }
    text_set_style(0, 1, 0);
    if (carsel_teams()) { /* teams: Triangle changes yours */
        int size = S(&v, 18), w = legend_text(&v, TRIANGLE " CHANGE TEAM", 0, 0, size, 0);
        legend_text(&v, TRIANGLE " CHANGE TEAM", X(&v, 320) - w / 2, text_top_for_center(Y(&v, 146), size), size, 1);
    }
    cs_part(&v, &emblem1, 0, 0, emblem1.w, emblem1.h, 506, CARSEL_EMBLEM_Y, 115, 115, 1);
    if (carsel_text[0] && gfont_ready(2) && !names_as_sprites && !turntable_on()) /* the game's text under the car, its font sharp (orange once chosen) */
        draw_car_name(&v, ovp, mod_is_look(number) ? car_label(number) : carsel_text, 320, 410, carsel_second); /* (a skin: its name) */
    if (!vp_on(VP_CARSEL_PORTRAITS) && !turntable_on()) { /* the original's legend box over the road (the PS1 art's: x 27-292, y 207-224 of
                                        * 320 x 240), sharp; the art under it is the cleaned road */
        static const uint8_t white[3] = {235, 235, 235};
        static const char *const legend[3] = {CROSS " = SELECT", SQUARE " = MAIN MENU", CIRCLE " = PREVIOUS"};
        int bx = 54, by = 414, bw = 530, bh = 34, line = S(&v, 2) > 1 ? S(&v, 2) : 1;
        draw_fill(ovp, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), white, 255);
        draw_fill(ovp, X(&v, bx) + line, Y(&v, by) + line, S(&v, bw) - 2 * line, S(&v, bh) - 2 * line, black, 255);
        static const int at[3] = {132, 312, 500}; /* (the original's: its lettering fills the box) */
        for (int i = 0; i < 3; i++) {
            int size = S(&v, 20), w = legend_text(&v, legend[i], 0, 0, size, 0);
            legend_text(&v, legend[i], X(&v, at[i]) - w / 2, text_top_for_center(Y(&v, by + bh / 2), size), size, 1);
        }
    }
    /* the bottom: the drivers (Vanilla Plus "Car select portrait bar") */
    int first, shown, x0, row_car = number >= 0x20 && mod_car_is_character(number) ? number : car; /* (a character's own) */
    bar_window(row_car, 320, 640, CS_PITCH, &first, &shown, &x0);
    int bar = vp_on(VP_CARSEL_PORTRAITS) && !turntable_on(); /* (tools: the car alone) */
    if (bar) bar_arrows(&v, ovp, first, shown, x0, CS_PITCH, CS_ROW_Y, CS_THUMB_H);
    for (int col = 0; col < shown && bar; col++) {
        int c = bar_car(first + col), chosen = c == row_car;
        int x = X(&v, x0 + col * CS_PITCH), y = Y(&v, CS_ROW_Y), w = S(&v, CS_THUMB_W), h = S(&v, CS_THUMB_H);
        int t = chosen ? S(&v, 3) : (S(&v, 1) > 1 ? S(&v, 1) : 1);
        draw_fill(ovp, x - t, y - t, w + 2 * t, h + 2 * t, chosen ? copper : frame, 255);
        draw_fill(ovp, x, y, w, h, black, 255);
        draw_car_portrait(&v, c, chosen && carsel_second, x, y, w, h); /* a locked secret driver: "?" */
        if (chosen && carsel_second) draw_fill(ovp, x, y, w, h, black, 110); /* chosen: the second portrait, dimmed */
    }
}

static void carsel_compose(Image *ovp, int car, int item, int rects[][4])
{
    View v = view_fit(ovp);
    memset(ovp->px, 0, (size_t)ovp->w * ovp->h * 3);
    /* the top: the picture, the portrait, the titles, the emblem */
    if (bg_carsel.px) {
        float k = bg_carsel.h / 480.0f;
        cs_part(&v, &bg_carsel, 0, 0, bg_carsel.w, (int)(CS_TOP * k), 0, 0, 640, CS_TOP, 0);
        /* under the portrait, down to where the game's (twice as tall) ends: the flames */
        cs_part(&v, &bg_carsel, (int)(CS_PORTRAIT_X * k), (int)(CS_TOP * k), (int)(CS_PORTRAIT_W * k),
                (int)((CS_PORTRAIT_END - CS_TOP) * k), CS_PORTRAIT_X, CS_TOP, CS_PORTRAIT_W, CS_PORTRAIT_END - CS_TOP, 0);
        cs_part(&v, &bg_carsel, 0, (int)(CS_BOTTOM * k), bg_carsel.w, bg_carsel.h - (int)(CS_BOTTOM * k), 0, CS_BOTTOM,
                640, 480 - CS_BOTTOM, 0);
    }
    carsel_art(&v, ovp, car, item);
    /* the two bands, copied over the game's screen */
    rects[0][0] = X(&v, 0); rects[0][1] = 0; rects[0][2] = S(&v, 640); rects[0][3] = Y(&v, CS_TOP);
    rects[2][0] = X(&v, CS_PORTRAIT_X); rects[2][1] = Y(&v, CS_TOP);
    rects[2][2] = S(&v, CS_PORTRAIT_W); rects[2][3] = Y(&v, CS_PORTRAIT_END) - Y(&v, CS_TOP);
    rects[1][0] = X(&v, 0); rects[1][1] = Y(&v, CS_BOTTOM); rects[1][2] = S(&v, 640); rects[1][3] = ovp->h - Y(&v, CS_BOTTOM);
}

static uint32_t carsel_split(void);

static int coop_duel_next(void);
/* screenDisplayImage (80121C8C): a picture the game puts up directly (LOADING, CAR INFO...) */
void F_80121C8C_orig(CPU *c);
void ui_DisplayImage(CPU *c)
{
    int side = c->r[4] != 0; /* screenDisplayImage(other buffer, tim, x, y) */
    uint32_t ra = c->r[31];
    F_80121C8C_orig(c);
    if (coop_duel_next() && bg_duel.px && ra >= GA(0x80136BB0u) && ra < GA(0x80136D98u)) /* the co-op win's COWIN: the duel's screen */
        Psyz_VideoLoadImageHD(side ? 320 : 0, 0, 320, 240, bg_duel.px, bg_duel.w, bg_duel.h);
    if (carsel_active && ra >= GA(0x801307ECu) && ra < GA(0x80131EECu)) { /* from car select's loop: CAR INFO, the PC's picture */
        const Image *info = carinfo_pic(vp_carousel_number() >= 0x20 ? vp_carousel_number() : vp_carousel_car());
        if (info) Psyz_VideoLoadImageHD(side ? 320 : 0, 0, 320, 240, info->px, info->w, info->h);
    }
}

/* The game's wait for a button (801291CC, here the CAR INFO picture's):
 * while car select shows it, car select's overlay is off. */
#define CAR_SELECT_START GA(0x801307ECu)
#define CAR_SELECT_END GA(0x80131EECu)
void F_801291CC_orig(CPU *c);
void ui_ScreenWait(CPU *c)
{
    uint32_t ra = c->r[31];
    if (!carsel_active || ra < CAR_SELECT_START || ra >= CAR_SELECT_END) {
        F_801291CC_orig(c);
        return;
    }
    carsel_info = 1;
    carsel_overlay(1);
    F_801291CC_orig(c);
    carsel_info = 2; /* put away: the bar again once car select has drawn itself (ui_frame_start) */
    carsel_info_frames = 0;
}

void ui_CarSelect(CPU *c)
{
    start_once();
    load_art();
    int live = (M.live_input || script) && text_ready() && portraits.px && bg_carsel.px;
    int humans = mem_r8(&M.cpu, GA(0x8016475Cu) + 4);
    if (live && humans == 2 && vp_on(VP_CARSEL_MULTI) && getenv("TM2PC_CARSEL_SPLIT")) { /* the earlier port screen */
        c->r[2] = carsel_split();
        return;
    }
    int on = live && humans >= 1; /* one player, or each in turn */
    vp_carousel_forget();
    carsel_start_turn = -1;
    carsel_heard_reset = 1;
    carsel_opened_at = M.vblanks;
    carsel_active = on;
    if (on && humans == 2 && (vp_on(VP_CARSEL_MULTI) || tourney_pick || survival_pick)) { /* both at once, each with a car (3-4 players: always) */
        carsel_live_begin(vp_value(VP_CARSEL_MULTI) == 1, play_players);
    }
    F_801307EC_orig(c);
    if (carsel_live_on())
        fprintf(stderr, "car select (2 players, live): %s and %s, next %08x\n",
                profile_character_name((int8_t)mem_r8(&M.cpu, GA(0x8016475Cu) + 8)),
                profile_character_name((int8_t)mem_r8(&M.cpu, GA(0x8016475Cu) + 9)), c->r[2]);
    carsel_live_end();
    vp_carsel_sound(-1); /* a special's sound (the flame loops) stops with car select */
    if (survival_pick) { /* 3-4 player Survival: each player's car (1-2 the game's, 3-4 the port's), then on as 2 players' */
        survival_pick = 0;
        if (carsel_live_count() > 2 && carsel_live_done()) {
            const uint32_t S = GA(0x8016475Cu);
            for (int p = 0; p < 2; p++) guest_call(GA(0x801378A4u), S, (uint32_t)p, (uint32_t)cs_look(p), 0);
            four_setup(carsel_live_count(), carsel_live_car(2), carsel_live_car(3));
            for (int h = 2; h < 4; h++) mod_cars_human_number(h, h < carsel_live_count() ? cs_look(h) : -1);
            c->r[2] = GA(0x80131EECu); /* on as 2 players' car select goes: the opponents (screenAiSelect), the globe, the arena */
        }
    }
    if (tourney_pick) { /* a 3-4 player tournament: all chose, on to the first level; else back to the menu */
        tourney_pick = 0;
        if (carsel_live_count() > 2 && carsel_live_done()) {
            const uint32_t S = GA(0x8016475Cu);
            for (int p = 0; p < 2; p++) guest_call(GA(0x801378A4u), S, (uint32_t)p, (uint32_t)cs_look(p), 0);
            guest_call(GA(0x80137900u), S, 0, 0, 0);
            four_setup(carsel_live_count(), carsel_live_car(2), carsel_live_car(3));
            for (int h = 2; h < 4; h++) mod_cars_human_number(h, h < carsel_live_count() ? cs_look(h) : -1);
            c->r[2] = GA(0x801334C0u); /* the opponents, the globe, the arena */
        } else {
            c->r[2] = GA(0x8012F5F8u);
            battle_back = 1;
        }
    }
    if (lobby_pick && on) { /* chosen for the lobby: back to it */
        lobby_pick = 0;
        if (carsel_live_count() > 2) { /* 3-4 players: the port's car select (done), or back with the cars as they were */
            for (int p = 0; p < carsel_live_count() && carsel_live_done(); p++) {
                lobby_car[p] = carsel_live_car(p);
                lobby_skin[p] = cs_look(p);
            }
        } else {
            for (int p = 0; p < humans && p < 2; p++) {
                lobby_car[p] = (int8_t)mem_r8(&M.cpu, GA(0x8016475Cu) + 8 + (uint32_t)p); /* (the byte: a skin's car) */
                lobby_skin[p] = (int)guest_call(GA(0x8013788Cu), GA(0x8016475Cu), (uint32_t)p, 0, 0); /* settingsGetHumanCar: the number */
                if (lobby_skin[p] == 14 && (mod_dt2_mask() >> p & 1)) lobby_skin[p] = LOOK_DT2; /* (his second phase) */
            }
        }
        if (net_carsel) { /* Network Play's lobby: the cars there, back to it (through the title: net_return) */
            net_carsel = 0;
            if (net_carsel_host_game) { /* (a joiner: the teams chosen, the host's game off again) */
                for (int p = 0; p < 4; p++) net_team[p] = battle_match()->player_team[p];
                battle_match_override(NULL);
                battle_type_override(NULL);
                net_carsel_host_game = 0;
            }
            for (int p = 0; p < play_players && p < 4; p++) {
                net_car[p] = lobby_car[p];
                net_skin[p] = lobby_skin[p];
                net_ready[p] = 1;
            }
            battle_live = 0;
            net_return = 1;
            c->r[2] = TITLE_SCREEN_FN;
            fprintf(stderr, "network: car chosen (%s), back to the lobby\n", profile_character_name(lobby_car[0]));
            carsel_active = 0;
            name_sprites_off();
            Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
            return;
        }
        lobby_next = c->r[2];
        if (carsel_live_count() > 2 && carsel_live_done()) lobby_next = GA(0x80131EECu); /* 3-4 players (the port's car select, left by "back"): on to the opponents, as a car select done */
        battle_live = 0;
        battle_back = 3;
        c->r[2] = humans == 2 ? GA(0x8012F5F8u) : GA(0x8012E908u);
        fprintf(stderr, "lobby: car chosen (%s), back to the lobby\n", car_label((int)lobby_number(0))); /* (a skin, his second phase: its name) */
        if (script && getenv("TM2PC_LOBBY_SCRIPT")) { script = getenv("TM2PC_LOBBY_SCRIPT"); script_tick = 600 - 24; } /* tests: the lobby again */
    }
    carsel_active = 0;
    name_sprites_off();
    if (on) Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
}

/* ---- car select for two players (docs/MENUS_PLAN.md) ----
 * The game's car select takes the players one after the other on one 3D
 * carousel. Here both choose at once, each on their half (one above the
 * other on a 4:3 window, side by side on a wide one): their driver's large
 * portrait (Portrait 3) and name; the drivers' portraits between the halves,
 * each player's in their color (player 1 red, player 2 blue) with a P1 / P2
 * tag. X locks the driver in, O unlocks it (or, player 1, goes back). A
 * driver one player has locked is taken: the other passes over it (the
 * original allows no duplicate cars). Sweet Tooth and Minion only when
 * unlocked. When both are locked in, the cars are set as the game's car
 * select sets them (801378A4 per player, the count of picks back to 0) and
 * its next screen for the mode follows. */
static const uint8_t PLAYER_COLOR_BASE[4][3] = {{228, 24, 36}, {50, 110, 235}, {50, 190, 70}, {238, 190, 60}};
static int carsel_teams(void);
static const uint8_t (*player_colors(void))[3] /* each player's color: with teams in car select, their team's */
{
    static uint8_t team_cols[4][3];
    if (!carsel_teams()) return PLAYER_COLOR_BASE;
    for (int p = 0; p < 4; p++)
        memcpy(team_cols[p], TEAM_COLOR[battle_match()->player_team[p] % BATTLE_TEAM_COLORS], 3);
    return (const uint8_t (*)[3])team_cols;
}
#define PLAYER_COLOR (player_colors())
/* a driver's frame in the car select strips: one player's color; two: the second inside the first; three or four:
 * the frame in quarters, each the color of the player whose tag is in that corner (P1 top left, P2 top right, P3
 * bottom left, P4 bottom right; a corner no one's: the first player's) */
static void strip_frame(Image *c, int x, int y, int w, int h, int t, unsigned on, int first, int second, const uint8_t *none)
{
    int n = (on & 1) + (on >> 1 & 1) + (on >> 2 & 1) + (on >> 3 & 1);
    if (n >= 3) {
        int mx = x + w / 2, my = y + h / 2;
        for (int k = 0; k < 4; k++) {
            int who = (on >> k & 1) ? k : first, l = (k & 1) ? mx : x - t, r = (k & 1) ? x + w + t : mx;
            int top = (k & 2) ? my : y - t, bot = (k & 2) ? y + h + t : my;
            draw_fill(c, l, top, r - l, bot - top, PLAYER_COLOR[who], 255);
        }
        return;
    }
    draw_fill(c, x - t, y - t, w + 2 * t, h + 2 * t, first >= 0 ? PLAYER_COLOR[first] : none, 255);
    if (second >= 0) draw_fill(c, x - t / 2, y - t / 2, w + t, h + t, PLAYER_COLOR[second], 255);
}
static struct { int car, locked; uint16_t prev; int held_for[2]; int look; } cs2[4]; /* (look: a skin's number, else 0) */
int mod_car_base(int number), mod_car_on(int number), mod_next_look(int number), mod_car_has_looks(int car); /* vplus/mod_cars.c */
static int cs_look(int p) /* the player's car number: their skin (Select), else the car */
{
    int l = cs2[p & 3].look;
    return mod_is_look(l) && mod_car_base(l) == cs2[p & 3].car && mod_car_on(l) ? l : cs2[p & 3].car; /* (a character: its car) */
}
static int cs_cycle_look(int p) /* Select: the car's next look; 0 if the car has no skins on */
{
    if (!mod_car_has_looks(cs2[p].car)) return 0;
    cs2[p].look = mod_next_look(cs_look(p));
    return 1;
}
static int cs_node_car(CPU *c, uint32_t node, int p) /* the look the carousel can show (its children: skins once extended) */
{
    int l = cs_look(p);
    return l < mem_r8(c, node + 6) ? l : cs2[p].car;
}
static int cs_players = 2; /* how many choose in the live car select (3 and 4: the port's, cl.n) */

static int cs_available(int car)
{
    if (!M.ram) return car >= 0 && car < 12; /* previews: the game is not running */
    if (car == 12) return mem_r8(&M.cpu, GA(0x80180D04u)) != 0;
    if (car == 13) return mem_r8(&M.cpu, GA(0x80180D05u)) != 0;
    if (car == 14) return vp_dt_player_offered();
    if (car >= 0x20) return mod_car_is_character(car) && mod_car_on(car); /* (a character; skins only through Select) */
    return car >= 0 && car < 12;
}

static int cs_taken(int p, int car) /* another player has locked this car in */
{
    if (vp_on(VP_DUPLICATE_CARS)) return 0;
    for (int q = 0; q < cs_players && q < 4; q++)
        if (q != p && cs2[q].locked && cs2[q].car == car) return 1;
    return 0;
}

static void cs_step(int p, int dir)
{
    int col = grid_column(cs2[p].car), n = roster_n();
    for (int tries = 0; tries < n; tries++) {
        col = (col + dir + n) % n;
        int c = grid_car(col);
        if (cs_available(c) && !cs_taken(p, c)) { cs2[p].car = c; cs2[p].look = 0; return; }
    }
}

static void draw_cover(Image *c, const Image *img, int x, int y, int w, int h)
{ /* the picture filling the box, its middle kept */
    if (!img->px || w <= 0 || h <= 0) return;
    float sa = (float)img->w / img->h, da = (float)w / h, sw = (float)img->w, sh = (float)img->h, sx = 0, sy = 0;
    if (sa > da) { sw = img->h * da; sx = (img->w - sw) / 2; }
    else { sh = img->w / da; sy = (img->h - sh) / 2; }
    draw_image(c, img, sx, sy, sw, sh, x, y, w, h, 0);
}

static void compose_cs2(Image *c)
{
    static const uint8_t black[3] = {0, 0, 0}, frame[3] = {60, 60, 66};
    int W = c->w, H = c->h, side = W * 3 > H * 4 + H / 2; /* side by side on a wide window */
    lettering();
    memset(c->px, 0, (size_t)W * H * 3);
    float s = H / 480.0f;
    int row_h = (int)(70 * s), thumb_h = (int)(52 * s), thumb_w = thumb_h / 2, pitch = thumb_w + (int)(6 * s);
    for (int p = 0; p < 2; p++) {
        int hx, hy, hw, hh; /* the half */
        if (side) { hx = p * W / 2; hy = 0; hw = W / 2; hh = H - row_h; }
        else { hx = 0; hw = W; hh = (H - row_h) / 2; hy = p ? hh + row_h : 0; }
        draw_cover(c, &bg_carsel, hx, hy, hw, hh);
        draw_fill(c, hx, hy, hw, hh, black, 90);
        /* the driver's large portrait */
        int ph = hh - (int)(24 * s), pw = ph / 2, px = side ? hx + hw / 2 - pw / 2 - (int)(60 * s) : hx + hw / 2 - pw - (int)(30 * s);
        int py = hy + (int)(12 * s), t = (int)(3 * s) > 1 ? (int)(3 * s) : 1;
        draw_fill(c, px - t, py - t, pw + 2 * t, ph + 2 * t, PLAYER_COLOR[p], 255);
        if (skin_portrait(c, cs_look(p), 0, px, py, pw, ph)) ; /* (a skin: its own) */
        else if (cs2[p].car >= PROFILE_CHARACTERS) draw_car_portrait(&(View){c, s, 0}, cs2[p].car, 0, px, py, pw, ph);
        else draw_portrait_image(&(View){c, s, 0}, cs2[p].car * PROFILE_PORTRAITS + 2, px, py, pw, ph);
        /* the player, the driver's name, the state */
        int tx = px + pw + (int)(24 * s), size = (int)(30 * s), small = (int)(18 * s);
        char line[48];
        snprintf(line, sizeof line, "PLAYER %d", p + 1);
        TextColor pc = {{PLAYER_COLOR[p][0], PLAYER_COLOR[p][1], PLAYER_COLOR[p][2]},
                        {(uint8_t)(PLAYER_COLOR[p][0] * 3 / 4), (uint8_t)(PLAYER_COLOR[p][1] * 3 / 4),
                         (uint8_t)(PLAYER_COLOR[p][2] * 3 / 4)}};
        text_draw(c, line, tx, py + (int)(10 * s), small, pc);
        snprintf(line, sizeof line, "%s", car_label(cs_look(p)));
        for (char *q = line; *q; q++) *q = (char)toupper((unsigned char)*q);
        text_draw(c, line, tx, py + (int)(40 * s), size, WHITE);
        const char *st = cs2[p].locked ? "READY" : "CHOOSING";
        text_draw(c, st, tx, py + (int)(90 * s), small, cs2[p].locked ? ORANGE : GRAY);
    }
    /* the drivers between the halves (at the bottom when side by side) */
    int ry = side ? H - row_h : (H - row_h) / 2;
    draw_fill(c, 0, ry, W, row_h, black, 255);
    int x0 = W / 2 - (PROFILE_CHARACTERS * pitch - (pitch - thumb_w)) / 2, ty = ry + (row_h - thumb_h) / 2;
    int tag = (int)(12 * s);
    for (int col = 0; col < PROFILE_CHARACTERS; col++) {
        int car = grid_car(col), x = x0 + col * pitch, t = (int)(2 * s) > 1 ? (int)(2 * s) : 1;
        int on0 = cs2[0].car == car, on1 = cs2[1].car == car;
        draw_fill(c, x - 2 * t, ty - 2 * t, thumb_w + 4 * t, thumb_h + 4 * t,
                  on0 ? PLAYER_COLOR[0] : on1 ? PLAYER_COLOR[1] : frame, 255);
        if (on0 && on1) /* both: player 2 inside player 1 */
            draw_fill(c, x - t, ty - t, thumb_w + 2 * t, thumb_h + 2 * t, PLAYER_COLOR[1], 255);
        draw_portrait_image(&(View){c, s, 0}, car * PROFILE_PORTRAITS, x, ty, thumb_w, thumb_h);
        if (!cs_available(car) && car < PROFILE_CHARACTERS && !profile_picture_secret(car * PROFILE_PORTRAITS))
            draw_fill(c, x, ty, thumb_w, thumb_h, black, 170);
        for (int p = 0; p < 2; p++) /* the P1 / P2 tags; a locked-in driver darkened */
            if (cs2[p].car == car) {
                /* P1 top left, P2 top right (P3 bottom left, P4 bottom right) */
                char tg[4] = {'P', (char)('1' + p), 0};
                int tw = text_width(tg, tag), right = p & 1, bottom = p >= 2;
                int gx = x + (right ? thumb_w - tw - 2 : 0), gy = ty + (bottom ? thumb_h - tag - 2 : 0);
                draw_fill(c, gx, gy, tw + 2, tag + 2, PLAYER_COLOR[p], 255);
                text_draw(c, tg, gx + 1, gy, tag, WHITE);
                if (cs2[p].locked) draw_fill(c, x, ty, thumb_w, thumb_h, black, 80);
            }
    }
}

static uint32_t carsel_split(void)
{
    const uint32_t S = GA(0x8016475Cu);
    memset(cs2, 0, sizeof cs2);
    cs2[0].car = 7; /* Roadkill, as the game's carousel starts; player 2 on the next */
    cs2[1].car = 7;
    cs_step(1, 1);
    cs2[0].prev = cs2[1].prev = 0xFFFF;
    uint64_t p2_tick = 600 - 24;
    if (script) script_tick = 600 - 24;
    int result = -1, dirty = 1;
    Image canvas = {0, 0, NULL};
    display_hold = 0; /* this page takes the screen */
    Psyz_VideoSetDisplayRGB24Fill(1);
    uint64_t next = SDL_GetTicksNS();
    while (result < 0) {
        for (int p = 0; p < 2 && result < 0; p++) {
            uint16_t b = signin_input(p, &p2_tick), pressed = (uint16_t)(b & ~cs2[p].prev);
            static const uint16_t dirs[2] = {B_LEFT, B_RIGHT};
            for (int d = 0; d < 2; d++) {
                if (!(b & dirs[d])) { cs2[p].held_for[d] = 0; continue; }
                if (++cs2[p].held_for[d] > 18 && (cs2[p].held_for[d] - 18) % 5 == 0) pressed |= dirs[d];
            }
            cs2[p].prev = b;
            if (!cs2[p].locked && (pressed & (B_LEFT | B_RIGHT))) {
                cs_step(p, (pressed & B_LEFT) ? -1 : 1);
                menu_sound(0);
                dirty = 1;
            } else if (!cs2[p].locked && (pressed & (B_CROSS | B_START))) {
                cs2[p].locked = 1;
                menu_sound(1);
                if (cs_taken(1 - p, cs2[1 - p].car) && !cs2[1 - p].locked) cs_step(1 - p, 1); /* no duplicates */
                dirty = 1;
            } else if (!cs2[p].locked && (pressed & B_SELECT) && cs_cycle_look(p)) { /* Select: the car's next skin */
                menu_sound(0);
                dirty = 1;
            } else if (pressed & (B_CIRCLE | B_SELECT)) {
                menu_sound(1);
                if (cs2[p].locked) cs2[p].locked = 0;
                else if (p == 0) result = 0;
                dirty = 1;
            }
        }
        if (cs2[0].locked && cs2[1].locked) result = 1;
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) &&
            image_resize(&canvas, size.w, size.h)) {
            compose_cs2(&canvas);
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
            dirty = 0;
        }
        ui_audio_frame();
        ui_vsync();
        next += 1000000000ull / 60;
        uint64_t now = SDL_GetTicksNS();
        if (next > now) SDL_DelayNS(next - now);
        else next = now;
    }
    display_to_game(&canvas);
    image_free(&canvas);
    uint32_t mode = guest_call(GA(0x8013793Cu), S, 0, 0, 0);
    if (result == 0) { /* back, where the game's car select goes back to */
        fprintf(stderr, "car select (2 players): back\n");
        return mode == 1 ? GA(0x8012E908u) : (mode == 3 || mode == 4) ? GA(0x8012FD30u) : mode == 2 ? GA(0x8012F5F8u) : GA(0x8012DF84u);
    }
    for (int p = 0; p < 2; p++)
        guest_call(GA(0x801378A4u), S, (uint32_t)p, (uint32_t)cs_look(p), 0); /* (settingsSetHumanCar: a skin's number too) */
    guest_call(GA(0x80137900u), S, 0, 0, 0);
    fprintf(stderr, "car select (2 players): %s and %s\n", car_label(cs_look(0)), car_label(cs_look(1)));
    return mode == 3 ? GA(0x80131EECu) : mode == 4 ? GA(0x801334E8u) : (mode == 1 || mode == 2) ? GA(0x801334C0u) : GA(0x8012DF84u);
}

/* ---- car select for two players, live (Vanilla Plus "New multiplayer car select") ----
 * The game's own car select runs (its picture, camera, lights and turning
 * carousel), and each player gets a car of their own (decomp
 * CAR_SELECT_CAR.md): the carousel's draw (80122124) is called once per
 * player, with that player's car (the model node's byte +7), place, heading
 * and animation, and its projection centre moved into the player's half
 * (after viewProc, 80155E80). The players' buttons drive the cars here: Left
 * and Right slide to the next car, R1 picks one at random (the car drops away
 * and comes back), X locks it in, O unlocks it (player 1 not locked: back).
 * The game's pads see nothing meanwhile; when both are locked in, the game
 * is given X once per player, with the carousel on that player's car, and
 * records the cars itself. The arrows and the game's name label are not
 * drawn: the port draws each player's name, the portraits (player 1 top left,
 * player 2 top right) and the portrait bar with the P1 / P2 tags. */
#define CAROUSEL_OBJ 9005
#define ARROW_OBJ 9004
static struct {
    int on, frame_vblank, finishing, inject_p, inject_t, back, dirty;
    int split;           /* split screen: each player's own car select (else one shared screen) */
    int shared_info;     /* the shared screen: player 1's CAR INFO is up */
    uint64_t last_vblank;
    uint64_t p2_tick;
    struct { int anim, t, dir, heading, x, y, z, title, info; } p[4]; /* title 0 SELECT CAR, 1 CAR INFO; info: shown */
    int n;               /* players choosing: 2, or the port's 3 and 4 (handed back to the lobby, not to the game) */
    int done;            /* 3-4 players: all chose (the back to the game is a hand-over to the lobby) */
} cl;
static int cl_on_script(int p) { return cl.on && p < cl.n; }
static int carsel_live_count(void) { return cl.n; }
static int carsel_live_done(void) { return cl.done; }
static int cs_byte(int car) { return car >= 0x20 ? mod_car_base(car) : car; } /* the settings' byte: a character's base */
static int carsel_live_car(int p) { return cs_byte(cs2[p & 3].car); }
/* player p's car number in car select (a mod's own), -1 none: the carousel's models (vplus/mod_cars.c, decomp request 71, CAR_PROFILES.md) */
int carsel_shown(int p)
{
    if (cl.on) return p < cl.n ? (cs_look(p) == LOOK_DT2 ? LOOK_DT2 : cs2[p & 3].car) : -1; /* (his second phase: its model) */
    int vp_carousel_look(void); /* vplus/fixes.c: the carousel's look (LOOK_DT2 too) */
    return carsel_active && p == 0 ? vp_carousel_look() : -1;
}
enum { CL_IDLE, CL_SLIDE_OUT, CL_SLIDE_IN, CL_DROP, CL_RISE };

static int cl_env(const char *name, int dflt) { const char *e = getenv(name); return e ? atoi(e) : dflt; }
/* the place of each car (world, before the projection's shift) and the shift (320x240 screen) */
#define CL_Y cl_env("TM2PC_CL_Y", -820)
#define CL_Z cl_env("TM2PC_CL_Z", -40)
#define CL_DX cl_env("TM2PC_CL_DX", 80)
#define CL_DY cl_env("TM2PC_CL_DY", 40)
#define CL1_Y (-960) /* the one-player screen's car (the game's place for it) */
#define CL1_Z (-30)
static int shared_dx(int p) /* 2 players: the game's places; 3-4: evenly across the picture */
{
    if (cl.n <= 2) return p ? CL_DX : -CL_DX;
    return (640 * (2 * p + 1) / (2 * cl.n) - 320) / 2;
}
/* 3-4 cars: smaller, to fit: the largest with four Mr. Slams (the widest) side by side, and three clear of the whole
 * portraits above them (were 0.8 and 0.66: small, the user's 2026-11-04; tests: TM2PC_SHARED_SCALE=3P,4P) */
static float shared_scale(void)
{
    static float s3 = 0.9f, s4 = 0.8f;
    static int read;
    if (!read) { read = 1; if (getenv("TM2PC_SHARED_SCALE")) sscanf(getenv("TM2PC_SHARED_SCALE"), "%f,%f", &s3, &s4); }
    return cl.n <= 2 ? 1.0f : cl.n == 3 ? s3 : s4;
}
#define CL_SLIDE (cl.split ? 8 : 16) /* a slide's step a frame (10 frames); short when split, to stay in the view */
/* further back for the big ones, so each car stays in its half (by car-select index) */
static const int16_t CL_CAR_DEPTH[15] = {
    70, 0, 0, 0, 0, 0, 0, 0, 0, /* Hammerhead .. Twister */
    160, 130, 0,                /* Axel, Mr. Slam, Shadow */
    70, 120,                    /* Sweet Tooth, Minion */
    0,                          /* Dark Tooth (his in-game model: carsel_far) */
};

static int carsel_live_on(void) { return cl.on; }
int ui_carsel_live(void) { return cl.on; }
int ui_carsel_game(void) { return carsel_active && !cl.on; } /* the game's own car select (its carousel) is up */
/* the hand-over to the game's car select (its X or O per player): its own sounds
 * (the select boom each time) are not played; ours already was */
int ui_mute_game_sounds(void) { return cl.on && cl.finishing; }
static int carsel_live_split(void) { return cl.on && cl.split; }
static int cl_shared_info(void) { return cl.on && cl.shared_info; }
static int cl_shared_car(void) { return cs_look(0); } /* (CAR INFO: a skin's own) */
static int carsel_live_state(void) /* what the overlay shows: the cars and who is locked in */
{
    if (!cl.on) return 0;
    int st = 1 + 1024 * cl.shared_info;
    for (int p = 0; p < cl.n; p++)
        st = st * 131 + cs2[p].car * 2 + cs2[p].locked + 32 * (battle_match()->player_team[p] % 4) + 256 * cs_look(p);
    return st;
}

/* The game's pads (active-low) while live: nothing, except the hand-over.
 * Back: O. Both locked in: for each player in turn (the game's count of
 * picks, settings +6), X held 4 VBlanks once the game has waited 10; the
 * carousel is then on that player's car (ui_SceneDraw). */
#define PSX_CROSS_BIT 0x4000u /* the raw pad halfword (input.c) */
#define PSX_CIRCLE_BIT 0x2000u
static uint16_t cl_pad_filter(int player, uint16_t buttons)
{
    (void)buttons;
    if (cl.on && player == 1) M.pad_connected[1] = 1; /* player 2 is here (signed in), even on the keyboard or in tests */
    if (!cl.on || !cl.finishing) return 0xFFFF;
    if (player == 0) cl.inject_t++; /* once a VBlank */
    if (cl.back)
        return cl.inject_t <= 4 ? (uint16_t)~PSX_CIRCLE_BIT : 0xFFFF;
    int picks = mem_r8(&M.cpu, GA(0x8016475Cu) + 6);
    if (player == 0 && picks != cl.inject_p) {
        fprintf(stderr, "car select (live): picks %d\n", picks);
        cl.inject_p = picks;
        cl.inject_t = 0;
    }
    /* each player's X on their own pad (the challenge mode, co-op Survival: both on pad 1, as its car select reads) */
    int pad = mem_r8(&M.cpu, GA(0x8016475Cu)) == 3 ? 0 : cl.inject_p;
    if (cl.inject_p >= 2 || player != pad) return 0xFFFF;
    if (cl.inject_t > 120) cl.inject_t = 0; /* not taken: again */
    return cl.inject_t > 45 && cl.inject_t <= 49 ? (uint16_t)~PSX_CROSS_BIT : 0xFFFF;
}

static void carsel_live_begin(int split, int n)
{
    memset(&cl, 0, sizeof cl);
    memset(cs2, 0, sizeof cs2);
    cl.n = cs_players = n < 2 ? 2 : n > 4 ? 4 : n;
    for (int p = 0; p < cl.n; p++) { /* Roadkill, as the game's carousel starts; the others on the next ones */
        cs2[p].car = p ? cs2[p - 1].car : 7;
        if (p) cs_step(p, 1);
        /* from the lobby: the car chosen there (the user's 2026-11-17: each player on their own car) */
        if (lobby_pick && !script && p < 4 && lobby_car[p] >= 0 && lobby_car[p] < 0x20 && cs_available(lobby_car[p]))
            cs2[p].car = lobby_car[p];
        cs2[p].prev = 0xFFFF;
    }
    cl.p2_tick = 600 - 24;
    if (getenv("TM2PC_TRAILER")) p34_ticks[0] = p34_ticks[2] = p34_ticks[3] = 600 - 24; /* (trailer footage: TM2PC_CARSEL_P3_SCRIPT / P4 from
                                                                         * their start, as player 2's; the tests' baselines as they were) */
    if (script) script_tick = 600 - 24;
    if (script && getenv("TM2PC_CARSEL_SCRIPT")) script = getenv("TM2PC_CARSEL_SCRIPT"); /* tests: car select's own */
    if (getenv("TM2PC_CARSEL_P2_SCRIPT")) p2_script = getenv("TM2PC_CARSEL_P2_SCRIPT");
    cl.on = 1;
    cl.split = split;
    cl.last_vblank = (uint64_t)-1;
    rt_pad_filter = cl_pad_filter;
}

static void split_wide_apply(int on);
static void carsel_live_end(void)
{
    if (!cl.on) return;
    if (cl.split) split_wide_apply(0);
    cl.on = 0;
    rt_pad_filter = NULL;
}

static int carsel_teams(void);
static void team_cycle(int p);
/* one scene frame of a player's car: input, then its animation */
static void cl_player_frame(int p)
{
    uint16_t b = signin_input(p, &cl.p2_tick), pressed = (uint16_t)(b & ~cs2[p].prev);
    cs2[p].prev = b;
    static int was[4] = {-1, -1, -1, -1};
    int now = cs2[p].locked + 2 * cl.p[p].info + 4 * cl.p[p].title;
    if (now != was[p] && getenv("TM2PC_CARSEL_PLAYERS")) /* tests: a player's lock, CAR INFO and title */
        fprintf(stderr, "car select: player %d locked %d info %d title %d anim %d (pressed %04X)\n", p + 1, now & 1, (now >> 1) & 1,
                now >> 2, cl.p[p].anim, pressed);
    was[p] = now;
    if (cl.finishing) pressed = 0;
    if (!cl.split && cl.shared_info) { /* player 1's CAR INFO up: only player 1, to put it away */
        if (p == 0 && (pressed & (B_CROSS | B_CIRCLE | B_START | B_SELECT | B_SQUARE))) { cl.shared_info = 0; menu_sound(1); }
        return;
    }
    if (!cl.split && p == 0 && (pressed & B_SQUARE) && cl.p[0].anim == CL_IDLE) {
        cl.shared_info = 1;
        menu_sound(1);
        return;
    }
    if (cl.split && cl.p[p].info) { /* CAR INFO up: X, O or Start puts it away */
        if (pressed & (B_CROSS | B_CIRCLE | B_START | B_SELECT)) { cl.p[p].info = 0; menu_sound(1); }
        pressed = 0;
    } else if (cl.split && cl.p[p].anim == CL_IDLE && !cs2[p].locked && (pressed & (B_UP | B_DOWN))) {
        cl.p[p].title ^= 1;
        menu_sound(0);
        pressed = 0;
    } else if (cl.split && cl.p[p].title && cl.p[p].anim == CL_IDLE && !cs2[p].locked &&
               (pressed & (B_CROSS | B_START))) {
        cl.p[p].info = 1;
        menu_sound(1);
        pressed = 0;
    }
    if (!cs2[p].locked && (pressed & B_TRIANGLE) && carsel_teams()) { team_cycle(p); pressed = 0; } /* the next team */
    if (cl.p[p].anim == CL_IDLE && !cs2[p].locked) {
        if (pressed & (B_LEFT | B_RIGHT)) {
            cl.p[p].anim = CL_SLIDE_OUT;
            cl.p[p].t = 0;
            cl.p[p].dir = (pressed & B_RIGHT) ? 1 : -1;
            menu_sound(0);
        } else if (pressed & (1 << 11)) { /* R1: a random car */
            cl.p[p].anim = CL_DROP;
            cl.p[p].t = 0;
            menu_sound(0);
        } else if (pressed & (B_CROSS | B_START)) {
            if (cs_taken(p, cs2[p].car)) {
                denied_sound();
            } else {
                cs2[p].locked = 1;
                menu_sound(1);
                for (int q = 0; q < cl.n; q++) /* no duplicates */
                    if (q != p && !cs2[q].locked && cs_taken(q, cs2[q].car)) cs_step(q, 1);
            }
        } else if ((pressed & B_SELECT) && cs_cycle_look(p)) { /* Select: the car's next skin */
            menu_sound(0);
        } else if (pressed & (B_CIRCLE | B_SELECT)) {
            if (p == 0) { cl.finishing = 1; cl.back = 1; cl.inject_t = 0; menu_sound(1); }
        }
    } else if (cs2[p].locked && (pressed & (B_CIRCLE | B_SELECT))) {
        cs2[p].locked = 0;
        menu_sound(1);
    }
    /* the animations, as the game's (CAR_SELECT_CAR.md 5): 10 frames each way */
    switch (cl.p[p].anim) {
    case CL_SLIDE_OUT:
        cl.p[p].x += cl.p[p].dir * CL_SLIDE;
        if (++cl.p[p].t >= 10) {
            cs_step(p, cl.p[p].dir);
            vp_carsel_sound(cs_byte(cs2[p].car));
            cl.p[p].x = -cl.p[p].dir * CL_SLIDE * 10;
            cl.p[p].anim = CL_SLIDE_IN;
            cl.p[p].t = 0;
        }
        break;
    case CL_SLIDE_IN:
        cl.p[p].x += cl.p[p].dir * CL_SLIDE;
        if (++cl.p[p].t >= 10) { cl.p[p].x = 0; cl.p[p].anim = CL_IDLE; }
        break;
    case CL_DROP: /* down out of view (split: away into the distance) */
        if (cl.split) cl.p[p].y += 300;
        else cl.p[p].z -= 320;
        if (++cl.p[p].t >= 10) {
            for (int tries = 0; tries < 64; tries++) { /* an allowed car, at random */
                int car = grid_car((int)SDL_rand(roster_n()));
                if (cs_available(car) && !cs_taken(p, car)) { cs2[p].car = car; cs2[p].look = 0; break; }
            }
            vp_carsel_sound(cs_byte(cs2[p].car));
            cl.p[p].x = 0;
            cl.p[p].y = cl.split ? 3000 : 320; /* further back and lower, half turned */
            cl.p[p].z = cl.split ? 0 : -80;
            cl.p[p].heading = 2048;
            cl.p[p].anim = CL_RISE;
            cl.p[p].t = 0;
        }
        break;
    case CL_RISE: /* toward the camera, rising */
        cl.p[p].y -= cl.split ? 300 : 32;
        cl.p[p].z += cl.split ? 0 : 8;
        if (++cl.p[p].t >= 10) { cl.p[p].y = 0; cl.p[p].z = 0; cl.p[p].anim = CL_IDLE; }
        break;
    }
    if (cl.p[p].anim != CL_DROP) cl.p[p].heading = (cl.p[p].heading + 20) & 4095;
}

/* once per scene frame: both players, then the hand-over to the game */
static struct { int x, y, z, heading; } cl_prev[4]; /* each player's car one scene frame before (in-between frames) */
static void cl_frame(void)
{
    for (int p = 0; p < 4; p++)
        cl_prev[p].x = cl.p[p].x, cl_prev[p].y = cl.p[p].y, cl_prev[p].z = cl.p[p].z, cl_prev[p].heading = cl.p[p].heading;
    int all = 1;
    for (int p = 0; p < cl.n; p++) { cl_player_frame(p); all &= cs2[p].locked; }
    if (!cl.finishing && all) {
        cl.finishing = 1;
        cl.inject_p = mem_r8(&M.cpu, GA(0x8016475Cu) + 6);
        cl.inject_t = 0;
        if (cl.n > 2) { cl.back = 1; cl.done = 1; } /* 3-4 players: back to the lobby with the cars (the game takes 2) */
    }
    cl.dirty = 1;
}

/* A driver's name as the game writes it under the car (font 2, its yellow),
 * centered on cx with its baseline at y (640x480); orange once locked in. */
static void draw_car_name_scaled(const View *v, Image *c, const char *name, int cx, int y, int locked, float scale)
{
    static const uint8_t yellow[3] = {255, 161, 0}, orange[3] = {255, 84, 0};
    if (!gfont_ready(2)) return;
    float gs = scale == 1 ? S(v, 2) : 2 * scale * v->s; /* (a split view: the one-player name at the view's scale) */
    gfont_draw(c, 2, name, X(v, cx) - gfont_width(2, name) * gs / 2, Y(v, y), gs, locked ? orange : yellow);
}

/* ---- the split screen: each player's view (640x480 screen units), the portraits' strip ---- */
/* The split screen is laid out on the whole window, in units of a 480-line
 * screen: split_wu wide (640 at 4:3, more when wider). Each player's view is
 * half of it (side by side over the strip); the game's 4:3 picture is its
 * middle 640 units, where the cars are drawn. 3-4 players: quarters, the
 * strip between the top and bottom rows. */
enum { SPLIT_STRIP_H = 76 };
#define SPLIT_NAME_Y 465        /* a split view's name: its line on the one-player screen's art (one player's: 410), */
#define SPLIT_NAME_SCALE 1.5f   /* and its size (one player's: 1), clear of the car in the road's free space */
static float split_wu = 640;
/* The split screen's width in the window (pixels): the window's, up to both
 * players' pictures whole side by side (black beyond). The game draws its
 * picture squeezed to 4:3 (its camera's x axis scaled) and it is shown
 * stretched over this width (PSY-Z patch 09), so the cars can be anywhere. */
#define VIEW_MODE1_AXIS_X (RB_viewModeTable + 0x60u + 0x28u) /* the shell scenes' view mode (1): its camera's x axis scale (4096) */
static int split_content_w(int W, int H)
{
    if (getenv("TM2PC_TEST_WIDE")) W = H * atoi(getenv("TM2PC_TEST_WIDE")) / 100; /* tests: as a window this wide (% of its height) */
    if (cl.n > 2) return H * 4 / 3; /* 3-4 players: quarters of the 4:3 picture (their art at its size) */
    int pics = (int)(2 * H * (480 - SPLIT_STRIP_H) / 480.0f * 4 / 3);
    int wc = W < pics ? W : pics;
    return wc < H * 4 / 3 ? H * 4 / 3 : wc;
}
static void split_wide_apply(int on)
{
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (on && size.w > 0 && size.h > 0) {
        int wc = split_content_w(size.w, size.h);
        Psyz_VideoSetGameAspect((float)wc / size.h);
        mem_w16(&M.cpu, VIEW_MODE1_AXIS_X, (uint16_t)(int)(4096.0f * (size.h * 4.0f / 3) / wc + 0.5f));
    } else {
        Psyz_VideoSetGameAspect(0);
        mem_w16(&M.cpu, VIEW_MODE1_AXIS_X, 4096);
    }
}
static int split_strip_y(void) /* the strip's top (screen units): 3-4 players, between the rows; else the bottom */
{
    return cl.n > 2 ? (480 - SPLIT_STRIP_H) / 2 : 480 - SPLIT_STRIP_H;
}
static void split_view(int p, int *x, int *y, int *w, int *h)
{
    if (cl.n > 2) { /* quarters; 3 players: player 1 top middle, 2 and 3 below */
        int qh = (480 - SPLIT_STRIP_H) / 2;
        *w = 320;
        *h = qh;
        if (cl.n == 3 && p == 0) { *x = 160; *y = 0; }
        else {
            int q = cl.n == 3 ? p + 1 : p;
            *x = (q & 1) ? 320 : 0;
            *y = (q & 2) ? qh + SPLIT_STRIP_H : 0;
        }
        return;
    }
    *x = p ? (int)(split_wu / 2) : 0;
    *y = 0;
    *w = (int)(split_wu / 2);
    *h = 480 - SPLIT_STRIP_H;
}
/* The car in a player's view, in proportion to the art behind it: the art is the full screen's (640x480
 * units) scaled into the view (quarters: covering it; 2 players: as tall as it), centered; the car is drawn
 * as on the one-player screen (its place, the camera), its projection scaled by the same factor (f: H times
 * f, which scales the whole picture about the projection's centre) and that centre moved to the view's
 * (dx, dy: 320x240 units). So the car stands where the game's stands on the art, at the art's size. */
/* A split view's one-player screen: as large as fits whole in the view, centered (2 players on a 16:9 window: the
 * halves are narrower than 4:3, so as wide as the half, black above and below); *ax, *ay its top left. */
static float split_art(int p, float *ax, float *ay)
{
    int x, y, w, h;
    split_view(p, &x, &y, &w, &h);
    float af = fminf(h / 480.0f, w / 640.0f);
    *ax = x + (w - 640 * af) / 2;
    *ay = y + (h - 480 * af) / 2;
    return af;
}
static void split_projection(int p, int *dx, int *dy, float *f)
{
    int x, y, w, h;
    float ax, ay;
    split_view(p, &x, &y, &w, &h);
    *f = split_art(p, &ax, &ay); /* (the art's scale; its middle the view's) */
    float cx = (x + w / 2.0f) * 640 / split_wu; /* in the game's (squeezed) picture */
    float cy = y + h / 2.0f;
    *dx = (int)((cx - 320) / 2);
    *dy = (int)((cy - 240) / 2 + 0.5f); /* (the one-player screen's centre: the art's) */
}

/* a skin's pictures (vplus/mod_cars.c: its folder's portrait_1.bmp, portrait_2.bmp, carinfo.bmp), else NULL */
static const Image *skin_pic(int number, int which)
{
    static Image pics[128][4];
    static unsigned char tried[128][4];
    static const char *const files[4] = {"portrait_1.bmp", "portrait_2.bmp", "carinfo.bmp", "plate.bmp"};
    int mod_car_picture(int number, const char *file, char *path, int size);
    int m = number - 0x20;
    if (m < 0 || m >= 128 || which < 0 || which > 3) return NULL;
    if (!tried[m][which]) {
        char path[700];
        tried[m][which] = 1;
        if (mod_car_picture(number, files[which], path, sizeof path)) pics[m][which] = image_load_bmp(path);
    }
    return pics[m][which].px ? &pics[m][which] : NULL;
}
/* a skin's driver portrait over a portrait's box (n: 0 choosing, 1 chosen): 1 if drawn */
static int skin_portrait(Image *c, int number, int n, int x, int y, int w, int h)
{
    const Image *img = skin_pic(number, n ? 1 : 0);
    if (!img && n) img = skin_pic(number, 0);
    if (!img) return 0;
    draw_image(c, img, 0, 0, (float)img->w, (float)img->h, x, y, w, h, 0);
    return 1;
}
/* a car number's name: a skin's own, else the car's */
static const char *car_label(int number)
{
    const char *mod_car_name(int number);
    int mod_car_base(int number);
    const char *n = mod_is_look(number) ? mod_car_name(number) : NULL; /* (a skin, Dark Tooth's second phase: its name) */
    return n ? n : profile_character_name(mod_is_look(number) ? mod_car_base(number) : number);
}

static Image carinfo_pics[2][14]; /* the PC's; Vanilla Plus's ratings (carinfo_vp_NN.bmp, for the cars whose differ) */
static unsigned char carinfo_tried[2][14];
static const Image *carinfo_pic(int car)
{
    if (car >= 0x20) { /* a skin: its own CAR INFO, else its car's */
        int mod_car_base(int number);
        const Image *own = skin_pic(car, 2);
        if (own) return own;
        car = mod_car_base(car);
    }
    if (car < 0 || car >= 14) return NULL;
    for (int vp = vp_on(VP_CARINFO_STATS); vp >= 0; vp--) {
        if (!carinfo_tried[vp][car]) {
            char path[512];
            snprintf(path, sizeof path, vp ? "%sui/carinfo_vp_%02d.bmp" : "%sui/carinfo_%02d.bmp", folder, car);
            carinfo_pics[vp][car] = image_load_bmp(path);
            carinfo_tried[vp][car] = 1;
        }
        if (carinfo_pics[vp][car].px) return &carinfo_pics[vp][car];
    }
    return NULL;
}

/* the picture as tall as a rectangle, centered: its sides cut when the
 * rectangle is narrower, black beside it when wider (never stretched) */
static void draw_fit_height(Image *c, const Image *img, int x, int y, int w, int h)
{
    if (!img || !img->px || h <= 0) return;
    int pw = (int)((float)h * img->w / img->h + 0.5f);
    if (pw >= w) {
        float sw = (float)w * img->h / h;
        draw_image(c, img, (img->w - sw) / 2, 0, sw, (float)img->h, x, y, w, h, 0);
    } else {
        draw_image(c, img, 0, 0, (float)img->w, (float)img->h, x + (w - pw) / 2, y, pw, h, 0);
    }
}
/* the picture whole, as large as fits, centered */
static void draw_contain(Image *c, const Image *img, int x, int y, int w, int h)
{
    if (!img || !img->px) return;
    float k = (float)w / img->w < (float)h / img->h ? (float)w / img->w : (float)h / img->h;
    int dw = (int)(img->w * k), dh = (int)(img->h * k);
    draw_image(c, img, 0, 0, (float)img->w, (float)img->h, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh, 0);
}

/* The split screen's background, composed for the renderer's upscaled VRAM:
 * each player's view (the car select picture, their portrait, SELECT CAR /
 * CAR INFO, their driver's name; or their CAR INFO picture) and the strip of
 * every driver's portrait between them. The game draws the cars over it. */
static int split_bg_state = -1;
static int split_state(void)
{
    PsyzSize size = Psyz_VideoGetDisplaySize();
    int s = size.w * 31 + size.h;
    for (int p = 0; p < cl.n; p++)
        s = s * 4099 + cs_look(p) * 16 + cs2[p].locked * 2 + cl.p[p].title * 4 + cl.p[p].info * 8 + 1 +
            256 * (battle_match()->player_team[p] % 4);
    return s * 2 + names_as_sprites;
}

/* an image copied onto another at x, y (clipped) */
static void blit_image(Image *dst, const Image *src, int x, int y)
{
    for (int r = 0; r < src->h; r++) {
        int dy = y + r, x0 = x < 0 ? -x : 0, x1 = x + src->w > dst->w ? dst->w - x : src->w;
        if (dy < 0 || dy >= dst->h || x1 <= x0) continue;
        memcpy(dst->px + ((size_t)dy * dst->w + x + x0) * 3, src->px + ((size_t)r * src->w + x0) * 3, (size_t)(x1 - x0) * 3);
    }
}

static void compose_split(void)
{
    static const uint8_t black[3] = {0, 0, 0}, frame[3] = {60, 60, 66};
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (size.w <= 0 || size.h <= 0 || !image_resize(&split_win, split_content_w(size.w, size.h), size.h)) return;
    Image *c = &split_win;
    View v = {c, c->h / 480.0f, 0};
    split_wu = c->w / v.s;
    memset(c->px, 0, (size_t)c->w * c->h * 3);
    lettering();
    /* Each player's view kept as drawn and copied back while it is unchanged, the art scaled once: a move redrew the
     * four views (four scalings of the art, 30 ms of 48 at 2560 x 1440) and the cars froze for a moment at each (the
     * user's 4-player split screen, 2026-11-04). TM2PC_SPLIT_NOCACHE: tests (all drawn each time) */
    static Image view_kept[4], art_scaled;
    static int view_key[4] = {-1, -1, -1, -1};
    static int nocache = -1;
    if (nocache < 0) nocache = getenv("TM2PC_SPLIT_NOCACHE") != NULL;
    for (int p = 0; p < cl.n; p++) {
        int vx, vy, vw, vh;
        split_view(p, &vx, &vy, &vw, &vh);
        float k = (float)vh / (480 - SPLIT_STRIP_H); /* quarters: everything at half size */
        int rx = X(&v, vx), ry = Y(&v, vy), rw = X(&v, vx + vw) - rx, rh = Y(&v, vy + vh) - ry;
        int key = ((((cs_look(p) * 2 + cs2[p].locked) * 2 + cl.p[p].title) * 4 + battle_match()->player_team[p] % 4) * 2 +
                   carsel_teams()) * 2 + names_as_sprites;
        key = (key * 2 + vp_on(VP_CARSEL_BORDERS)) * 8 + cl.n + 1;
        key = key * 31 + c->w * 7 + c->h;
        if (!nocache && !cl.p[p].info && view_key[p] == key && view_kept[p].px && view_kept[p].w == rw && view_kept[p].h == rh) {
            blit_image(c, &view_kept[p], rx, ry);
            continue;
        }
        view_key[p] = -1;
        lettering(); /* (each view's letters from the same style: the last view's name left its own, and a view drawn alone
                      * had its titles a few pixels over) */
        if (cl.p[p].info) { /* their CAR INFO, whole, as large as fits */
            draw_contain(c, carinfo_pic(cs_look(p)), X(&v, vx), Y(&v, vy), S(&v, vw), S(&v, vh));
            continue;
        }
        /* the one-player screen as tall as the view (the sides black, as its own on a wide window), everything at
         * its place on it: the driver's portrait whole where the game has it (x 56, y 10, 128 x 256), so its
         * flames meet the art's; the titles, the car and the name as in one player */
        float ax, ay, af = split_art(p, &ax, &ay);
        uint64_t tb = SDL_GetTicksNS();
        if (bg_carsel.px && (nocache || !image_resize(&art_scaled, S(&v, 640 * af), S(&v, 480 * af))))
            draw_image(c, &bg_carsel, 0, 0, (float)bg_carsel.w, (float)bg_carsel.h, X(&v, ax), Y(&v, ay), S(&v, 640 * af), S(&v, 480 * af), 0);
        else if (bg_carsel.px) {
            static int art_w, art_h;
            static const void *art_src;
            if (art_w != art_scaled.w || art_h != art_scaled.h || art_src != bg_carsel.px) { /* (a new size or art: scaled again) */
                memset(art_scaled.px, 0, (size_t)art_scaled.w * art_scaled.h * 3);
                draw_image(&art_scaled, &bg_carsel, 0, 0, (float)bg_carsel.w, (float)bg_carsel.h, 0, 0, art_scaled.w, art_scaled.h, 0);
                art_w = art_scaled.w, art_h = art_scaled.h, art_src = bg_carsel.px;
            }
            blit_image(c, &art_scaled, X(&v, ax), Y(&v, ay));
        }
        if (getenv("TM2PC_CARSEL_TIMES")) fprintf(stderr, "  player %d art %.1f ms (%dx%d)\n", p + 1, (SDL_GetTicksNS() - tb) / 1e6, S(&v, 640 * af), S(&v, 480 * af));
        int px = (int)(ax + 56 * af), py = (int)(ay + 10 * af), pw = (int)(128 * af), ph = (int)(256 * af);
        int t = S(&v, 2);
        int borders = vp_on(VP_CARSEL_BORDERS); /* the player's color: a border and their tag */
        if (borders) draw_fill(c, X(&v, px) - t, Y(&v, py) - t, S(&v, pw) + 2 * t, S(&v, ph) + 2 * t, PLAYER_COLOR[p], 255);
        if (skin_portrait(c, cs_look(p), cs2[p].locked, X(&v, px), Y(&v, py), S(&v, pw), S(&v, ph))) ; /* (a skin: its own) */
        else if (cs2[p].car >= PROFILE_CHARACTERS)
            draw_car_portrait(&v, cs2[p].car, cs2[p].locked, X(&v, px), Y(&v, py), S(&v, pw), S(&v, ph));
        else if (portraits.px && portraits.w >= PROFILE_CHARACTERS * 2) {
            float fw = (float)portraits.w / (PROFILE_CHARACTERS * 2);
            draw_image(c, &portraits, (cs2[p].car * 2 + cs2[p].locked) * fw + 1, 1, fw - 2, (float)portraits.h - 1, X(&v, px), Y(&v, py),
                       S(&v, pw), S(&v, ph), 0);
        }
        char tg[4] = {'P', (char)('1' + p), 0};
        int ts = S(&v, 13 * k < 9 ? 9 : 13 * k), tw = text_width(tg, ts);
        if (borders) draw_fill(c, X(&v, px), Y(&v, py), tw + S(&v, 4), ts + S(&v, 3), PLAYER_COLOR[p], 255);
        if (borders) text_draw(c, tg, X(&v, px) + S(&v, 2), Y(&v, py), ts, WHITE);
        /* SELECT CAR / CAR INFO, the chosen one on its bar */
        static const char *const items[2] = {"SELECT CAR", "CAR INFO"};
        /* where the one-player screen has them on the art, at the art's scale (f: as the car, split_projection):
         * the art drawn from its top; clear of the portrait */
        float f = af;
        int tsz = S(&v, 34 * f < 12 ? 12 : 34 * f);
        int tx = vx + vw / 2, half = text_width(items[0], tsz) / 2 + S(&v, 16 * f);
        if (X(&v, tx) - half < X(&v, px + pw + 6)) tx = px + pw + 6 + (int)(half / v.s);
        text_set_style(0, 0.97f, 0);
        for (int i = 0; i < 2; i++) {
            int size = tsz, cy = Y(&v, ay + (i ? 106 : 60) * f), w = text_width(items[i], size), x = X(&v, tx) - w / 2;
            if (cl.p[p].title == i && !cs2[p].locked) draw_bar(&v, x - S(&v, 16 * f), x + w + S(&v, 16 * f), cy, size);
            text_draw(c, items[i], x, text_top_for_center(cy, size), size, WHITE);
        }
        text_set_style(0, 1, 0);
        { /* the emblem at the top right, as the one-player screen's: player 1's 1, the others' 2 (3 and 4 to be drawn) */
            const Image *em = p == 0 || !emblem2.px ? &emblem1 : &emblem2;
            if (em->px) {
                static const uint8_t key[3] = {255, 0, 255};
                draw_image_keyed(c, em, 0, 0, (float)em->w, (float)em->h, X(&v, ax + 506 * af), Y(&v, ay + CARSEL_EMBLEM_Y * af), S(&v, 115 * af),
                                 S(&v, 115 * af), key);
            }
        }
        if (carsel_teams() && !cs2[p].locked) { /* teams: Triangle changes theirs */
            int size = S(&v, 15 * k < 10 ? 10 : 15 * k), w = legend_text(&v, TRIANGLE " CHANGE TEAM", 0, 0, size, 0);
            legend_text(&v, TRIANGLE " CHANGE TEAM", X(&v, tx) - w / 2, text_top_for_center(Y(&v, vy + (int)(94 * k)), size), size, 1);
        }
        /* the driver's name under the car; orange once locked in */
        char name[48];
        snprintf(name, sizeof name, "%s", car_label(cs_look(p)));
        if (!names_as_sprites) /* lower and larger than one player's (410), in the road's free space under the car */
            draw_car_name_scaled(&v, c, name, vx + vw / 2, (int)(ay + SPLIT_NAME_Y * af), cs2[p].locked, af * SPLIT_NAME_SCALE);
        if (!nocache && rw > 0 && rh > 0 && image_resize(&view_kept[p], rw, rh)) { /* the view as drawn, kept */
            for (int r = 0; r < rh; r++) {
                int y = ry + r;
                if (y < 0 || y >= c->h || rx < 0 || rx + rw > c->w) { view_key[p] = -2; break; }
                memcpy(view_kept[p].px + (size_t)r * rw * 3, c->px + ((size_t)y * c->w + rx) * 3, (size_t)rw * 3);
            }
            if (view_key[p] != -2) view_key[p] = key;
        }
    }
    if (cl.n > 2) { /* between the quarters (the rows: the strip) */
        int qh = (480 - SPLIT_STRIP_H) / 2;
        if (cl.n == 4) draw_fill(c, X(&v, 320) - S(&v, 1), 0, S(&v, 2), Y(&v, qh), black, 255);
        draw_fill(c, X(&v, 320) - S(&v, 1), Y(&v, qh + SPLIT_STRIP_H), S(&v, 2), c->h - Y(&v, qh + SPLIT_STRIP_H), black, 255);
    } else
        draw_fill(c, X(&v, split_wu / 2) - S(&v, 1), 0, S(&v, 2), Y(&v, 480 - SPLIT_STRIP_H), black, 255); /* between the views */
    /* the strip: every driver, each player's framed in their color with their tag */
    int sy = split_strip_y(), pitch = CS_PITCH;
    int bfirst, shown, x0;
    bar_window(cs2[0].car, (int)(split_wu / 2), (int)split_wu, pitch, &bfirst, &shown, &x0);
    draw_fill(c, 0, Y(&v, sy), c->w, Y(&v, sy + SPLIT_STRIP_H) - Y(&v, sy), black, 255);
    bar_arrows(&v, c, bfirst, shown, x0, pitch, sy + 7, CS_THUMB_H);
    for (int col = 0; col < shown; col++) {
        int car = bar_car(bfirst + col), first = -1, second = -1, chosen = 0; /* the players on it: the first two framed */
        unsigned on = 0;
        for (int q = 0; q < cl.n; q++)
            if (cs2[q].car == car) {
                on |= 1u << q;
                if (first < 0) first = q; else if (second < 0) second = q;
                chosen |= cs2[q].locked; /* locked in: the second portrait, dimmed */
            }
        int x = X(&v, x0 + col * pitch), y = Y(&v, sy + 7), w = S(&v, CS_THUMB_W), h = S(&v, CS_THUMB_H);
        int t = first >= 0 ? S(&v, 3) : (S(&v, 1) > 1 ? S(&v, 1) : 1);
        strip_frame(c, x, y, w, h, t, on, first, second, frame);
        draw_fill(c, x, y, w, h, black, 255);
        draw_car_portrait(&v, car, chosen, x, y, w, h);
        if (chosen) draw_fill(c, x, y, w, h, black, 110);
        int tag = S(&v, 11);
        for (int q = 0; q < cl.n; q++)
            if (cs2[q].car == car) { /* the tags: each player's own corner (P1 top left, P2 top right, P3 bottom left,
                                       * P4 bottom right), so all four can be on one driver */
                char tg[4] = {'P', (char)('1' + q), 0};
                int tw = text_width(tg, tag), gx = x + ((q & 1) ? w - tw - 2 : 0), gy = y + ((q & 2) ? h - tag - 2 : 0);
                draw_fill(c, gx, gy, tw + 2, tag + 2, PLAYER_COLOR[q], 255);
                text_draw(c, tg, gx + 1, gy, tag, WHITE);
            }
    }
}

static int cl_offset = -1; /* the player whose car is being drawn: the projection's shift */
void F_80155E80_orig(CPU *c);
int killcam_camera(int view); /* vplus/killcam.c */
void ui_ViewProc(CPU *c)
{
    int view = (int)c->r[4];
    int put = killcam_camera(view);
    void killcam_spectate_blend(int phase); /* vplus/killcam.c: spectating, the camera flying to a new car */
    if (view == 0 && !put) killcam_spectate_blend(0);
    void killcam_spectate_steps(int view, int put); /* vplus/killcam.c: spectating's in-between frames, the steps' cameras */
    int killcam_spectate_flying(void);
    killcam_spectate_steps(view, put || (view == 0 && killcam_spectate_flying()));
    F_80155E80_orig(c);
    if (view == 0 && !put) killcam_spectate_blend(1); /* (the game's camera back) */
    if (cl_offset >= 0) {
        int dx = shared_dx(cl_offset), dy = CL_DY;
        if (cl.split) {
            float f;
            split_projection(cl_offset, &dx, &dy, &f);
            c->gte_ctrl[26] = (uint32_t)(int)((int32_t)(uint16_t)c->gte_ctrl[26] * f + 0.5f); /* H: the view's scale */
        }
        c->gte_ctrl[24] += (uint32_t)(dx << 16);
        c->gte_ctrl[25] += (uint32_t)(dy << 16);
    }
}

/* ---- the drivers' names over the cars ----
 * The art is the picture behind the cars, so a name in it is covered by a
 * big car. Instead each name (sharp, the game's font) goes into a free part
 * of VRAM (x 832.., y 400.., unused on these screens: a 16-bit page) whose
 * texels the renderer draws from the sharp picture instead, with its alpha
 * (PSY-Z patch 10, HD texture replacement); the game draws it as a textured
 * quad at the front of the frame (ui_SceneDraw), over the cars, as its own
 * name is. The replacement ends with the car select. */
enum { NAME_VRAM_X = 832, NAME_VRAM_Y = 400, NAME_SLOT_W = 128, NAME_SLOT_H = 24, NAME_HD_SLOT = 0, /* slots 0-1 */
       NAME_TPAGE = (NAME_VRAM_X / 64) | (1 << 4) | (2 << 7) }; /* the page at 832, 256; 15-bit texels */
static struct { int on, x, y, w, h, pw, ph; uint8_t *rgba; } name_spr[2]; /* each: its place on the game's 320x240 screen */
static Image name_layer, name_white;
static uint32_t name_state = 0xFFFFFFFFu;

/* The name drawn alone on black and on white (the art's size: the game's
 * 320x240) is cut out to a whole number of the game's pixels, its alpha
 * from the two (1 - (white - black)). */
static void name_sprite_make(int i, const Image *black, const Image *white)
{
    int x0 = black->w, y0 = black->h, x1 = -1, y1 = -1;
    for (int y = 0; y < black->h; y++) {
        const uint8_t *row = black->px + (size_t)y * black->w * 3, *wrow = white->px + (size_t)y * white->w * 3;
        for (int x = 0; x < black->w; x++)
            if (row[x * 3] | row[x * 3 + 1] | row[x * 3 + 2] || wrow[x * 3] != 255 || wrow[x * 3 + 2] != 255) {
                if (x < x0) x0 = x;
                if (x > x1) x1 = x;
                if (y < y0) y0 = y;
                if (y > y1) y1 = y;
            }
    }
    name_spr[i].on = 0;
    if (x1 < 0) return;
    float kx = 320.0f / black->w, ky = 240.0f / black->h;
    int nx = (int)(x0 * kx), ny = (int)(y0 * ky), nx1 = (int)(x1 * kx) + 1, ny1 = (int)(y1 * ky) + 1;
    int nw = nx1 - nx, nh = ny1 - ny;
    if (nw > NAME_SLOT_W) nw = NAME_SLOT_W;
    if (nh > NAME_SLOT_H) nh = NAME_SLOT_H;
    int cx = (int)(nx / kx), cy = (int)(ny / ky), cw = (int)(nw / kx), ch = (int)(nh / ky);
    if (cx + cw > black->w) cw = black->w - cx;
    if (cy + ch > black->h) ch = black->h - cy;
    if (cw <= 0 || ch <= 0 || cw > 512 || ch > 512) return;
    uint8_t *p = realloc(name_spr[i].rgba, (size_t)cw * ch * 4);
    if (!p) return;
    name_spr[i].rgba = p;
    for (int y = 0; y < ch; y++)
        for (int x = 0; x < cw; x++) {
            const uint8_t *b = black->px + ((size_t)(cy + y) * black->w + cx + x) * 3;
            const uint8_t *w = white->px + ((size_t)(cy + y) * white->w + cx + x) * 3;
            int a = 255 - (w[1] - b[1]); /* green: the font's colors keep it */
            if (a < 0) a = 0;
            if (a > 255) a = 255;
            uint8_t *o = p + ((size_t)y * cw + x) * 4;
            for (int k = 0; k < 3; k++) o[k] = (uint8_t)(a ? (b[k] * 255 / a > 255 ? 255 : b[k] * 255 / a) : 0);
            o[3] = (uint8_t)a;
        }
    name_spr[i].x = nx;
    name_spr[i].y = ny;
    name_spr[i].w = nw;
    name_spr[i].h = nh;
    name_spr[i].pw = cw;
    name_spr[i].ph = ch;
    name_spr[i].on = 1;
}

/* Ends the names' replacement (the car select is over: that VRAM is the game's again). */
static void name_sprites_off(void)
{
    for (int p = 0; p < 2; p++) {
        if (name_spr[p].on) Psyz_VideoClearTextureHD(NAME_HD_SLOT + p);
        name_spr[p].on = 0;
    }
    name_state = 0xFFFFFFFFu;
}

/* The names for the frame: 1 player's (under the car) or each split view's;
 * made again when they change, and put in VRAM with the background. */
static void name_sprites_update(void)
{
    uint32_t st = 5381;
    const char *names[2] = {NULL, NULL};
    int locked[2] = {0, 0};
    if (!cl.on) {
        { int vp_carousel_look(void); int lk = vp_carousel_look(); names[0] = mod_is_look(lk) ? car_label(lk) : carsel_text[0] ? carsel_text : NULL; }
        locked[0] = carsel_second;
    } else if (cl.split) {
        for (int p = 0; p < 2; p++)
            if (!cl.p[p].info) { names[p] = car_label(cs_look(p)); locked[p] = cs2[p].locked; }
    }
    for (int p = 0; p < 2; p++) {
        for (const char *q = names[p] ? names[p] : ""; *q; q++) st = st * 33 + (uint8_t)*q;
        st = st * 33 + (uint32_t)locked[p] * 7 + (names[p] != NULL);
    }
    st ^= (uint32_t)(cl.on * 3 + cl.split) * 2654435761u ^ (uint32_t)(split_wu * 16);
    if (st != name_state) {
        name_state = st;
        int W = cl.on ? (split_win.w > 0 ? split_win.w : 1280) : 1280, H = cl.on ? (split_win.h > 0 ? split_win.h : 960) : 960;
        for (int p = 0; p < 2; p++) {
            if (name_spr[p].on) Psyz_VideoClearTextureHD(NAME_HD_SLOT + p);
            name_spr[p].on = 0;
            if (!names[p] || !image_resize(&name_layer, W, H) || !image_resize(&name_white, W, H)) continue;
            memset(name_layer.px, 0, (size_t)W * H * 3);
            memset(name_white.px, 255, (size_t)W * H * 3);
            for (int k = 0; k < 2; k++) {
                Image *layer = k ? &name_white : &name_layer;
                View v = {layer, H / 480.0f, 0};
                if (!cl.on) {
                    draw_car_name(&v, layer, names[p], 320, 410, locked[p]);
                } else {
                    int vx, vy, vw, vh;
                    split_view(p, &vx, &vy, &vw, &vh);
                    float ax, ay, af = split_art(p, &ax, &ay);
                    draw_car_name_scaled(&v, layer, names[p], vx + vw / 2, (int)(ay + SPLIT_NAME_Y * af), locked[p],
                                         af * SPLIT_NAME_SCALE); /* (lower and larger than one player's) */
                }
            }
            name_sprite_make(p, &name_layer, &name_white);
            if (name_spr[p].on) {
                int v0 = NAME_VRAM_Y - 256 + p * NAME_SLOT_H;
                name_spr[p].on = Psyz_VideoSetTextureHD(NAME_HD_SLOT + p, NAME_VRAM_X, 256, -1, 0, v0, name_spr[p].w,
                                                        v0 + name_spr[p].h, name_spr[p].rgba, name_spr[p].pw, name_spr[p].ph);
            }
        }
    }
}

/* The names' quads (GP0 2C: textured, the texture's own colors), at the
 * front of the frame's OT (slot 0, drawn last). */
static void ot_area(CPU *c, uint32_t frame, uint32_t ot, int k, int x0, int y0, int x1, int y1);
void gte_precise_put(uint32_t ea, uint32_t word, float x, float y, float w); /* runtime/gte.c */
static void ot_names(CPU *c, uint32_t frame)
{
    uint32_t ot = mem_r32(c, frame);
    for (int p = 0; p < 2; p++) {
        if (!name_spr[p].on) continue;
        uint32_t cur = mem_r32(c, frame + 8), end = mem_r32(c, frame + 0xC);
        if (cur + 40 > end) return;
        mem_w32(c, frame + 8, cur + 40);
        uint32_t slot = ot, link = mem_r32(c, slot);
        int x0 = name_spr[p].x, y0 = name_spr[p].y, x1 = x0 + name_spr[p].w, y1 = y0 + name_spr[p].h;
        uint32_t u0 = 0, u1 = (uint32_t)name_spr[p].w, v0 = (uint32_t)(NAME_VRAM_Y - 256 + p * NAME_SLOT_H), v1 = v0 + (uint32_t)name_spr[p].h;
        uint32_t w[10] = {
            (9u << 24) | (link & 0xFFFFFF), 0x2C808080u,
            ((uint32_t)y0 << 16) | (uint16_t)x0, (v0 << 8) | u0,
            ((uint32_t)y0 << 16) | (uint16_t)x1, ((uint32_t)NAME_TPAGE << 16) | (v0 << 8) | u1,
            ((uint32_t)y1 << 16) | (uint16_t)x0, (v1 << 8) | u0,
            ((uint32_t)y1 << 16) | (uint16_t)x1, (v1 << 8) | u1,
        };
        for (int i = 0; i < 10; i++) mem_w32(c, cur + (uint32_t)i * 4, w[i]);
        /* the corners' exact places: else a corner on the pixel of one of the turning car's vertices took that
         * vertex's floats (by value) and the name leaned and grew for a frame (the user's, 2026-11-02) */
        for (int i = 0; i < 4; i++)
            gte_precise_put(cur + 8 + (uint32_t)i * 8, w[2 + i * 2], (float)(i & 1 ? x1 : x0), (float)(i & 2 ? y1 : y0), 1);
        mem_w32(c, slot, (link & 0xFF000000u) | (cur & 0xFFFFFF));
    }
    /* the whole picture's draw area just before them (the split screen fences each half in) */
    int16_t cx = (int16_t)mem_r16(c, frame + 0x10), cy = (int16_t)mem_r16(c, frame + 0x12);
    int16_t cw = (int16_t)mem_r16(c, frame + 0x14), ch = (int16_t)mem_r16(c, frame + 0x16);
    if (cw > 0 && ch > 0) ot_area(c, frame, ot, 0, cx, cy, cx + cw - 1, cy + ch - 1);
}

/* The scene's background picture: a TIM in RAM that screenDisplayImage
 * (80121C8C) LoadImages into the frame being drawn each frame, at x 0 or 320
 * (the other buffer). In car select the PC's picture (640x480, its legend
 * cleaned away) goes over it in the renderer's upscaled VRAM (PSY-Z patch
 * 08), so the background behind the cars is as sharp as the port's art. */
void F_8012201C_orig(CPU *c);
void ui_SceneBackground(CPU *c)
{
    uint32_t scene = c->r[4], other = c->r[5];
    /* (CAR INFO put away, 2: car select draws itself again; the port's picture from its first frame, else the game's
     * own, its legend, flashed under the car for the frames until the overlay came back, the user's 2026-11-19) */
    int on = carsel_active && carsel_info != 1 && bg_carsel.px && mem_r32(c, scene + 0x2C);
    if (on && carsel_info == 2) carsel_info = 3; /* (ui_frame_start: the overlay with the frame shown) */
    names_as_sprites = on && (!cl.on || (cl.split && cl.n <= 2)) && carsel_hd;
    int x = on && other != guest_call(GA(0x800D19E0u), 0, 0, 0, 0) ? 320 : 0;
    F_8012201C_orig(c);
    if (on && cl.on && cl.split) { /* the split screen's layout instead */
        int st = split_state();
        if (st != split_bg_state || !split_bg.px) {
            uint64_t t0 = SDL_GetTicksNS();
            compose_split(); /* all of it for the renderer: squeezed into the game's picture, shown stretched */
            uint64_t t1 = SDL_GetTicksNS();
            if (split_win.px && image_resize(&split_bg, split_win.w, split_win.h))
                memcpy(split_bg.px, split_win.px, (size_t)split_win.w * split_win.h * 3);
            if (getenv("TM2PC_CARSEL_TIMES")) fprintf(stderr, "split compose %.1f ms, copy %.1f ms\n", (t1 - t0) / 1e6, (SDL_GetTicksNS() - t1) / 1e6);
            split_bg_state = st;
            carsel_art_gen++;
        }
        split_wide_apply(1);
        if (split_bg.px) carsel_hd = Psyz_VideoLoadImageHD(x, 0, 320, 240, split_bg.px, split_bg.w, split_bg.h);
        if (carsel_hd) name_sprites_update();
    } else if (on) { /* the picture with the port's art: the cars and the game's arrows and name over it */
        static int hd_state = -1;
        Image *hdp = &carsel_hd_img;
        int car = vp_carousel_car(), item = carsel_chosen_item();
        int st = (cl.on ? 1 + carsel_live_state() * 2
                        : 2 + (car + 1) * 4 + (item == ITEM_SELECT_CAR) * 2 + carsel_second * 256 + (int)(carsel_text_hash << 9)) ^
                 (carsel_title_x[0] * 7919 + carsel_title_x[1] * 104729) ^ (names_as_sprites << 30);
        /* the other item's picture kept: SELECT CAR / CAR INFO flicked up and down swaps the two, not composed again each
         * time (each ~40 ms at 1280 x 960 and more with the overlay at the window's size: the user's stutter, 2026-11-03) */
        static Image other_img;
        static int other_state = -1;
        if (st != hd_state && hdp->px && other_img.px && other_state == st) {
            Image t = *hdp;
            *hdp = other_img, other_img = t;
            other_state = hd_state, hd_state = st;
        } else if (st != hd_state || !hdp->px) {
            if (hdp->px && hd_state != -1) { /* (the one shown kept as the other) */
                Image t = other_img;
                other_img = *hdp, *hdp = t;
                other_state = hd_state;
            }
            if (!image_resize(hdp, 1280, 960)) goto composed;
            if (getenv("TM2PC_CARSEL_TRACE")) /* tests: each time the background is composed again, and why */
                fprintf(stderr, "carsel bg: %llu car %d item %d second %d titles %d %d hash %u\n", (unsigned long long)M.vblanks, car,
                        item, carsel_second, carsel_title_x[0], carsel_title_x[1], (unsigned)carsel_text_hash);
            View v = {hdp, 2.0f, 0};
            uint64_t t0 = SDL_GetTicksNS();
            { /* the art scaled once and copied (19 ms each change, the cars stalling: the user's, 2026-11-04) */
                static Image bg_scaled;
                static const void *bg_src;
                if (bg_src != bg_carsel.px || bg_scaled.w != hdp->w || bg_scaled.h != hdp->h) {
                    if (image_resize(&bg_scaled, hdp->w, hdp->h)) {
                        draw_image(&bg_scaled, &bg_carsel, 0, 0, (float)bg_carsel.w, (float)bg_carsel.h, 0, 0, hdp->w, hdp->h, 0);
                        bg_src = bg_carsel.px;
                    }
                }
                if (bg_src == bg_carsel.px && bg_scaled.w == hdp->w && bg_scaled.h == hdp->h)
                    memcpy(hdp->px, bg_scaled.px, (size_t)hdp->w * hdp->h * 3);
                else
                    draw_image(hdp, &bg_carsel, 0, 0, (float)bg_carsel.w, (float)bg_carsel.h, 0, 0, hdp->w, hdp->h, 0);
            }
            uint64_t t1 = SDL_GetTicksNS();
            if (cl.on) carsel_compose2_art(&v, hdp, item, NULL);
            else if (car >= 0) carsel_art(&v, hdp, car, item);
            if (getenv("TM2PC_CARSEL_TIMES")) /* tests: the picture's parts' times */
                fprintf(stderr, "carsel bg %.1f ms, art %.1f ms\n", (t1 - t0) / 1e6, (SDL_GetTicksNS() - t1) / 1e6);
            hd_state = st;
            static int base_state = -1; /* without the titles' slide: the overlay's parts only change with it */
            /* (and without the chosen item: the overlay's parts, the bottom bar, are the same for both) */
            int bs = (cl.on ? 1 + carsel_live_state() * 2 : 2 + (car + 1) * 4 + carsel_second * 256 + (int)(carsel_text_hash << 9)) ^
                     (names_as_sprites << 30);
            if (bs != base_state) { base_state = bs; carsel_art_gen++; }
        }
    composed:
        carsel_hd = Psyz_VideoLoadImageHD(x, 0, 320, 240, hdp->px, hdp->w, hdp->h);
        if (carsel_hd && !cl.on) name_sprites_update();
        else if (cl.on) name_sprites_off(); /* the shared screen: its own names */
    } else {
        name_sprites_off();
    }
}

