/* The scene's text (801373EC's objects: in car select the driver's name
 * under the car, at 160, 205 in font 2). With the art in the background its
 * text is read (+0x38: the string) and drawn there with the game's font,
 * sharp; the 2-player screens draw their own names. */
void F_801372C4_orig(CPU *c);
void ui_TextDraw(CPU *c)
{
    if (cl.on) return;
    if (!(carsel_active && carsel_hd)) { F_801372C4_orig(c); return; }
    uint32_t str = mem_r32(c, c->r[4] + 0x38), h = 5381;
    int n = 0;
    for (; str && n < (int)sizeof carsel_text - 1; n++) {
        char ch = (char)mem_r8(c, str + (uint32_t)n);
        if (!ch) break;
        carsel_text[n] = ch;
        h = h * 33 + (uint8_t)ch;
    }
    carsel_text[n] = 0;
    carsel_text_hash = h;
}

/* A draw area packet (GP0 E3/E4, VRAM coordinates, inclusive) linked into
 * the frame's OT at slot k, from the frame's packet buffer. */
static void ot_area(CPU *c, uint32_t frame, uint32_t ot, int k, int x0, int y0, int x1, int y1)
{
    uint32_t cur = mem_r32(c, frame + 8), end = mem_r32(c, frame + 0xC);
    if (cur + 12 > end) return;
    mem_w32(c, frame + 8, cur + 12);
    uint32_t slot = ot + (uint32_t)k * 4, link = mem_r32(c, slot);
    mem_w32(c, cur, (2u << 24) | (link & 0xFFFFFF));
    mem_w32(c, cur + 4, 0xE3000000u | ((uint32_t)y0 << 10) | (uint32_t)x0);
    mem_w32(c, cur + 8, 0xE4000000u | ((uint32_t)y1 << 10) | (uint32_t)x1);
    mem_w32(c, slot, (link & 0xFF000000u) | (cur & 0xFFFFFF));
}

/* Car select with teams (a Challenge Match): each player's spinning car in
 * their team's colors (decomp TEAM_COLORS.md 5.2). The team's palette goes
 * to a CLUT row nothing else uses, (768, 40 + player); for that player's
 * draw the body primitives of the shown car (the select node's child, CLUT
 * id 48 | (23 + car) << 6) point at it, and back after (the emitter copies
 * the id at each draw). Triangle switches the player's team. */
int net_carsel_neutral(void);
static int carsel_teams(void) { return battle_live && !survival_on && battle_match_teams() >= 2 && !net_carsel_neutral(); }
static struct { int car, team; } team_row[2] = {{-1, -1}, {-1, -1}};
static uint32_t team_patched[1024];
static int team_npatched;
static uint16_t team_patched_from; /* the car's own body CLUT id */
static void team_walk(CPU *c, uint32_t node, uint16_t from, uint16_t to, int depth)
{
    if (!node || (node & 3) || node < 0x80000000u || node >= 0x80000000u + GUEST_RAM_BYTES || depth > 16) return;
    int type = mem_r8(c, node), n;
    uint32_t kids;
    switch (type) {
    case 0: { /* a mesh: its primitives */
        uint32_t p = mem_r32(c, node + 0x0C);
        int count = mem_r16(c, node + 0x10);
        for (int i = 0; i < count && p >= 0x80000000u && p < 0x80000000u + GUEST_RAM_BYTES; i++) {
            int len = mem_r8(c, p + 2) * 4;
            if (mem_r8(c, p) & 0x7F) { /* textured: the CLUT id after the colour words */
                uint32_t at = p + 16 + 4u * mem_r8(c, p + 1) + 2;
                if (mem_r16(c, at) == from && team_npatched < 1024) {
                    mem_w16(c, at, to);
                    team_patched[team_npatched++] = at;
                }
            }
            if (len <= 0) break;
            p += (uint32_t)len;
        }
        return;
    }
    case 1: n = mem_r8(c, node + 0x14); kids = node + 0x18; break;
    case 3: n = mem_r8(c, node + 0x0B); kids = node + 0x20; break;
    case 4: n = mem_r16(c, node + 0x12); kids = node + 0x14; break;
    case 5: n = mem_r16(c, node + 0x26); kids = node + 0x28; break;
    case 9: n = mem_r8(c, node + 6); kids = node + 0x10; break;
    default: return;
    }
    for (int i = 0; i < n && i < 64; i++) team_walk(c, mem_r32(c, kids + 4u * (uint32_t)i), from, to, depth + 1);
}
static void team_paint_begin(CPU *c, uint32_t select, int car, int p)
{
    team_npatched = 0;
    if (!carsel_teams() || car < 0 || car > 13 || !select || mem_r8(c, select) != 9) return;
    int team = battle_match()->player_team[p & 1] % 4;
    if (team_row[p & 1].car != car || team_row[p & 1].team != team) { /* the row: this car in this team's colors */
        static uint16_t in[256], out[256];
        gpu_backend->download(768, 23 + car, 256, 1, in);
        vp_team_palette(car, team, in, out);
        gpu_backend->upload(768, 40 + (p & 1), 256, 1, out);
        void hdtex_vram_written(int x, int y, int w, int h);
        hdtex_vram_written(768, 40 + (p & 1), 256, 1);
        team_row[p & 1].car = car;
        team_row[p & 1].team = team;
    }
    team_patched_from = (uint16_t)(48 | (23 + car) << 6);
    team_walk(c, mem_r32(c, select + 0x10 + 4u * (uint32_t)car), team_patched_from,
              (uint16_t)(48 | (40 + (p & 1)) << 6), 0);
}
static void team_paint_end(CPU *c)
{
    for (int i = 0; i < team_npatched; i++) mem_w16(c, team_patched[i], team_patched_from); /* the car's own row again */
    team_npatched = 0;
}
static void team_cycle(int p) /* Triangle: the player's next team */
{
    int n = battle_match_teams();
    if (!carsel_teams() || n < 2) return;
    battle_match()->player_team[p & 3] = (battle_match()->player_team[p & 3] + 1) % n;
    changed |= SAVE_BATTLE;
    menu_sound(0);
    fprintf(stderr, "car select: player %d on the %s team\n", p + 1, team_values[battle_match()->player_team[p & 3]]);
}

void F_80122124_orig(CPU *c);
/* the carousel's distance for a car drawn with its in-game model (decomp request 71, CAR_PROFILES.md): Dark Tooth's truck is
 * about twice a car's size and taller: 3.4 times as far, nearer Minion's size (4 times looked small, the user's
 * 2026-11-04) (% of the usual, 0 = as the others; TM2PC_DT_FAR: tests) */
static int carsel_far(int car)
{
    const char *tf = getenv("TM2PC_TURNTABLE_FAR"); /* tools: "car:percent,..." (the art's wide crops: Minion whole) */
    for (int c, p, n; tf && sscanf(tf, "%d:%d%n", &c, &p, &n) == 2; tf += n + (tf[n] == ',')) {
        if (c == car) return p;
        if (!tf[n]) break;
    }
    if (car != 14) return 0;
    const char *e = getenv("TM2PC_DT_FAR");
    return e ? atoi(e) : 340;
}
void gte_tr_smooth_begin(int slot, double between); /* runtime/gte.c */
extern int vp_emit_fine; /* vplus/precise.c: the car select's car sorted over more order-table slots */
void gte_tr_smooth_end(void);
double interp_scene_t(void); /* vplus/interp.c */
void ui_SceneDraw(CPU *c)
{
    uint32_t obj = c->r[4], frame = c->r[5];
    uint16_t id = mem_r16(c, obj);
    if (id == 9007) carsel_second = mem_r16(c, obj + 8) != 0; /* the driver's second portrait: chosen */
    if (id == 9001 || id == 9002) carsel_title_x[id - 9001] = (int32_t)mem_r32(c, obj + 24); /* the titles slide in */
    if (!cl.on) {
        if (id == ARROW_OBJ && carsel_active && turntable_on()) return; /* (tools: no arrows beside the car) */
        /* 1 player with the art in the background: the game's titles, portraits and emblems are ours */
        if (!(carsel_active && carsel_hd && ((id >= 9006 && id <= 9009) || id == 9001 || id == 9002))) {
            uint32_t sel_node = id == CAROUSEL_OBJ && carsel_active ? mem_r32(c, obj + 4) : 0;
            if (sel_node) { /* with teams: the car in player 1's team colors; Triangle the next team */
                static uint16_t tprev = 0xFFFF;
                uint16_t b = script ? 0 : input_player_menu_buttons(0);
                if ((b & ~tprev) & B_TRIANGLE) team_cycle(0);
                tprev = b;
                team_paint_begin(c, sel_node, mem_r8(c, sel_node + 7), 0);
            }
            if (id == CAROUSEL_OBJ && getenv("TM2PC_CARSEL_HEADING")) /* tests: the car held at a heading (pictures) */
                mem_w32(c, obj + 36, (uint32_t)(atoi(getenv("TM2PC_CARSEL_HEADING")) & 4095));
            if (id == CAROUSEL_OBJ && turntable_heading >= 0) mem_w32(c, obj + 36, (uint32_t)(turntable_heading & 4095));
            void port_precise_ring_drop(void); /* vplus/port_config.c */
            if (id == CAROUSEL_OBJ) port_precise_ring_drop(); /* (the emitter's places of an earlier build: not this one's) */
            /* (its turning car: no rocking; sorted finely, vplus/precise.c) */
            if (id == CAROUSEL_OBJ) gte_tr_smooth_begin(0, interp_scene_t());
            if (id == CAROUSEL_OBJ) vp_emit_fine = 2;
            uint32_t place[3];
            int far = id == CAROUSEL_OBJ && mem_r32(c, obj + 4) ? carsel_far(mem_r8(c, mem_r32(c, obj + 4) + 7)) : 0;
            for (int i = 0; far && i < 3; i++) place[i] = mem_r32(c, obj + 24 + 4u * (uint32_t)i);
            if (far) { /* (a big in-game model: further back, its middle where the cars' is) */
                mem_w32(c, obj + 24, (uint32_t)((int32_t)place[0] * far / 100));
                mem_w32(c, obj + 28, (uint32_t)(-1200 + ((int32_t)place[1] + 1200) * far / 100));
                mem_w32(c, obj + 32, (uint32_t)(80 + ((int32_t)place[2] - 80) * far / 100));
            }
            F_80122124_orig(c);
            for (int i = 0; far && i < 3; i++) mem_w32(c, obj + 24 + 4u * (uint32_t)i, place[i]);
            vp_emit_fine = 0;
            gte_tr_smooth_end();
            if (sel_node) team_paint_end(c);
        }
        if (id == CAROUSEL_OBJ && carsel_active && carsel_hd && names_as_sprites && !turntable_on()) ot_names(c, frame);
        if (id == CAROUSEL_OBJ && carsel_active) { /* the highlighted driver's special sound (Vanilla Plus) */
            static int heard = -1;
            if (carsel_heard_reset) heard = -1, carsel_heard_reset = 0; /* opened: its first driver's too */
            int car = vp_carousel_car();
            /* (the first one a second in: the menu's select boom, on two voices, would lose one to it) */
            if (car >= 0 && car != heard && (heard >= 0 || M.vblanks >= carsel_opened_at + 60)) vp_carsel_sound(car);
            else if (car >= 0 && car != heard) car = heard; /* (not heard yet) */
            heard = car;
        }
        return;
    }
    if (id != CAROUSEL_OBJ && id != ARROW_OBJ && !(id >= 9006 && id <= 9009) &&
        !((cl.split || carsel_hd) && (id == 9001 || id == 9002))) {
        F_80122124_orig(c);
        return;
    }
    if (id == ARROW_OBJ && cl.split) { /* the game's arrows in each view, beside its car (as the car: the view's projection) */
        uint32_t ot = mem_r32(c, frame);
        for (int p = 0; p < cl.n; p++) {
            if (cl.p[p].info) continue;
            mem_w32(c, frame, ot + 1024u * 4 * (uint32_t)(cl.n - 1 - p)); /* player p's group of OT slots */
            cl_offset = p;
            c->r[4] = obj;
            c->r[5] = frame;
            F_80122124_orig(c);
            cl_offset = -1;
        }
        mem_w32(c, frame, ot);
        return;
    }
    if (id != CAROUSEL_OBJ) return; /* the name labels (split: the titles): the port's instead */
    if (M.vblanks != cl.last_vblank) { cl.last_vblank = M.vblanks; cl_frame(); }
    uint32_t node = mem_r32(c, obj + 4);
    if (!node) { F_80122124_orig(c); return; }
    uint8_t saved_car = mem_r8(c, node + 7);
    uint32_t pos[6];
    for (int i = 0; i < 6; i++) pos[i] = mem_r32(c, obj + 24 + (uint32_t)i * 4);
    /* split: each player's car only in their half of the picture. Player 1's
     * polygons go to OT slots 1024 and up (drawn first), player 2's to the
     * usual ones; a draw area packet before each group fences it in, and one
     * after both gives the whole picture back. */
    uint32_t ot = mem_r32(c, frame);
    for (int p = 0; p < cl.n; p++) {
        if (cl.split && cl.p[p].info) continue; /* their CAR INFO is up */
        if (cl.split) mem_w32(c, frame, ot + 1024u * 4 * (uint32_t)(cl.n - 1 - p)); /* player p's group of OT slots */
        int base = cs_byte(cs2[p].car), extra = base >= 0 && base < 15 ? CL_CAR_DEPTH[base] : 0, depth = CL_Y + extra;
        /* further back, lowered in proportion (the camera at y -1200, z 80): its base where the others' are */
        int z = 80 + (int)((CL_Z - 80) * (float)(depth + 1200) / (float)(CL_Y + 1200));
        if (cl.split) { depth = CL1_Y; z = CL1_Z; } /* split: where the one-player screen has its car (its size on the art) */
        int far = carsel_far(cs2[p].car);
        if (far) { /* (a big in-game model: further back) */
            depth = -1200 + (depth + 1200) * far / 100;
            z = 80 + (z - 80) * far / 100;
        }
        if (!cl.split && cl.n > 2) { /* 3-4 on one screen: further back, so they fit side by side */
            float sc = shared_scale();
            depth = -1200 + (int)((depth + 1200) / sc);
            z = 80 + (int)((z - 80) / sc);
        }
        /* Uncapped: drawn between its last two scene frames (vplus/interp.c redraws the scene there), as the game's
         * own objects are; a jump (a slide wrapping round, a new car) as it is */
        double interp_scene_t(void);
        double st = interp_scene_t();
        int px = cl.p[p].x, py = cl.p[p].y, pz = cl.p[p].z, ph = cl.p[p].heading;
        if (st >= 0 && abs(px - cl_prev[p].x) < 2000 && abs(py - cl_prev[p].y) < 2000 && abs(pz - cl_prev[p].z) < 2000) {
            int dh = ((ph - cl_prev[p].heading + 2048) & 4095) - 2048; /* (turns: the shortest way round) */
            px = cl_prev[p].x + (int)lround((px - cl_prev[p].x) * st);
            py = cl_prev[p].y + (int)lround((py - cl_prev[p].y) * st);
            pz = cl_prev[p].z + (int)lround((pz - cl_prev[p].z) * st);
            ph = (cl_prev[p].heading + (int)lround(dh * st)) & 4095;
        }
        if (st >= 0 && getenv("TM2PC_INTERP_DEBUG")) fprintf(stderr, "carsel: player %d at t %.2f heading %d (%d..%d)\n", p + 1, st, ph, cl_prev[p].heading, cl.p[p].heading);
        if (getenv("TM2PC_CARSEL_HEADING")) ph = atoi(getenv("TM2PC_CARSEL_HEADING")) & 4095; /* tests: the cars held at a heading (pictures) */
        mem_w8(c, node + 7, (uint8_t)cs_node_car(c, node, p));
        mem_w32(c, obj + 24, (uint32_t)px);
        mem_w32(c, obj + 28, (uint32_t)(depth + py));
        mem_w32(c, obj + 32, (uint32_t)(z + pz)); /* lower, as further */
        mem_w32(c, obj + 36, (uint32_t)ph);
        mem_w32(c, obj + 40, 0);
        mem_w32(c, obj + 44, 0);
        cl_offset = p;
        c->r[4] = obj;
        c->r[5] = frame;
        static uint32_t ot_before[4096];
        uint32_t otb = mem_r32(c, frame);
        int dbg = getenv("TM2PC_OT_DEBUG") != NULL;
        if (dbg) for (int i = 0; i < 4096; i++) ot_before[i] = mem_r32(c, otb + (uint32_t)i * 4);
        team_paint_begin(c, node, cs_byte(cs2[p].car), p); /* with teams: their team's colors */
        void port_precise_ring_drop(void); /* vplus/port_config.c */
        if (p == 0) port_precise_ring_drop(); /* (the emitter's places of an earlier build: not this one's) */
        gte_tr_smooth_begin(p, st); /* (its turning car: no rocking) */
        vp_emit_fine = 2; /* (sorted finely: vplus/precise.c) */
        F_80122124_orig(c);
        vp_emit_fine = 0;
        gte_tr_smooth_end();
        team_paint_end(c);
        mem_w32(c, frame, ot);
        if (dbg) {
            int lo = 4096, hi = -1;
            for (int i = 0; i < 4096; i++) if (mem_r32(c, otb + (uint32_t)i * 4) != ot_before[i]) { if (i < lo) lo = i; if (i > hi) hi = i; }
            fprintf(stderr, "ot: player %d car %d slots %d..%d\n", p, cs2[p].car, lo, hi);
        }
        cl_offset = -1;
    }
    for (int i = 0; i < 6; i++) mem_w32(c, obj + 24 + (uint32_t)i * 4, pos[i]);
    if (cl.split) {
        int16_t cx = (int16_t)mem_r16(c, frame + 0x10), cy = (int16_t)mem_r16(c, frame + 0x12);
        int16_t cw = (int16_t)mem_r16(c, frame + 0x14), ch = (int16_t)mem_r16(c, frame + 0x16);
        for (int p = 0; p < cl.n; p++) { /* each player's view (before their group: the slot above it) */
            int vx, vy, vw, vh;
            split_view(p, &vx, &vy, &vw, &vh);
            int x0 = cx + (int)((float)vx * cw / split_wu), x1 = cx + (int)((float)(vx + vw) * cw / split_wu) - 1;
            int y0 = cy + vy * ch / 480, y1 = cy + (vy + vh) * ch / 480 - 1;
            ot_area(c, frame, ot, p == 0 ? 4095 : 1024 * (cl.n - p) - 1, x0, y0, x1, y1);
        }
        ot_area(c, frame, ot, 0, cx, cy, cx + cw - 1, cy + ch - 1);       /* then the whole picture */
        if (carsel_hd && names_as_sprites && !turntable_on()) ot_names(c, frame); /* the names over the cars, last */
    }
    /* the hand-over: the carousel on the player's car while the game takes X */
    mem_w8(c, node + 7, cl.finishing && !cl.back ? (uint8_t)cs_node_car(c, node, cl.inject_p < 2 ? cl.inject_p : 1) : saved_car);
    (void)0;
}

/* The 2-player overlay: the top (the picture, both portraits, the titles),
 * each player's name under their car, and the portrait bar with the tags. */
/* The shared screen's art (640x480 places): both portraits, the titles, each
 * player's name under their car, the drivers' bar with the tags. rects: the
 * overlay's name rectangles (NULL in the background). */
static void carsel_compose2_art(const View *vp, Image *ovp, int item, int rects[][4])
{
    static const uint8_t frame[3] = {60, 60, 66}, black[3] = {0, 0, 0};
    View v = *vp;
    float k = bg_carsel.h / 480.0f;
    /* the portraits: player 1 where the game's is, player 2 mirrored at the right; 3-4
     * players: all along the top, in their order (the buttons' legend makes room) */
    static const int PX2[2] = {56, 456}, PX3[3] = {56, 256, 456}, PX4[4] = {16, 176, 336, 496};
    int n = carsel_live_on() ? cl.n : 2;
    const int *PX = n == 4 ? PX4 : n == 3 ? PX3 : PX2;
    for (int p = 0; p < n; p++) {
        int t = S(&v, 3);
        int ph = getenv("TM2PC_CARSEL_PH") ? atoi(getenv("TM2PC_CARSEL_PH")) : 256; /* the whole portrait, as one player's (cropped at 200 a mod's or a skin's was squeezed; the user's, 2026-11-04); tests: TM2PC_CARSEL_PH */
        int borders = vp_on(VP_CARSEL_BORDERS); /* the player's color: a border and their tag */
        if (borders)
            draw_fill(ovp, X(&v, PX[p]) - t, Y(&v, CS_PORTRAIT_Y) - t, S(&v, 128) + 2 * t, S(&v, ph) + 2 * t, PLAYER_COLOR[p], 255);
        if (skin_portrait(ovp, cs_look(p), cs2[p].locked, X(&v, PX[p]), Y(&v, CS_PORTRAIT_Y), S(&v, 128), S(&v, ph))) ; /* (a skin) */
        else if (cs2[p].car >= PROFILE_CHARACTERS)
            draw_car_portrait(&v, cs2[p].car, cs2[p].locked, X(&v, PX[p]), Y(&v, CS_PORTRAIT_Y), S(&v, 128), S(&v, ph));
        else if (portraits.px && portraits.w >= PROFILE_CHARACTERS * 2) {
            /* each driver's portrait scaled once and copied after (four scaled each change: the cars stalled, the
             * user's 2026-11-04) */
            static Image scaled[PROFILE_CHARACTERS * 2];
            static int scaled_key[PROFILE_CHARACTERS * 2];
            static const void *scaled_src;
            if (scaled_src != portraits.px) { memset(scaled_key, 0, sizeof scaled_key); scaled_src = portraits.px; }
            int i = cs2[p].car * 2 + cs2[p].locked, w = S(&v, 128), h = S(&v, ph), key = w * 65536 + h + 1;
            float fw = (float)portraits.w / (PROFILE_CHARACTERS * 2);
            if (scaled_key[i] != key && image_resize(&scaled[i], w, h)) {
                draw_image(&scaled[i], &portraits, i * fw + 1, 1, fw - 2, portraits.h * ph / 256.0f - 1, 0, 0, w, h, 0);
                scaled_key[i] = key;
            }
            if (scaled_key[i] == key) blit_image(ovp, &scaled[i], X(&v, PX[p]), Y(&v, CS_PORTRAIT_Y));
            else draw_image(ovp, &portraits, i * fw + 1, 1, fw - 2, portraits.h * ph / 256.0f - 1, X(&v, PX[p]), Y(&v, CS_PORTRAIT_Y), w, h, 0);
        }
        char tg[4] = {'P', (char)('1' + p), 0};
        int ts = S(&v, 16), tw = text_width(tg, ts);
        int gx = n == 2 && p ? X(&v, PX[p] + 128) - tw - S(&v, 4) : X(&v, PX[p]);
        if (borders) draw_fill(ovp, gx, Y(&v, CS_PORTRAIT_Y), tw + S(&v, 4), ts + S(&v, 4), PLAYER_COLOR[p], 255);
        if (borders) text_draw(ovp, tg, gx + S(&v, 2), Y(&v, CS_PORTRAIT_Y + 1), ts, WHITE);
    }
    /* the shared screen has no SELECT CAR / CAR INFO: what the buttons do, between the portraits */
    (void)item;
    lettering();
    static const char *const legend[4] = {CROSS " SELECT", SQUARE " CAR INFO", CIRCLE " BACK", TRIANGLE " CHANGE TEAM"};
    int lines = carsel_teams() ? 4 : 3;
    for (int i = 0; i < lines && n == 2; i++) {
        int size = S(&v, 19), w = legend_text(&v, legend[i], 0, 0, size, 0);
        legend_text(&v, legend[i], X(&v, 320) - w / 2, text_top_for_center(Y(&v, 50 + i * 30), size), size, 1);
    }
    if (n > 2 && carsel_teams()) {
        int size = S(&v, 16), w = legend_text(&v, legend[3], 0, 0, size, 0);
        legend_text(&v, legend[3], X(&v, 320) - w / 2, text_top_for_center(Y(&v, CS_PORTRAIT_Y + 212), size), size, 1);
    }
    /* each player's name under their car (the game's label is not drawn) */
    for (int p = 0; p < n; p++) {
        int cx = 320 + 2 * (carsel_live_on() ? shared_dx(p) : (p ? CL_DX : -CL_DX)), y0 = CS_NAME_Y - 14;
        int nw = n <= 2 ? 240 : 640 / n - 8; /* the name's box: 3-4 players, narrower */
        cs_part(&v, &bg_carsel, (int)((cx - nw / 2) * k), (int)(y0 * k), (int)(nw * k), (int)(28 * k), cx - nw / 2, y0, nw, 28, 0);
        char line[48];
        snprintf(line, sizeof line, "%s", car_label(cs_look(p)));
        draw_car_name(&v, ovp, line, cx, CS_NAME_Y + 8, cs2[p].locked);
        if (rects && p < 2) {
            rects[3 + p][0] = X(&v, cx - nw / 2); rects[3 + p][1] = Y(&v, y0);
            rects[3 + p][2] = S(&v, nw); rects[3 + p][3] = S(&v, 28);
        } else if (rects && p < 4) { /* 3-4: the names' row as one rectangle (rect 5) */
            rects[5][0] = 0; rects[5][1] = Y(&v, y0); rects[5][2] = ovp->w; rects[5][3] = S(&v, 28);
        }
    }
    /* the portrait bar: each player's driver framed in their color, with their tag */
    int bfirst, shown, x0;
    bar_window(cs2[0].car, 320, 640, CS_PITCH, &bfirst, &shown, &x0);
    bar_arrows(&v, ovp, bfirst, shown, x0, CS_PITCH, CS_ROW_Y, CS_THUMB_H);
    for (int col = 0; col < shown; col++) {
        int car = bar_car(bfirst + col), first = -1, second = -1, chosen = 0;
        unsigned on = 0;
        for (int q = 0; q < n; q++)
            if (cs2[q].car == car) {
                on |= 1u << q;
                if (first < 0) first = q; else if (second < 0) second = q;
                chosen |= cs2[q].locked; /* locked in: the second portrait, dimmed */
            }
        int x = X(&v, x0 + col * CS_PITCH), y = Y(&v, CS_ROW_Y), w = S(&v, CS_THUMB_W), h = S(&v, CS_THUMB_H);
        int t = first >= 0 ? S(&v, 3) : (S(&v, 1) > 1 ? S(&v, 1) : 1);
        strip_frame(ovp, x, y, w, h, t, on, first, second, frame);
        draw_fill(ovp, x, y, w, h, black, 255);
        draw_car_portrait(&v, car, chosen, x, y, w, h);
        if (chosen) draw_fill(ovp, x, y, w, h, black, 110);
        int tag = S(&v, 11), slot = 0;
        for (int p = 0; p < n; p++)
            if (cs2[p].car == car) {
                char tg[4] = {'P', (char)('1' + p), 0};
                int tw = text_width(tg, tag), gx = x + ((slot & 1) ? w - tw - 2 : 0), gy = y + ((slot & 2) ? h - tag - 2 : 0);
                draw_fill(ovp, gx, gy, tw + 2, tag + 2, PLAYER_COLOR[p], 255);
                text_draw(ovp, tg, gx + 1, gy, tag, WHITE);
                slot++;
            }
    }
}

static void carsel_compose2(Image *ovp, int item, int rects[][4])
{
    View v = view_fit(ovp);
    memset(ovp->px, 0, (size_t)ovp->w * ovp->h * 3);
    float k = bg_carsel.h / 480.0f;
    cs_part(&v, &bg_carsel, 0, 0, bg_carsel.w, (int)(CS_TOP * k), 0, 0, 640, CS_TOP, 0);
    cs_part(&v, &bg_carsel, 0, (int)(CS_BOTTOM * k), bg_carsel.w, bg_carsel.h - (int)(CS_BOTTOM * k), 0, CS_BOTTOM,
            640, 480 - CS_BOTTOM, 0);
    cs_part(&v, &bg_carsel, (int)(CS_PORTRAIT_X * k), (int)(CS_TOP * k), (int)(CS_PORTRAIT_W * k),
            (int)((CS_PORTRAIT_END - CS_TOP) * k), CS_PORTRAIT_X, CS_TOP, CS_PORTRAIT_W, CS_PORTRAIT_END - CS_TOP, 0);
    carsel_compose2_art(&v, ovp, item, rects);
    rects[0][0] = X(&v, 0); rects[0][1] = 0; rects[0][2] = S(&v, 640); rects[0][3] = Y(&v, CS_TOP);
    rects[1][0] = X(&v, 0); rects[1][1] = Y(&v, CS_BOTTOM); rects[1][2] = S(&v, 640); rects[1][3] = ovp->h - Y(&v, CS_BOTTOM);
    /* the portraits' lower part (the game's portrait is twice as tall) */
    rects[2][0] = X(&v, CS_PORTRAIT_X); rects[2][1] = Y(&v, CS_TOP);
    rects[2][2] = S(&v, CS_PORTRAIT_W); rects[2][3] = Y(&v, CS_PORTRAIT_END) - Y(&v, CS_TOP);
    if (!(carsel_live_on() && cl.n > 2)) { rects[5][0] = 0; rects[5][1] = 0; rects[5][2] = 0; rects[5][3] = 0; }
}

/* ---- the pause menu ----
 * The game's pause (80129528, decomp game_code10.c), called every frame: on
 * Start (pad 1, or pad 2 in split screen) it stops the music, darkens the
 * frame and shows BATTLE PAUSED with RESUME and QUIT (and the tournament's
 * password when it has one), Up/Down and Start, then resumes the music or
 * aborts the battle. The port draws its own at the window's resolution, over
 * the paused frame: RESUME, OPTIONS (the Options pages that can change during
 * a battle) and QUIT, the game's own steps kept around it. */
#define SETTINGS_BLOCK GA(0x8016475Cu)
#define PAUSE_PASSWORD GA(0x80191074u)      /* the password text sub_801292A4 writes */
#define PAUSE_SHOWN_VBLANKS 60          /* "BATTLE ABORTED" before the battle ends */
void F_80129528_orig(CPU *c);
void vp_pause_boom(void);               /* vplus/fixes.c: Pause menu boom */

static const char *const pause_items[4] = {"RESUME", "OPTIONS", "PHOTO MODE", "QUIT"};
static const char *const *menu_items = pause_items; /* the menu shown: the pause's, or a tournament one */
static int menu_count = 4;
static const char *menu_title = "BATTLE PAUSED";
static unsigned pause_frame_gen; /* (each new picture: the results backdrop made again) */
static Image pause_frame;               /* the paused game, as it was shown */
static const char *menu_note;           /* a line under a tournament menu's items for a while ("SAVE COMPLETE") */
static uint64_t menu_note_until;        /* SDL_GetTicksNS() */
static int menu_keep_frame;             /* the next tournament menu keeps the frame behind it (back from a page) */

static int menu_items_y = 140, menu_note_y = 205; /* the first item's line (the game's 320x240); the level's menu: under its texts */
static void compose_pause(Image *c, int sel, const char *password, const char *banner)
{
    static const uint8_t black[3] = {0, 0, 0};
    /* the game's fonts and colors (font_init.c, 801142B0): 6 the title, 0 an
     * item, 1 the chosen one, 5 the password in 255,161,0 */
    static const uint8_t title_c[3] = {115, 84, 35}, item_c[3] = {93, 30, 23}, chosen_c[3] = {115, 61, 27},
                         password_c[3] = {255, 161, 0};
    memset(c->px, 0, (size_t)c->w * c->h * 3);
    /* the game's 320x240 screen, at the window's height, centered */
    float s = c->h / 240.0f;
    if (c->w / 320.0f < s) s = c->w / 320.0f; /* narrower than 4:3: letterboxed */
    float ox = (c->w - 320 * s) / 2, oy = (c->h - 240 * s) / 2;
    if (pause_frame.px) { /* the frame at its own aspect, darkened by half as the game's */
        int h = c->h, w = (int)((float)pause_frame.w * h / pause_frame.h + 0.5f);
        if (w > c->w) { w = c->w; h = (int)((float)pause_frame.h * w / pause_frame.w + 0.5f); } /* narrower: letterboxed */
        draw_image(c, &pause_frame, 0, 0, (float)pause_frame.w, (float)pause_frame.h, (c->w - w) / 2, (c->h - h) / 2, w, h, 0);
        draw_fill(c, 0, 0, c->w, c->h, black, 128);
    }
    if (!gfont_ready(0) || !gfont_ready(6)) { /* without the font sheet: the port's lettering */
        View v = view_fit(c);
        lettering();
        int ts = S(&v, TITLE_SIZE);
        const char *title = banner ? banner : menu_title;
        text_draw(c, title, X(&v, 320) - text_width(title, ts) / 2, text_top_for_center(Y(&v, 120), ts), ts, TITLE);
        for (int i = 0; i < menu_count && !banner; i++) {
            int size = S(&v, 28), cy = Y(&v, 280 + i * 40), w = text_width(menu_items[i], size);
            text_draw(c, menu_items[i], X(&v, 320) - w / 2, text_top_for_center(cy, size), size, i == sel ? ORANGE : WHITE);
        }
        return;
    }
    /* as fontPrintCenteredXY(font, 159, y, text) */
#define PAUSE_TEXT(font, text, gy, color) \
    gfont_draw(c, font, text, ox + (159 - (gfont_width(font, text) >> 1)) * s, oy + (gy) * s, s, color)
    { /* (a long title, "KRISTA SPARKS WINS THE TOURNAMENT!": the items' font, to fit the screen) */
        const char *t = banner ? banner : menu_title;
        PAUSE_TEXT(gfont_width(6, t) > 312 ? 0 : 6, t, 60, title_c);
    }
    if (banner) return;
    for (int i = 0; i < menu_count; i++) /* the game: RESUME at 140, QUIT at 160; OPTIONS between */
        PAUSE_TEXT(i == sel ? 1 : 0, menu_items[i], menu_items_y + 20 * i, i == sel ? chosen_c : item_c);
    if (password && *password)
        PAUSE_TEXT(5, password, 222, password_c);
    else if (menu_note && SDL_GetTicksNS() < menu_note_until)
        PAUSE_TEXT(0, menu_note, menu_note_y, password_c);
#undef PAUSE_TEXT
}

/* Shows the pause screen until a choice: 0 resume, 2 quit (Options opens
 * the pages and comes back here). Runs the game's VBlanks, as its own pause
 * does (VSync), so its sounds play. */
static int pause_run(const char *password)
{
    int sel = 0, dirty = 1, held_for[2] = {0}, chosen = -1, menu_key;
    uint16_t prev = 0xFFFF;
    Image canvas = {0, 0, NULL};
    display_hold = 0; /* this page takes the screen */
    Psyz_VideoSetDisplayRGB24Fill(1);
    while (chosen < 0) {
        uint16_t b = menu_input(&menu_key), pressed = (uint16_t)(b & ~prev);
        static const uint16_t dirs[2] = {B_UP, B_DOWN};
        for (int d = 0; d < 2; d++) {
            if (!(b & dirs[d])) { held_for[d] = 0; continue; }
            if (++held_for[d] > 18 && (held_for[d] - 18) % 6 == 0) pressed |= dirs[d];
        }
        prev = b;
        if (pressed & (B_UP | B_DOWN)) {
            sel = (sel + ((pressed & B_UP) ? menu_count - 1 : 1)) % menu_count;
            spu_port_keyon = 1; /* the pause's own sounds: not thinned as a battle's stacked sounds */
            guest_call(GA(0x800D3334u), 28, 0, 0, 99); /* the game's cursor sound, as its pause */
            guest_call(GA(0x800D34C0u), 0, 0, 0, 0);
            guest_call(GA(0x800D34E8u), 0, 0, 0, 0);
            spu_port_keyon = 0;
            dirty = 1;
        } else if (pressed & (B_CIRCLE | B_START)) { /* (Start: resume, as the game's; not the item under the cursor:
                                                       * back from photo mode it reopened photo mode, the user's) */
            sel = 0;
            chosen = 0;
        } else if (pressed & B_CROSS) {
            if (sel == 2) { /* photo mode, then back here */
                /* the pause's picture off first: left up, it hid every frame photo mode drew (its camera seemed never to
                 * move, the user's) */
                Psyz_VideoSetDisplayRGB24Fill(0);
                Psyz_VideoSetDisplayRGB24(NULL, 0, 0);
                int photo = photo_mode_run();
                if (photo == 1) { /* a rewind's moment: the battle goes there (the photo stays) */
                    pause_rewinding = 1;
                    image_free(&canvas);
                    return 0;
                }
                if (photo == 3) chosen = 0; /* X (play) at the present: the battle on */
                sel = 0; /* back from photo mode: the cursor on Resume (X there reopened photo mode, the user's) */
                Psyz_VideoSetDisplayRGB24Fill(1);
                prev = 0xFFFF;
                dirty = 1;
            } else if (sel == 1) { /* the Options pages, then back here */
                from_title = 0;
                run(PAGE_MAIN);
                Psyz_VideoSetDisplayRGB24Fill(1);
                prev = 0xFFFF;
                dirty = 1;
            } else {
                chosen = sel == 3 ? 2 : sel; /* QUIT: the callers' 2 */
            }
        }
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) &&
            image_resize(&canvas, size.w, size.h)) {
            compose_pause(&canvas, sel, password, NULL);
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
            dirty = 0;
        }
        rt_vblank(); /* the game's VBlank (sounds), and the frame shown */
    }
    /* the confirm sound and the game's steps after it, heard over "BATTLE ABORTED" */
    /* the menus' select boom (the battle's sound 29 is a lower, quieter explosion) */
    if (settings_game.menu_sounds) menu_sound(1);
    else { guest_call(GA(0x800D3334u), 29, 0, 0, 99); guest_call(GA(0x800D34C0u), 0, 0, 0, 0); guest_call(GA(0x800D34E8u), 0, 0, 0, 0); vp_pause_boom(); }
    if (chosen == 2) { /* "BATTLE ABORTED" a moment, as the game */
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w > 0 && size.h > 0 && image_resize(&canvas, size.w, size.h)) {
            compose_pause(&canvas, sel, NULL, "BATTLE ABORTED");
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
        }
        for (int i = 0; i < PAUSE_SHOWN_VBLANKS; i++) rt_vblank();
    }
    /* the game goes on with the buttons released */
    while (input_menu_buttons(&menu_key) && !script)
        rt_vblank();
    Psyz_VideoSetDisplayRGB24Fill(0);
    Psyz_VideoSetDisplayRGB24(NULL, 0, 0);
    image_free(&canvas);
    return chosen;
}

void ui_PauseMenu(CPU *c)
{
    void rbs_iteration_end(void); /* net/rb_state.c: between two steps */
    rbs_iteration_end();
    start_once();
    load_art();
    if ((!M.live_input && !script) || !text_ready() || in_pause) {
        F_80129528_orig(c); /* tests and tapes: the game's own */
        return;
    }
    /* as the game: only in a battle, on Start from pad 1 (or pad 2 in split screen) */
    if (!guest_call(GA(0x8012CC04u), SETTINGS_BLOCK, 0, 0, 0))
        return;
    int pause_port = 0, back_from_rewind = pause_again >= 0;
    if (pause_again >= 0) { /* back from photo mode rewind */
        pause_port = pause_again;
        pause_again = -1;
    } else if (!guest_call(GA(0x80150CFCu), 8, 0, 0, 0)) {
        if (!(guest_call(GA(0x800D1C18u), 0, 0, 0, 0) && guest_call(GA(0x80150CFCu), 8, 1, 0, 0)))
            return;
        pause_port = 1;
    }
    last_pause_port = pause_port;
    in_pause = 1;
    uint64_t paused_at = M.vblanks; /* the game's clock stands still while paused (time limits, timers) */
    feats_flush(); /* what was done so far, kept */
    int w = 0, h = 0;
    unsigned char *shot = pause_rewinding ? NULL : ui_capture_clean(&w, &h); /* (back from a rewind: the frame paused on) */
    pause_rewinding = 0;
    if (shot) { image_free(&pause_frame); pause_frame.w = w; pause_frame.h = h; pause_frame.px = shot; pause_frame_gen++; }
    cd_audio_pause(1); /* the music stops where it is (and goes on from there) */
    /* and the sounds playing (engines, flamethrowers...), as the game's pause
     * does (in screenLostALife, 8012940C): the sound object at gp+500 */
    port_sounds_stop();
    set_serial_volume(0);
    /* the tournament's password (from level 2; not for Sweet Tooth or Minion) */
    char password[64] = "";
    if (!vp_on(VP_PASSWORDS_OFF) && /* without passwords, none shown here either */
        guest_call(GA(0x8012CC04u), SETTINGS_BLOCK, 0, 0, 0) == 1 && (int32_t)guest_call(GA(0x8012CB90u), SETTINGS_BLOCK, 0, 0, 0) >= 2) {
        int car = (int8_t)guest_call(GA(0x8012CBD4u), SETTINGS_BLOCK, 0, 0, 0);
        if (car != 12 && car != 13) {
            guest_call(GA(0x801292A4u), 0, 0, 0, 0);
            for (int i = 0; i < (int)sizeof password - 1; i++) {
                password[i] = (char)mem_r8(&M.cpu, PAUSE_PASSWORD + (uint32_t)i);
                if (!password[i]) break;
            }
        }
    }
    guest_call(GA(0x80150C50u), 0, 0, 0, 0);
    /* tests: TM2PC_PAUSE_SCRIPT drives the pause menu (and the pages it opens) */
    const char *saved_script = script, *pause_script = getenv(back_from_rewind ? "TM2PC_PAUSE_SCRIPT_AFTER" : "TM2PC_PAUSE_SCRIPT");
    if (pause_script) { script = pause_script; script_tick = 600 - 24; }
    input_set_menu_player(pause_port); /* the player who paused */
    int chosen = pause_run(password);
    input_set_menu_player(0);
    script = saved_script;
    if (!pause_rewinding) cd_audio_pause(0); /* (a rewind: the music waits) */
    if (chosen == 0) { /* resume: the music goes on, at the music volume */
        if (!pause_rewinding) set_serial_volume((int32_t)guest_call(GA(0x800D362Cu), 0, 0, 0, 0));
        guest_call(GA(0x80150C50u), 1, 0, 0, 0);
        /* as the game's pause: the pads read until every button is let go, so
         * the press that resumed is not seen as a new one (a Start pausing again) */
        while (guest_call(GA(0x80150CD8u), (uint32_t)pause_port, 0, 0, 0) & 0xFF) {
            rt_vblank();
            guest_call(GA(0x80150E00u), 0, 0, 0, 0);
        }
        guest_call(GA(0x80150E00u), 0, 0, 0, 0);
    } else { /* quit: the battle ends */
        two_return = battle_live ? 0 : mem_r8(&M.cpu, SETTINGS_BLOCK + 4) >= 2 ? 2 : 1;
        music_call(3, 2);
        guest_call(GA(0x800D181Cu), 2, 0, 0, 0);
    }
    if (!pause_rewinding) { image_free(&pause_frame); pause_frame_gen++; } /* (a rewind: kept for the pause after it) */
    M.vblank_offset += M.vblanks - paused_at; /* (vp_gv, VSync(-1): the pause's VBlanks left out) */
    in_pause = 0;
    fprintf(stderr, "pause: %s\n", chosen == 0 ? "resume" : "quit");
}

/* ---- between tournament levels, and after the last life (decomp TOURNAMENT_FLOW.md) ----
 * screenScrollText (80136BB0) runs a level (the session runner, 8012BE5C)
 * and returns the next screen. After a won level 1-7 it returns 801334C0
 * (the next level's opponents, the globe, the arena) with level +24 already
 * the next one: here CONTINUE goes on, SAVE puts the run in one of the
 * profile's save slots (1 player), QUIT goes to the title as the pause
 * menu's Quit does. After the last life (the runner's result 1) it returns
 * the title: here RESTART plays the level again from its start (the
 * settings set as the decomp's recipe: the players and their cars kept;
 * the opponents, their count and the lives anew), QUIT goes on to the
 * title. Drawn as the pause menu, over the last frame. */
#define RUNNER_WON 3
#define RUNNER_LOST 1
#define NEXT_LEVEL_SCREEN GA(0x801334C0u)
#define TITLE_SCREEN GA(0x8012DF84u)
static int runner_result = -1;

/* ---- the co-op tournament's duel ----
 * Won co-op (level 8, Dark Tooth beaten): the game shows COWIN.TIM, then the
 * title. Here its picture is the duel's (DUEL_TEXT: "there can only be ONE
 * winner... Be the last one standing"), then the two players fight it out:
 * Deathmatch (mode 4) on level 8, no computer cars, one round, one life each
 * (decomp MATCH_START.md 4). With 3-4 players: everyone (their cars kept,
 * vplus/four.c), on the port's last-car-standing rules (a Challenge Match
 * of Twisted Metal, one life, no computer cars: vp_duo). The winner's ending
 * plays (screenEnding 80136D98, as for one player) and goes to every
 * player's profile. */
static const char *match_human_name(int h); /* (below) */
int humans_local_count(void);               /* vplus/humans.c */
int humans_slot(int h);                    /* vplus/humans.c: human -> this PC's view (-1: another machine's) */
static int duel_active, duel_result;
static int coop_duel_next(void) /* the co-op tournament was just won: its duel comes */
{
    return (M.live_input || script) && text_ready() && !getenv("TM2PC_NO_DUEL") && runner_result == RUNNER_WON &&
           mem_r8(&M.cpu, SETTINGS_BLOCK) == 2 && mem_r8(&M.cpu, SETTINGS_BLOCK + 24) == 8;
}
static int tournament_menu(const char *title, const char *const *items, int count);
static uint32_t coop_duel(void)
{
    const uint32_t S = SETTINGS_BLOCK;
    uint8_t saved[48];
    for (int i = 0; i < 48; i++) saved[i] = mem_r8(&M.cpu, S + (uint32_t)i);
    int n = four_humans() > 2 ? four_humans() : 2;
    int car[4] = {(int8_t)saved[8], (int8_t)saved[9], four_car_of(2), four_car_of(3)}, difficulty = saved[36];
    int mod_cars_human_car(int h), mod_car_is_character(int number); /* vplus/mod_cars.c */
    int number[4]; /* (a mod character's number: its own ending, never its base car's) */
    for (int p = 0; p < 4; p++) number[p] = mod_cars_human_car(p) >= 0x20 && mod_car_is_character(mod_cars_human_car(p)) ? mod_cars_human_car(p) : -1;
    fprintf(stderr, "co-op: the duel (%d players: %s, %s%s%s%s%s)\n", n, profile_character_name(car[0]), profile_character_name(car[1]),
            n > 2 ? ", " : "", n > 2 ? profile_character_name(car[2]) : "", n > 3 ? ", " : "", n > 3 ? profile_character_name(car[3]) : "");
    MatchSetup match_saved = *battle_match();
    int live_saved = battle_live, survival_saved = survival_on;
    const GameType *type_saved = battle_type_overridden();
    if (n > 2) { /* everyone: the port's rules (a Challenge Match of Twisted Metal: the last car alive, one life) */
        /* (online the server's game type is in place, the match's name not read: its Deathmatch made the duel one
         * to kills with respawns, a player's report 2026-11-21) */
        battle_type_override(battle_builtin(0)); /* Twisted Metal */
        MatchSetup *m = battle_match();
        snprintf(m->game_type, sizeof m->game_type, "Twisted Metal");
        m->arena = 8;
        m->opponents = 0;
        m->lives = 1;
        m->kills = m->time_limit = m->teams = 0;
        battle_live = 1;
        survival_on = 0;
        battle_new_match = 1;
    }
    guest_call(GA(0x80137948u), S, n > 2 ? 3 : 4, 0, 0); /* mode: 2 players against each other (3-4: the challenge mode, the port's rules) */
    guest_call(GA(0x80137930u), S, 2, 0, 0);           /* two humans */
    guest_call(GA(0x80137864u), S, 0, 0, 0);           /* the opponents' slots cleared */
    guest_call(GA(0x80137918u), S, 0, 0, 0);           /* no computer cars */
    guest_call(GA(0x80137814u), S, 8, 0, 0);           /* level 8 */
    guest_call(GA(0x801377FCu), S, 0, 0, 0);           /* from its start (no Dark Tooth stage) */
    for (int p = 0; p < 2; p++) {
        guest_call(GA(0x801378A4u), S, (uint32_t)p, (uint32_t)car[p], 0);
        guest_call(GA(0x80137820u), S, (uint32_t)p, 1, 0); /* one life */
    }
    guest_call(GA(0x8011ED88u), (uint32_t)(n > 2 ? 3 : 4), 0, 0, 0); /* gameSetMode: a death is a round's end (3 / 4) */
    mem_w32(&M.cpu, GA(0x80188B5Cu) + 0x30, 0);        /* computer car 0 no longer Dark Tooth */
    duel_active = 1;
    duel_result = 0;
    if (getenv("TM2PC_TEST_DUEL_RESULT")) { /* tests: this result, without the round */
        duel_result = atoi(getenv("TM2PC_TEST_DUEL_RESULT"));
    } else {
        guest_call(GA(0x801414CCu), 0, 0, 0, 0);       /* as screenScrollText before its run */
        guest_call(GA(0x8014510Cu), 0, 0, 0, 0);
        guest_call(GA(0x8012BE5Cu), S, 0, 0, 0);       /* sessionRun(settings): one round (ui_MainLoop quits after it) */
    }
    duel_active = 0;
    int duo_h = -1, duo_ai = -1; /* (3-4 players: the player left, asked while the duel's settings are still in place: vp_duo
                                  * reads the mode; asked after they were put back it said none, and no ending played) */
    int duo_won = n > 2 && duel_result == 3 && vp_duo_winner(&duo_h, &duo_ai);
    for (int i = 0; i < 48; i++) mem_w8(&M.cpu, S + (uint32_t)i, saved[i]);
    int winner = duel_result == 3 ? 0 : duel_result == 4 ? 1 : -1;
    if (n > 2) { /* the port's rules: the player left */
        winner = duo_won && duo_h >= 0 && duo_h < n ? duo_h : -1;
        if (getenv("TM2PC_TEST_DUEL_RESULT")) winner = duel_result == 3 ? 0 : -1;
        *battle_match() = match_saved;
        battle_type_override(type_saved);
        battle_live = live_saved;
        survival_on = survival_saved;
    }
    fprintf(stderr, "co-op: the duel's result %d\n", duel_result);
    if (winner < 0) return TITLE_SCREEN;
    static char title[64];
    static const char *const anon[4] = {"PLAYER 1", "PLAYER 2", "PLAYER 3", "PLAYER 4"};
    const char *who = net_tour_on && netplay_in_match() ? match_human_name(winner)
                    : winner == 0 ? (profile_signed_in() ? profile_name() : anon[0])
                    : winner == 1 ? (profile_p2_name()[0] ? profile_p2_name() : anon[1])
                                  : (profile_extra_name(winner)[0] ? profile_extra_name(winner) : anon[winner]);
    snprintf(title, sizeof title, "%s WINS", who);
    upper(title);
    static const char *const items[1] = {"CONTINUE"};
    tournament_menu(title, items, 1);
    fprintf(stderr, "co-op: %s wins the duel (%s)\n", who, profile_character_name(car[winner]));
    /* the winner's ending, as a won 1-player tournament's (profile_WinnerMovies records it for player 1's profile) */
    guest_call(GA(0x80137948u), S, 1, 0, 0);
    guest_call(GA(0x80137930u), S, 1, 0, 0);
    guest_call(GA(0x801378A4u), S, 0, (uint32_t)car[winner], 0);
    static uint32_t numbers = 1; /* (a character: its number as player 1's, so screenEnding shows its ending) */
    if (numbers == 1) numbers = port_sym("portSettingsHumanCar");
    if (numbers && number[winner] >= 0) mem_w16(&M.cpu, numbers, (uint16_t)number[winner]);
    int local = net_tour_on && netplay_in_match() ? humans_local_count() : n; /* (online: this PC's players' profiles) */
    const char *mod_car_uid(int number), *mod_car_name(int number);
    for (int p = 1; p < n && p < local; p++) { /* players 2-4 too */
        if (number[winner] >= 0 && p == 1) profile_p2_mod_tournament_won(mod_car_uid(number[winner]), mod_car_name(number[winner]), difficulty);
        else if (number[winner] >= 0) profile_extra_mod_tournament_won(p, mod_car_uid(number[winner]), mod_car_name(number[winner]), difficulty);
        else if (p == 1) profile_p2_tournament_won(car[winner], difficulty);
        else profile_extra_tournament_won(p, car[winner], difficulty);
    }
    uint32_t next = guest_call(GA(0x80136D98u), 0, 0, 0, 0);
    for (int i = 0; i < 48; i++) mem_w8(&M.cpu, S + (uint32_t)i, saved[i]);
    if (net_tour_on && netplay_in_match()) return TITLE_SCREEN; /* (online: the ending seen, the server's lobby) */
    return next ? next : TITLE_SCREEN;
}

void wide_rows_restore(void); /* vplus/wide.c */
void wide_round(int on);
void F_8012BE5C_orig(CPU *c);
void ui_SessionRunner(CPU *c)
{
    const char *test = duel_active ? NULL : getenv("TM2PC_TEST_RUNNER"); /* tests: no level, this result (the duel plays) */
    int mode = mem_r8(&M.cpu, SETTINGS_BLOCK), humans = mem_r8(&M.cpu, SETTINGS_BLOCK + 4);
    for (int p = 0; p < humans && p < 2 && (mode == 1 || mode == 2); p++) feat_set(p, FEAT_TOURNAMENT_STARTED);
    if (tournament_new && (mode == 1 || mode == 2)) {
        tournament_new = 0;
        for (int p = 0; p < (four_humans() > 2 ? four_humans() : humans) && p < 4; p++) stat_add(p, STAT_TOURNAMENTS, 1);
    } else if (mode == 3 || mode == 4) tournament_new = 0;
    if (test) {
        c->r[2] = (uint32_t)atoi(test);
        if (c->r[2] == RUNNER_LOST) mem_w8(&M.cpu, SETTINGS_BLOCK + 20, 0);
    } else {
        int custom = battle_live && (mode == 3 || mode == 4);
        if (custom) mem_w8(&M.cpu, SETTINGS_BLOCK + 36, (uint8_t)(survival_on ? 2 : battle_match()->difficulty));
        if (custom && (mode == 3 || (mode == 4 && (M.live_input || script)))) /* the cars' cards dealt, as before a tournament
                                  * level (all players, no computer cars: the players' cards; the game's own LOADING over the globe
                                  * was low resolution, the user's). Mode 4 (2 players, no computer cars) too, the port's line-up
                                  * only: it had the game's LOADING globe, low resolution and stretched for a frame (the user's
                                  * split-screen 1v1 take 2026-11-16) */
            guest_call(GA(0x8012A910u), 0, 0, 0, 0);
        feats_battle(1);
        menu_loop_stop_all(0); /* the menus' loop (sound 27) never into a battle */
        F_8012BE5C_orig(c);
        wide_round(0); /* widescreen: the session's pictures done (its texts too) */
        wide_rows_restore(); /* widescreen: the view-mode rows as the game's again (menus, car select) */
        feats_battle(0);
        if (custom) apply_game_settings(); /* the Gameplay difficulty again */
    }
    runner_result = (int)c->r[2];
    if (mode == 3 && (runner_result == RUNNER_WON || runner_result == RUNNER_LOST)) /* a challenge match played out */
        for (int p = 0; p < (four_humans() > 2 ? four_humans() : humans) && p < 4; p++) feat_set(p, FEAT_CUSTOM_FINISHED); /* 3-4 players too */
    if (runner_result == RUNNER_LOST && (mode == 1 || mode == 2))
        for (int p = 0; p < humans && p < 2; p++) feat_set(p, FEAT_LOST_ALL_LIVES);
    feats_flush();
}

/* Shows a menu as the pause menu (game font, over the last frame); returns
 * the item chosen (X or Start). */
/* The game's GAME OVER (screenShowMessageLines 8012B5FC from the session
 * runner, font 6 at y 80): with the port's GAME OVER menu to follow, its
 * text is left out (an empty string: the end of "GAME OVER" itself), or the
 * last frame under the menu shows it a second time, dimmed. */
#define STR_GAME_OVER GA(0x800CF880u)
void F_8012B5FC_orig(CPU *c);
/* The session's message screens (screenShowMessageLines 8012B5FC: "CONGRATULATIONS! / Prepare for / the next
 * level", the Minion and Dark Tooth texts, the last win, GAME OVER) drawn by the port: the battle's last frame
 * as it was shown (full resolution, widescreen), darkened as the game's screenLostALife does, and the lines in
 * the game's fonts at the window's size, one after another 30 frames apart as the game's. The wait after
 * (padWaitConfirmOrTimeout, ui_PadWait): before a level's menu half a second plus, the menu then over this
 * picture (no "LEVEL COMPLETE"); a story text waits for a button, "PRESS X TO CONTINUE" under it. */
static int prepare_text; /* "Prepare for" or GAME OVER: the level's menu comes next */
static char story_wait_text[48]; /* (online, a machine) WAITING FOR <host>, where the host's PRESS X TO CONTINUE is */
static int msg_on, msg_menu, msg_inner, msg_n;
static Image msg_frame, msg_canvas;
static struct { int font, x, y; char text[64]; } msg_line[3];
static void msg_compose(int lines, int press)
{
    /* every line red-orange, as the game: sessionRun sets fonts 6, 2 and 0 to (115, 25, 8) right after the battle
     * (session_runner.cpp 161-163), so CONGRATULATIONS!, Prepare for, the arena, the story texts and GAME OVER share it */
    static const uint8_t msg_rgb[3] = {115, 25, 8};
    static const uint8_t black[3] = {0, 0, 0};
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (size.w <= 0 || size.h <= 0 || !image_resize(&msg_canvas, size.w, size.h)) return;
    Image *c = &msg_canvas;
    memset(c->px, 0, (size_t)c->w * c->h * 3);
    float sc = c->h / 240.0f;
    if (c->w / 320.0f < sc) sc = c->w / 320.0f;
    float ox = (c->w - 320 * sc) / 2, oy = (c->h - 240 * sc) / 2;
    if (msg_frame.px) {
        int h = c->h, w = (int)((float)msg_frame.w * h / msg_frame.h + 0.5f);
        if (w > c->w) { w = c->w; h = (int)((float)msg_frame.h * w / msg_frame.w + 0.5f); }
        draw_image(c, &msg_frame, 0, 0, (float)msg_frame.w, (float)msg_frame.h, (c->w - w) / 2, (c->h - h) / 2, w, h, 0);
        draw_fill(c, 0, 0, c->w, c->h, black, 128);
    }
    for (int i = 0; i < lines && i < 3; i++) {
        int f = msg_line[i].font >= 0 && msg_line[i].font < 7 && gfont_ready(msg_line[i].font) ? msg_line[i].font : 2;
        if (!gfont_ready(f) || !msg_line[i].text[0]) continue;
        gfont_draw(c, f, msg_line[i].text, ox + (msg_line[i].x - (gfont_width(f, msg_line[i].text) >> 1)) * sc, oy + msg_line[i].y * sc, sc,
                   msg_rgb);
    }
    if (press && gfont_ready(0)) {
        const char *t = press == 2 ? story_wait_text : "PRESS X TO CONTINUE";
        gfont_draw(c, 0, t, ox + (159 - (gfont_width(0, t) >> 1)) * sc, oy + 212 * sc, sc, msg_rgb);
    }
    Psyz_VideoSetDisplayRGB24Fill(1);
    Psyz_VideoSetDisplayRGB24(c->px, c->w, c->h);
}
static void guest_text_copy(char *out, size_t n, uint32_t a)
{
    size_t i = 0;
    for (; a && i + 1 < n; i++) { out[i] = (char)mem_r8(&M.cpu, a + (uint32_t)i); if (!out[i]) break; }
    out[i < n ? i : n - 1] = 0;
}
void ui_MessageLines(CPU *c)
{
    if (c->r[6] == STR_GAME_OVER && (M.live_input || script) && text_ready()) c->r[6] = STR_GAME_OVER + 9;
    uint32_t sp = c->r[29];
    char second[8] = {0}; /* the second line (screenShowMessageLines(s, font1, line1, x, y, font2, line2, ...): the stack's +24) */
    uint32_t l2 = mem_r32(c, sp + 24);
    for (int i = 0; i < 7 && l2; i++) second[i] = (char)toupper(mem_r8(c, l2 + (uint32_t)i));
    prepare_text = !strncmp(second, "PREPARE", 7) || c->r[6] == STR_GAME_OVER + 9;
    if (!((M.live_input || script) && text_ready() && gfont_ready(2))) { F_8012B5FC_orig(c); return; }
    int w = 0, h = 0; /* the battle's last frame, as shown */
    unsigned char *shot = ui_capture_clean(&w, &h);
    image_free(&msg_frame);
    if (shot) { msg_frame.w = w; msg_frame.h = h; msg_frame.px = shot; }
    const uint32_t str[3] = {c->r[6], mem_r32(c, sp + 24), mem_r32(c, sp + 40)};
    const int font[3] = {(int)c->r[5], (int)mem_r32(c, sp + 20), (int)mem_r32(c, sp + 36)};
    const int xs[3] = {(int)c->r[7], (int)mem_r32(c, sp + 28), (int)mem_r32(c, sp + 44)};
    const int ys[3] = {(int)mem_r32(c, sp + 16), (int)mem_r32(c, sp + 32), (int)mem_r32(c, sp + 48)};
    int n = 0;
    for (int i = 0; i < 3; i++) {
        if (i && !str[i]) break;
        msg_line[i].font = font[i]; msg_line[i].x = xs[i]; msg_line[i].y = ys[i];
        guest_text_copy(msg_line[i].text, sizeof msg_line[i].text, str[i]);
        if (i) { msg_inner = 1; guest_call(GA(0x801290CCu), 30, 30, 0, 0); msg_inner = 0; } /* as the game's: 30 frames a line */
        n = i + 1;
        msg_compose(n, 0);
        if (str[i] && msg_line[i].text[0] && c->r[6] != STR_GAME_OVER + 9) { /* the game's sound as the line appears */
            guest_call(GA(0x800D3334u), 28, 0, 0, 99);
            guest_call(GA(0x800D34C0u), 0, 0, 0, 0);
            guest_call(GA(0x800D34E8u), 0, 0, 0, 0);
        }
    }
    msg_on = 1;
    msg_n = n;
    msg_menu = prepare_text;
}
/* A story screen's wait (the boss texts, Dark Tooth's, the co-op win's duel screen): STORY_MIN frames (the user's: one
 * time for all, the game's shortest; its own were 120 and 300), then PRESS X TO CONTINUE and a press. Online player 1
 * goes on; the others show WAITING FOR <host> there and go on with them (the host's count in its settings). draw(mode):
 * 0 the screen, 1 with the prompt, 2 with the waiting */
enum { STORY_MIN = 120 };
static void story_wait(void (*draw)(int mode))
{
    int online = net_tour_on && netplay_in_match();
    story_idx++;
    draw(0);
    for (int f = 0; f < STORY_MIN; f++) { rt_vblank(); if (online) netplay_poll(); }
    int shown = -1, key;
    uint16_t prev = 0xFFFF;
    for (;;) {
        Lobby *l = online ? netplay_lobby() : NULL;
        int host = !online || !l || lobby_is_host(l);
        if (!host) {
            const LobbyView *v = lobby_view(l);
            if (v->settings_len == (int)sizeof(NetSettings) && ((const NetSettings *)v->settings)->story_n >= story_idx) {
                fprintf(stderr, "story: screen %d: player 1 went on\n", story_idx);
                break;
            }
        }
        if (shown != (host ? 1 : 2)) {
            shown = host ? 1 : 2;
            if (!host) {
                const char *h = match_human_name(0);
                snprintf(story_wait_text, sizeof story_wait_text, "WAITING FOR %s", h && h[0] ? h : "PLAYER 1");
                upper(story_wait_text);
            }
            draw(shown);
        }
        rt_vblank();
        if (online) netplay_poll();
        uint16_t b = menu_input(&key), pr = (uint16_t)(b & ~prev);
        prev = b;
        if (host && (pr & (B_CROSS | B_START | B_CIRCLE))) {
            fprintf(stderr, "story: screen %d: on (pressed)\n", story_idx);
            if (online && l) {
                net_story_n = story_idx;
                net_send_settings();
                for (int f = 0; f < 20; f++) { rt_vblank(); netplay_poll(); } /* (the press out to the others) */
            }
            break;
        }
    }
}
static void story_msg_draw(int mode) { msg_compose(msg_n, mode); }
/* the co-op win's duel screen (its picture, DUEL_TEXT), drawn by the port as the story texts are: one 4:3 picture in
 * the middle (the game's own showed the last message's widescreen picture over it, then itself for a moment with
 * LOADING: a flash, 4:3 and widescreen), the prompt under its text */
static Image duel_canvas;
static void duel_draw(int mode)
{
    static const uint8_t prompt_rgb[3] = {230, 110, 20};
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (size.w <= 0 || size.h <= 0 || !image_resize(&duel_canvas, size.w, size.h)) return;
    Image *c = &duel_canvas;
    memset(c->px, 0, (size_t)c->w * c->h * 3);
    float sc = c->h / 240.0f;
    if (c->w / 320.0f < sc) sc = c->w / 320.0f;
    float ox = (c->w - 320 * sc) / 2, oy = (c->h - 240 * sc) / 2;
    if (bg_duel.px) draw_image(c, &bg_duel, 0, 0, (float)bg_duel.w, (float)bg_duel.h, (int)ox, (int)oy, (int)(320 * sc), (int)(240 * sc), 0);
    if (mode && gfont_ready(0)) {
        const char *t = mode == 2 ? story_wait_text : "PRESS X TO CONTINUE";
        gfont_draw(c, 0, t, ox + (159 - (gfont_width(0, t) >> 1)) * sc, oy + 212 * sc, sc, prompt_rgb);
    }
    Psyz_VideoSetDisplayRGB24Fill(1);
    Psyz_VideoSetDisplayRGB24(c->px, c->w, c->h);
}
void F_801290CC_orig(CPU *c);
void ui_PadWait(CPU *c) /* padWaitConfirmOrTimeout(min, max) */
{
    uint32_t ra = c->r[31];
    if (!msg_inner && !msg_on && coop_duel_next() && bg_duel.px && ra >= GA(0x80136BB0u) && ra < GA(0x80136D98u)) {
        story_wait(duel_draw); /* the co-op win's screen: the duel's, as a story text */
        c->r[2] = 1;
        display_to_game(&duel_canvas); /* (until the duel's arena draws) */
        return;
    }
    if (msg_inner || !msg_on) { F_801290CC_orig(c); return; }
    if (getenv("TM2PC_MSG_SHOT") && msg_canvas.px) image_save_bmp(&msg_canvas, getenv("TM2PC_MSG_SHOT")); /* tests: the picture */
    if (msg_menu) { c->r[4] = 45; c->r[5] = 45; } /* the level's menu soon after */
    if (!msg_menu && (M.live_input || script)) { /* a story text: STORY_MIN, then the prompt and one press (online: player 1's) */
        story_wait(story_msg_draw);
        c->r[2] = 1;
    } else
        F_801290CC_orig(c);
    msg_on = 0;
    display_to_game(&msg_canvas); /* the picture stays until the game's next one (or the menu's) */
    if (msg_menu) { /* the level's menu over it */
        image_free(&pause_frame); pause_frame_gen++;
        if (image_resize(&pause_frame, msg_canvas.w, msg_canvas.h)) memcpy(pause_frame.px, msg_canvas.px, (size_t)msg_canvas.w * msg_canvas.h * 3);
        menu_keep_frame = 1;
    }
}

static int (*tmenu_poll)(void); /* (set around a call) each frame: >= 0 closes the menu with 1000 + it */
static int tmenu_inert = -1;     /* (set around a call) the item X does nothing on (a joiner's WAITING FOR ...) */
static int tmenu_start;          /* (set around a call) the item highlighted first (YES / NO: NO, the user's) */
static int tournament_menu(const char *title, const char *const *items, int count)
{
    if (!menu_keep_frame || !pause_frame.px) {
        int w = 0, h = 0;
        unsigned char *shot = ui_capture_clean(&w, &h);
        image_free(&pause_frame); pause_frame_gen++;
        if (shot) { pause_frame.w = w; pause_frame.h = h; pause_frame.px = shot; pause_frame_gen++; }
    }
    menu_keep_frame = 0;
    menu_items = items;
    menu_count = count;
    menu_title = title;
    int sel = tmenu_start > 0 && tmenu_start < count ? tmenu_start : 0, dirty = 1, held_for[2] = {0}, chosen = -1, menu_key;
    uint16_t prev = 0xFFFF;
    Image canvas = {0, 0, NULL};
    display_hold = 0; /* this page takes the screen */
    Psyz_VideoSetDisplayRGB24Fill(1);
    uint64_t next = SDL_GetTicksNS();
    while (chosen < 0) {
        uint16_t b = menu_input(&menu_key), pressed = (uint16_t)(b & ~prev);
        static const uint16_t dirs[2] = {B_UP, B_DOWN};
        for (int d = 0; d < 2; d++) {
            if (!(b & dirs[d])) { held_for[d] = 0; continue; }
            if (++held_for[d] > 18 && (held_for[d] - 18) % 6 == 0) pressed |= dirs[d];
        }
        prev = b;
        if (pressed & (B_UP | B_DOWN)) {
            sel = (sel + ((pressed & B_UP) ? count - 1 : 1)) % count;
            menu_sound(0);
            dirty = 1;
        } else if ((pressed & (B_CROSS | B_START)) && sel != tmenu_inert) {
            chosen = sel;
        }
        if (chosen < 0 && tmenu_poll) {
            int r = tmenu_poll();
            if (r >= 0) chosen = 1000 + r;
        }
        if (menu_note && SDL_GetTicksNS() >= menu_note_until) { menu_note = NULL; dirty = 1; } /* the note goes */
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) &&
            image_resize(&canvas, size.w, size.h)) {
            compose_pause(&canvas, sel, NULL, NULL);
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
            dirty = 0;
            static char shot_first[48]; /* tests: TM2PC_MENU_SHOT=dir, each menu's first picture (named by its first item) */
            if (getenv("TM2PC_MENU_SHOT") && count > 0 && strncmp(shot_first, items[0], sizeof shot_first - 1)) {
                char path[512], tag[24];
                int t = 0;
                for (const char *q = items[0]; *q && t < 23; q++) if ((*q >= 'A' && *q <= 'Z') || (*q >= '0' && *q <= '9')) tag[t++] = *q;
                tag[t] = 0;
                snprintf(shot_first, sizeof shot_first, "%s", items[0]);
                snprintf(path, sizeof path, "%s/menu_%s.bmp", getenv("TM2PC_MENU_SHOT"), tag);
                image_save_bmp(&canvas, path);
            }
        }
        ui_audio_frame();
        ui_vsync();
        next += 1000000000ull / 60; /* 60 a second: the held-button repeat counts frames */
        uint64_t now = SDL_GetTicksNS();
        if (next > now) SDL_DelayNS(next - now);
        else next = now;
    }
    if (chosen < 1000) menu_sound(1);
    while (chosen < 1000 && input_menu_buttons(&menu_key) && !script) /* on with the buttons released */
        ui_vsync();
    display_to_game(&canvas);
    image_free(&canvas);
    menu_items = pause_items;
    menu_count = 4;
    menu_title = "BATTLE PAUSED";
    menu_note = NULL;
    return chosen;
}

/* The settings for playing a level again from its start (decomp
 * TOURNAMENT_FLOW.md 3: "What a restart needs"). */
static void tournament_restart(int level, int mode)
{
    const uint32_t S = SETTINGS_BLOCK;
    guest_call(GA(0x80137900u), S, 0, 0, 0);  /* +6, +7: the picks */
    guest_call(GA(0x801378E8u), S, 0, 0, 0);
    guest_call(GA(0x80137864u), S, 0, 0, 0);  /* the opponents' slots (and the lives) cleared */
    guest_call(GA(0x801377FCu), S, 0, 0, 0);  /* +29: from the level's start */
    guest_call(GA(0x80137814u), S, (uint32_t)level, 0, 0);
    uint32_t value = guest_call(GA(0x8012AFE8u), S, guest_call(GA(0x80137808u), S, 0, 0, 0), 0, 0);
    guest_call(GA(0x80137918u), S, value - guest_call(GA(0x80137924u), S, 0, 0, 0), 0, 0);
    if (mode == 2) { /* co-op: the shared 6 */
        guest_call(GA(0x80137820u), S, 0, 6, 0);
        guest_call(GA(0x80137820u), S, 1, 6, 0);
    } else {
        guest_call(GA(0x80137820u), S, 0, 3, 0);
    }
}

static void tournament_after(CPU *c, uint32_t next, int mode, int level);
void F_80136BB0_orig(CPU *c);
static int net_tour_over(CPU *c) /* an online tournament over (the title next: won, lost, the duel's ending): the lobby */
{
    if (!net_tour_on || !netplay_in_match() || (c->r[2] != TITLE_SCREEN && c->r[2] != TITLE_SCREEN_FN)) return 0;
    netplay_match_end();
    netplay_each_battle(0);
    net_tour_on = 0;
    humans_set_map(0, NULL);
    void stats_online(int on);
    stats_online(0);
    profile_unlocks_mine(); /* (this PC's own unlocks again: profile_hooks.c) */
    battle_match_override(NULL);
    battle_type_override(NULL);
    apply_game_settings(); /* (this PC's difficulty again) */
    net_return = 1;
    c->r[2] = TITLE_SCREEN_FN;
    return 1;
}
static void net_tour_leave(void);
static int net_quit_leaving; /* (below: the online menu's QUIT, the battle quit) */
void ui_ScrollText(CPU *c)
{
    const uint32_t S = SETTINGS_BLOCK;
    int mode = mem_r8(&M.cpu, S), level = (int8_t)mem_r8(&M.cpu, S + 24);
    runner_result = -1;
    if (getenv("TM2PC_TEST_DUEL") && mode == 2) { /* tests: the co-op duel at once */
        start_once();
        load_art();
        const char *saved = script;
        if (getenv("TM2PC_TMENU_SCRIPT")) { script = getenv("TM2PC_TMENU_SCRIPT"); script_tick = 600 - 24; }
        c->r[2] = coop_duel();
        script = saved;
        net_tour_over(c);
        return;
    }
    F_80136BB0_orig(c);
    uint32_t next = c->r[2];
    start_once();
    load_art();
    /* tests: TM2PC_TMENU_SCRIPT drives these menus (and the pages they open) */
    const char *saved_script = script, *menu_script = getenv("TM2PC_TMENU_SCRIPT");
    if (menu_script) { script = menu_script; script_tick = 600 - 24; }
    if ((M.live_input || script) && text_ready() && (mode == 1 || mode == 2))
        tournament_after(c, next, mode, level);
    if (mode == 2 && level == 8 && coop_duel_next() && c->r[2] == TITLE_SCREEN)
        c->r[2] = coop_duel();
    if (net_quit_leaving && netplay_in_match()) { /* QUIT in the online menu: out of the match and the server (the others go on) */
        net_quit_leaving = 0;
        if (trun.versus) versus_end();
        else if (trun.on) tour_end();
        net_tour_leave();
        battle_live = 0;
        fprintf(stderr, "network: left the match (the menu's Quit)\n");
        c->r[2] = TITLE_SCREEN_FN;
    } else if (tour_left_server) { /* (a custom co-op tournament: this machine left the server at a stage's choice) */
        tour_left_server = 0;
        if (trun.on) tour_end();
        battle_live = 0;
        c->r[2] = TITLE_SCREEN_FN;
    } else if (net_tour_over(c)) {
    } else if (battle_live && mode == 3 && trun.on && trun.next != TOUR_NEXT_NONE) {
        c->r[2] = tour_next_stage(); /* a custom tournament's next stage (or this one again): its opponents, then on */
    } else if (battle_live && netplay_in_match()) { /* a server's match: its lobby again (a playlist: its vote) */
        fprintf(stderr, "network: the match's end (mode %d, tournament %d, next %d)\n", mode, trun.on, (int)trun.next);
        if (trun.versus) versus_end();
        else if (trun.on) tour_end(); /* (a custom co-op tournament over) */
        netplay_match_end();
        humans_set_map(0, NULL); /* (every human local again, offline) */
        void stats_online(int on);
        stats_online(0);
        profile_unlocks_mine(); /* (this PC's own unlocks again: profile_hooks.c) */
        battle_match_override(NULL);
        battle_type_override(NULL);
        battle_live = 0;
        net_return = 1;
        c->r[2] = TITLE_SCREEN_FN;
    } else if (battle_live && (mode == 3 || mode == 4) && (M.live_input || script) && text_ready()) {
        if (trun.on) tour_end();
        battle_back = 2; /* the match is over: its page again (and the menus' music) */
        c->r[2] = mem_r8(&M.cpu, S + 4) >= 2 ? GA(0x8012F5F8u) : GA(0x8012E908u);
    }
    script = saved_script;
}

/* the tournament's menus behind: the port's own sharp pictures, not a capture of the game's screen (it held the game's
 * low resolution texts: the user's "old low resolution" screen) */
static void menu_frame_from(const Image *im)
{
    if (!im->px || !image_resize(&pause_frame, im->w, im->h)) return;
    memcpy(pause_frame.px, im->px, (size_t)im->w * im->h * 3);
    menu_keep_frame = 1;
}
static void net_tour_leave(void) /* this machine leaves an online tournament: the others carry on */
{
    netplay_match_end();
    netplay_leave();
    humans_set_map(0, NULL);
    void stats_online(int on);
    stats_online(0);
    profile_unlocks_mine(); /* (this PC's own unlocks again: profile_hooks.c) */
    battle_match_override(NULL);
    battle_type_override(NULL);
    net_tour_on = 0;
    netplay_each_battle(0);
    net_in_server = 0;
    net_server.host = 0;
}
void ui_net_wait_notice(const char *title, const char *line); /* (below) */
/* (host) a choice that asks again: EXIT / QUIT, "ARE YOU SURE?" (NO first) */
static int tour_sure(void)
{
    static const char *const yes_no[2] = {"YES", "NO"}; /* (YES on top, NO highlighted: the user's) */
    menu_keep_frame = 1; /* (the same picture behind) */
    tmenu_start = 1;
    int yes = tournament_menu("ARE YOU SURE?", yes_no, 2) == 0;
    tmenu_start = 0;
    return yes;
}
/* An online tournament's choice after level `level` (kind 0 won, 1 lost): the host's menu, a machine the host's
 * (TOUR_DEC_*; -1 this machine left the server) */
static int tour_wait_level, tour_wait_kind, tour_wait_got;
static int tour_wait_poll(void) /* (a machine waiting, each frame) the host's choice for its level and kind: >= 0 */
{
    Lobby *l = netplay_lobby();
    if (!l) { tour_wait_got = tour_wait_kind ? TOUR_DEC_QUIT : TOUR_DEC_EXIT; return 0; }
    if (lobby_is_host(l)) { tour_wait_got = -2; return 0; } /* (the host left: this machine chooses now) */
    const LobbyView *v = lobby_view(l);
    if (v->settings_len != (int)sizeof(NetSettings)) return -1;
    const NetSettings *ns = (const NetSettings *)v->settings;
    if (ns->tour_dec_n > net_tour_dec.n && ns->tour_dec_level == tour_wait_level && ns->tour_dec_kind == tour_wait_kind) {
        net_tour_dec.n = ns->tour_dec_n;
        tour_wait_got = ns->tour_dec;
        return 0;
    }
    return -1;
}
static void net_tour_save(void) /* (host) SAVE between levels: the next level, every player's car, profile online and name */
{
    const uint32_t S = SETTINGS_BLOCK;
    Lobby *l = netplay_lobby();
    if (!l) return;
    const LobbyView *v = lobby_view(l);
    saving.active = 1;
    saving.saved = 0;
    saving.online = 1;
    saving.level = mem_r8(&M.cpu, S + 24);
    saving.players = play_players < 1 ? 1 : play_players > PROFILE_SAVE_PLAYERS ? PROFILE_SAVE_PLAYERS : play_players;
    for (int p = 0; p < saving.players; p++) saving.cars[p] = p >= 2 ? four_car_of(p) : (int8_t)mem_r8(&M.cpu, S + 8 + (uint32_t)p);
    saving.difficulty = mem_r8(&M.cpu, S + 36);
    memset(saving.who, 0, sizeof saving.who);
    memset(saving.ids, 0, sizeof saving.ids);
    for (int n = 0; n < SES_MAX_NODES; n++) /* (each human's profile online, by the start's order) */
        for (int i = 0; v->start.first[n] != 0xFF && i < v->m[n].count; i++) {
            int h = v->start.first[n] + i;
            if (h < 0 || h >= saving.players) continue;
            snprintf(saving.who[h], sizeof saving.who[h], "%s", v->m[n].p[i].name);
            memcpy(saving.ids[h], v->m[n].p[i].online_id, 8);
        }
    from_title = 0;
    if (getenv("TM2PC_TEST_TOUR_SAVE")) { /* tests: into slot N, no page */
        int slot = atoi(getenv("TM2PC_TEST_TOUR_SAVE")) - 1;
        profile_set_tournament_save_who(slot, saving.level, saving.players, saving.cars, saving.difficulty, 1,
                                        (const char (*)[32])saving.who, (const unsigned char (*)[8])saving.ids);
        saving.saved = slot + 1;
    } else run(PAGE_LOAD);
    saving.active = 0;
    if (saving.saved && settings_game.menu_sounds) guest_call(GA(0x800D3334u), 0x1D, 0, 0, 99); /* (the select boom) */
    if (saving.saved) {
        menu_note = "SAVE COMPLETE";
        menu_note_until = SDL_GetTicksNS() + 3000000000ull;
        fprintf(stderr, "tournament: saved online in slot %d (level %d)\n", saving.saved, saving.level);
    }
}
static int net_tour_choose(int level, int kind)
{
    static const char *const won[2] = {"CONTINUE", "EXIT"}, *const lost[2] = {"RESTART", "QUIT"};
    for (;;) {
        Lobby *l = netplay_lobby();
        if (!l) return kind ? TOUR_DEC_QUIT : TOUR_DEC_EXIT;
        if (lobby_is_host(l)) {
            int choice;
            for (;;) {
                static const char *const won_save[3] = {"CONTINUE", "SAVE", "EXIT"};
                int can_save = !kind && !net_custom_coop() && profile_signed_in() && play_players <= PROFILE_SAVE_PLAYERS; /* (in the host's profile) */
                menu_items_y = kind ? 140 : 172;
                menu_note_y = 100;
                int pick = tournament_menu(kind ? "GAME OVER" : "", kind ? lost : can_save ? won_save : won, can_save ? 3 : 2);
                menu_items_y = 140;
                menu_note_y = 205;
                static int test_saved; /* tests: TM2PC_TEST_TOUR_SAVE, each level's SAVE taken by itself (once a level) */
                if (can_save && test_saved != level && getenv("TM2PC_TEST_TOUR_SAVE")) test_saved = level, pick = 1;
                if (can_save && pick == 1) { net_tour_save(); menu_keep_frame = 1; continue; }
                if (can_save && pick == 2) pick = 1;
                if (pick == 0) { choice = kind ? TOUR_DEC_RESTART : TOUR_DEC_CONTINUE; break; }
                if (tour_sure()) { choice = kind ? TOUR_DEC_QUIT : TOUR_DEC_EXIT; break; }
                menu_keep_frame = 1;
            }
            net_tour_dec.n++, net_tour_dec.level = level, net_tour_dec.kind = kind, net_tour_dec.choice = choice;
            net_send_settings();
            for (int i = 0; i < 30; i++) ui_vsync(); /* (half a second: the choice out to the others) */
            return choice;
        }
        /* a machine: a menu as the host's, where the host's is: WAITING FOR <host> (X does nothing) and QUIT (leaves the
         * server, asked again); the host's choice for this level closes it (the user's, 2026-11-05) */
        tour_wait_level = level, tour_wait_kind = kind, tour_wait_got = -1;
        const char *host = match_human_name(0);
        static char waiting[48];
        snprintf(waiting, sizeof waiting, "WAITING FOR %s", host && host[0] ? host : "PLAYER 1");
        upper(waiting);
        const char *items[2] = {waiting, "QUIT"};
        tmenu_poll = tour_wait_poll;
        tmenu_inert = 0;
        menu_items_y = kind ? 140 : 172;
        int pick = tournament_menu(kind ? "GAME OVER" : "", items, 2);
        menu_items_y = 140;
        tmenu_poll = NULL;
        tmenu_inert = -1;
        if (pick >= 1000 && tour_wait_got == -2) { menu_keep_frame = 1; continue; } /* (the host left: this one chooses) */
        if (pick >= 1000) return tour_wait_got; /* the host's choice */
        if (pick == 1) {
            static const char *const yes_no[2] = {"YES", "NO"}; /* (YES on top, NO highlighted) */
            menu_keep_frame = 1;
            tmenu_start = 1;
            int yes = tournament_menu("LEAVE THE SERVER?", yes_no, 2) == 0;
            tmenu_start = 0;
            if (yes) {
                fprintf(stderr, "tournament: left the server after level %d\n", level);
                net_tour_leave();
                return -1;
            }
            menu_keep_frame = 1; /* (no: the waiting again, the same picture) */
        }
    }
}
static void tournament_after(CPU *c, uint32_t next, int mode, int level)
{
    const uint32_t S = SETTINGS_BLOCK;
    if (next == NEXT_LEVEL_SCREEN && runner_result == RUNNER_WON) menu_frame_from(&msg_canvas); /* Congratulations, sharp */
    if (runner_result == RUNNER_LOST && next == TITLE_SCREEN) menu_frame_from(&msg_frame);     /* the battle, before GAME OVER */
    int online = net_tour_on && netplay_in_match();
    int won_now = next == NEXT_LEVEL_SCREEN && runner_result == RUNNER_WON, lost_now = runner_result == RUNNER_LOST && next == TITLE_SCREEN;
    if (online && (won_now || lost_now)) { /* online: no saves; player 1 chooses, the others follow */
        int choice = net_tour_choose(level, won_now ? 0 : 1);
        if (choice == TOUR_DEC_CONTINUE) {
            fprintf(stderr, "tournament: continue to level %d\n", mem_r8(&M.cpu, S + 24));
        } else if (choice == TOUR_DEC_RESTART) {
            tournament_restart(level, mode);
            c->r[2] = NEXT_LEVEL_SCREEN;
            fprintf(stderr, "tournament: restart level %d (online)\n", level);
        } else if (choice < 0) { /* (this machine left the server) */
            c->r[2] = TITLE_SCREEN;
        } else { /* EXIT, QUIT: the match over, everyone to the server's lobby */
            c->r[2] = TITLE_SCREEN;
            fprintf(stderr, "tournament: %s after level %d (online): the lobby\n", choice == TOUR_DEC_EXIT ? "exit" : "quit", level);
        }
        return;
    }
    if (next == NEXT_LEVEL_SCREEN && runner_result == RUNNER_WON) {
        int can_save = profile_signed_in(); /* in player 1's profile, co-op too */
        static const char *const without[2] = {"CONTINUE", "EXIT"};
        static const char *const items[3] = {"CONTINUE", "SAVE", "EXIT"};
        for (;;) {
            menu_items_y = 172; /* (under "Prepare for / the next level", 120 and 140, still on the picture) */
            menu_note_y = 100; /* SAVE COMPLETE: between CONGRATULATIONS! (80) and Prepare for (120) */
            int choice = tournament_menu("", can_save ? items : without, can_save ? 3 : 2); /* (the texts behind say it) */
            menu_items_y = 140;
            menu_note_y = 205;
            if (!can_save && choice == 1) choice = 2;
            if (choice == 0) {
                fprintf(stderr, "tournament: continue to level %d\n", mem_r8(&M.cpu, S + 24));
                return;
            }
            if (choice == 2) { /* as the pause menu's Quit: fresh weapons next time, the title */
                mem_w8(&M.cpu, S + 24, 1);
                guest_call(GA(0x80119834u), 1, 0, 0, 0);
                guest_call(GA(0x80119834u), 1, 1, 0, 0);
                c->r[2] = TITLE_SCREEN;
                two_return = mode == 2 ? 2 : 1;
                fprintf(stderr, "tournament: quit after level %d\n", level);
                return;
            }
            /* SAVE: the next level (from its start), player 1's car, the difficulty */
            saving.active = 1;
            saving.saved = 0;
            saving.level = mem_r8(&M.cpu, S + 24);
            saving.players = four_humans() ? four_humans() : mem_r8(&M.cpu, S + 4);
            if (saving.players < 1 || saving.players > PROFILE_SAVE_PLAYERS) saving.players = 1;
            for (int p = 0; p < saving.players; p++) saving.cars[p] = p >= 2 ? four_car_of(p) : (int8_t)mem_r8(&M.cpu, S + 8 + (uint32_t)p);
            saving.difficulty = mem_r8(&M.cpu, S + 36);
            saving.online = 0;
            memset(saving.who, 0, sizeof saving.who);
            memset(saving.ids, 0, sizeof saving.ids);
            for (int p = 0; p < saving.players; p++) /* (who played it: only they load it) */
                snprintf(saving.who[p], sizeof saving.who[p], "%s", local_seat_name(p));
            from_title = 0;
            run(PAGE_LOAD);
            saving.active = 0;
            if (saving.saved && settings_game.menu_sounds) guest_call(GA(0x800D3334u), 0x1D, 0, 0, 99); /* (the select boom) */
            menu_keep_frame = 1; /* the level's last frame behind the menu again, not the save page */
            if (saving.saved) { /* a note for a few seconds; the menu as before */
                menu_note = "SAVE COMPLETE";
                menu_note_until = SDL_GetTicksNS() + 3000000000ull;
                fprintf(stderr, "tournament: saved in slot %d\n", saving.saved);
            }
        }
    }
    if (runner_result == RUNNER_LOST && next == TITLE_SCREEN) {
        static const char *const items[2] = {"RESTART", "QUIT"};
        if (tournament_menu("GAME OVER", items, 2) == 0) {
            tournament_restart(level, mode);
            c->r[2] = NEXT_LEVEL_SCREEN;
            fprintf(stderr, "tournament: restart level %d\n", level);
        } else {
            two_return = mode == 2 ? 2 : 1;
            fprintf(stderr, "tournament: quit after game over (level %d)\n", level);
        }
    }
}

int ui_shot(int page, int sel, int w, int h, const char *bmp_path)
{
    Image canvas = {0, 0, NULL};
    float scroll = 0;
    load_art();
    if (getenv("TM2PC_HUD_PREVIEW")) hud_preview_players = atoi(getenv("TM2PC_HUD_PREVIEW")); /* tests: the HUD test screen's players */
    if (page == PAGE_MOD_ENDINGS && getenv("TM2PC_ENDING_PAGE")) { /* tests: the sel-th character's ending page */
        int mod_ending_compose(int number, Image *canvas, int w, int h);
        int ok = mod_ending_compose(mod_character(sel), &canvas, w, h) && image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (getenv("TM2PC_UI_PLAYERS")) play_players = atoi(getenv("TM2PC_UI_PLAYERS")); /* tests: the pages as for N players */
    if (getenv("TM2PC_UI_NET_GAME")) net_server.game = atoi(getenv("TM2PC_UI_NET_GAME")) % NET_GAMES; /* tests: Host Server's game */
    if (getenv("TM2PC_UI_HOSTING")) net_hosting = 1;  /* tests: the pages as a server's (Versus Tournament's title) */
    if (getenv("TM2PC_UI_PLAYLIST")) net_pl.on = 1;   /* tests: Host Server with the playlist chosen */
    if (getenv("TM2PC_NET_TOUR_CUSTOM")) net_tour_custom = 1; /* (tests: a custom co-op tournament's page) */
    if (getenv("TM2PC_TEST_ARENA_VALUE")) battle_match()->arena = atoi(getenv("TM2PC_TEST_ARENA_VALUE")); /* (tests: the arena row) */
    if (page == PAGE_NET_VOTE) { /* tests: a vote's sample cards (three built-in game types on three arenas) */
        static const int arenas[3] = {1, 3, 6};
        net_vote_n = 3;
        for (int i = 0; i < 3; i++) {
            net_vote_card[i].match = *battle_match();
            net_vote_card[i].match.arena = arenas[i];
            net_vote_card[i].match.teams = i == 1 ? 2 : 0;
            net_vote_card[i].match.lives = i == 2 ? 3 : 1;
            net_vote_card[i].type = *battle_builtin(i % battle_builtin_count());
        }
        net_vote_local = getenv("TM2PC_VOTE_LOCAL") ? atoi(getenv("TM2PC_VOTE_LOCAL")) : 1;
        for (int q = 0; q < 4; q++) { net_vote_mine[q] = -1; net_vote_cursor[q] = q % 3; }
        if (getenv("TM2PC_VOTE_CURSORS")) /* tests: each player's card ("0,0,1,0") */
            for (int q = 0, k = 0; q < 4 && getenv("TM2PC_VOTE_CURSORS")[k]; q++, k += 2) net_vote_cursor[q] = getenv("TM2PC_VOTE_CURSORS")[k] - '0';
        net_vote_mine[0] = getenv("TM2PC_VOTE_MINE") ? atoi(getenv("TM2PC_VOTE_MINE")) : -1;
        net_vote_winner = getenv("TM2PC_VOTE_WINNER") ? atoi(getenv("TM2PC_VOTE_WINNER")) : -1;
        net_vote_left = 11;
        if (getenv("TM2PC_VOTE_CARS")) { /* tests: the cars' panel too (players on their car: TM2PC_VOTE_ROW mask; selected:
                                          * TM2PC_VOTE_SELECTED mask) */
            int rowm = getenv("TM2PC_VOTE_ROW") ? atoi(getenv("TM2PC_VOTE_ROW")) : 0;
            int selm = getenv("TM2PC_VOTE_SELECTED") ? atoi(getenv("TM2PC_VOTE_SELECTED")) : 0;
            static const int cars[4] = {7, 3, 6, 11};
            net_vote_cars = 1;
            for (int q = 0; q < 4; q++) {
                net_car[q] = cars[q];
                net_vote_row[q] = (rowm >> q) & 1;
                net_vote_lock[q] = (selm >> q) & 1;
            }
        }
    }
    if (getenv("TM2PC_TEST_SERVERS") && (page == PAGE_NET_BROWSER || page == PAGE_NET_SERVER)) { /* tests: samples */
        net_refresh();
        if (page == PAGE_NET_SERVER) {
            net_action(ACT_NET_JOIN, getenv("TM2PC_LOBBY_JOIN") ? atoi(getenv("TM2PC_LOBBY_JOIN")) : 0); /* (a sample's index) */
            net_chat_add("CBTEST", "Ready when you are");
            if (getenv("TM2PC_LOBBY_HOST")) net_server.host = 1; /* tests: the host's lobby */
            if (getenv("TM2PC_LOBBY_FIXED")) net_server.fixed_cpus = atoi(getenv("TM2PC_LOBBY_FIXED"));
            if (getenv("TM2PC_LOBBY_TEAMS")) battle_match()->teams = atoi(getenv("TM2PC_LOBBY_TEAMS"));
            if (getenv("TM2PC_LOBBY_MAX")) net_server.max_players = atoi(getenv("TM2PC_LOBBY_MAX"));
            if (getenv("TM2PC_LOBBY_BOTS")) net_server.bots = atoi(getenv("TM2PC_LOBBY_BOTS"));
            if (getenv("TM2PC_LOBBY_READY")) net_ready[0] = 1;
            if (getenv("TM2PC_LOBBY_TYPING")) { /* the chat's keyboard open */
                net_action(ACT_NET_SAY, 0);
                snprintf(naming.text, sizeof naming.text, "%s", getenv("TM2PC_LOBBY_TYPING"));
            }
        }
    }
    if (page == 98 && text_ready() && image_resize(&canvas, w, h)) { /* the title screen */
        compose_title(&canvas, sel >= 0 && sel < 3 ? sel : 0, 5);
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page == 99 && text_ready() && image_resize(&canvas, w, h)) {
        /* font sample: the menu lettering at several weights and widths,
         * 36-pixel capitals (the game's at 1280x960) */
        static const float styles[][3] = {{0, 1, 0}, {0.015f, 1.1f, 0.03f}, {0.02f, 1.12f, 0.045f},
                                          {0.025f, 1.15f, 0.04f}, {0.02f, 1.2f, 0.02f}};
        int top, ch;
        text_caps(100, &top, &ch);
        int size = 36 * 100 / ch;
        memset(canvas.px, 0, (size_t)w * h * 3);
        for (int i = 0; i < 5; i++) {
            text_set_style(styles[i][0], styles[i][1], styles[i][2]);
            text_draw(&canvas, "TOURNAMENT", 20, 20 + i * 70, size, WHITE);
            text_draw(&canvas, "CHALLENGE MATCH", 560, 20 + i * 70, size, WHITE);
        }
        text_set_style(0, 1, 0);
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page == 91 && text_ready() && image_resize(&canvas, w, h)) { /* 2-player car select */
        memset(cs2, 0, sizeof cs2);
        cs2[0].car = 9;
        cs2[0].locked = 1;
        cs2[1].car = sel >= 0 ? sel : 11;
        compose_cs2(&canvas);
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page == 92 && text_ready() && image_resize(&canvas, w, h)) { /* car select's portraits, sel: the car */
        memset(canvas.px, 0, (size_t)w * h * 3);
        Image ov = {0, 0, NULL}, bg = {0, 0, NULL};
        int rects[3][4];
        image_resize(&ov, w, h);
        carsel_compose(&ov, sel >= 0 ? sel : 7, getenv("TM2PC_SHOT_ITEM") ? atoi(getenv("TM2PC_SHOT_ITEM")) : 9001, rects);
        if (getenv("TM2PC_SHOT_BG")) bg = image_load_bmp(getenv("TM2PC_SHOT_BG"));
        if (bg.px) {
            int gw = h * 4 / 3;
            draw_image(&canvas, &bg, 0, 0, (float)bg.w, (float)bg.h, (w - gw) / 2, 0, gw, h, 0);
        }
        for (int i = 0; i < 3; i++)
            for (int y = rects[i][1]; y < rects[i][1] + rects[i][3]; y++)
                if (y >= 0 && y < h)
                    memcpy(canvas.px + ((size_t)y * w + rects[i][0]) * 3, ov.px + ((size_t)y * w + rects[i][0]) * 3,
                           (size_t)rects[i][2] * 3);
        image_free(&ov);
        image_free(&bg);
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page == 87 && text_ready() && image_resize(&canvas, w, h)) { /* the Challenge Match results (a sample) */
        match_sample();
        if (getenv("TM2PC_SHOT_BG")) { image_free(&pause_frame); pause_frame = image_load_bmp(getenv("TM2PC_SHOT_BG")); pause_frame_gen++; }
        results_title = "AXEL WINS";
        results_winner = match_car(1);
        int was_live = battle_live;
        if (getenv("TM2PC_SHOT_TEAMS")) { battle_live = 1; results_title = "RED TEAM WINS"; results_winner = NULL; } /* the profile's teams */
        compose_results(&canvas, 0);
        battle_live = was_live;
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page == 13 && getenv("TM2PC_SHOT_SAVES")) { /* tests: saves with 1-4 players (in memory only) */
        static const int cars[5][4] = {{7}, {9, 8}, {0, 4, 11}, {3, 6, 2, 10}, {12}};
        for (int i = 0; i < 4; i++) profile_preview_save(i, 2 + i, i + 1, cars[i], 1);
        play_players = 4;
    }
    if (page == 88 && text_ready() && image_resize(&canvas, w, h)) { /* the tournament menus: row 0 won, 1 lost */
        static const char *const won[3] = {"CONTINUE", "SAVE", "EXIT"}, *const lost[2] = {"RESTART", "QUIT"};
        if (sel == 2) { menu_note = "SAVE COMPLETE"; menu_note_until = SDL_GetTicksNS() + 3000000000ull; sel = 0; }
        if (getenv("TM2PC_SHOT_BG")) { pause_frame = image_load_bmp(getenv("TM2PC_SHOT_BG")); pause_frame_gen++; }
        menu_items = sel == 1 ? lost : won;
        menu_count = sel == 1 ? 2 : 3;
        menu_title = sel == 1 ? "GAME OVER" : "LEVEL COMPLETE";
        if (sel == 3) { /* (row 3: a custom tournament's end, TM2PC_SHOT_TITLE its title) */
            static const char *const finish[1] = {"FINISH"};
            menu_items = finish, menu_count = 1;
            menu_title = getenv("TM2PC_SHOT_TITLE") ? getenv("TM2PC_SHOT_TITLE") : "TOURNAMENT WON!";
        }
        compose_pause(&canvas, 0, NULL, NULL);
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        image_free(&pause_frame); pause_frame_gen++;
        return ok;
    }
    if ((page == 94 || page == 95) && text_ready() && image_resize(&canvas, w, h)) { /* the 3 (94) and 4 (95) player sign-in */
        memset(sp, 0, sizeof sp);
        profile_rescan();
        sp_n = page == 94 ? 3 : 4;
        for (int p = 0; p < sp_n; p++) sp[p].joined = p < sp_n - 1 || sel > 0; /* the last: PRESS START, unless sel > 0 */
        sp[0].ready = 1;
        snprintf(sp[0].name, sizeof sp[0].name, "%s", profile_list_name(0));
        sp[1].sel = profile_count(); /* Guest */
        sp[2].sel = profile_count() + 1; /* New Profile */
        compose_signin(&canvas);
        sp_n = 2;
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page == 93 && text_ready() && image_resize(&canvas, w, h)) { /* the 2-player sign-in */
        memset(sp, 0, sizeof sp);
        profile_rescan();
        sp[0].joined = sp[1].joined = 1;
        sp[0].sel = profile_count() > 1 ? 1 : 0;
        sp[0].ready = 1;
        snprintf(sp[0].name, sizeof sp[0].name, "%s", profile_list_name(sp[0].sel));
        sp[1].sel = sel >= 0 ? sel : 0;
        if (sel <= -3 && sel >= -5) { /* rows -3, -4, -5: player 2's profile options, its portrait grid, deleting */
            sp[1].sel = 0;
            sp_edit_begin(1, profile_list_name(0));
            sp[1].mode = sel == -3 ? SP_MENU : sel == -4 ? SP_GRID : SP_DELETE;
            sp[1].msel = sel == -5 ? 2 : 0;
            sp_build_pics();
            sp_read_unlocks(1);
            sp[1].gsel = 7;
            sp[1].gtop = 0;
            sp[1].held_since = sel == -5 ? SDL_GetTicks() - 1500 : 0;
        }
        if (sel == -2) { /* row -2: player 2 naming a new profile */
            sp[1].nm.active = 1;
            sp[1].nm.caps = 1;
            sp[1].nm.row = 1;
            sp[1].nm.col = 3;
            snprintf(sp[1].nm.text, sizeof sp[1].nm.text, "Player");
        }
        uint64_t t0 = SDL_GetTicksNS();
        compose_signin(&canvas);
        uint64_t t1 = SDL_GetTicksNS();
        compose_signin(&canvas); /* again: what a move on the page costs */
        fprintf(stderr, "ui shot: drawn in %.1f ms, redrawn in %.1f ms\n", (t1 - t0) / 1e6, (SDL_GetTicksNS() - t1) / 1e6);
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page >= 94 && page <= 96 && text_ready() && image_resize(&canvas, w, h)) {
        /* 94 the profiles at startup (on the title picture), 95 deleting
         * (the bar half full), 96 the portrait grid */
        from_title = 1;
        startup = page == 94;
        PageId pg = page == 94 ? PAGE_PROFILES : PAGE_PROFILE;
        build(pg);
        if (page == 95) { delhold.active = 1; delhold.ready = 1; delhold.frames = DELETE_HOLD / 2; }
        if (page == 96) {
            pgrid.active = 1;
            pgrid.sel = sel >= 0 && sel < profile_picture_total() ? sel : profile_picture();
            build_grid();
            int row, col;
            grid_find(pgrid.sel, &row, &col);
            pgrid.top = row < GRID_SHOWN ? 0 : row - GRID_SHOWN + 1;
        }
        uint64_t t0 = SDL_GetTicksNS();
        compose(&canvas, pg, page == 94 ? signed_in_row() : 1, &scroll);
        uint64_t t1 = SDL_GetTicksNS();
        compose(&canvas, pg, page == 94 ? signed_in_row() : 1, &scroll); /* again: what a move on the page costs */
        fprintf(stderr, "ui shot: drawn in %.1f ms, redrawn in %.1f ms\n", (t1 - t0) / 1e6, (SDL_GetTicksNS() - t1) / 1e6);
        delhold.active = pgrid.active = startup = 0;
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (page == 97 && text_ready() && image_resize(&canvas, w, h)) { /* entering a name */
        name_start(0);
        snprintf(naming.text, sizeof naming.text, "Tokat");
        naming.row = 1;
        naming.col = 9;
        compose(&canvas, PAGE_PROFILES, 0, &scroll);
        naming.active = 0;
        int ok = image_save_bmp(&canvas, bmp_path);
        image_free(&canvas);
        return ok;
    }
    if (!text_ready() || page < 0 || page >= PAGE_COUNT || !image_resize(&canvas, w, h))
        return 0;
    from_title = 1; /* as opened from the title menu */
    build((PageId)page);
    if (sel < 0 || sel >= row_count || !selectable(sel))
        sel = first_selectable();
    uint64_t t0 = SDL_GetTicksNS();
    compose(&canvas, (PageId)page, sel, &scroll);
    uint64_t t1 = SDL_GetTicksNS();
    compose(&canvas, (PageId)page, sel, &scroll); /* again: what a change on the page costs */
    fprintf(stderr, "ui shot: drawn in %.1f ms, redrawn in %.1f ms\n", (t1 - t0) / 1e6, (SDL_GetTicksNS() - t1) / 1e6);
    int ok = image_save_bmp(&canvas, bmp_path);
    image_free(&canvas);
    return ok;
}

/* The game's arena select (8012FD30), reached back from a Challenge Match's
 * car select: the match's page instead. */
void F_8012FD30_orig(CPU *c);
void ui_LevelSelect(CPU *c)
{
    if (!battle_live) {
        F_8012FD30_orig(c);
        return;
    }
    battle_back = 1;
    c->r[2] = play_players == 2 ? GA(0x8012F5F8u) : GA(0x8012E908u);
}

/* The game's opponent select (80131EEC) after a Challenge Match's car
 * select: the opponents set on its page instead (Random: an allowed driver
 * not in the match yet), then on to the match as the select's Done. */
void F_80131EEC_orig(CPU *c);
void ui_AiSelect(CPU *c)
{
    const uint32_t S = GA(0x8016475Cu);
    void vp_boss_wave(int first); /* vplus/fixes.c */
    vp_jugg_car_set(-1);
    vp_boss_wave(-1);
    tour_dt_boss = 0;
    if (!battle_live || mem_r8(&M.cpu, S) != 3) {
        F_80131EEC_orig(c);
        return;
    }
    const char *test_opps = getenv("TM2PC_TEST_OPPONENTS"); /* tests: the opponents' cars ("32,6,-1": numbers, -1 Random) */
    for (int i = 0; test_opps && *test_opps && i < BATTLE_OPPONENT_SLOTS; i++) {
        battle_match()->opponent[i] = atoi(test_opps);
        test_opps = strchr(test_opps, ',');
        test_opps = test_opps ? test_opps + 1 : NULL;
    }
    const MatchSetup *b = battle_match();
    unsigned drivers = trun.on ? battle_tour()->roster : battle_match_type()->drivers;
    if (!trun.on) /* Challenge Match: the bosses by their own rows (Minion in random, Dark Tooth in random) */
        drivers = (drivers & ~(1u << TOUR_MINION)) | (battle_match_type()->minion_random ? 1u << TOUR_MINION : 0u) |
                  (battle_match_type()->dark_tooth ? 1u << TOUR_DARK_TOOTH : 0u);
    /* (a tournament: the roster's, CPU Drivers: Sweet Tooth, Minion and Dark Tooth too, once unlocked; else the bosses
     * only in their waves) */
    /* the mod characters that are on, for the Random drivers (Options > Mods; offline: online every machine rolls the
     * same picks from the same pool, and the setting is this PC's) */
    int mod_characters(void), mod_character(int i), netplay_in_match(void);
    int chars = mods_cpu_characters() && !netplay_in_match() ? mod_characters() : 0;
    if (chars > 128) chars = 128;
    if (survival_on) { /* random distinct regular cars (and characters), Minion (or Dark Tooth) the last (round 10) */
        int n = mem_r8(&M.cpu, S + 5), used[BATTLE_DRIVERS + 1] = {0}, used_mod[128] = {0};
        for (int h = 0; h < mem_r8(&M.cpu, S + 4) && h < 2; h++) used[mem_r8(&M.cpu, S + 8 + (uint32_t)h) % (BATTLE_DRIVERS + 1)] = 1;
        for (int h = 2; h < four_humans(); h++) used[four_car_of(h) % (BATTLE_DRIVERS + 1)] = 1; /* players 3-4 */
        for (int i = 0; i < n; i++) {
            int car = survival_boss_on ? 14 : 13; /* (Dark Tooth loaded last: SURVIVAL.md 4.2) */
            if (i < n - 1) {
                int pool[BATTLE_OPPONENT_CARS + 128], k = 0;
                for (int cc = 0; cc < BATTLE_OPPONENT_CARS; cc++) if (!used[cc]) pool[k++] = cc;
                for (int j = 0; j < chars; j++) if (!used_mod[j]) pool[k++] = mod_character(j);
                car = k ? pool[SDL_rand(k)] : 0;
                if (car >= 0x20) for (int j = 0; j < chars; j++) used_mod[j] |= mod_character(j) == car;
                else used[car] = 1;
            }
            guest_call(GA(0x80137854u), S, (uint32_t)i, (uint32_t)car, 0);
            fprintf(stderr, "survival: car %d is %s\n", i + 1, car_label(car));
        }
        c->r[2] = GA(0x801334E8u);
        return;
    }
    int n = mem_r8(&M.cpu, S + 5), humans = mem_r8(&M.cpu, S + 4), used[BATTLE_DRIVERS + 1] = {0}, used_mod[128] = {0};
    /* Juggernaut with its car forced: the car is a 17th, parked (below): 16 cars drive, the computer-car records hold
     * the opponents and it (the decomp's TM2_MAX_AI_CARS: 1 player + 15 opponents + the parked car); one opponent fewer
     * only when the records are full */
    const GameType *jt = battle_match_type();
    int jforce = jt->mode == MODE_JUGGERNAUT && jt->jugg_force && jt->jugg_car >= 0 && jt->jugg_car < BATTLE_DRIVERS &&
                 vp_jugg_car_swap() && !trun.on;
    if (jforce && n > 1 && n >= cars_ai_max()) n--;
    for (int h = 0; h < humans; h++) used[mem_r8(&M.cpu, S + 8 + h) % (BATTLE_DRIVERS + 1)] = 1;
    for (int h = 2; h < four_humans(); h++) used[four_car_of(h) % (BATTLE_DRIVERS + 1)] = 1; /* players 3-4 */
    /* (a player drives Dark Tooth: online none of the computer cars may; offline the picked ones still come, each his
     * own key and head beside the player's, DARK_TOOTH_PLAYER.md 5; Random never adds him beside the player's) */
    int human_dt = used[TOUR_DARK_TOOTH];
    for (int i = 0; i < n && i < BATTLE_OPPONENT_SLOTS; i++) {
        int car = b->opponent[i];
        if (car >= 0x20 && car < 0x20 + 128) used_mod[car - 0x20] = 1; /* (a character picked on the page) */
        else if (car >= 0 && car <= BATTLE_DRIVERS) used[car] = 1;
    }
    int level = mem_r8(&M.cpu, S + 24), types = 0;
    for (int cc = 0; cc <= BATTLE_DRIVERS; cc++) types += used[cc];
    for (int j = 0; j < 128; j++) types += used_mod[j]; /* (a character: textures of its own) */
    if (jforce && !used[jt->jugg_car]) { used[jt->jugg_car] = 1; types++; } /* (its textures counted: the arena's room) */
    /* the random opponents: the 12, then Sweet Tooth, Minion and Dark Tooth once unlocked (decomp request 42, CUSTOM_TOURNAMENT_ANSWERS.md: Sweet Tooth's
     * AI is all there; Dark Tooth his first phase only, portCarOptions bit 10, four.c), Dark Tooth once a match, never
     * beside his boss fight (a stage's boss), and where his textures fit (texture banks, or the arena's room) */
    int dt_boss_here = 0;
    if (trun.on && !trun.duel)
        for (int bi = 0; bi < battle_tour()->stage[trun.stage].bosses && bi < TOUR_BOSSES_MAX; bi++)
            dt_boss_here |= battle_tour()->stage[trun.stage].boss[bi] == TOUR_DARK_TOOTH;
    int open[TOUR_DARK_TOOTH + 1];
    for (int cc = 0; cc <= TOUR_DARK_TOOTH; cc++)
        open[cc] = cc < BATTLE_OPPONENT_CARS || (cc == 12 && profile_sweet_tooth_unlocked()) ||
                   (cc == TOUR_MINION && profile_minion_unlocked()) ||
                   (cc == TOUR_DARK_TOOTH && profile_dark_tooth_unlocked() && !dt_boss_here && port_config_on() &&
                    (cars_banks() || level >= 13 || boss_room[level] > humans + n));
    int pool_cars = TOUR_DARK_TOOTH + 1;
    if (getenv("TM2PC_TEST_PRE42")) { /* tests: the pool before request 42 (CUSTOM_TOURNAMENT_ANSWERS.md; the 12; a tournament's regular Minion) */
        pool_cars = trun.on && (battle_tour()->roster >> TOUR_MINION & 1) && profile_minion_unlocked() ? TOUR_MINION + 1 : BATTLE_OPPONENT_CARS;
        open[TOUR_DARK_TOOTH] = 0;
    }
    int dt_picked = 0, online = netplay_in_match();
    static int dt_multi_off = -1; /* tests: TM2PC_DT_ONE=1, Dark Tooth once a match offline too (as before) */
    if (dt_multi_off < 0) dt_multi_off = getenv("TM2PC_DT_ONE") != NULL;
    int dt_room = !dt_boss_here && port_config_on() && (cars_banks() || level >= 13 || boss_room[level] > humans + n);
    for (int i = 0; i < n && i < BATTLE_OPPONENT_SLOTS; i++) {
        int car = b->opponent[i];
        /* a boss picked on the page (opponent_values_init): only while this profile has him (another profile's match setup
         * keeps its picks; online the host's pick, every machine alike) and, Dark Tooth, once a match where his textures
         * fit, as the random ones; else Random */
        if (car >= 12 && car <= TOUR_DARK_TOOTH &&
            ((!online && !open[car]) || (car == TOUR_DARK_TOOTH && (((dt_picked || human_dt) && (online || dt_multi_off)) || !dt_room)))) {
            fprintf(stderr, "challenge match: opponent %d, %s, not here (locked, or no room): Random\n", i + 1, car_label(car));
            car = -1;
        }
        dt_picked |= car == TOUR_DARK_TOOTH;
        if (car < 0 && trun.versus && i < versus_cpu_n) { /* versus: the first stage's contestant, if the arena has room */
            int r = versus_cpu[i], full = cars_duplicates() && types >= cars_arena_types(level);
            if (r >= 0 && r <= TOUR_DARK_TOOTH && open[r] && (!full || used[r]) && !(r == TOUR_DARK_TOOTH && used[r])) car = r;
        }
        if (car < 0) {
            /* a type more only while the arena's VRAM holds it (cars_arena_types); past that, with duplicates, a type
             * already in the match (its textures are there); the characters with the allowed drivers */
            int full = cars_duplicates() && types >= cars_arena_types(level);
            int pool[TOUR_DARK_TOOTH + 1 + 128], k = 0;
            for (int pass = 0; pass < 3 && !k; pass++) { /* allowed and new; allowed; any of the 12 (full: in the match only) */
                for (int cc = 0; cc < pool_cars; cc++)
                    if (open[cc] && (pass == 2 ? cc < BATTLE_OPPONENT_CARS : (drivers >> cc) & 1) &&
                        (full ? used[cc] : pass >= 1 || !used[cc]) && !(cc == TOUR_DARK_TOOTH && used[cc]))
                        pool[k++] = cc;
                for (int j = 0; j < chars && pass < 2; j++) {
                    int m = mod_character(j) - 0x20;
                    if (m >= 0 && m < 128 && (full ? used_mod[m] : pass >= 1 || !used_mod[m])) pool[k++] = 0x20 + m;
                }
            }
            car = pool[SDL_rand(k)];
        }
        if (car >= 0x20 && car < 0x20 + 128) {
            types += !used_mod[car - 0x20];
            used_mod[car - 0x20] = 1;
        } else {
            types += !used[car];
            used[car] = 1;
        }
        guest_call(GA(0x80137854u), S, (uint32_t)i, (uint32_t)car, 0);
        fprintf(stderr, "challenge match: opponent %d is %s\n", i + 1, car_label(car));
    }
    /* Juggernaut: the game type's car loaded as one opponent more (the last), parked until a Juggernaut takes it
     * (vplus/fixes.c); a 17th car (it never drives with the others: 16 active), while the computer-car records have room
     * and the arena's VRAM its type */
    const GameType *t = battle_match_type();
    int jc = t->jugg_force ? t->jugg_car : -1, everyone = (humans > four_humans() ? humans : four_humans()) + n;
    if (t->mode == MODE_JUGGERNAUT && jc >= 0 && jc < BATTLE_DRIVERS && vp_jugg_car_swap() && everyone <= CARS_MAX &&
        n < cars_ai_max() && (used[jc] || types < cars_arena_types(level))) {
        guest_call(GA(0x80137854u), S, (uint32_t)n, (uint32_t)jc, 0);
        guest_call(GA(0x80137918u), S, (uint32_t)(n + 1), 0, 0);
        vp_jugg_car_set(n);
        fprintf(stderr, "challenge match: the Juggernaut's car is %s (opponent %d, parked)\n", profile_character_name(jc), n + 1);
    } else if (t->mode == MODE_JUGGERNAUT && jc >= 0) {
        fprintf(stderr, "challenge match: no room for the Juggernaut's car (swap %d, cars %d, opponents %d of %d, types %d of %d)\n",
                vp_jugg_car_swap(), everyone, n, cars_ai_max(), types, cars_arena_types(level));
        if (jforce && n != mem_r8(&M.cpu, S + 5)) guest_call(GA(0x80137918u), S, (uint32_t)n, 0, 0); /* (the opponents as picked) */
    }
    /* a custom tournament's bosses: loaded last, parked until the others are out (vplus/fixes.c vp_boss_wave); each while
     * the match has room (16 cars, the records) and the arena's VRAM for its type (Dark Tooth: as Survival's, his
     * fight on any arena, texture banks) */
    const TourStage *ts = trun.on && !trun.duel && !trun.versus ? &battle_tour()->stage[trun.stage] : NULL; /* (the final
                                                                    * battle: none; versus: a player drives the boss) */
    int first = n, nb = 0;
    for (int bi = 0; ts && bi < ts->bosses && bi < TOUR_BOSSES_MAX; bi++) {
        int car = ts->boss[bi];
        if (car < 0 || car > TOUR_DARK_TOOTH) continue;
        int dt = car == TOUR_DARK_TOOTH;
        if (dt && (!port_config_on() || (!cars_banks() && level < 13 && boss_room[level] <= everyone + nb))) {
            fprintf(stderr, "custom tournament: no room for Dark Tooth here\n");
            continue;
        }
        if (everyone + nb >= CARS_MAX || n + nb >= cars_ai_max() || (!used[car] && !dt && types >= cars_arena_types(level))) {
            fprintf(stderr, "custom tournament: no room for the boss %s\n", profile_character_name(car));
            continue;
        }
        guest_call(GA(0x80137854u), S, (uint32_t)(n + nb), (uint32_t)car, 0);
        types += !used[car];
        used[car] = 1;
        tour_dt_boss |= dt;
        nb++;
        fprintf(stderr, "custom tournament: the boss %s (opponent %d, parked)\n", profile_character_name(car), n + nb);
    }
    if (nb) {
        guest_call(GA(0x80137918u), S, (uint32_t)(n + nb), 0, 0);
        vp_boss_wave(first);
    }
    c->r[2] = GA(0x801334E8u); /* the globe, then the match (as the select's Done) */
}

/* ---- Challenge Match: the match's end, the results, the scoreboard ----
 * The game's challenge (mode 3) and Deathmatch (4) play rounds until Quit.
 * In a Challenge Match the round's result ends it: the results (the winner,
 * then the scoreboard) over the last frame, then a rematch (the runner's
 * next round) or back to the Challenge Match page (the runner told to quit).
 * The game's own tally screens are left out then. Holding the scoreboard
 * button (a controller's touchpad or guide button, or Tab) in a battle shows
 * the scoreboard over the game. */
static const uint8_t SB_PLAYER[2][3] = {{228, 24, 36}, {40, 110, 230}};

/* The player's name (a human: the profile's, or Player N; a computer car: CPU) and the driver's */
/* human h of the match's name: a server's match, as its lobby has the player (every machine the same names); else this
 * PC's player h's */
static const char *match_human_name(int h)
{
    Lobby *l = netplay_lobby();
    if (netplay_human_name(h)) return netplay_human_name(h); /* (a player who left since: still theirs) */
    if (l && netplay_in_match()) {
        const LobbyView *v = lobby_view(l);
        for (int n = 0; n < SES_MAX_NODES; n++)
            if (v->start.first[n] != 0xFF && h >= v->start.first[n] && h < v->start.first[n] + v->m[n].count)
                return v->m[n].p[h - v->start.first[n]].name;
    }
    if (h < 4) return player_name(h);
    static char name[16];
    snprintf(name, sizeof name, "Player %d", h + 1);
    return name;
}
static int match_human_friend(int h) /* human h of a server's match: this profile's friend */
{
    Lobby *l = netplay_lobby();
    if (!l || !netplay_in_match() || h < 0) return 0;
    const LobbyView *v = lobby_view(l);
    for (int n = 0; n < SES_MAX_NODES; n++)
        if (v->start.first[n] != 0xFF && h >= v->start.first[n] && h < v->start.first[n] + v->m[n].count)
            return friends_is(v->m[n].p[h - v->start.first[n]].online_id);
    return 0;
}
static int match_human_ping(int h)
{
    Lobby *l = netplay_lobby();
    if (!l || !netplay_in_match() || h < 0) return -2;
    const LobbyView *v = lobby_view(l);
    for (int n = 0; n < SES_MAX_NODES; n++)
        if (v->start.first[n] != 0xFF && h >= v->start.first[n] && h < v->start.first[n] + v->m[n].count)
            return n == lobby_host_node(l) ? -1 : v->m[n].ping ? v->m[n].ping : -2;
    return -2;
}
static void scoreboard_player(const MatchCar *m, char *out, size_t n)
{
    snprintf(out, n, "%s", m->human >= 0 ? match_human_name(m->human) : "CPU");
    upper(out);
}
static void scoreboard_driver(const MatchCar *m, char *out, size_t n)
{
    snprintf(out, n, "%s", m->car >= 0 ? profile_character_name(m->car) : "?");
    upper(out);
}
/* a winner's name: the player's, or a computer car's driver */
static void scoreboard_name(const MatchCar *m, char *out, size_t n)
{
    if (m->human >= 0) scoreboard_player(m, out, n);
    else scoreboard_driver(m, out, n);
}

/* the order shown: still in first (by kills, then damage), then by place */
int vp_deathmatch(void);
static int scoreboard_order(int *order)
{
    int n = match_cars();
    /* the best first: in a mode with respawns its points (Gun Game's level, the kills...), a destroyed car's place
     * meaning nothing there (each death gave one); else the place (still in first), then lives left (Last Car Standing
     * with lives), then points, kills, damage */
    int respawns = battle_live && !survival_on && vp_deathmatch();
    int by_lives = battle_live && !survival_on && battle_match_type()->mode == MODE_LAST_CAR && battle_match()->lives > 1;
    for (int i = 0; i < n; i++) order[i] = i;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++) {
            const MatchCar *a = match_car(order[i]), *b = match_car(order[j]);
            int ka = respawns ? 0 : a->place, kb = respawns ? 0 : b->place;
            int swap = ka != kb ? (ka == 0 ? 0 : kb == 0 ? 1 : ka > kb)
                     : by_lives && b->lives != a->lives ? b->lives > a->lives
                     : b->points != a->points ? b->points > a->points /* the modes' points first */
                     : b->kills != a->kills ? b->kills > a->kills : b->damage > a->damage;
            if (swap) { int t = order[i]; order[i] = order[j]; order[j] = t; }
        }
    return n;
}

/* A car's card (the opponent cards' picture, 2:1), framed in the player's color. */
static int car_team(const MatchCar *m);
static void draw_plate(const View *v, const MatchCar *m, int x, int y, int w, int h)
{
    static const uint8_t frame[3] = {90, 90, 98}, dark[3] = {20, 20, 24};
    int t = S(v, 1.5f) > 1 ? S(v, 1.5f) : 1;
    int team = m->human >= 0 && battle_live && !survival_on && battle_match_teams() ? car_team(m) : -1;
    int slot = m->human < 0 ? -1 : netplay_in_match() ? humans_slot(m->human) : m->human; /* (online: this PC's players) */
    const uint8_t *edge = m->human < 0 ? frame : team >= 0 ? TEAM_COLOR[team % BATTLE_TEAM_COLORS] /* teams: the player's team, not P1/P2 */
                       : slot >= 0 ? SB_PLAYER[slot & 1] : frame;
    draw_fill(v->c, x - t, y - t, w + 2 * t, h + 2 * t, edge, 255);
    if (m->car >= 0 && m->car < 14 && plates.px) draw_image(v->c, &plates, m->car * 128.0f, 0, 128, 64, x, y, w, h, 0);
    else { /* no card (Dark Tooth, a mod's car without one): its name on the dark card */
        draw_fill(v->c, x, y, w, h, dark, 255);
        char nm[32];
        snprintf(nm, sizeof nm, "%s", m->car >= 0 ? car_label(m->car) : "");
        upper(nm);
        int sz = h * 2 / 5, tw = text_width(nm, sz);
        if (tw > w - 4 && tw > 0) sz = sz * (w - 4) / tw, tw = text_width(nm, sz);
        if (nm[0] && sz >= 5) text_draw(v->c, nm, x + (w - tw) / 2, text_top_for_center(y + h / 2, sz), sz, ORANGE);
    }
}

/* The table, in (x0, y0)-(x1, y1) of the 640x480 screen: the place (final),
 * the player (profile name, or CPU), the car's card, KILLS, DEATHS, DAMAGE,
 * and LIVES left (Last Car Standing with more than one; PING online, later).
 * More than 8 cars: two columns side by side (up to 16). */
/* the board's fourth column: 1 lives (Last Car Standing with lives), 2 points (Juggernaut, Hunted), 3 the Gun Game level */
static int scoreboard_lives(void)
{
    if (!battle_live || survival_on) return 0;
    int mode = battle_match_type()->mode;
    return mode == MODE_LAST_CAR ? battle_match()->lives > 1
         : mode == MODE_JUGGERNAUT || mode == MODE_ODDBALL || mode == MODE_KING_OF_THE_HILL ? 2
         : mode == MODE_GUN_GAME ? 3 : 0;
}
/* Teams on the board: a car's team, -1 without teams */
static int car_team(const MatchCar *m)
{
    const MatchSetup *ms = battle_match();
    if (!battle_live || survival_on || !battle_match_teams() || (m->human < 0 && m->ai < 0))
        return -1;
    return (m->human >= 0 ? ms->player_team[m->human & 15] : ms->team[m->ai % BATTLE_OPPONENT_SLOTS]) % BATTLE_TEAM_COLORS;
}
enum { TEAM_LINE_H = 24 }; /* the teams' totals, at the board's bottom */
/* Teams: two columns, a team in each; three or four: two teams one above the
 * other in each column (red and green left, blue and gold right), the rows
 * of each pair level. Fills order with the cars (column 0 then 1, -1 for an
 * empty row), *per the rows per column, tc the teams (tc[0] tc[1] the first
 * pair, tc[2] tc[3] the second, -1 none), *g1 the first pair's rows. Returns
 * the pairs (1 or 2), 0 when the board is not split so. */
static int scoreboard_split(int *order, int *per, int tc[4], int *g1)
{
    int n = match_cars(), seen[BATTLE_TEAM_COLORS] = {0}, teams = 0, list[BATTLE_TEAM_COLORS];
    for (int i = 0; i < n; i++) {
        int t = car_team(match_car(i));
        if (t < 0) return 0;
        if (!seen[t]++) list[teams++] = t;
    }
    if (teams < 2) return 0;
    for (int i = 0; i < teams; i++) /* in color order */
        for (int j = i + 1; j < teams; j++) if (list[j] < list[i]) { int x = list[i]; list[i] = list[j]; list[j] = x; }
    for (int k = 0; k < 4; k++) tc[k] = k < teams ? list[k] : -1;
    int a = seen[tc[0]] > seen[tc[1]] ? seen[tc[0]] : seen[tc[1]];
    int b = teams > 2 ? (seen[tc[2]] > (tc[3] >= 0 ? seen[tc[3]] : 0) ? seen[tc[2]] : seen[tc[3]]) : 0;
    *g1 = a;
    *per = a + b;
    int sorted[MATCH_MAX], fill[4] = {0};
    scoreboard_order(sorted);
    for (int i = 0; i < 2 * *per; i++) order[i] = -1;
    for (int i = 0; i < n; i++) {
        int t = car_team(match_car(sorted[i])), k = 0;
        while (k < 3 && tc[k] != t) k++;
        int col = k & 1, row = (k >= 2 ? a : 0) + fill[k]++;
        order[col * *per + row] = sorted[i];
    }
    return teams > 2 ? 2 : 1;
}
static int scoreboard_rows(int y0, int y1, int *cols)
{
    int n = match_cars(), order[32], per, tc[4], g1, pairs = scoreboard_split(order, &per, tc, &g1);
    int teams = n && car_team(match_car(0)) >= 0, room = y1 - y0 - 38 - (teams ? TEAM_LINE_H * (pairs > 1 ? 2 : 1) : 0);
    if (pairs) {
        *cols = 2;
    } else {
        *cols = n > 8 ? 2 : 1;
        per = (n + *cols - 1) / *cols;
    }
    int rowh = per ? room / per : 30;
    return rowh > 40 ? 40 : rowh;
}
static int scoreboard_height(int y0, int y1)
{
    int cols, rowh = scoreboard_rows(y0, y1, &cols), n = match_cars(), order[32], per, tc[4], g1;
    int pairs = scoreboard_split(order, &per, tc, &g1);
    if (!pairs) per = (n + cols - 1) / cols;
    return 30 + per * rowh + 8 + (n && car_team(match_car(0)) >= 0 ? TEAM_LINE_H * (pairs > 1 ? 2 : 1) : 0);
}
/* the board's left and right (640 x 480 units): 40..600 on 4:3; wider screens give it most of their extra width (up to
 * 1000 units), so the names have room (the user's: "TOK..." on an ultrawide) */
static void scoreboard_span(const View *v, int *x0, int *x1)
{
    float units = v->s > 0 ? v->c->w / v->s : 640, extra = (units - 640) * 0.4f;
    if (extra < 0) extra = 0;
    if (560 + 2 * extra > 1000) extra = (1000 - 560) / 2.0f;
    *x0 = 40 - (int)extra;
    *x1 = 600 + (int)extra;
}
static void draw_scoreboard(const View *v, int x0, int y0, int x1, int y1, int final)
{
    static const uint8_t panel[3] = {8, 8, 10}, line[3] = {188, 188, 196};
    int order[2 * MATCH_MAX], n = scoreboard_order(order), head = 30, cols, tc[4], g1 = 0;
    int rowh = scoreboard_rows(y0, y1, &cols), per = (n + cols - 1) / cols, lives = scoreboard_lives();
    /* Last Car Standing: lives in place of deaths (what decides it), the cars out greyed (the user's 2026-11-01) */
    int lcs = battle_live && !survival_on && battle_match_type()->mode == MODE_LAST_CAR;
    if (lcs) lives = 0;
    int split = scoreboard_split(order, &per, tc, &g1), teams = n && car_team(match_car(0)) >= 0;
    if (split) n = 2 * per; /* the columns' slots, -1 the empty ones */
    int lines = split > 1 ? 2 : 1; /* the teams' totals: a line per pair */
    int t = S(v, 1.5f) > 1 ? S(v, 1.5f) : 1, h = head + per * rowh + 8 + (teams ? TEAM_LINE_H * lines : 0);
    if (split > 1) /* between the pairs */
        draw_fill(v->c, X(v, x0 + 10), Y(v, y0 + head + g1 * rowh), S(v, x1 - x0 - 20), t, line, 90);
    draw_fill(v->c, X(v, x0), Y(v, y0), S(v, x1 - x0), S(v, h), panel, 215);
    draw_fill(v->c, X(v, x0), Y(v, y0), S(v, x1 - x0), t, line, 255);
    draw_fill(v->c, X(v, x0), Y(v, y0 + h) - t, S(v, x1 - x0), t, line, 255);
    int colw = (x1 - x0) / cols;
    for (int col = 0; col < cols; col++) {
        int cx0 = x0 + col * colw, cx1 = cx0 + colw - (cols > 1 ? 6 : 0);
        if (col) draw_fill(v->c, X(v, cx0 - 3), Y(v, y0 + 6), t, S(v, h - 12), line, 120);
        /* lives (a mode's column) next to damage; in two columns on a 4:3 screen damage gives way */
        int small = cols > 1, wide = v->c->w > (int)(700 * v->s), drop_damage = lives && small && !wide;
        int nums = lives && !drop_damage ? 4 : 3, numw = small ? 32 : 76;
        int ping = netplay_in_match() && netplay_lobby() && !final; /* online: each player's round trip, last */
        int cx_place = cx0 + 16, cx_player = cx0 + (final ? 32 : 12);
        int ch = small ? (rowh - 10 < 26 ? rowh - 10 : 26) : rowh - 6, cw = ch * 2, num0 = cx1 - (nums + ping) * numw + numw / 2 - 6;
        int namew = num0 - numw / 2 - 16 - cw - cx_player; /* the name, then the card right after it */
        if (namew > 240) namew = 240;
        int cx_card = cx_player + namew + 8;
        const char *heads[4] = {"KILLS", lcs ? "LIVES" : "DEATHS", "DAMAGE", lives == 2 ? "POINTS" : lives == 3 ? "LEVEL" : "LIVES"};
        const char *short_heads[4] = {"K", lcs ? "L" : "D", "DMG", lives == 2 ? "PTS" : lives == 3 ? "LVL" : "L"};
        int col_of[4] = {0, 1, 2, 3};
        if (drop_damage) col_of[2] = 3; /* the third column: lives */
        lettering();
        int hs = S(v, 13), hy = text_top_for_center(Y(v, y0 + head / 2 + 2), hs);
        if (final) text_draw(v->c, "#", X(v, cx_place) - text_width("#", hs) / 2, hy, hs, COPPER);
        text_draw(v->c, "PLAYER", X(v, cx_player), hy, hs, COPPER);
        text_draw(v->c, "CAR", X(v, cx_card + cw / 2) - text_width("CAR", hs) / 2, hy, hs, COPPER);
        for (int k = 0; k < nums; k++) {
            const char *hd = small ? short_heads[col_of[k]] : heads[col_of[k]];
            text_draw(v->c, hd, X(v, num0 + k * numw) - text_width(hd, hs) / 2, hy, hs, COPPER);
        }
        if (ping) text_draw(v->c, small ? "MS" : "PING", X(v, num0 + nums * numw) - text_width(small ? "MS" : "PING", hs) / 2, hy, hs, COPPER);
        for (int r = 0; r < per; r++) {
            int i = col * per + r;
            if (i >= n) break;
            if (order[i] < 0) continue;
            const MatchCar *m = match_car(order[i]);
            int ry = y0 + head + r * rowh, size = S(v, small ? 13 : rowh >= 34 ? 17 : rowh >= 26 ? 15 : 13), cy = Y(v, ry + rowh / 2);
            int ty = text_top_for_center(cy, size);
            char player[48], num[16], fit[48];
            scoreboard_player(m, player, sizeof player);
            int out = lcs && !final && m->place != 0; /* (out of the match: greyed) */
            TextColor c = out ? GRAY : m->human >= 0 ? WHITE : PALE;
            if (final) {
                snprintf(num, sizeof num, "%d", split ? (r >= g1 && split > 1 ? r - g1 : r) + 1 : m->place ? m->place : i + 1);
                text_draw(v->c, num, X(v, cx_place) - text_width(num, size) / 2, ty, size, c);
            }
            int pal = m->human >= 0 && match_human_friend(m->human), pw = pal ? S(v, 17) : 0;
            fit_text(fit, sizeof fit, player, S(v, namew) - pw, size);
            text_draw(v->c, fit, X(v, cx_player), ty, size, c);
            if (pal) /* (this profile's friend: the person, sky blue, as in the lobby) */
                draw_person(v, X(v, cx_player) + text_width(fit, size) + S(v, 5), cy, size * 9 / 10, CUSTOM);
            const MatchSetup *ms = battle_match();
            if (battle_live && !survival_on && battle_match_teams() &&
                (m->human >= 0 || m->ai >= 0)) { /* teams: a bar of the team's color before the name */
                int team = m->human >= 0 ? ms->player_team[m->human & 15] : ms->team[m->ai % BATTLE_OPPONENT_SLOTS];
                int bh = S(v, rowh * 0.7f);
                draw_fill(v->c, X(v, cx_player - 9), cy - bh / 2, S(v, 4), bh, TEAM_COLOR[team % BATTLE_TEAM_COLORS], 255);
            }
            draw_plate(v, m, X(v, cx_card), Y(v, ry + (rowh - ch) / 2), S(v, cw), S(v, ch));
            if (out) { /* (the card dimmed) */
                static const uint8_t dim[3] = {0, 0, 0};
                draw_fill(v->c, X(v, cx_card), Y(v, ry + (rowh - ch) / 2), S(v, cw), S(v, ch), dim, 170);
            }
            int left = m->place != 0 ? 0 : m->lives > 0 ? m->lives : 1; /* (Last Car Standing: the lives left, this one too) */
            int vals[4] = {m->kills, lcs ? left : m->deaths, m->damage, lives == 2 ? m->points : lives == 3 ? m->points + 1 : m->lives};
            for (int k = 0; k < nums; k++) {
                snprintf(num, sizeof num, "%d", vals[col_of[k]]);
                text_draw(v->c, num, X(v, num0 + k * numw) - text_width(num, size) / 2, ty, size, c);
            }
            int pms = ping && m->human >= 0 ? match_human_ping(m->human) : -3;
            if (pms > -3) { /* (the host's players: HOST; not known yet: a dash) */
                if (pms >= 0) snprintf(num, sizeof num, "%d", pms);
                else snprintf(num, sizeof num, "%s", pms == -1 ? (small ? "H" : "HOST") : "-");
                text_draw(v->c, num, X(v, num0 + nums * numw) - text_width(num, size) / 2, ty, size,
                          pms < 0 ? GRAY : pms < 100 ? c : pms <= 150 ? ORANGE : BAD);
            }
        }
        plain_text();
    }
    /* teams: each team's kills and cars left, along the board's bottom (two teams: under each column) */
    if (teams) {
        int kills[BATTLE_TEAM_COLORS] = {0}, left[BATTLE_TEAM_COLORS] = {0}, cars[BATTLE_TEAM_COLORS] = {0}, pts[BATTLE_TEAM_COLORS] = {0};
        for (int i = 0; i < match_cars(); i++) {
            const MatchCar *m = match_car(i);
            int team = car_team(m);
            if (team < 0) continue;
            cars[team]++;
            kills[team] += m->kills;
            pts[team] += m->points;
            left[team] += m->place == 0 ? (m->lives > 0 ? m->lives : 1) : 0; /* the lives the team has left */
        }
        int list[BATTLE_TEAM_COLORS], nt = 0;
        for (int k = 0; k < BATTLE_TEAM_COLORS; k++) if (cars[k]) list[nt++] = k;
        int per_line = split ? 2 : nt ? nt : 1; /* split: under each column, a line per pair */
        if (split) for (int k = 0; k < 4; k++) list[k] = tc[k];
        int ts = S(v, 14), sq = S(v, 10), colw = (x1 - x0) / per_line, top = y0 + h - 8 - TEAM_LINE_H * lines;
        draw_fill(v->c, X(v, x0 + 10), Y(v, top), S(v, x1 - x0 - 20), t, line, 120);
        lettering();
        for (int j = 0; j < (split ? 4 : nt); j++) {
            int k = list[j];
            if (k < 0) continue;
            int cy = Y(v, top + TEAM_LINE_H * (j / per_line) + TEAM_LINE_H / 2);
            char text[48];
            int mode = battle_match_type()->mode;
            if (mode == MODE_KING_OF_THE_HILL || mode == MODE_ODDBALL) /* (points win: the team's, the user's; kills and lives
                                                                       * do not matter there) */
                snprintf(text, sizeof text, "%s  %d POINT%s", team_values[k], pts[k], pts[k] == 1 ? "" : "S");
            else if (mode == MODE_DEATHMATCH)
                snprintf(text, sizeof text, "%s  %d KILL%s", team_values[k], kills[k], kills[k] == 1 ? "" : "S");
            else
                snprintf(text, sizeof text, "%s  %d KILL%s, %d %s LEFT", team_values[k], kills[k], kills[k] == 1 ? "" : "S", left[k],
                         left[k] == 1 ? "LIFE" : "LIVES");
            int w = sq + S(v, 6) + text_width(text, ts), x = X(v, x0 + colw * (j % per_line) + colw / 2) - w / 2;
            draw_fill(v->c, x, cy - sq / 2, sq, sq, TEAM_COLOR[k], 255);
            text_draw(v->c, text, x + sq + S(v, 6), text_top_for_center(cy, ts), ts, WHITE);
        }
        plain_text();
    }
}

/* The final kill cam's "FINAL KILL" over the picture (an overlay; none with on 0) */
void killcam_banner(int on)
{
    static Image kb;
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (!on || size.w <= 0 || size.h <= 0 || !text_ready() || !image_resize(&kb, size.w, size.h)) {
        Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
        return;
    }
    static const uint8_t bar[3] = {0, 0, 0};
    memset(kb.px, 0, (size_t)kb.w * kb.h * 3);
    View v = view_fit(&kb);
    int bh = kb.h / 9; /* letterbox bars, the title in the top one */
    draw_fill(&kb, 0, 0, kb.w, bh, bar, 255);
    draw_fill(&kb, 0, kb.h - bh, kb.w, bh, bar, 255);
    lettering();
    const char *t = "FINAL KILL";
    int ts = S(&v, 30);
    text_draw(&kb, t, kb.w / 2 - text_width(t, ts) / 2, text_top_for_center(bh / 2, ts), ts, ORANGE);
    plain_text();
    int rects[2][4] = {{0, 0, kb.w, bh}, {0, kb.h - bh, kb.w, bh}};
    Psyz_VideoSetOverlay(kb.px, kb.w, kb.h, &rects[0][0], 2);
}

/* Photo mode's banner of buttons along the bottom (an overlay; none with show 0) */
static int tl_on, tl_playing;
static float tl_frac, tl_back;
void photo_timeline(int on, float frac, float back_s, int playing) /* photo.c: the rewind's timeline (drawn with the legend) */
{
    tl_on = on; tl_frac = frac < 0 ? 0 : frac > 1 ? 1 : frac; tl_back = back_s; tl_playing = playing;
}
void photo_legend(int show)
{
    static Image pl;
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (!show || size.w <= 0 || size.h <= 0 || !text_ready() || !image_resize(&pl, size.w, size.h)) {
        Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
        return;
    }
    static const uint8_t panel[3] = {8, 8, 10}, line[3] = {188, 188, 196};
    memset(pl.px, 0, (size_t)pl.w * pl.h * 3);
    View v = view_fit(&pl);
    int bx = 20, bw = 600, by = tl_on ? 418 : 446, bh = tl_on ? 54 : 26;
    draw_fill(&pl, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), panel, 255);
    draw_fill(&pl, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, 1.5f) > 1 ? S(&v, 1.5f) : 1, line, 255);
    lettering();
    if (tl_on) { /* the rewind's timeline: the last 30 seconds, the moment shown marked */
        static const uint8_t track[3] = {60, 60, 66}, fill[3] = {176, 94, 34}, mark[3] = {238, 164, 74};
        int ls = S(&v, 10), ty = text_top_for_center(Y(&v, by + 14), ls);
        /* (a button's picture only at an item's start: one item each) */
        const char *hint[2] = {tl_playing == 1 ? CROSS " STOP" : "L2 R2: TIME",
                               tl_playing == 1 ? CIRCLE " BACK" : tl_playing == 2 ? CROSS " GO THERE" : CROSS " PLAY"}; /* (2: the mark moved) */
        int hx = X(&v, bx + 12);
        for (int k = 0; k < 2; k++) hx += legend_text(&v, hint[k], hx, ty, ls, 1) + S(&v, 14);
        char when[32];
        if (tl_back < 0.05f) snprintf(when, sizeof when, "LIVE");
        else snprintf(when, sizeof when, "-%.1f S", tl_back);
        text_draw(&pl, when, X(&v, bx + bw - 12) - text_width(when, ls), ty, ls, COPPER);
        int tx = X(&v, bx + 200), tw = X(&v, bx + bw - 70) - tx, th = S(&v, 4) > 2 ? S(&v, 4) : 2, tyb = Y(&v, by + 14) - th / 2;
        draw_fill(&pl, tx, tyb, tw, th, track, 255);
        draw_fill(&pl, tx, tyb, (int)(tw * tl_frac), th, fill, 255);
        int mw = S(&v, 3) > 2 ? S(&v, 3) : 2, mh = S(&v, 14);
        draw_fill(&pl, tx + (int)(tw * tl_frac) - mw / 2, Y(&v, by + 14) - mh / 2, mw, mh, mark, 255);
        by += 28; bh = 26; /* the buttons under it */
    }
    const char *const items[] = {"PHOTO MODE", "L1 R1: DOWN, UP", /* (the sticks: self-explanatory) */
                                 SQUARE " PICTURE", TRIANGLE " HIDE", CIRCLE " BACK"};
    enum { ITEMS = 5, FIRST_GLYPH = 2 };
    int ls = S(&v, 10), ty = text_top_for_center(Y(&v, by + bh / 2), ls), gap = S(&v, 14), glyph = S(&v, 10), total = 0;
    for (int k = 0; k < ITEMS; k++) total += text_width(items[k], ls) + (k ? gap : 0) + (k >= FIRST_GLYPH ? glyph : 0); /* (a button's picture: wider) */
    int x = X(&v, bx) + (S(&v, bw) - total) / 2; /* spread evenly, measured */
    for (int k = 0; k < ITEMS; k++) {
        if (k == 0) text_draw(&pl, items[0], x, ty, ls, COPPER);
        else legend_text(&v, items[k], x, ty, ls, 1);
        x += text_width(items[k], ls) + gap + (k >= FIRST_GLYPH ? glyph : 0);
    }
    plain_text();
    if (tl_on) { by -= 28; bh += 28; }
    int rect[4] = {X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh)};
    Psyz_VideoSetOverlay(pl.px, pl.w, pl.h, rect, 1);
}

/* In a battle, while the button is held: the scoreboard over the game (the overlay). The
 * thin split lines (vplus/hud_layout.c) share the overlay: drawn into it while it is ours. */
void hudlay_overlay_ui(int on);
int hudlay_divider_rects(int w, int h, int r[2][4]);
int vp_watching(int player);
static void overlay_with_lines(Image *sb, int *rect, int n) /* our rects, and the split lines */
{
    static const uint8_t black[3] = {0, 0, 0};
    int all[8][4], k = 0, lines[2][4];
    for (int i = 0; i < n && k < 6; i++) memcpy(all[k++], rect + 4 * i, sizeof all[0]);
    int nl = hudlay_divider_rects(sb->w, sb->h, lines);
    for (int i = 0; i < nl; i++) { draw_fill(sb, lines[i][0], lines[i][1], lines[i][2], lines[i][3], black, 255); memcpy(all[k++], lines[i], sizeof all[0]); }
    hudlay_overlay_ui(1);
    Psyz_VideoSetOverlay(sb->px, sb->w, sb->h, &all[0][0], k);
}
/* ---- online, in a match: the Players menu and the kick vote's note ----
 * Online nobody pauses everyone (Start never reaches the game), so a player's Start opens the Players menu over the
 * game, which goes on; that player's car is still meanwhile (ui_net_menu_holds). It lists every player of the match
 * (name, car, host, muted, talking), Up and Down, X on another player: Mute / Unmute and Vote to kick (the host: Kick).
 * A kick vote running: a note at the side for everyone (the game not interrupted) and its YES / NO at the menu's top.
 * O backs out, Start closes. */
extern int killcam_replaying; /* vplus/killcam.c */
enum { PM_ROWS = 16 };
static int pm_open = -1;              /* this PC's player (slot) whose menu is open, -1 none */
static int pm_sel, pm_sub = -1, pm_sub_sel; /* the row; the player whose actions are open (human), its action */
static uint16_t pm_prev[4];
static int pm_voted = -1;             /* the machine whose kick vote this PC answered (-1: none running) */
/* Start opens the pause menu's items over the running game (the user's 2026-11-07: as local play's, Photo Mode as
 * PLAYERS, and the game never stops): RESUME, OPTIONS (the pages beside the match, mf_open), PLAYERS (the list below:
 * O back to these), QUIT (sure? then this machine leaves the match: a computer driver takes the car) */
static const char *const np_items[4] = {"RESUME", "OPTIONS", "PLAYERS", "QUIT"};
static int np_on, np_sel, np_sure, np_sure_sel; /* the menu shown (else the Players list), its row; QUIT's question */
static int net_quit_asked;            /* QUIT chosen: the battle quits at the next step (net/game_tm2.c, ui_net_quit_take) */
static int net_quit_leaving;          /* (then) the menus leave the server for the title (ui_ScrollText) */
int ui_net_quit_take(void) { int q = net_quit_asked; net_quit_asked = 0; if (q) net_quit_leaving = 1; return q; }
int ui_net_menu_holds(int slot) { return (pm_open >= 0 && pm_open == slot) || (mf_slot >= 0 && mf_slot == slot); }
static void net_pause_reopen(int slot) { pm_open = slot; np_on = 1; np_sure = 0; pm_sub = -1; pm_prev[slot & 3] = 0xFFFF; }
unsigned ui_net_muted(void) { return net_mute_node; }            /* (net/game_tm2.c: voices dropped) */
int ui_net_voice_on(void) { return net_in_server && net_server.voice; }
static int pm_humans(int8_t node_of[16])
{
    Lobby *l = netplay_lobby();
    if (!l) return 0;
    const LobbyView *v = lobby_view(l);
    int n = v->start.humans > 16 ? 16 : v->start.humans;
    for (int h = 0; h < 16; h++) node_of[h] = -1;
    for (int k = 0; k < SES_MAX_NODES; k++)
        for (int i = 0; v->start.first[k] != 0xFF && i < v->m[k].count && v->start.first[k] + i < 16; i++)
            node_of[v->start.first[k] + i] = (int8_t)k;
    return n;
}
static int pm_vote(int *target, int *yes, int *needed) /* a kick vote running (not about this PC, not answered yet) */
{
    Lobby *l = netplay_lobby();
    int state;
    uint32_t at;
    if (!l || !lobby_kick_progress(l, target, yes, needed, &state, &at) || state != SES_KICK_RUNNING) { pm_voted = -1; return 0; }
    (void)at;
    return *target != lobby_node(l) && *target != pm_voted && lobby_view(l)->m[*target].count; /* (not about this PC) */
}
static const char *pm_node_name(int node)
{
    Lobby *l = netplay_lobby();
    const LobbyView *v = l ? lobby_view(l) : NULL;
    return v && node >= 0 && node < SES_MAX_NODES && v->m[node].count ? v->m[node].p[0].name : "A PLAYER";
}
static void pm_input(void)
{
    uint16_t input_player_menu_buttons(int p);
    Lobby *l = netplay_lobby();
    int local = humans_local_count();
    if (local < 1) local = 1;
    int8_t node_of[16];
    int n = pm_humans(node_of), target, yes, needed, vote = pm_vote(&target, &yes, &needed);
    for (int p = 0; p < local && p < 4; p++) {
        uint16_t b = (uint16_t)(input_player_menu_buttons(p) | (p == 0 ? net_test_menu_buttons() : 0)), pressed = (uint16_t)(b & ~pm_prev[p]);
        pm_prev[p] = b;
        static const char *test_at;
        static int test_read;
        if (!test_read) { test_read = 1; test_at = getenv("TM2PC_NET_TEST_MENU_AT"); } /* tests: the menu opens then */
        if (test_at && p == 0 && pm_open < 0 && M.vblanks >= strtoull(test_at, NULL, 10)) { test_at = NULL; pressed = B_START; }
        if (pm_open < 0) {
            if (pressed & B_START) { /* the menu (a kick vote running: the Players list at once, to vote) */
                pm_open = p; pm_sel = 0; pm_sub = -1; np_on = !vote; np_sel = 0; np_sure = 0;
                menu_sound(1);
                fprintf(stderr, "%s menu: open\n", np_on ? "online" : "players");
            }
            continue;
        }
        if (p != pm_open) continue;
        int rows = n + (vote ? 1 : 0);
        if (pressed & B_START) { pm_open = -1; np_on = 0; menu_sound(0); continue; }
        if (np_on) { /* the menu's items */
            if (np_sure) { /* QUIT: sure? (YES on top, NO highlighted, as the tournament's) */
                if (pressed & (B_UP | B_DOWN)) { np_sure_sel = !np_sure_sel; menu_sound(0); }
                if (pressed & B_CIRCLE) { np_sure = 0; menu_sound(0); }
                if (pressed & B_CROSS) {
                    menu_sound(1);
                    if (np_sure_sel == 0) {
                        net_quit_asked = 1;
                        pm_open = -1; np_on = np_sure = 0;
                        fprintf(stderr, "online menu: quit the match\n");
                    } else np_sure = 0;
                }
                continue;
            }
            if (pressed & B_UP) { np_sel = (np_sel + 3) % 4; menu_sound(0); }
            if (pressed & B_DOWN) { np_sel = (np_sel + 1) % 4; menu_sound(0); }
            if (pressed & B_CIRCLE) { pm_open = -1; np_on = 0; menu_sound(0); continue; }
            if (pressed & B_CROSS) {
                menu_sound(1);
                if (np_sel == 0) { pm_open = -1; np_on = 0; }
                else if (np_sel == 1) { /* the pages beside the match (their own picture over it) */
                    if (mf_open(p)) { pm_open = -1; np_on = 0; }
                } else if (np_sel == 2) { np_on = 0; pm_sel = 0; pm_sub = -1; }
                else { np_sure = 1; np_sure_sel = 1; }
            }
            continue;
        }
        if (pm_sub >= 0) { /* a player's actions */
            if (pressed & (B_UP | B_DOWN)) { pm_sub_sel = !pm_sub_sel; menu_sound(0); }
            if (pressed & B_CIRCLE) { pm_sub = -1; menu_sound(0); }
            if (pressed & B_CROSS) {
                int node = node_of[pm_sub];
                if (pm_sub_sel == 0) {
                    net_mute_node ^= 1u << node;
                    fprintf(stderr, "players menu: %s %s\n", (net_mute_node >> node) & 1 ? "muted" : "unmuted", pm_node_name(node));
                } else if (l && lobby_is_host(l)) {
                    lobby_kick(l, node);
                    fprintf(stderr, "players menu: kicked %s\n", pm_node_name(node));
                } else if (l) {
                    lobby_kick_vote(l, node);
                    fprintf(stderr, "players menu: a vote to kick %s\n", pm_node_name(node));
                }
                menu_sound(1);
                pm_sub = -1;
            }
            continue;
        }
        if (pressed & B_UP) { pm_sel = (pm_sel + rows - 1) % (rows ? rows : 1); menu_sound(0); }
        if (pressed & B_DOWN) { pm_sel = (pm_sel + 1) % (rows ? rows : 1); menu_sound(0); }
        if (pressed & B_CIRCLE) { np_on = 1; menu_sound(0); continue; } /* (back to the menu) */
        if (vote && pm_sel == 0 && (pressed & (B_LEFT | B_RIGHT))) { pm_sub_sel = !pm_sub_sel; menu_sound(0); }
        if (pressed & B_CROSS) {
            if (vote && pm_sel == 0) { /* the vote: YES (this machine's vote) or NO (left at that) */
                if (pm_sub_sel == 0 && l) lobby_kick_vote(l, target);
                fprintf(stderr, "players menu: voted %s on kicking %s\n", pm_sub_sel == 0 ? "yes" : "no", pm_node_name(target));
                pm_voted = target;
                pm_sub_sel = 0;
                pm_sel = 0;
                menu_sound(1);
                continue;
            }
            int h = pm_sel - (vote ? 1 : 0);
            if (h >= 0 && h < n && node_of[h] >= 0 && node_of[h] != lobby_node(l)) { pm_sub = h; pm_sub_sel = 0; menu_sound(1); }
        }
    }
}
/* the menu (or the vote's note) over the game: 1 if this drew (or keeps) the overlay */
static int pm_frame(Image *sb, int *shown)
{
    if (mf_slot >= 0) { /* the Options pages beside the match: their own picture, nothing over it */
        if (*shown == 2) { Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0); hudlay_overlay_ui(0); }
        *shown = 0;
        return 1;
    }
    if (!netplay_in_match() || !feats_in_battle() || killcam_replaying) {
        pm_open = -1;
        return 0;
    }
    pm_input();
    static const char *kick_at; /* tests: TM2PC_NET_TEST_KICKVOTE_AT, the host starts a vote to kick the last machine then */
    static int kick_read;
    if (!kick_read) { kick_read = 1; kick_at = getenv("TM2PC_NET_TEST_KICKVOTE_AT"); }
    if (kick_at && M.vblanks >= strtoull(kick_at, NULL, 10) && netplay_lobby() && lobby_is_host(netplay_lobby())) {
        kick_at = NULL;
        int last = -1;
        for (int k = 0; k < SES_MAX_NODES; k++) if (lobby_view(netplay_lobby())->m[k].present && k != lobby_node(netplay_lobby())) last = k;
        if (last >= 0) lobby_kick_vote(netplay_lobby(), last);
    }
    int target = -1, yes = 0, needed = 0, vote = pm_vote(&target, &yes, &needed);
    unsigned talking = 0; /* (the machines talking now, this PC's too) */
    for (int k = 0; k < SES_MAX_NODES && netplay_lobby(); k++) if (voice_io_talking(netplay_lobby(), k)) talking |= 1u << k;
    if (pm_open < 0 && !vote && !talking) return 0;
    int8_t node_of[16];
    int n = pm_humans(node_of);
    Lobby *l = netplay_lobby();
    PsyzSize size = Psyz_VideoGetDisplaySize();
    uint32_t key = 2166136261u;
#define PM_MIX(x) (key = (key ^ (uint32_t)(x)) * 16777619u)
    PM_MIX(size.w); PM_MIX(size.h); PM_MIX(pm_open); PM_MIX(pm_sel); PM_MIX(pm_sub); PM_MIX(pm_sub_sel); PM_MIX(net_mute_node);
    PM_MIX(vote); PM_MIX(target); PM_MIX(yes); PM_MIX(needed); PM_MIX(n); PM_MIX(talking); PM_MIX(0x5A11);
    PM_MIX(np_on); PM_MIX(np_sel); PM_MIX(np_sure); PM_MIX(np_sure_sel);
#undef PM_MIX
    static uint32_t shown_key;
    if (*shown == 2 && key == shown_key) return 1;
    if (size.w <= 0 || size.h <= 0 || !image_resize(sb, size.w, size.h)) return 1;
    memset(sb->px, 0, (size_t)sb->w * sb->h * 3);
    View v = view_fit(sb);
    static const uint8_t panel[3] = {10, 10, 14}, line[3] = {188, 188, 196};
    int rect[8], nr = 0;
    char text[96];
    static const uint8_t mic_on[3] = {120, 220, 120};
    if (pm_open < 0 && talking) { /* who is talking: a note each at the side, under the kill feed (and the vote's) */
        float bx = 470, by = vote ? 148 : 96, bw = 160, bh = 18;
        for (int k = 0; k < SES_MAX_NODES && nr < 2; k++) {
            if (!((talking >> k) & 1)) continue;
            draw_fill(sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), panel, 255);
            draw_mic(&v, X(&v, bx + 5), Y(&v, by + 2), S(&v, 14), mic_on, 0);
            int ls = S(&v, 10);
            snprintf(text, sizeof text, "%s", k == lobby_node(l) ? "YOU" : pm_node_name(k));
            upper(text);
            text_draw(sb, text, X(&v, bx + 20), text_top_for_center(Y(&v, by + bh / 2), ls), ls, WHITE);
            by += bh + 3;
        }
        int talkers = 0; /* (their notes: one overlay piece, from the first to the last) */
        for (int k = 0; k < SES_MAX_NODES; k++) talkers += (talking >> k) & 1;
        float top = vote ? 148 : 96;
        rect[4 * nr] = X(&v, bx), rect[4 * nr + 1] = Y(&v, top), rect[4 * nr + 2] = S(&v, bw), rect[4 * nr + 3] = S(&v, (bh + 3) * talkers);
        nr++;
    }
    if (pm_open < 0 && vote) { /* the vote's note: at the side, under the kill feed; START (the menu) to vote */
        float bx = 420, by = 96, bw = 210, bh = 46;
        draw_fill(sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), panel, 255);
        draw_fill(sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, 1.5f) > 1 ? S(&v, 1.5f) : 1, line, 255);
        int ls = S(&v, 11);
        snprintf(text, sizeof text, "VOTE TO KICK %s (%d/%d)", pm_node_name(target), yes, needed);
        upper(text);
        text_draw(sb, text, X(&v, bx + 8), text_top_for_center(Y(&v, by + 15), ls), ls, COPPER);
        text_draw(sb, "START: VOTE", X(&v, bx + 8), text_top_for_center(Y(&v, by + 33), ls), ls, WHITE); /* (Start: the list at once) */
        rect[4 * nr] = X(&v, bx), rect[4 * nr + 1] = Y(&v, by), rect[4 * nr + 2] = S(&v, bw), rect[4 * nr + 3] = S(&v, bh);
        nr++;
    } else if (pm_open >= 0 && np_on) { /* the online menu: the pause menu's items (or QUIT's question) */
        int items = np_sure ? 2 : 4;
        float bx = 220, bw = 200, rh = 24, bh = 56 + rh * (float)items, by = 240 - bh / 2;
        draw_fill(sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), panel, 255);
        draw_fill(sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, 1.5f) > 1 ? S(&v, 1.5f) : 1, line, 255);
        lettering();
        int ts = S(&v, 16), ls = S(&v, 14);
        const char *title = np_sure ? "QUIT THE MATCH?" : "MENU";
        text_draw(sb, title, X(&v, 320) - text_width(title, ts) / 2, text_top_for_center(Y(&v, by + 20), ts), ts, TITLE);
        static const char *const yn[2] = {"YES", "NO"};
        for (int k = 0; k < items; k++) {
            const char *it = np_sure ? yn[k] : np_items[k];
            int chosen = np_sure ? np_sure_sel == k : np_sel == k, cy = Y(&v, by + 48 + rh * (k + 0.5f));
            if (chosen) draw_bar(&v, X(&v, bx + 10), X(&v, bx + bw - 10), cy, ls);
            text_draw(sb, it, X(&v, 320) - text_width(it, ls) / 2, text_top_for_center(cy, ls), ls, chosen ? WHITE : PALE);
        }
        plain_text();
        rect[4 * nr] = X(&v, bx), rect[4 * nr + 1] = Y(&v, by), rect[4 * nr + 2] = S(&v, bw), rect[4 * nr + 3] = S(&v, bh);
        nr++;
    } else if (pm_open >= 0) { /* the Players list */
        int rows = n + (vote ? 1 : 0);
        float bx = 110, bw = 420, rh = 22, bh = 52 + rh * (float)rows + (pm_sub >= 0 ? 0 : 0), by = 240 - bh / 2;
        draw_fill(sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), panel, 255);
        draw_fill(sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, 1.5f) > 1 ? S(&v, 1.5f) : 1, line, 255);
        lettering();
        int ts = S(&v, 18);
        text_draw(sb, "PLAYERS", X(&v, 320) - text_width("PLAYERS", ts) / 2, text_top_for_center(Y(&v, by + 18), ts), ts, TITLE);
        plain_text();
        int ls = S(&v, 12);
        float y = by + 42;
        if (vote) { /* the vote, first */
            snprintf(text, sizeof text, "KICK %s? (%d/%d)", pm_node_name(target), yes, needed);
            upper(text);
            int cy = Y(&v, y + rh / 2);
            if (pm_sel == 0) draw_bar(&v, X(&v, bx + 6), X(&v, bx + bw - 6), cy, ls);
            text_draw(sb, text, X(&v, bx + 14), text_top_for_center(cy, ls), ls, COPPER);
            const char *yn[2] = {"YES", "NO"};
            for (int k = 0; k < 2; k++) {
                int x = X(&v, bx + bw - 120 + 56 * k);
                text_draw(sb, yn[k], x, text_top_for_center(cy, ls), ls, pm_sel == 0 && pm_sub_sel == k ? ORANGE : GRAY);
            }
            y += rh;
        }
        for (int h = 0; h < n; h++, y += rh) {
            int row = h + (vote ? 1 : 0), node = node_of[h], cy = Y(&v, y + rh / 2);
            const LobbyView *lv = l ? lobby_view(l) : NULL;
            if (row == pm_sel && pm_sub < 0) draw_bar(&v, X(&v, bx + 6), X(&v, bx + bw - 6), cy, ls);
            snprintf(text, sizeof text, "%s", match_human_name(h));
            upper(text);
            int gone = node < 0 || !lv || !lv->m[node].present;
            text_draw(sb, text, X(&v, bx + 14), text_top_for_center(cy, ls), ls, gone ? GRAY : WHITE);
            int car = lv ? lv->start.car[h] : -1;
            snprintf(text, sizeof text, "%s", car >= 0 ? profile_character_name(car) : "");
            upper(text);
            text_draw(sb, text, X(&v, bx + 170), text_top_for_center(cy, ls), ls, PALE);
            const char *tag = gone ? "LEFT" : node == lobby_host_node(l) ? "HOST" : "";
            if (node == lobby_node(l)) tag = node == lobby_host_node(l) ? "YOU, HOST" : "YOU";
            if (!gone && node >= 0 && (net_mute_node >> node) & 1) tag = "MUTED";
            text_draw(sb, tag, X(&v, bx + 300), text_top_for_center(cy, ls), ls, COPPER);
            if (!gone && node >= 0 && ((talking >> node) & 1)) draw_mic(&v, X(&v, bx + 278), Y(&v, y + rh / 2 - 7), S(&v, 14), mic_on, 0); /* (talking) */
            if (pm_sub == h) { /* its actions, beside it */
                const char *acts[2] = {(net_mute_node >> node) & 1 ? "UNMUTE" : "MUTE", lobby_is_host(l) ? "KICK" : "VOTE TO KICK"};
                for (int k = 0; k < 2; k++) {
                    int ay = Y(&v, y + rh / 2 + (k ? rh * 0.5f : -rh * 0.5f) + 2);
                    text_draw(sb, acts[k], X(&v, bx + bw - 120), text_top_for_center(ay, S(&v, 10)), S(&v, 10),
                              pm_sub_sel == k ? ORANGE : GRAY);
                }
            }
        }
        rect[4 * nr] = X(&v, bx), rect[4 * nr + 1] = Y(&v, by), rect[4 * nr + 2] = S(&v, bw), rect[4 * nr + 3] = S(&v, bh);
        nr++;
    }
    overlay_with_lines(sb, rect, nr);
    static int shot;
    if (getenv("TM2PC_NET_MENU_SHOT") && shot < 4 && key != shown_key) { /* tests: the first few looks, as BMPs */
        char path[512];
        snprintf(path, sizeof path, "%s/players_%d.bmp", getenv("TM2PC_NET_MENU_SHOT"), shot++);
        image_save_bmp(sb, path);
    }
    *shown = 2;
    shown_key = key;
    return 1;
}
/* the scoreboard (held, and on the results) only in Challenge Matches (and online): not in the tournament, Survival or
 * a custom tournament, which are the story, as the game's */
static int scoreboard_allowed(void) { return battle_live && !survival_on && !trun.on; }
static int battle_overlay_dropped; /* battle_overlay_off: the overlay taken away by a page or a line-up */
/* the battle's overlay (the spectate legend, the scoreboard) away: a port page or a line-up after the battle drew under
 * it (the legend over the line-up and Save Tournament, the user's co-op take 2026-11-17); scoreboard_frame draws it
 * again when its battle is on */
static void battle_overlay_off(void)
{
    Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
    hudlay_overlay_ui(0);
    battle_overlay_dropped = 1;
}
/* ---- Escape: "QUIT OPENTM2?" over whatever is shown (N4h's suggestion, Phoenix's report 2026-11-22: a stray Escape
 * closed the game at once). runtime/gpu_psyz.c opens it and asks each VBlank; the game goes on under it (online
 * too: nobody is held). Its own keys: Up / Down / Left / Right, Enter or Y (YES), Escape or N (NO); meanwhile the
 * keyboard is not the game's or the menus' (input_keys_off). NO is chosen first. */
extern int input_keys_off, input_pads_off; /* runtime/input.c */
uint16_t input_pad_buttons_raw(void);
static int qp_open, qp_sel, qp_drawn;
static bool qp_prev[SDL_SCANCODE_COUNT];
static uint16_t qp_pad_prev; /* (the controllers too: D-pad / stick, Cross picks, Circle no; Tegu's, no keyboard) */
void ui_quit_ask(void)
{
    if (qp_open) return;
    const bool *k = SDL_GetKeyboardState(NULL);
    if (k) memcpy(qp_prev, k, sizeof qp_prev); /* (the Escape that opened it, still held, is not an answer) */
    qp_pad_prev = input_pad_buttons_raw(); /* (the button that opened it, still held, is not an answer) */
    qp_open = 1, qp_sel = 1, qp_drawn = 0;
    input_keys_off = 1;
    input_pads_off = 1;
    menu_sound(1);
    fprintf(stderr, "escape: asking to quit\n");
}
static void qp_close(void)
{
    qp_open = 0;
    input_keys_off = 0;
    input_pads_off = 0;
    battle_overlay_off(); /* (the battle's overlay drawn again by scoreboard_frame) */
}
int ui_quit_frame(void) /* 1: quit now */
{
    if (!qp_open) return 0;
    const bool *k = SDL_GetKeyboardState(NULL);
    if (!k) return 0;
#define QP_HIT(sc) (k[sc] && !qp_prev[sc])
    int yes = QP_HIT(SDL_SCANCODE_Y), no = QP_HIT(SDL_SCANCODE_N) || QP_HIT(SDL_SCANCODE_ESCAPE);
    int pick = QP_HIT(SDL_SCANCODE_RETURN) || QP_HIT(SDL_SCANCODE_KP_ENTER) || QP_HIT(SDL_SCANCODE_SPACE);
    int move = QP_HIT(SDL_SCANCODE_UP) || QP_HIT(SDL_SCANCODE_DOWN) || QP_HIT(SDL_SCANCODE_LEFT) || QP_HIT(SDL_SCANCODE_RIGHT);
#undef QP_HIT
    memcpy(qp_prev, k, sizeof qp_prev);
    uint16_t pad = input_pad_buttons_raw(), pad_hit = (uint16_t)(pad & ~qp_pad_prev);
    qp_pad_prev = pad;
    if (pad_hit & (B_UP | B_DOWN | B_LEFT | B_RIGHT)) move = 1;
    if (pad_hit & B_CROSS) pick = 1;
    if (pad_hit & B_CIRCLE) no = 1;
    if (move) { qp_sel = !qp_sel; qp_drawn = 0; menu_sound(0); }
    if (yes || (pick && qp_sel == 0)) {
        fprintf(stderr, "escape: quit\n");
        return 1;
    }
    if (no || pick) {
        menu_sound(0);
        qp_close();
        fprintf(stderr, "escape: not quitting\n");
        return 0;
    }
    if (qp_drawn) return 0;
    static Image qb;
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (size.w <= 0 || size.h <= 0 || !image_resize(&qb, size.w, size.h)) return 0;
    memset(qb.px, 0, (size_t)qb.w * qb.h * 3);
    View v = view_fit(&qb);
    static const uint8_t panel[3] = {10, 10, 14}, line[3] = {188, 188, 196};
    /* a small box: the question, then YES and NO side by side (Left / Right), a thin frame all around */
    float bw = 176, bh = 74, bx = 320 - bw / 2, by = 240 - bh / 2;
    int th = S(&v, 1) > 1 ? S(&v, 1) : 1;
    draw_fill(&qb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), line, 255);
    draw_fill(&qb, X(&v, bx) + th, Y(&v, by) + th, S(&v, bw) - 2 * th, S(&v, bh) - 2 * th, panel, 255);
    lettering();
    int ts = S(&v, 15), ls = S(&v, 13);
    const char *title = "QUIT OPENTM2?";
    text_draw(&qb, title, X(&v, 320) - text_width(title, ts) / 2, text_top_for_center(Y(&v, by + 24), ts), ts, TITLE);
    static const char *const yn[2] = {"YES", "NO"};
    int half = text_width("YES", ls) / 2 + S(&v, 9), cy = Y(&v, by + 52); /* (the bar about the word, the same for both) */
    for (int i = 0; i < 2; i++) {
        int cx = X(&v, i ? 320 + 36 : 320 - 36);
        if (qp_sel == i) draw_bar(&v, cx - half, cx + half, cy, ls);
        text_draw(&qb, yn[i], cx - text_width(yn[i], ls) / 2, text_top_for_center(cy, ls), ls, qp_sel == i ? WHITE : PALE);
    }
    plain_text();
    int rect[4] = {X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh)};
    hudlay_overlay_ui(1);
    Psyz_VideoSetOverlay(qb.px, qb.w, qb.h, rect, 1);
    if (getenv("TM2PC_QUIT_SHOT")) image_save_bmp(&qb, getenv("TM2PC_QUIT_SHOT")); /* tests: the box, as a BMP */
    qp_drawn = 1;
    return 0;
}

static void scoreboard_frame(void)
{
    static int shown;
    static Image sb;
    if (qp_open) { shown = 0; return; } /* (Escape's question has the overlay) */
    if (battle_overlay_dropped) { battle_overlay_dropped = 0; shown = 0; }
    if (pm_frame(&sb, &shown)) return; /* (online: the Players menu, a kick vote's note) */
    if (shown == 2) { Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0); shown = 0; hudlay_overlay_ui(0); }
    int live = feats_in_battle() && !in_pause && (M.live_input || script) && text_ready();
    /* a Versus Tournament (a custom tournament, so no match scoreboard): held, its standings so far (the user's 2026-11-08) */
    int vs_board = live && trun.versus && battle_live && versus_podium != 2 && input_scoreboard_held();
    if (vs_board) {
        if (shown == 3) return; /* (the standings change only between rounds: drawn once while held) */
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w <= 0 || size.h <= 0 || !image_resize(&sb, size.w, size.h)) return;
        memset(sb.px, 0, (size_t)sb.w * sb.h * 3);
        View v = view_fit(&sb);
        VsRow r[32];
        int n = vs_rows(r, 32), pitch = n > 12 ? 17 : n > 10 ? 21 : 26;
        float y0 = 84, y1 = 140 + 8 + (n - 0.5f) * pitch + 10, x0 = 60, x1 = 580;
        static const uint8_t panel[3] = {8, 8, 10};
        draw_fill(&sb, X(&v, x0), Y(&v, y0), S(&v, x1 - x0), S(&v, y1 - y0), panel, 255);
        lettering();
        uint64_t keep = versus_anim_at;
        versus_anim_at = 0; /* (the standings settled: no count, no slide) */
        vs_live_board = 1; /* (the players out of this stage grayed) */
        draw_versus_standings(&v);
        vs_live_board = 0;
        versus_anim_at = keep;
        plain_text();
        int rect[4] = {X(&v, x0), Y(&v, y0), S(&v, x1 - x0), S(&v, y1 - y0)};
        overlay_with_lines(&sb, rect, 1);
        if (getenv("TM2PC_NET_MENU_SHOT")) { /* tests: the standings, as a BMP */
            char path[512];
            snprintf(path, sizeof path, "%s/versus_board.bmp", getenv("TM2PC_NET_MENU_SHOT"));
            image_save_bmp(&sb, path);
        }
        shown = 3;
        return;
    }
    if (shown == 3) { Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0); shown = 0; hudlay_overlay_ui(0); }
    int want = live && match_cars() > 0 && input_scoreboard_held() && scoreboard_allowed();
    int wm[4], any_wm = 0;
    for (int p = 0; p < 4; p++) any_wm |= wm[p] = !want && live ? vp_watching(p) : 0;
    if (!want && live && (vp_spectating() || any_wm)) { /* out of lives: a banner while the others play on */
        PsyzSize size = Psyz_VideoGetDisplaySize();
        int netplay_watching(void); /* net/game_tm2.c: in to watch the match on, playing from the next one */
        int watching = netplay_watching() && vp_spectating();
        int key = 1000 + (wm[0] + 1) * 10 + (wm[1] + 1) + 100 * vp_spectating() + 1000 * (wm[2] + 3 * wm[3]) + 100000 * watching;
        if (shown == key || size.w <= 0 || size.h <= 0 || !image_resize(&sb, size.w, size.h)) return;
        static const uint8_t panel[3] = {8, 8, 10}, line[3] = {188, 188, 196};
        memset(sb.px, 0, (size_t)sb.w * sb.h * 3);
        View v = view_fit(&sb);
        int rect[16], nr = 0;
        int four_view_box(int p, float *x, float *y, float *w, float *h); /* vplus/four.c: 3-4 players' views */
        for (int b = 0; b < 5 && nr < 4; b++) { /* the whole screen (1 player), or each watching player's view */
            int wp = b - 1, mode = wp < 0 ? (any_wm ? 0 : vp_spectating() + 1) : wm[wp] ? wm[wp] + 1 : 0;
            if (!mode) continue; /* (2 the chase camera, 3 cinematic) */
            /* along the bottom of the view */
            float bx = 40, bw = 560, by = 452, bh = 24, s = 1, vx, vy, vw, vh;
            float wide = wide_k(); /* widescreen battles: the views as wide as the window (the 640 units' 4:3 middle grown by k) */
            if (wp >= 0 && four_view_box(wp, &vx, &vy, &vw, &vh)) { /* 3-4 players: its view's bottom, centered in it (player
                                                                    * 4's was pulled toward the middle, the user's 2026-11-04) */
                vx = 320 + (vx - 320) * wide;
                vw *= wide;
                bw = vw - 20 < 560 ? vw - 20 : 560;
                s = bw / 560;
                bx = vx + (vw - bw) / 2;
                bh = 24 * s;
                by = vy + vh - bh - 4;
            } else if (wp >= 0 && (humans_local_count() < 0 ? play_players == 2 : humans_local_count() == 2)) { /* 2 views: its
                                                                                       * half (one view, online: the whole screen's bottom) */
                int vert = mem_r32(&M.cpu, GA(0x801809E4u)) == 1;
                if (vert) { /* centered in its half (widescreen: the half k times as wide) */
                    bw = 300 * wide < 560 ? 300 * wide : 560;
                    bx = 320 + ((wp ? 480 : 160) - 320) * wide - bw / 2;
                    s = bw / 560;
                }
                else by = wp ? 452 : 212;
            }
            draw_fill(&sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, bh), panel, 255);
            draw_fill(&sb, X(&v, bx), Y(&v, by), S(&v, bw), S(&v, 1.5f) > 1 ? S(&v, 1.5f) : 1, line, 255);
            lettering();
            const char *legend[5] = {mode == 4 ? "FREECAM" : mode == 3 ? "CINEMATIC" : "SPECTATING",
                                     mode == 4 ? SQUARE " = CINEMATIC" : mode == 3 && wp < 0 ? SQUARE " = FREECAM" : mode == 3 ? SQUARE " = NEW CAR"
                                               : CROSS " = NEXT",
                                     mode >= 3 ? CROSS " = CHASE CAM" : CIRCLE " = BACK", mode >= 3 ? "" : SQUARE " = CINEMATIC",
                                     TRIANGLE " = HIDE"};
            int ls = S(&v, 13 * s), ty = text_top_for_center(Y(&v, by + bh / 2), ls);
            /* the title at the left, then the buttons spread evenly over the rest (each measured: equal gaps) */
            int x0 = X(&v, bx + 14 * s), x1 = X(&v, bx + bw - 14 * s);
            text_draw(&sb, legend[0], x0, ty, ls, COPPER);
            int wt = text_width(legend[0], ls), wk[5] = {0}, sum = 0, n = 0;
            for (int k = 1; k < 5; k++) if (legend[k][0]) { wk[k] = legend_text(&v, legend[k], 0, ty, ls, 0); sum += wk[k]; n++; }
            int gap = n ? (x1 - x0 - wt - sum) / n : 0, x = x0 + wt + gap;
            for (int k = 1; k < 5; k++) if (legend[k][0]) { legend_text(&v, legend[k], x, ty, ls, 1); x += wk[k] + gap; }
            plain_text();
            rect[nr * 4] = X(&v, bx), rect[nr * 4 + 1] = Y(&v, by), rect[nr * 4 + 2] = S(&v, bw), rect[nr * 4 + 3] = S(&v, bh);
            nr++;
            if (wp < 0 && watching && nr < 4) { /* in to watch (joined mid-match): when they play, above the banner */
                const char *note = trun.on && trun.versus ? "YOU JOIN THE NEXT STAGE" : "YOU JOIN THE NEXT MATCH";
                float nh = 22, ny = by - nh - 6;
                lettering();
                int ns = S(&v, 12), nw = text_width(note, ns) + S(&v, 28), nx = X(&v, 320) - nw / 2;
                draw_fill(&sb, nx, Y(&v, ny), nw, S(&v, nh), panel, 255);
                draw_fill(&sb, nx, Y(&v, ny), nw, S(&v, 1.5f) > 1 ? S(&v, 1.5f) : 1, line, 255);
                text_draw(&sb, note, nx + S(&v, 14), text_top_for_center(Y(&v, ny + nh / 2), ns), ns, COPPER);
                plain_text();
                rect[nr * 4] = nx, rect[nr * 4 + 1] = Y(&v, ny), rect[nr * 4 + 2] = nw, rect[nr * 4 + 3] = S(&v, nh);
                nr++;
            }
        }
        overlay_with_lines(&sb, rect, nr);
        static int spect_shot;
        if (getenv("TM2PC_NET_MENU_SHOT") && spect_shot < 2) { /* tests: the banner, as BMPs */
            char path[512];
            snprintf(path, sizeof path, "%s/spectate_%d.bmp", getenv("TM2PC_NET_MENU_SHOT"), spect_shot++);
            image_save_bmp(&sb, path);
        }
        shown = key;
        return;
    }
    if (!want) {
        if (shown) { Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0); shown = 0; hudlay_overlay_ui(0); }
        return;
    }
    PsyzSize size = Psyz_VideoGetDisplaySize();
    /* drawn again only when what it shows changes (every frame at a high resolution: the game at 1 FPS behind it) */
    uint32_t key = 2166136261u;
#define SB_MIX(x) (key = (key ^ (uint32_t)(x)) * 16777619u)
    SB_MIX(size.w); SB_MIX(size.h); SB_MIX(match_cars());
    for (int i = 0; i < match_cars(); i++) {
        const MatchCar *m = match_car(i);
        SB_MIX(m->kills); SB_MIX(m->deaths); SB_MIX(m->damage); SB_MIX(m->points); SB_MIX(m->lives); SB_MIX(m->place);
        SB_MIX(m->car);
    }
#undef SB_MIX
    static uint32_t shown_key;
    if (shown == 1 && key == shown_key) return;
    /* at most 4 times a second: a number ticking every step (the Juggernaut's points, the damage) redrew the whole
     * screen-sized picture 20 times a second, the game lagging behind it (the user's 2026-10-30) */
    static Uint64 drawn_at;
    if (shown == 1 && SDL_GetTicks() - drawn_at < 250) return;
    drawn_at = SDL_GetTicks();
    if (size.w <= 0 || size.h <= 0 || !image_resize(&sb, size.w, size.h)) return;
    memset(sb.px, 0, (size_t)sb.w * sb.h * 3);
    View v = view_fit(&sb);
    int hgt = scoreboard_height(60, 420), y = 240 - hgt / 2, x0, x1;
    scoreboard_span(&v, &x0, &x1);
    draw_scoreboard(&v, x0, y, x1, y + hgt, 0);
    int rect[4] = {X(&v, x0), Y(&v, y), S(&v, x1 - x0), S(&v, hgt)};
    overlay_with_lines(&sb, rect, 1);
    static int board_shot;
    if (getenv("TM2PC_NET_MENU_SHOT") && board_shot < 2) { /* tests: the scoreboard, as BMPs */
        char path[512];
        snprintf(path, sizeof path, "%s/scoreboard_%d.bmp", getenv("TM2PC_NET_MENU_SHOT"), board_shot++);
        image_save_bmp(&sb, path);
    }
    shown = 1;
    shown_key = key;
}

static int results_no_choices;      /* the results without REMATCH / EXIT (a server's playlist: the vote comes after) */
enum { NET_SCOREBOARD_MS = 8000 };  /* (a server's playlist: the final scoreboard this long before the vote) */
static void compose_results(Image *c, int sel)
{
    static const uint8_t black[3] = {0, 0, 0};
    /* the backdrop: the battle's last frame, darkened (as the pause menu); made once per frame size and picture, then
     * copied (the standings' count and slide draw every frame: scaling the picture each time was most of the work) */
    static Image bg;
    static unsigned bg_gen = ~0u;
    if (bg.w != c->w || bg.h != c->h || bg_gen != pause_frame_gen) {
        if (!image_resize(&bg, c->w, c->h)) { memset(c->px, 0, (size_t)c->w * c->h * 3); goto backdrop_done; }
        memset(bg.px, 0, (size_t)bg.w * bg.h * 3);
        if (pause_frame.px) {
            int h = bg.h, w = (int)((float)pause_frame.w * h / pause_frame.h + 0.5f);
            if (w > bg.w) { w = bg.w; h = (int)((float)pause_frame.h * w / pause_frame.w + 0.5f); } /* narrower: letterboxed */
            draw_image(&bg, &pause_frame, 0, 0, (float)pause_frame.w, (float)pause_frame.h, (bg.w - w) / 2, (bg.h - h) / 2, w, h, 0);
            draw_fill(&bg, 0, 0, bg.w, bg.h, black, 150);
        }
        bg_gen = pause_frame_gen;
    }
    memcpy(c->px, bg.px, (size_t)c->w * c->h * 3);
backdrop_done:;
    View v = view_fit(c);
    /* the winner: their card, then "<NAME> WINS" */
    lettering();
    int ts = S(&v, 30), tw = text_width(results_title, ts), pw = 96, ph = 48, gap = 14;
    { /* a long title (BOSS ROUND: KRISTA SPARKS VS MIRANDA WATTS) smaller, to fit the screen with its card (the user's) */
        int room = S(&v, 620 - (results_winner || (trun.versus && versus_final_on()) ? pw + gap : 0));
        if (tw > room) ts = ts * room / tw, tw = text_width(results_title, ts);
    }
    const MatchCar *card = results_winner;
    MatchCar champ;
    if (trun.versus && versus_final_on()) { /* the final: the champion with their own car (the last round's winner could
                                             * be someone else, or the boss: the user's 2026-11-07) */
        memset(&champ, 0, sizeof champ);
        if (versus_champion >= 0) {
            champ.human = versus_champion, champ.ai = -1, champ.car = trun.car[versus_champion & 15];
            for (int i = 0; i < match_cars(); i++)
                if (match_car(i)->human == versus_champion) champ = *match_car(i), champ.car = trun.car[versus_champion & 15];
        } else {
            champ.human = -1, champ.ai = versus_champion_ai, champ.car = versus_champion_ai < versus_cpu_n ? versus_cpu[versus_champion_ai] : -1;
        }
        card = &champ;
    }
    int total = (card ? pw + gap : 0) + (int)(tw / v.s), x = 320 - total / 2;
    int ty = !trun.versus && !scoreboard_allowed() ? 120 : 56; /* (no scoreboard (Survival): lower, off the HUD's top line and
                                                              * clock, the user's 2026-11-01; with one: 56, under the
                                                              * HUD's info line, the user's 2026-11-02) */
    if (card) {
        draw_plate(&v, card, X(&v, x), Y(&v, ty - ph / 2), S(&v, pw), S(&v, ph));
        x += pw + gap;
    }
    text_draw(c, results_title, X(&v, x), text_top_for_center(Y(&v, ty), ts), ts,
              trun.versus && versus_final_on() && versus_anim_at && SDL_GetTicks() - versus_anim_at >= VS_SETTLED ? GOLD : TITLE);
    int sx0, sx1;
    scoreboard_span(&v, &sx0, &sx1); /* (wide screens: wider, the names' room) */
    void draw_versus_standings(const View *v);
    if (trun.versus) draw_versus_standings(&v);
    else if (scoreboard_allowed()) draw_scoreboard(&v, sx0 - 10, 86, sx1 + 10, 422, 1); /* (under the title, over REMATCH) */
    else
        for (int i = 0; i < 3; i++) {
            if (!results_lines[i][0]) continue;
            int size = S(&v, 28), w = text_width(results_lines[i], size);
            text_draw(c, results_lines[i], X(&v, 320) - w / 2, text_top_for_center(Y(&v, 190 + i * 50), size), size, WHITE);
        }
    const char *items[2] = {survival_on ? "RETRY" : "REMATCH", survival_on ? "QUIT" : "EXIT"};
    if (results_items[0]) items[0] = results_items[0], items[1] = results_items[1];
    for (int i = 0; i < 2 && items[i] && !results_no_choices; i++) { /* side by side */
        int size = S(&v, 24), cx = X(&v, 240 + i * 160), cy = Y(&v, 444), w = text_width(items[i], size);
        if (i == sel) draw_bar(&v, cx - w / 2 - S(&v, 14), cx + w / 2 + S(&v, 14), cy, size);
        text_draw(c, items[i], cx - w / 2, text_top_for_center(cy, size), size, WHITE);
    }
    plain_text();
    static int results_shot, shot_key = -1;
    if (getenv("TM2PC_NET_MENU_SHOT") && results_shot < 24 && shot_key != (int)(trun.stage * 16 + (sel & 15))) {
        shot_key = (int)(trun.stage * 16 + (sel & 15)); /* tests: the results, as BMPs (one a stage) */
        char path[512];
        snprintf(path, sizeof path, "%s/results_%d.bmp", getenv("TM2PC_NET_MENU_SHOT"), results_shot++);
        image_save_bmp(c, path);
    }
}

/* The playlist's vote over the match's end (the results' place: the battle's last frame, dimmed): each of this machine's
 * players moves along the cards (Left, Right) and votes (X); the tally as the votes come; the winner, the others greyed,
 * then on (the next match: net_play, from the title's way back). The host decides; a joiner shows what it sends. */
static void net_vote_overlay(void)
{
    Lobby *l = netplay_lobby();
    if (!l) return;
    int host = lobby_is_host(l), me = lobby_node(l);
    net_vote_local = me >= 0 && me < SES_MAX_NODES && lobby_view(l)->m[me].count ? lobby_view(l)->m[me].count : 1;
    for (int p = 0; p < 4; p++) { net_vote_cursor[p] = 0; net_vote_mine[p] = -1; net_vote_row[p] = net_vote_lock[p] = 0; }
    if (host) net_vote_begin();
    else net_vote_read();
    uint64_t started = SDL_GetTicks(), decided = 0;
    int auto_car = getenv("TM2PC_NET_AUTOCAR") ? atoi(getenv("TM2PC_NET_AUTOCAR")) : -2; /* tests: each player's car, locked */
    uint32_t starts = lobby_view(l)->starts;
    uint16_t prev[4] = {0xFFFF, 0xFFFF, 0xFFFF, 0xFFFF};
    Image canvas = {0, 0, NULL};
    int auto_vote = getenv("TM2PC_NET_AUTOVOTE") ? atoi(getenv("TM2PC_NET_AUTOVOTE")) : -1; /* tests: every player's vote */
    for (;;) {
        if (host) net_vote_host_tick(started);
        else net_vote_read();
        if (lobby_status(l) != LOBBY_IN || lobby_view(l)->starts != starts) break; /* (gone, or the host started already) */
        if (net_vote_winner >= 0 && net_vote_go && !decided) decided = SDL_GetTicks();
        if (decided && SDL_GetTicks() - decided >= 1500) break;
        if (!host && !net_vote_n && SDL_GetTicks() - started > 30000) break; /* (no vote came) */
        uint16_t bb[4] = {0, 0, 0, 0}; /* (each player's buttons, read once a frame) */
        for (int p = 0; p < net_vote_local && p < 4; p++) {
            int menu_key;
            bb[p] = script ? (p == 0 ? menu_input(&menu_key) : 0) : input_player_menu_buttons(p);
        }
        for (int p = 0; p < net_vote_local && p < 4 && net_vote_n && net_vote_cars && !net_vote_go; p++) { /* their car */
            uint16_t b = bb[p], pressed = (uint16_t)(b & ~prev[p]);
            if (net_vote_winner >= 0 || net_vote_mine[p] >= 0) net_vote_row[p] = 1; /* (voted: their car next) */
            if (net_vote_row[p] == 0 && net_vote_winner < 0) continue; /* (on the cards: the vote's own, below) */
            prev[p] = b;
            int car = net_car[p], was = net_vote_lock[p];
            if (auto_car >= -1) pressed &= (uint16_t)~(B_CROSS | B_START); /* (tests: the script's presses not the lock) */
            if (auto_car >= -1 && !net_vote_lock[p] && SDL_GetTicks() - started > 3000) { /* (tests: the car, its first skin
                                                                                       * with TM2PC_NET_AUTOSKIN, selected) */
                if (car != auto_car) car = auto_car;
                else if (getenv("TM2PC_NET_AUTOSKIN") && !mod_is_look(vote_look(p)) && vote_has_looks(car)) pressed = B_DOWN;
                else pressed = B_CROSS;
            }
            if (pressed & B_TRIANGLE && net_vote_winner < 0 && net_vote_mine[p] < 0) { net_vote_row[p] = 0; menu_sound(0); continue; }
            int look = vote_look(p);
            if (pressed & (B_UP | B_DOWN) && car >= 0) { /* its skins (the server's list's, on here), then its own look */
                int nl = vote_next_look(car, look, pressed & B_UP ? -1 : 1);
                if (nl != look) {
                    int idx = mod_is_look(nl) ? lobby_mods_skin_index(nl) : -1;
                    net_skin[p] = mod_is_look(nl) ? nl : -1;
                    lobby_set_skin(l, p, idx);
                    net_skin_sent[p] = idx;
                    net_vote_lock[p] = 0;
                    menu_sound(0);
                }
            }
            if (pressed & (B_LEFT | B_RIGHT)) { /* the next car this profile has (-1: random) */
                int dir = pressed & B_LEFT ? -1 : 1;
                for (int k = 0; k < 64; k++) {
                    car += dir;
                    if (car < -1) car = PROFILE_CHARACTERS - 1;
                    if (car >= PROFILE_CHARACTERS) car = -1;
                    if (car == -1 || cs_available(car)) break;
                }
                net_vote_lock[p] = 0;
                menu_sound(0);
            }
            if (pressed & (B_CROSS | B_START)) { net_vote_lock[p] = !net_vote_lock[p]; menu_sound(1); }
            if (car != net_car[p]) { /* (the lobby has it: the host's next start takes it; its own look) */
                net_car[p] = car;
                if (net_skin[p] >= 0) { net_skin[p] = -1; lobby_set_skin(l, p, -1); net_skin_sent[p] = -1; }
                int team = net_teams() ? get_net_team(p) : -1;
                lobby_set_player(l, p, car, team, net_ready[p]);
                net_sent[p][0] = car, net_sent[p][1] = team, net_sent[p][2] = net_ready[p];
            }
            if (net_vote_lock[p] != was) {
                lobby_set_vote(l, p, net_vote_round & 0xFF, vote_enc(net_vote_mine[p], net_vote_lock[p]));
                fprintf(stderr, "network: player %d's car %s: %s%s%s\n", p + 1, net_vote_lock[p] ? "selected" : "open",
                        car >= 0 ? profile_character_name(car) : "random", vote_look(p) >= 0x20 ? ", skin " : "",
                        vote_look(p) >= 0x20 && mod_car_name(vote_look(p)) ? mod_car_name(vote_look(p)) : "");
            }
        }
        for (int p = 0; p < net_vote_local && p < 4 && net_vote_n && net_vote_winner < 0; p++) {
            if (net_vote_cars && net_vote_row[p] == 1) continue; /* (on their car) */
            uint16_t b = bb[p], pressed = (uint16_t)(b & ~prev[p]);
            prev[p] = b;
            if (auto_vote >= 0 && net_vote_mine[p] < 0) { net_vote_cursor[p] = auto_vote % net_vote_n; pressed = B_CROSS; }
            if (net_vote_cars && (pressed & B_TRIANGLE)) { net_vote_row[p] = 1; menu_sound(0); continue; } /* (no vote: the
                                                                         * car; O again back, the user's 2026-11-11) */
            if (pressed & B_LEFT) { net_vote_cursor[p] = (net_vote_cursor[p] + net_vote_n - 1) % net_vote_n; menu_sound(0); }
            if (pressed & B_RIGHT) { net_vote_cursor[p] = (net_vote_cursor[p] + 1) % net_vote_n; menu_sound(0); }
            if (pressed & (B_CROSS | B_START)) {
                net_vote_mine[p] = net_vote_cursor[p];
                lobby_set_vote(l, p, net_vote_round & 0xFF, vote_enc(net_vote_mine[p], net_vote_lock[p]));
                if (net_vote_cars) net_vote_row[p] = 1; /* (their car next) */
                menu_sound(1);
                fprintf(stderr, "network: player %d voted for %d\n", p + 1, net_vote_mine[p] + 1);
            }
        }
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w > 0 && size.h > 0 && image_resize(&canvas, size.w, size.h)) {
            static const uint8_t black[3] = {0, 0, 0};
            memset(canvas.px, 0, (size_t)canvas.w * canvas.h * 3);
            if (pause_frame.px) { /* the battle's last frame, dimmed */
                int h = canvas.h, w = (int)((float)pause_frame.w * h / pause_frame.h + 0.5f);
                if (w > canvas.w) { w = canvas.w; h = (int)((float)pause_frame.h * w / pause_frame.w + 0.5f); }
                draw_image(&canvas, &pause_frame, 0, 0, (float)pause_frame.w, (float)pause_frame.h, (canvas.w - w) / 2,
                           (canvas.h - h) / 2, w, h, 0);
                draw_fill(&canvas, 0, 0, canvas.w, canvas.h, black, 150);
            }
            View v = view_fit(&canvas);
            lettering();
            if (results_title) { /* who won the match, small, at the top */
                int ts = S(&v, 16);
                text_draw(&canvas, results_title, X(&v, 320) - text_width(results_title, ts) / 2,
                          text_top_for_center(Y(&v, 16), ts), ts, TITLE);
            }
            plain_text();
            int counts[3], voted, voters;
            net_vote_tally(counts, &voted, &voters);
            draw_vote_cards(&v, 54, counts, voted, voters);
            static uint64_t shot_for; /* tests: the vote's screen, as BMPs (1 its start, 2 a car locked, 3 the go) */
            static int shot_last;
            if (shot_for != started) shot_for = started, shot_last = 0;
            int want = SDL_GetTicks() - started > 1000 ? 1 + (net_vote_lock[0] != 0) + net_vote_go : 0;
            if (getenv("TM2PC_NET_MENU_SHOT") && want > shot_last) {
                char path[512];
                snprintf(path, sizeof path, "%s/vote_%d.bmp", getenv("TM2PC_NET_MENU_SHOT"), want);
                image_save_bmp(&canvas, path);
                shot_last = want;
            }
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
        }
        ui_audio_frame();
        ui_vsync();
    }
    display_to_game(&canvas);
    image_free(&canvas);
}
/* (net/game_tm2.c, while a match waits on the network) the game held: its last frame dimmed, a box with the words over
 * it; title NULL: the game shows again */
static Image wn_frame; /* (the wait notice's: the game's frame under it, as it was before the notice) */
static int wn_on;
/* The frame as shown, for a screen drawn over it (the results, the pause): under a wait notice still up (a player
 * leaving as the round ended: the host's wait, the results came after it), the game's frame from before the notice,
 * not the notice ("WAITING FOR PLAYERS" behind the board, the user's) */
unsigned char *ui_capture_clean(int *w, int *h)
{
    if (wn_on && wn_frame.px && wn_frame.w > 0 && wn_frame.h > 0) {
        size_t n = (size_t)wn_frame.w * wn_frame.h * 3;
        unsigned char *copy = malloc(n);
        if (copy) {
            memcpy(copy, wn_frame.px, n);
            *w = wn_frame.w, *h = wn_frame.h;
            return copy;
        }
    }
    return wide_capture(w, h);
}
void ui_net_wait_notice(const char *title, const char *line)
{
    static Image canvas;
    if (!title) {
        if (wn_on) { /* the game's frame from before it on the screen again, until the game draws (2 frames): after a
                      * round's end the game draws none, and the notice stayed what a screen over it took ("WAITING FOR
                      * PLAYERS" behind the results' board) */
            wn_on = 0;
            if (wn_frame.px) display_to_game(&wn_frame);
            else display_release();
            image_free(&wn_frame);
        }
        return;
    }
    if (!wn_on) {
        int w = 0, h = 0;
        unsigned char *shot = wide_capture(&w, &h); /* (the notice's own: the game's frame) */
        image_free(&wn_frame);
        if (shot) { wn_frame.w = w; wn_frame.h = h; wn_frame.px = shot; }
        wn_on = 1;
    }
    PsyzSize size = Psyz_VideoGetDisplaySize();
    if (size.w <= 0 || size.h <= 0 || !image_resize(&canvas, size.w, size.h)) return;
    static const uint8_t black[3] = {0, 0, 0};
    memset(canvas.px, 0, (size_t)canvas.w * canvas.h * 3);
    if (wn_frame.px) {
        int h = canvas.h, w = (int)((float)wn_frame.w * h / wn_frame.h + 0.5f);
        if (w > canvas.w) { w = canvas.w; h = (int)((float)wn_frame.h * w / wn_frame.w + 0.5f); }
        draw_image(&canvas, &wn_frame, 0, 0, (float)wn_frame.w, (float)wn_frame.h, (canvas.w - w) / 2, (canvas.h - h) / 2, w, h, 0);
        draw_fill(&canvas, 0, 0, canvas.w, canvas.h, black, 110);
    }
    View v = view_fit(&canvas);
    int ts = S(&v, 18), ls = S(&v, 11), bw = S(&v, 300), bh = S(&v, 64);
    plain_text(); /* (the line's font, measured) */
    if (line && line[0] && text_width(line, ls) + S(&v, 24) > bw) bw = text_width(line, ls) + S(&v, 24); /* (a long name in it) */
    draw_fill(&canvas, X(&v, 320) - bw / 2, Y(&v, 240) - bh / 2, bw, bh, black, 200);
    lettering();
    text_draw(&canvas, title, X(&v, 320) - text_width(title, ts) / 2, text_top_for_center(Y(&v, 226), ts), ts, TITLE);
    plain_text();
    if (line && line[0]) text_draw(&canvas, line, X(&v, 320) - text_width(line, ls) / 2, text_top_for_center(Y(&v, 254), ls), ls, TITLE);
    Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
    static char shot_title[32], shot_line[96]; /* (tests: TM2PC_NET_NOTICE_SHOT, each notice's first frame as a BMP
                                                * there; again when its line changes, the same file) */
    if (getenv("TM2PC_NET_NOTICE_SHOT") && (strcmp(shot_title, title) || strcmp(shot_line, line ? line : ""))) {
        char path[512];
        snprintf(shot_title, sizeof shot_title, "%s", title);
        snprintf(shot_line, sizeof shot_line, "%s", line ? line : "");
        char tag[24];
        int t = 0;
        for (const char *q = title; *q && t < 23; q++) if ((*q >= 'A' && *q <= 'Z') || (*q >= '0' && *q <= '9')) tag[t++] = *q;
        tag[t] = 0;
        snprintf(path, sizeof path, "%s/notice_%s.bmp", getenv("TM2PC_NET_NOTICE_SHOT"), tag);
        image_save_bmp(&canvas, path);
    }
    Psyz_VideoVSync(0);
    rt_heartbeat++;
    void gpu_escape_frame(void);
    gpu_escape_frame();
}
/* The results: returns 0 a rematch, 1 back to the Challenge Match page. */
/* A Versus Tournament's boss round coming (the user's, 2026-11-05): the board gone, BOSS ROUND; at the left the
 * stage's winner (LAST SURVIVOR), their car and name; VS; at the right SELECTING BOSS... runs through the other
 * players, fast and slowing like a slot machine, a tick each, and lands on the boss's driver; then the boss's portrait
 * and "<NAME> IS <BOSS>". Each machine its own (no game state); every one the same length. */
enum { BI_SPIN = 3600, BI_LAND = 4200, BI_END = 7500 };
static void compose_boss_intro(Image *c, int w, int b, int shown, int landed, int boss_car)
{
    static const uint8_t black[3] = {0, 0, 0};
    memset(c->px, 0, (size_t)c->w * c->h * 3);
    if (pause_frame.px) {
        int h = c->h, wd = (int)((float)pause_frame.w * h / pause_frame.h + 0.5f);
        if (wd > c->w) { wd = c->w; h = (int)((float)pause_frame.h * wd / pause_frame.w + 0.5f); }
        draw_image(c, &pause_frame, 0, 0, (float)pause_frame.w, (float)pause_frame.h, (c->w - wd) / 2, (c->h - h) / 2, wd, h, 0);
        draw_fill(c, 0, 0, c->w, c->h, black, 190);
    }
    View v = view_fit(c);
    lettering();
    const MatchCar *mw = NULL, *ms = NULL;
    for (int i = 0; i < match_cars(); i++) {
        if (match_car(i)->human == w) mw = match_car(i);
        if (match_car(i)->human == shown) ms = match_car(i);
    }
#define CTR(str, xu, yu, sz, col) text_draw(c, str, X(&v, xu) - text_width(str, sz) / 2, text_top_for_center(Y(&v, yu), sz), sz, col)
    CTR("BOSS ROUND", 320, 64, S(&v, 40), TITLE);
    char nm[64], fit[64];
    int ls = S(&v, 15), ns = S(&v, 20), pw = 176, ph = 88;
    /* the winner */
    CTR("LAST SURVIVOR", 160, 150, ls, COPPER);
    if (mw) draw_plate(&v, mw, X(&v, 160 - pw / 2), Y(&v, 175), S(&v, pw), S(&v, ph));
    snprintf(nm, sizeof nm, "%s", match_human_name(w) ? match_human_name(w) : "PLAYER");
    upper(nm);
    fit_text(fit, sizeof fit, nm, S(&v, 250), ns);
    CTR(fit, 160, 290, ns, WHITE);
    CTR("VS", 320, 220, S(&v, 44), ORANGE);
    /* the boss: the drivers running by, then the one */
    CTR(landed ? "THE BOSS" : "SELECTING BOSS...", 480, 150, ls, COPPER);
    if (ms) { /* landed: the driver's card is the boss's (Dark Tooth, with no card: his name on it) */
        MatchCar card = *ms;
        if (landed && boss_car >= 0) card.car = boss_car;
        draw_plate(&v, &card, X(&v, 480 - pw / 2), Y(&v, 175), S(&v, pw), S(&v, ph));
    }
    snprintf(nm, sizeof nm, "%s", match_human_name(shown) ? match_human_name(shown) : "PLAYER");
    upper(nm);
    fit_text(fit, sizeof fit, nm, S(&v, 250), ns);
    CTR(fit, 480, 290, ns, landed ? ORANGE : WHITE);
    if (landed && boss_car >= 0) {
        char line[96], name[64];
        snprintf(name, sizeof name, "%s", match_human_name(b) ? match_human_name(b) : "PLAYER");
        snprintf(line, sizeof line, "%s IS %s!", name, profile_character_name(boss_car));
        upper(line);
        int sz = S(&v, 28), room = S(&v, 600);
        if (text_width(line, sz) > room) sz = sz * room / text_width(line, sz);
        CTR(line, 320, 360, sz, TITLE);
    }
#undef CTR
}
static void versus_boss_intro(int w, int b, int boss_car)
{
    int humans = (int)mem_r32(&M.cpu, GA(0x80181014u)), cand[16], nc = 0;
    if (humans > 16) humans = 16;
    int vp_human_left_match(int h); /* vplus/fixes.c: a player who left: not on the wheel */
    for (int i = 0; i < versus_wheel_n && i < 16; i++) /* (only those who could be drawn: the bottom 4) */
        if (versus_wheel[i] != w && versus_wheel[i] < humans && !vp_human_left_match(versus_wheel[i])) cand[nc++] = versus_wheel[i];
    if (nc < 1) cand[nc++] = b;
    int at = 0; /* the spin: steps growing from 55 ms, so it lands on b at BI_SPIN */
    uint64_t steps[64];
    int ns = 0;
    for (double t = 0, d = 55; t < BI_SPIN && ns < 64; t += d, d *= 1.12) steps[ns++] = (uint64_t)t;
    int start = 0; /* (the first shown: so the last step is b) */
    for (int i = 0; i < nc; i++) if (cand[i] == b) start = ((i - (ns - 1)) % nc + nc) % nc;
    Image canvas = {0, 0, NULL};
    display_hold = 0;
    Psyz_VideoSetDisplayRGB24Fill(1);
    uint64_t t0 = SDL_GetTicks();
    int last_step = -1, landed_sounded = 0, shot = 0;
    fprintf(stderr, "versus: the boss intro: player %d against player %d as %s\n", w + 1, b + 1, profile_character_name(boss_car));
    for (;;) {
        uint64_t t = SDL_GetTicks() - t0;
        if (t >= BI_END) break;
        int step = 0;
        while (step + 1 < ns && steps[step + 1] <= t) step++;
        int landed = t >= BI_LAND;
        int shown = landed ? b : cand[(start + step) % nc];
        if (step != last_step && !landed) { menu_sound(0); last_step = step; }
        if (landed && !landed_sounded) { game_boom(); landed_sounded = 1; }
        PsyzSize size = Psyz_VideoGetDisplaySize();
        if (size.w > 0 && size.h > 0 && image_resize(&canvas, size.w, size.h)) {
            compose_boss_intro(&canvas, w, b, shown, landed, boss_car);
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
            if (getenv("TM2PC_VERSUS_SHOT") && shot < 2 && t >= (uint64_t)(shot == 0 ? 1500 : 6000)) { /* tests: the intro */
                char path[600];
                snprintf(path, sizeof path, "%s_boss%d.bmp", getenv("TM2PC_VERSUS_SHOT"), shot++);
                image_save_bmp(&canvas, path);
            }
        }
        ui_audio_frame();
        ui_vsync();
    }
    (void)at;
    display_to_game(&canvas); /* (held until the game draws again: freed under the screen, the intro stayed up) */
    image_free(&canvas);
}

static int battle_results(int result, int mode)
{
    static char title[64];
    int order[MATCH_MAX];
    /* the battle's sounds (engines, flames) stopped as the pause stops them (the sound object at gp+500): only the music
     * and the menu sounds over the results */
    port_sounds_stop();
    scoreboard_order(order);
    results_winner = match_car(order[0]); /* the last car in (with several: the most kills) */
    int duo_h = -1, duo_ai = -1;
    if (vp_duo_winner(&duo_h, &duo_ai)) { /* 2 players and computer cars: the port's last car in */
        for (int i = 0; i < match_cars(); i++)
            if ((duo_h >= 0 && match_car(i)->human == duo_h) || (duo_ai >= 0 && match_car(i)->ai == duo_ai))
                results_winner = match_car(i);
    } else if (mode == 4) { /* 2 players: the one still in */
        for (int i = 0; i < match_cars(); i++)
            if (match_car(i)->human == (result == 3 ? 0 : 1)) results_winner = match_car(i);
    } else if (result == 3) {
        for (int i = 0; i < match_cars(); i++)
            if (match_car(i)->human == 0) results_winner = match_car(i);
    }
    char name[48] = "";
    if (results_winner) scoreboard_name(results_winner, name, sizeof name);
    snprintf(title, sizeof title, "%s WINS", name);
    int team = vp_teams_winner();
    if (team >= 0) { /* teams: the team's win */
        snprintf(title, sizeof title, "%s TEAM WINS", team_values[team]);
        results_winner = NULL;
    }
    memset(results_lines, 0, sizeof results_lines);
    if (survival_on) {
        int vp_survival_seconds(void); /* vplus/fixes.c */
        int round = vp_survival_round(), secs = vp_survival_seconds(), damage = 0;
        if (result == 3) snprintf(title, sizeof title, "YOU SURVIVED ALL %d ROUNDS!", round);
        else snprintf(title, sizeof title, "YOU SURVIVED %d ROUND%s", round - 1, round - 1 == 1 ? "" : "S");
        results_winner = NULL;
        for (int i = 0; i < match_cars(); i++) if (match_car(i)->human >= 0) damage += match_car(i)->damage;
        snprintf(results_lines[0], sizeof results_lines[0], "ROUNDS: %d OF %d", result == 3 ? round : round - 1, round > 10 ? round : 10);
        if (result == 3) snprintf(results_lines[1], sizeof results_lines[1], "TIME: %d:%02d", secs / 60, secs % 60);
        snprintf(results_lines[2], sizeof results_lines[2], "DAMAGE DEALT: %d", damage);
        int humans = (int)mem_r32(&M.cpu, GA(0x80181014u));
        for (int p = 0; p < humans && p < 16 && result == 3; p++) stat_best_low(p, STAT_SURVIVAL_TIME, secs);
    }
    { /* the Stats screen: the match for everyone in it; the win for its winner (or the winning team's players);
       * Survival: the rounds survived, a best */
        int humans = (int)mem_r32(&M.cpu, GA(0x80181014u));
        for (int p = 0; p < humans && p < 16; p++) { /* (every player of the match: online, stat_add counts this
                                                     * machine's own, whatever their number) */
            stat_add(p, STAT_MATCHES, 1);
            if (survival_on) {
                int round = vp_survival_round();
                stat_best(p, STAT_SURVIVAL_BEST, result == 3 ? round : round - 1);
            } else if (team >= 0 ? vp_team_of_human(p) == team : results_winner && results_winner->human == p) {
                stat_add(p, STAT_MATCH_WINS, 1);
            }
        }
        feats_flush();
    }
    if (results_title_tour[0]) snprintf(title, sizeof title, "%s", results_title_tour);
    results_title = title;
    /* the battle's sounds stop (engines, guns, flames: as the pause does, 801605B4 on the sound object at gp+500); the music plays on */
    port_sounds_stop();
    guest_call(GA(0x800D34C0u), 0, 0, 0, 0); /* soundUpdate */
    guest_call(GA(0x800D34E8u), 0, 0, 0, 0); /* soundFlush: to the sound chip now (no game frame runs here) */
    void spu_all_keys_off(void); /* runtime/hw.c: and every voice off (loops the stop missed: lava, an engine) */
    spu_all_keys_off();
    int w = 0, h = 0;
    unsigned char *shot = ui_capture_clean(&w, &h);
    image_free(&pause_frame); pause_frame_gen++;
    if (shot) { pause_frame.w = w; pause_frame.h = h; pause_frame.px = shot; pause_frame_gen++; }
    Psyz_VideoSetOverlay(NULL, 0, 0, NULL, 0);
    int sel = 0, dirty = 1, chosen = -1, menu_key;
    uint16_t prev = 0xFFFF;
    Image canvas = {0, 0, NULL};
    if (!results_skip) { /* (no screen: the game's last frame stays) */
        display_hold = 0;
        Psyz_VideoSetDisplayRGB24Fill(1);
    }
    fprintf(stderr, "challenge match: %s\n", title);
    for (int i = 0; i < match_cars(); i++) {
        char name[48];
        scoreboard_name(match_car(i), name, sizeof name);
        fprintf(stderr, "challenge match: %s kills %d deaths %d damage %d place %d\n", name, match_car(i)->kills,
                match_car(i)->deaths, match_car(i)->damage, match_car(i)->place);
    }
    if (netplay_in_match() && netplay_lobby()) { /* online: the match's result to the masters (the stats: counted once two
                                                  * machines agree; not with mods: none exist yet, so every match) */
        const LobbyView *lv = lobby_view(netplay_lobby());
        FriendResult fr[MASTER_RESULT_PLAYERS];
        int fn = 0;
        static const uint8_t none[MASTER_ID_BYTES];
        for (int i = 0; i < match_cars() && fn < MASTER_RESULT_PLAYERS; i++) {
            const MatchCar *mc = match_car(i);
            if (mc->human < 0) continue;
            const uint8_t *oid = NULL;
            for (int n = 0; n < SES_MAX_NODES && !oid; n++)
                if (lv->start.first[n] != 0xFF && mc->human >= lv->start.first[n] && mc->human < lv->start.first[n] + lv->m[n].count)
                    oid = lv->m[n].p[mc->human - lv->start.first[n]].online_id;
            if (!oid || !memcmp(oid, none, MASTER_ID_BYTES)) continue; /* (a guest: no stats) */
            memcpy(fr[fn].id, oid, MASTER_ID_BYTES);
            fr[fn].car = (uint8_t)mc->car;
            fr[fn].won = (uint8_t)(results_winner == mc);
            fr[fn].kills = (uint16_t)mc->kills;
            fr[fn].deaths = (uint16_t)mc->deaths;
            fr[fn].damage = (uint32_t)mc->damage;
            fn++;
        }
        uint8_t key[8]; /* (the same on every machine: the match's seed and its number) */
        for (int k = 0; k < 4; k++) key[k] = (uint8_t)(lv->start.seed >> (8 * k)), key[4 + k] = (uint8_t)(lv->starts >> (8 * k));
        const int no_mods = 1; /* (the user's: modded games are not counted; Vanilla Plus is) */
        friends_report(key, no_mods, battle_match()->arena, battle_match_type() ? battle_match_type()->mode : 0, fr, fn);
    }
    if (results_skip) return 0; /* (a custom tournament's stage: counted, no screen) */
    if (trun.versus) { /* a Versus Tournament's stage: the standings a while, then on (no choices: every machine the same) */
        if (versus_final_on()) { /* the players' medals to their Stats (each machine its own players) */
            VsRow mr[32];
            int mn = vs_rows(mr, 32), mst[32], med[32];
            vs_standing_order(mr, mn, mst);
            vs_medals(mr, mn, mst, med);
            for (int q = 0; q < mn; q++) {
                if (mr[q].human >= 0) stat_add(mr[q].human, STAT_VERSUS_PLAYED, 1);
                if (mr[q].human >= 0 && med[q])
                    stat_add(mr[q].human, med[q] == 1 ? STAT_VERSUS_GOLD : med[q] == 2 ? STAT_VERSUS_SILVER : STAT_VERSUS_BRONZE, 1);
            }
            feats_flush();
        }
        uint64_t until = SDL_GetTicks() + (versus_final_on() ? VS_FINAL_MS : VS_RESULTS_MS);
        results_no_choices = 1;
        versus_anim_at = SDL_GetTicks();
        int shots = 0, draws = 0, cheered = 0;
        uint64_t draw_ns = 0, began = SDL_GetTicks();
        while (SDL_GetTicks() < until) {
            PsyzSize size = menu_canvas_size(); /* (4K: too many pixels to draw each frame, the count crawled at 2 a second) */
            uint64_t t = SDL_GetTicks() - versus_anim_at;
            if (t < VS_HOLD + VS_COUNT + VS_PAUSE + VS_SLIDE + 100 || versus_final_on()) dirty = 1; /* (the count and the
                                                                          * slide, the final's confetti: each frame) */
            if (versus_final_on() && t >= VS_SETTLED && !cheered) { game_boom(); cheered = 1; }
            if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) && image_resize(&canvas, size.w, size.h)) {
                uint64_t t0 = SDL_GetTicksNS();
                compose_results(&canvas, -1);
                Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
                draw_ns += SDL_GetTicksNS() - t0, draws++;
                dirty = 0;
            }
            if (getenv("TM2PC_VERSUS_SHOT") && canvas.px && shots < 4 && t >= (uint64_t)(shots == 0 ? 1000 : shots == 1 ? VS_HOLD + VS_COUNT / 2
                                                                 : shots == 2 ? VS_HOLD + VS_COUNT + VS_PAUSE + VS_SLIDE / 2
                                                                 : versus_final_on() ? VS_SETTLED + 2500 : 9000)) {
                char path[600]; /* tests: the standings at four moments (TM2PC_VERSUS_SHOT: a path; _N.bmp after it) */
                snprintf(path, sizeof path, "%s_%d.bmp", getenv("TM2PC_VERSUS_SHOT"), shots++);
                image_save_bmp(&canvas, path);
            }
            ui_audio_frame();
            ui_vsync();
        }
        fprintf(stderr, "versus standings: %d pictures in %.1f s, %.1f ms each (%dx%d)\n", draws, (SDL_GetTicks() - began) / 1000.0,
                draws ? draw_ns / 1e6 / draws : 0.0, canvas.w, canvas.h);
        versus_anim_at = 0;
        results_no_choices = 0;
        display_to_game(&canvas); /* (held until the game or the next screen draws) */
        image_free(&canvas);
        return 0;
    }
    if (netplay_in_match() && net_pl.on && net_pl.n > 0 && netplay_lobby() && !lobby_migrated_at(netplay_lobby(), NULL)) { /* a server's playlist: the final scoreboard a while, then the vote, then on */
        uint64_t until = SDL_GetTicks() + NET_SCOREBOARD_MS;
        results_no_choices = 1;
        while (SDL_GetTicks() < until) {
            PsyzSize size = menu_canvas_size();
            if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) && image_resize(&canvas, size.w, size.h)) {
                compose_results(&canvas, -1);
                Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
                dirty = 0;
            }
            ui_audio_frame();
            ui_vsync();
        }
        results_no_choices = 0;
        image_free(&canvas);
        net_vote_overlay();
        return 1;
    }
    while (chosen < 0) {
        uint16_t b = menu_input(&menu_key), pressed = (uint16_t)(b & ~prev);
        prev = b;
        if (pressed & (B_UP | B_DOWN | B_LEFT | B_RIGHT)) { sel = !sel; menu_sound(0); dirty = 1; }
        else if (pressed & (B_CROSS | B_START)) chosen = sel;
        else if (pressed & B_CIRCLE) chosen = 1;
        PsyzSize size = menu_canvas_size();
        if (size.w > 0 && size.h > 0 && (dirty || size.w != canvas.w || size.h != canvas.h) &&
            image_resize(&canvas, size.w, size.h)) {
            compose_results(&canvas, sel);
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
            dirty = 0;
        }
        ui_audio_frame();
        ui_vsync();
    }
    menu_sound(1);
    while (input_menu_buttons(&menu_key) && !script) ui_vsync();
    display_to_game(&canvas);
    image_free(&canvas);
    fprintf(stderr, "challenge match: %s\n", chosen ? "back to its page" : "rematch");
    return chosen;
}

void F_800D1318_orig(CPU *c);
void vp_battle_round(void); /* vplus/fixes.c */
void vp_lives_match_start(void);
int vp_lives_take(int p);
int vp_deathmatch(void);
/* ---- the line-up before a battle ----
 * Before a level the game deals a card per opponent over the arena's picture (8012A910: its card sprites, the
 * cards' pictures, the deal). Its card table holds 9 (decomp request 32, CAR_GROUPS_PLAN.md 2.8). The port shows
 * its own instead in a Challenge Match (every car: the players' with their names, frames in the team colors)
 * and in a tournament past 9 opponents: dealt as the game deals (each card flying in, turning, landing askew
 * with its sound), then held 2.5 seconds (X or Start: on at once). TM2PC_TEST_LINEUP=N: ours for any match,
 * held N frames (tests). */
void F_8012A910_orig(CPU *c);
static void tournament_lineup(void)
{
    battle_overlay_off();
    const uint32_t set = GA(0x8016475Cu); /* the session settings */
    int four_computer_cars(void); /* vplus/four.c: the computer cars (a 3-4 player tournament's count has players 3-4 in it) */
    int level = mem_r8(&M.cpu, set + 24), humans = mem_r8(&M.cpu, set + 4), opps = four_computer_cars();
    if (four_humans() > humans) humans = four_humans(); /* players 3-4 (the port's) */
    LineupCard cards[16];
    int n = 0;
    int vp_versus_duelist(int h); /* vplus/fixes.c: a Versus boss round's two */
    int duel = trun.versus && vp_versus_boss_driver() >= 0;
    for (int i = 0; i < humans && i < 16 && n < 16 && battle_live && (!trun.on || trun.versus); i++, n++) { /* (a Challenge
                                       * Match's players, a Versus Tournament's; a tournament's line-up the opponents only, as the game's) */
        if (duel && !vp_versus_duelist(i)) { n--; continue; } /* (a boss round: its two only, the user's 2026-11-11) */
        cards[n].car = i < 2 ? mem_r8(&M.cpu, set + 8 + (uint32_t)i) : four_car_of(i);
        cards[n].player = i + 1;
        cards[n].color = netplay_in_match() ? humans_slot(i) : i; /* (online: this PC's players; the others by their names) */
        cards[n].team = battle_live && battle_match_teams() ? battle_match()->player_team[i & 15] % BATTLE_TEAM_COLORS : -1;
        snprintf(cards[n].name, sizeof cards[n].name, "%s", match_human_name(i)); /* (online: every player's lobby name) */
    }
    for (int i = 0; i < opps && n < 16; i++, n++) { /* (slots 9..15: request 32's port table, through the accessor) */
        if (i == vp_minion_opponent()) { n--; continue; } /* the Juggernaut's Minion: no card (it waits, hidden) */
        int car = (int16_t)guest_call(GA(0x8013783Cu), set, (uint32_t)i, 0, 0); /* (a mod character: its number) */
        cards[n].car = (car >= 0 && car < PROFILE_CHARACTERS) || mod_car_base(car) >= 0 ? car : -1;
        cards[n].player = 0;
        cards[n].color = -1;
        cards[n].team = battle_live && battle_match_teams() ? battle_match()->team[i % BATTLE_OPPONENT_SLOTS] % BATTLE_TEAM_COLORS : -1;
        snprintf(cards[n].name, sizeof cards[n].name, "%s", car_label(car));
        if (!battle_live || (trun.on && !trun.versus)) cards[n].name[0] = 0; /* (a tournament: no names, as the game's own line-up) */
    }
    for (int fill = getenv("TM2PC_TEST_LINEUP_CARS") ? atoi(getenv("TM2PC_TEST_LINEUP_CARS")) : 0; n > 0 && n < fill && n < 16; n++) {
        cards[n] = cards[n - 1]; /* tests: the line-up filled to N cards with other cars (the 4 x 4 grid) */
        cards[n].car = (cards[n].car + 1) % BATTLE_OPPONENT_CARS;
        cards[n].player = 0;
        cards[n].color = -1;
        snprintf(cards[n].name, sizeof cards[n].name, "%s", profile_character_name(cards[n].car));
    }
    fprintf(stderr, "line-up: level %d, %d players, %d opponents (the port's)\n", level, humans, opps);
    load_art();
    Image canvas = {0, 0, NULL};
    Psyz_VideoSetDisplayRGB24Fill(1);
    const char *test = getenv("TM2PC_TEST_LINEUP");
    /* the game's pace: 11 frames a card at 60, then on (its last picture stays through the loading); half a second here */
    int trailer = getenv("TM2PC_TRAILER") != NULL; /* (trailer footage: scripted, but paced and heard as a player's game) */
    const int dealt = n * DEAL_FRAMES, hold = test && atoi(test) > 1 ? atoi(test) : script && !trailer ? 0 : 30;
    Image base = {0, 0, NULL}; /* the arena's picture, scaled once, and the cards that have landed */
    int in_base = 0;
    uint64_t began = SDL_GetTicksNS();
    float tilt[16];
    for (int i = 0; i < n; i++) { /* each lands a little askew: 0, 2, 4 or 6 degrees either way (the game's rand & 6) */
        int r = (int)SDL_rand(16);
        tilt[i] = (float)((r & 8) ? -(r & 6) : (r & 6));
    }
    uint16_t prev = 0xFFFF;
    uint64_t next = SDL_GetTicksNS();
    for (int f = 0; f < dealt + hold; f++) {
        int key;
        uint16_t b = menu_input(&key), pressed = (uint16_t)(b & ~prev);
        prev = b;
        if ((pressed & (B_CROSS | B_START)) && f > 20) { /* on: every card, then away */
            if (f < dealt) f = dealt;
            else break;
        }
        if (f < dealt && f % DEAL_FRAMES == DEAL_FRAMES - 1) shell_sound(3); /* a card lands: the game's sound for it */
        PsyzSize size = menu_canvas_size(); /* (at most 1440p's pixels: composed each frame, a 4K screen slowed the deal) */
        if (size.w > 0 && size.h > 0 && (base.w != size.w || base.h != size.h) && image_resize(&base, size.w, size.h)) {
            static const uint8_t black[3] = {0, 0, 0};
            draw_fill(&base, 0, 0, base.w, base.h, black, 255);
            View bv = view_fit(&base);
            draw_lineup_cards(&bv, X(&bv, 0), Y(&bv, 0), S(&bv, 640), S(&bv, 480), level >= 10 && level <= 12 ? level - 1 : level, cards,
                              n, -1, NULL, 0, 0, 0); /* (the secret levels 10..12 as the arena values 9..11) */
            in_base = 0;
        }
        const char *at = getenv("TM2PC_TEST_LINEUP_AT"); /* tests: the deal drawn as at that frame */
        int df = at ? atoi(at) : f;
        int landed = df >= dealt ? n : (df + 1) / DEAL_FRAMES; /* cards that have landed: drawn into the picture once */
        if (base.px && landed > in_base) {
            View bv = view_fit(&base);
            draw_lineup_cards(&bv, X(&bv, 0), Y(&bv, 0), S(&bv, 640), S(&bv, 480), -2, cards, n, dealt + 1, tilt, 0, in_base, landed);
            in_base = landed;
        }
        if (base.px && image_resize(&canvas, base.w, base.h)) { /* each frame: the picture, and the card in flight */
            memcpy(canvas.px, base.px, (size_t)base.w * base.h * 3);
            View v = view_fit(&canvas);
            draw_lineup_cards(&v, X(&v, 0), Y(&v, 0), S(&v, 640), S(&v, 480), -2, cards, n, df, tilt, 0, in_base, n);
            Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
        }
        /* the game's VBlank (shown, paced): its sound driver runs each frame as under the game's own card screen (without
         * it the cards' sound came out quiet, popping and cut short, the user's) */
        if (!script || trailer) { rt_vblank(); continue; }
        ui_audio_frame(); /* (scripted runs: as before, the game's VBlanks not run: the tests' timing) */
        ui_vsync();
        next += 1000000000ull / 60;
        uint64_t t = SDL_GetTicksNS();
        if (next > t) SDL_DelayNS(next - t);
        else next = t;
    }
    fprintf(stderr, "line-up: %d cards in %.2f s\n", n, (double)(SDL_GetTicksNS() - began) / 1e9);
    /* the game's next screen, sharp: "LOADING" at the top as its loader prints it (font 0 centered on 159, y 40) and a
     * tournament's password (font 5, y 222, 255,161,0, from level 2; not with Remove password menu) over the line-up,
     * held through the load (display_to_game). The game's own prints of them stay under it, unseen (the user's: the
     * low resolution screen during the load) */
    if (canvas.px && gfont_ready(0)) {
        static const uint8_t loading_c[3] = {93, 30, 23}, password_c[3] = {255, 161, 0};
        float s = canvas.h / 240.0f;
        if (canvas.w / 320.0f < s) s = canvas.w / 320.0f;
        float ox = (canvas.w - 320 * s) / 2, oy = (canvas.h - 240 * s) / 2;
        gfont_draw(&canvas, 0, "LOADING", ox + (159 - (gfont_width(0, "LOADING") >> 1)) * s, oy + 196 * s, s, loading_c); /* (under the cards: the port's grid fills the top) */
        char password[64] = "";
        if (!vp_on(VP_PASSWORDS_OFF) && !battle_live && gfont_ready(5) &&
            guest_call(GA(0x8012CC04u), SETTINGS_BLOCK, 0, 0, 0) == 1 && (int32_t)guest_call(GA(0x8012CB90u), SETTINGS_BLOCK, 0, 0, 0) >= 2) {
            int car = (int8_t)guest_call(GA(0x8012CBD4u), SETTINGS_BLOCK, 0, 0, 0);
            if (car != 12 && car != 13) {
                guest_call(GA(0x801292A4u), 0, 0, 0, 0);
                for (int i = 0; i < (int)sizeof password - 1; i++) {
                    password[i] = (char)mem_r8(&M.cpu, PAUSE_PASSWORD + (uint32_t)i);
                    if (!password[i]) break;
                }
            }
        }
        if (password[0]) gfont_draw(&canvas, 5, password, ox + (159 - (gfont_width(5, password) >> 1)) * s, oy + 222 * s, s, password_c);
    }
    if (getenv("TM2PC_LINEUP_SHOT") && canvas.px) image_save_bmp(&canvas, getenv("TM2PC_LINEUP_SHOT")); /* tests: the held picture */
    display_to_game(&canvas);
    display_hold_to_round(1);
    image_free(&canvas);
    image_free(&base);
}
/* Survival (no line-up): the globe's last frame as shown, sharp, with "LOADING" where the game's loader prints it, held
 * through the load: the game's own copy of the globe under its LOADING was the PS1's resolution (the user's 2026-11-02) */
static PsyzSize menu_canvas_size(void);
static void survival_loading(void)
{
    battle_overlay_off();
    /* the globe as it was shown: 4:3 between black bars on a wider window (wide_capture widens a frame by the last
     * round's stretch: a Survival after another stretched the globe as LOADING came up, the user's 2026-11-03) */
    Image raw = {0, 0, NULL}, shot = {0, 0, NULL};
    raw.px = Psyz_VideoAllocCapturedFrame(&raw.w, &raw.h);
    PsyzSize size = menu_canvas_size();
    if (!raw.px || raw.w < 64 || raw.h < 48 || !gfont_ready(0) || size.w < 64 || size.h < 48 || !image_resize(&shot, size.w, size.h)) {
        free(raw.px);
        return;
    }
    static const uint8_t black[3] = {0, 0, 0};
    draw_fill(&shot, 0, 0, shot.w, shot.h, black, 255);
    int gh = shot.h, gw = (int)lrintf(gh * 4.0f / 3);
    if (gw > shot.w) gw = shot.w, gh = (int)lrintf(gw * 3.0f / 4);
    draw_image(&shot, &raw, 0, 0, (float)raw.w, (float)raw.h, (shot.w - gw) / 2, (shot.h - gh) / 2, gw, gh, 0);
    free(raw.px);
    static const uint8_t loading_c[3] = {93, 30, 23};
    float s = shot.h / 240.0f;
    if (shot.w / 320.0f < s) s = shot.w / 320.0f;
    float ox = (shot.w - 320 * s) / 2, oy = (shot.h - 240 * s) / 2;
    gfont_draw(&shot, 0, "LOADING", ox + (159 - (gfont_width(0, "LOADING") >> 1)) * s, oy + 40 * s, s, loading_c);
    if (getenv("TM2PC_LINEUP_SHOT")) image_save_bmp(&shot, getenv("TM2PC_LINEUP_SHOT")); /* tests: the held picture */
    display_to_game(&shot);
    if (trun.versus && versus_podium == 2 && (M.live_input || getenv("TM2PC_TRAILER"))) { /* the podium's LOADING held as a
        * line-up is (its deal and half a second), not gone at once (the user's 16-player take 2026-11-17); X or Start: on */
        uint16_t prev = 0xFFFF;
        for (int f = 0; f < 90; f++) {
            int key;
            uint16_t b = menu_input(&key), pressed = (uint16_t)(b & ~prev);
            prev = b;
            if ((pressed & (B_CROSS | B_START)) && f > 20) break;
            rt_vblank();
        }
    }
    display_hold_to_round(trun.versus && versus_podium == 2 ? 2 : 1);
    image_free(&shot);
}

void ui_CardScreen(CPU *c)
{
    int opps = mem_r8(&M.cpu, GA(0x8016475Cu) + 5);
    static int test = -1;
    if (test < 0) test = getenv("TM2PC_TEST_LINEUP") != NULL;
    if (ui_survival()) { survival_loading(); return; } /* Survival: no line-up (its cars change every round) */
    if (trun.versus && versus_podium == 2 && (M.live_input || script)) { survival_loading(); return; } /* the podium: not a battle, the
                                                                                          * globe with LOADING (the user's) */
    if (!M.live_input && !script && !test) { F_8012A910_orig(c); return; } /* (tapes: the game's) */
    (void)opps; /* every line-up the port's, sharp (the game's own was low resolution, the user's) */
    tournament_lineup();
}

void ui_MainLoop(CPU *c) /* rtMainLoop: one round, its result */
{
    if (!battle_live || battle_new_match) { /* a restarted round (a lost life) keeps the match's tally */
        match_begin(battle_live && !survival_on ? (battle_match_type()->mode == MODE_DEATHMATCH ? 99 : battle_match()->lives) : 1);
        void tour_carry_round(void);
        tour_carry_round(); /* (a Custom or Versus Tournament's next stage: its players' weapons kept) */
        if (battle_live) vp_lives_match_start();
        battle_new_match = 0;
    }
    vp_battle_round();
    if (duel_active) fprintf(stderr, "co-op: the duel's round starts\n");
    wide_round(1); /* widescreen: the round shown stretched (its views squeezed, vplus/wide.c) */
    F_800D1318_orig(c); /* (the stretch stays on to the session's end: its end texts over the frozen battle, wide) */
    if (duel_active) { /* the co-op duel: one round, then the runner quits */
        int dr = (int)c->r[2];
        fprintf(stderr, "co-op: the duel's round ended (%d)\n", dr);
        if (dr == 3 || dr == 4) { duel_result = dr; c->r[2] = 2; }
        return;
    }
    int mode = mem_r8(&M.cpu, SETTINGS_BLOCK), r = (int)c->r[2];
    if (!battle_live || !(M.live_input || script) || !text_ready()) return;
    if ((mode == 3 && (r == 1 || r == 3)) || (mode == 4 && (r == 3 || r == 4))) {
        /* without "No round restarts": a player's lost life with lives left restarts the round */
        int p = mode == 4 ? (r == 3 ? 1 : 0) : 0;
        if (!vp_deathmatch() && !vp_on(VP_NO_ROUND_RESTARTS) && (mode == 4 || r == 1) && vp_lives_take(p)) return;
        battle_new_match = 1;
        int humans = (int)mem_r32(&M.cpu, GA(0x80181014u)); /* the match played out: a feat for everyone in it (quit or rematch) */
        for (int p = 0; p < humans && p < 4; p++) feat_set(p, FEAT_CUSTOM_FINISHED);
        feats_flush();
        if (trun.on) { tour_stage_end(r, mode); c->r[2] = 2; } /* a custom tournament's stage: on to the next, or out */
        else if (battle_results(r, mode) || netplay_in_match()) c->r[2] = 2; /* the runner quits (a server's match: no rematch yet) */
    }
}

