/* ---- a mod character's ending (docs/MODDING.md 6): the port's page where the game would play the ending's movie ----
 * Its ending.bmp (640 x 480, or 16:9) over the screen, else its car-select portrait on black; "<NAME> WINS" and its
 * ending.txt (else nothing more) over it; until X, Start or Circle after 2 seconds (scripted tests: 3 seconds, the
 * picture saved to TM2PC_ENDING_SHOT). From a won tournament (moviePlayEnding wrapped: the character's name of the
 * port's, vplus/mod_cars.c) and from Movies > Mods. */
static void wrap_lines(const char *text, int maxw, int size, char lines[][160], int max_lines, int *n)
{
    *n = 0;
    char word[160], line[160] = "";
    for (const char *p = text;; p++) {
        if (*p && *p != ' ' && *p != '\n' && *p != '\r' && *p != '\t') continue;
        const char *start = p;
        while (start > text && start[-1] != ' ' && start[-1] != '\n' && start[-1] != '\r' && start[-1] != '\t') start--;
        size_t len = (size_t)(p - start) < sizeof word - 1 ? (size_t)(p - start) : sizeof word - 1;
        memcpy(word, start, len);
        word[len] = 0;
        if (len) {
            char test[320];
            snprintf(test, sizeof test, "%s%s%s", line, line[0] ? " " : "", word);
            if (line[0] && text_width(test, size) > maxw) {
                if (*n < max_lines) snprintf(lines[(*n)++], 160, "%s", line);
                snprintf(line, sizeof line, "%s", word);
            } else
                snprintf(line, sizeof line, "%.159s", test);
        }
        if (*p == '\n' || !*p) { /* a line end: a new line (an empty one too, between paragraphs) */
            if ((line[0] || (*p == '\n' && *n)) && *n < max_lines) snprintf(lines[(*n)++], 160, "%s", line);
            line[0] = 0;
        }
        if (!*p) break;
    }
}
int mod_ending_compose(int number, Image *canvas_out, int cw, int ch) /* (tests: ui_shot) */
{
    const char *mod_car_name(int number);
    int mod_car_picture(int number, const char *file, char *path, int size);
    const char *name = mod_car_name(number);
    if (!name || !text_ready() || cw <= 0 || ch <= 0 || !image_resize(canvas_out, cw, ch)) return 0;
    Image canvas = *canvas_out;
    memset(canvas.px, 0, (size_t)canvas.w * canvas.h * 3);
    float k = canvas.h / 480.0f;
    if (canvas.w / 640.0f < k) k = canvas.w / 640.0f;
    int ox = (int)((canvas.w - 640 * k) / 2), oy = (int)((canvas.h - 480 * k) / 2);
    char path[700];
    Image pic = {0};
    if (mod_car_picture(number, "ending.bmp", path, sizeof path)) pic = image_load_bmp(path);
    int text_x = ox + (int)(48 * k), text_w = (int)(544 * k), text_y = oy + (int)(300 * k);
    if (pic.px) { /* the picture, the text over its lower part darkened */
        draw_contain(&canvas, &pic, 0, 0, canvas.w, canvas.h);
        draw_darken_x(&canvas, 0, oy + (int)(280 * k), canvas.w, canvas.h - (oy + (int)(280 * k)), 170, 170);
    } else { /* the driver's portrait at the left, the text beside it */
        const Image *portrait = skin_pic(number, 1);
        if (!portrait) portrait = skin_pic(number, 0);
        if (portrait) draw_contain(&canvas, portrait, ox + (int)(48 * k), oy + (int)(96 * k), (int)(160 * k), (int)(320 * k));
        text_x = ox + (int)(240 * k);
        text_w = (int)(352 * k);
        text_y = oy + (int)(96 * k);
    }
    image_free(&pic);
    char title[96];
    snprintf(title, sizeof title, "%s WINS", name);
    upper(title);
    int ts = (int)(34 * k), bs = (int)(19 * k);
    text_draw(&canvas, title, text_x, text_y, ts, ORANGE);
    char *story = NULL;
    if (mod_car_picture(number, "ending.txt", path, sizeof path)) {
        FILE *f = fopen(path, "rb");
        if (f) {
            story = calloc(1, 64 * 1024 + 1);
            if (story) story[fread(story, 1, 64 * 1024, f)] = 0;
            fclose(f);
        }
    }
    if (story) {
        static char lines[24][160];
        int n = 0, line_h = (int)(bs * 1.35f), y = text_y + (int)(ts * 1.6f);
        int room = (oy + (int)(440 * k) - y) / (line_h > 0 ? line_h : 1);
        wrap_lines(story, text_w, bs, lines, room < 24 ? (room > 0 ? room : 0) : 24, &n);
        for (int i = 0; i < n; i++, y += line_h) text_draw(&canvas, lines[i], text_x, y, bs, WHITE);
        free(story);
    }
    const char *press = CROSS " = CONTINUE";
    text_draw(&canvas, press, canvas.w - ox - (int)(24 * k) - text_width(press, bs), oy + (int)(452 * k), bs, GRAY);
    fprintf(stderr, "ending: %s (a mod character's)\n", name);
    return 1;
}
static uint64_t video_start;
static uint16_t video_prev;
static int video_skip(void) /* a press of X, Start or Circle half a second in (scripted tests: never) */
{
    uint16_t b = input_pad_buttons(), pressed = (uint16_t)(b & ~video_prev);
    video_prev = b;
    return !script && M.live_input && M.vblanks > video_start + 30 && (pressed & (B_CROSS | B_START | B_CIRCLE));
}
void ui_mod_ending(int number)
{
    char path[700];
    int mod_car_picture(int number, const char *file, char *path, int size);
    if (mod_car_picture(number, "ending.mpg", path, sizeof path)) { /* its video; then its page only with a story */
        video_start = M.vblanks;
        video_prev = input_pad_buttons();
        int played = mod_video_play(path, video_skip);
        Psyz_VideoSetDisplayRGB24(NULL, 0, 0);
        if (played && !mod_car_picture(number, "ending.txt", path, sizeof path)) return;
    }
    PsyzSize size = Psyz_VideoGetDisplaySize();
    Image canvas = {0};
    if (!mod_ending_compose(number, &canvas, size.w, size.h)) return;
    if (getenv("TM2PC_ENDING_SHOT")) image_save_bmp(&canvas, getenv("TM2PC_ENDING_SHOT"));
    Psyz_VideoSetDisplayRGB24Fill(1);
    Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
    uint64_t start = M.vblanks;
    uint16_t prev = input_pad_buttons(); /* (a button held from before: not a press) */
    for (;;) {
        rt_vblank();
        Psyz_VideoSetDisplayRGB24(canvas.px, canvas.w, canvas.h);
        uint16_t b = input_pad_buttons(), pr = (uint16_t)(b & ~prev);
        prev = b;
        if (script || !M.live_input ? M.vblanks > start + 180 : M.vblanks > start + 120 && (pr & (B_CROSS | B_START | B_CIRCLE)))
            break;
    }
    display_to_game(&canvas);
    image_free(&canvas);
}
void F_8012B898_orig(CPU *c);
void ui_MoviePlayEnding(CPU *c) /* moviePlayEnding(settings, name, frames, wide, skip): a mod character's: its page */
{
    int mod_cars_ending_number(uint32_t name); /* vplus/mod_cars.c */
    int number = mod_cars_ending_number(c->r[5]);
    /* the battle's frames forgotten: uncapped, the pacing wait kept presenting the last one (the CONGRATULATIONS page) over
     * the movie, about 10 s of its sound with no picture (the user's playtest of 2026-10-30) */
    void interp_snap(void), interp_frame_start(void); /* vplus/interp.c */
    interp_snap();
    interp_frame_start();
    if (number < 0) { F_8012B898_orig(c); return; }
    ui_mod_ending(number);
    c->r[2] = 0;
}
